<script>
import tseGeometryRows from "../data/tse.json";
import plantsCatalogRows from "../data/plants.json";

// STREET/SATELLITE TOOLTIP DATE LOOKUP
// ------------------------------------
// fin_project.json lives in src/data with the other Map.vue JSON sources. Load
// it only when Street/Satellite needs tooltip dates, as a webpack async chunk.
// There are no /data/... URL probes or public fetch fallbacks. Tooltip hovers
// use one compact contract-name -> dates Map, so each lookup is O(1) and Vue 2
// never makes the FIN_Project rows reactive.
let finProjectTooltipDateIndex = null;
let finProjectTooltipDateLoadPromise = null;
let finProjectTooltipDatePreloadHandle = null;

function normalizeFinProjectTooltipContractName(value) {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function firstNonEmptyFinProjectTooltipValue(row, keys) {
  for (const key of keys) {
    const value = row?.[key];
    if (value !== null && value !== undefined && String(value).trim() !== "") {
      return value;
    }
  }
  return null;
}

async function loadFinProjectTooltipDateIndex() {
  if (finProjectTooltipDateIndex) return finProjectTooltipDateIndex;
  if (finProjectTooltipDateLoadPromise) {
    return finProjectTooltipDateLoadPromise;
  }

  finProjectTooltipDateLoadPromise = import(
    /* webpackChunkName: "fin-project-tooltip-data" */
    "../data/fin_project.json"
  )
    .then((finProjectModule) => {
      const rows =
        finProjectModule && finProjectModule.default
          ? finProjectModule.default
          : finProjectModule;

      if (!Array.isArray(rows)) {
        throw new Error(
          "Expected ../data/fin_project.json to contain a JSON array.",
        );
      }

      const index = new Map();

      rows.forEach((row) => {
        const contractName = firstNonEmptyFinProjectTooltipValue(row, [
          "Procurement Project",
          "Procurment Project",
          "Contract_Name",
          "Contract Name",
        ]);
        const key = normalizeFinProjectTooltipContractName(contractName);
        if (!key) return;

        const expire = firstNonEmptyFinProjectTooltipValue(row, [
          "Contract_Expire",
          "Contract Expire",
        ]);
        const voApproved = firstNonEmptyFinProjectTooltipValue(row, [
          "VO_Date",
          "VO Date",
        ]);
        const cmoForecast = firstNonEmptyFinProjectTooltipValue(row, [
          "CMO_Forecast",
          "CMO Forecast",
          "CMO forecast",
        ]);

        // Duplicate Procurement Project values can exist. Retain only the
        // matching contract key and the three date values needed by tooltips.
        const score = [expire, voApproved, cmoForecast].filter(
          (value) =>
            value !== null &&
            value !== undefined &&
            String(value).trim() !== "",
        ).length;
        const current = index.get(key);

        if (!current || score > current.score) {
          index.set(key, {
            expire,
            voApproved,
            cmoForecast,
            score,
          });
        }
      });

      finProjectTooltipDateIndex = index;
      return index;
    })
    .catch((error) => {
      // Cache an empty lookup so a malformed/missing local source file does not
      // cause a new async import attempt on every mouse hover.
      console.warn(
        "Street/Satellite tooltip dates could not be loaded from ../data/fin_project.json:",
        error,
      );
      finProjectTooltipDateIndex = new Map();
      return finProjectTooltipDateIndex;
    })
    .finally(() => {
      finProjectTooltipDateLoadPromise = null;
    });

  return finProjectTooltipDateLoadPromise;
}

// 3D RUNTIME LAZY LOAD
// --------------------
// Keep the working one-file Map.vue architecture, but do not pull the heavy
// Three.js runtime into Street/Satellite-only pages. Webpack creates a separate
// async chunk for these dependencies and downloads it only after the user
// explicitly enters the standalone 3D view.
let THREE = null;
let OrbitControls = null;
let createThreeCameraControls = null;
let createStairTreadGroup = null;
let standaloneThreeRuntimePromise = null;

async function loadStandaloneThreeRuntimeDependencies() {
  if (
    THREE &&
    OrbitControls &&
    createThreeCameraControls &&
    createStairTreadGroup
  ) {
    return;
  }

  if (!standaloneThreeRuntimePromise) {
    standaloneThreeRuntimePromise = Promise.all([
      import(
        /* webpackChunkName: "map-3d-runtime" */
        "three"
      ),
      import(
        /* webpackChunkName: "map-3d-runtime" */
        "three/examples/jsm/controls/OrbitControls.js"
      ),
      import(
        /* webpackChunkName: "map-3d-runtime" */
        "../utils/threeCameraControls.js"
      ),
      import(
        /* webpackChunkName: "map-3d-runtime" */
        "../map/three/createThreeParkLayer.js"
      ),
    ])
      .then(([threeModule, orbitModule, cameraControlsModule, stairModule]) => {
        THREE = threeModule && (threeModule.default || threeModule);
        OrbitControls =
          orbitModule && (orbitModule.OrbitControls || orbitModule.default);
        createThreeCameraControls =
          cameraControlsModule &&
          (cameraControlsModule.createThreeCameraControls ||
            cameraControlsModule.default);
        createStairTreadGroup =
          stairModule &&
          (stairModule.createStairTreadGroup || stairModule.default);

        if (
          !THREE ||
          !OrbitControls ||
          typeof createThreeCameraControls !== "function" ||
          typeof createStairTreadGroup !== "function"
        ) {
          throw new Error(
            "The standalone 3D runtime did not expose all required modules.",
          );
        }
      })
      .catch((error) => {
        // Allow a later 3D click to retry if a transient chunk/network error
        // prevented the first lazy load.
        standaloneThreeRuntimePromise = null;
        THREE = null;
        OrbitControls = null;
        createThreeCameraControls = null;
        createStairTreadGroup = null;
        throw error;
      });
  }

  await standaloneThreeRuntimePromise;
}

