    isProjectDetailsMap() {
      const routeName =
        this.$route && this.$route.name ? String(this.$route.name) : "";
      return (
        this.activeViewMode === "project" &&
        Boolean(this.currentProjectId) &&
        (routeName === "projects" || routeName === "project_details")
      );
    },

    isStandaloneThreeMode() {
      return this.activeBaseMapMode === "3d" && this.isProjectDetailsMap;
    },

    fullscreenThreeProjectTitle() {
      if (!this.currentProjectId) return "";

      const project = this.getProjectItemById(this.currentProjectId);
      if (!project) return "";

      const nameEn = String(project.name_en || "").trim();
      const nameAr = String(project.name_ar || "").trim();

      return this.isArabicUI() ? nameAr || nameEn : nameEn || nameAr;
    },

    shouldShowMainMapFilter() {
      return (
        !this.isStandaloneThreeMode &&
        this.$route &&
        this.$route.name === "Home"
