    threeTreeTypeTotal() {
      return (
        Array.isArray(this.threeTreeTypeStats) ? this.threeTreeTypeStats : []
      ).reduce((sum, item) => sum + (Number(item && item.count) || 0), 0);
    },

    threeTreeLabelsAnyEnabled() {
      return Object.values(this.threeTreeLabelVisibility || {}).some(Boolean);
    },

    threeTreeLabelsAllEnabled() {
      const stats = Array.isArray(this.threeTreeTypeStats)
        ? this.threeTreeTypeStats
        : [];
      if (!stats.length) return false;
      return stats.every((tree) =>
        Boolean(this.threeTreeLabelVisibility[String(tree && tree.name)]),
      );
    },

    threeShrubTypeTotal() {
      return (
        Array.isArray(this.threeShrubTypeStats) ? this.threeShrubTypeStats : []
      ).reduce((sum, item) => sum + (Number(item && item.count) || 0), 0);
    },

    threeShrubLabelsAnyEnabled() {
      return Object.values(this.threeShrubLabelVisibility || {}).some(Boolean);
    },

    threeShrubLabelsAllEnabled() {
