        ? this.threeShrubTypeStats
        : [];
      if (!stats.length) return false;
      return stats.every((plant) =>
        Boolean(this.threeShrubLabelVisibility[String(plant && plant.name)]),
      );
    },

    threeGroundCoverTypeTotal() {
      return (
        Array.isArray(this.threeGroundCoverTypeStats)
          ? this.threeGroundCoverTypeStats
          : []
      ).reduce((sum, item) => sum + (Number(item && item.count) || 0), 0);
    },

    threeGroundCoverLabelsAnyEnabled() {
