    threeGroundCoverLabelsAllEnabled() {
      const stats = Array.isArray(this.threeGroundCoverTypeStats)
        ? this.threeGroundCoverTypeStats
        : [];
      if (!stats.length) return false;
      return stats.every((plant) =>
        Boolean(
          this.threeGroundCoverLabelVisibility[String(plant && plant.name)],
        ),
      );
    },

    standaloneThreeLayerOptions() {
      const terrainActive = Boolean(this.threeLayerVisibility.terrain);
      const terrainDisabledReason = terrainActive
        ? ""
        : this.mapUiText(
            "Enable TERRAIN (Before) or TERRAIN (After) first",
            "فعّل التضاريس (قبل) أو التضاريس (بعد) أولاً",
            "Enable TERRAIN (Before) or TERRAIN (After) first",
          );

      const createExpandableLayer = (key, label, available) => {
        const children = this.getStandaloneThreeSubLayerOptions(key);
        return {
          key,
          label,
          available: Boolean(available),
          locked: false,
          active: this.isStandaloneThreeParentLayerActive(key),
          partiallyActive:
            this.isStandaloneThreeParentLayerPartiallyActive(key),
          expandable: children.length > 0,
          expanded: Boolean(this.threeLayerExpanded[key]),
          children,
        };
      };

      const createSimpleLayer = (key, label, available) => ({
        key,
        label,
        available: Boolean(available),
        locked: false,
        active: Boolean(this.threeLayerVisibility[key]),
        partiallyActive: false,
        expandable: false,
        expanded: false,
        children: [],
      });

      const terrainBefore = {
        key: "terrainBefore",
        label: this.mapUiText(
          "TERRAIN (Before)",
          "التضاريس (قبل)",
          "TERRAIN (Before)",
        ),
        available: true,
        locked: false,
        active: terrainActive && this.threeTerrainMode === "before",
        partiallyActive: false,
        expandable: true,
        expanded: Boolean(this.threeLayerExpanded.terrainBefore),
        children: [
          {
            key: "satelliteGround",
            label: this.mapUiText(
              "Satellite Ground",
              "أرضية القمر الصناعي",
              "Satellite Ground",
            ),
            available: terrainActive,
            active: Boolean(this.threeLayerVisibility.satelliteGround),
            disabledReason: terrainDisabledReason,
          },
        ],
      };

      const terrainAfter = {
        key: "terrainAfter",
        label: this.mapUiText(
          "TERRAIN (After)",
          "التضاريس (بعد)",
          "TERRAIN (After)",
        ),
        available: true,
        locked: false,
        active: terrainActive && this.threeTerrainMode === "after",
        partiallyActive: false,
        expandable: true,
        expanded: Boolean(this.threeLayerExpanded.terrainAfter),
        children: [
          {
            key: "compactedGround",
            label: this.mapUiText(
              "Sealed Ground",
              "أرضية مختومة",
              "Sealed Ground",
            ),
            available: terrainActive,
            active: Boolean(this.threeLayerVisibility.compactedGround),
            disabledReason: terrainDisabledReason,
          },
        ],
      };

      // UI order: terrain controls first, then built/site systems, with
      // VEGETATION intentionally last as requested.
      return [
        terrainBefore,
        terrainAfter,
        (() => {
          const waterChildren = this.getStandaloneThreeSubLayerOptions("water");
          return waterChildren.length > 1
            ? createExpandableLayer(
                "water",
                this.mapUiText("WATER", "المياه", "WATER"),
                this.threeLayerAvailability.water,
              )
            : createSimpleLayer(
                "water",
                this.mapUiText("WATER", "المياه", "WATER"),
                this.threeLayerAvailability.water,
              );
        })(),
        createExpandableLayer(
          "paths",
          this.mapUiText("PATHS", "المسارات", "PATHS"),
          this.threeLayerAvailability.paths,
        ),
        createExpandableLayer(
          "structures",
          this.mapUiText("STRUCTURES", "المنشآت", "STRUCTURES"),
          this.threeLayerAvailability.structures,
        ),
        createExpandableLayer(
          "tse",
          this.mapUiText("UTILITY", "المرافق", "UTILITY"),
          this.threeLayerAvailability.tse,
        ),
        createExpandableLayer(
          "vegetation",
          this.mapUiText("VEGETATION", "النباتات", "VEGETATION"),
          this.threeLayerAvailability.vegetation,
        ),
      ];
    },

    standaloneThreeToolOptions() {
