    visibleConceptMapLayers() {
      const qadisiyahItem = this.getQadisiyah3ProjectItem();
      const images = this.getConceptImageList(qadisiyahItem);
      return QADISIYAH_3_CONCEPT_LAYERS.filter((layer) => {
        const imagePath = this.getConceptLayerImagePath(layer, images);
        return Boolean(imagePath);
      });
    },
  },
  watch: {
    $route(to, from) {
      // Full-screen/expanded map mode belongs to a single page only. Never
      // carry it into the next route.
      if (this.isMapExpanded) {
        this.setMapExpanded(false);
      }

      // Leaving ProjectDetails should always return the shared map component
      // to its normal default state before the destination page configures it.
      if (this.isProjectDetailsRoute(from) && !this.isProjectDetailsRoute(to)) {
        this.resetMapAfterProjectDetails();
      }
    },
  },

  async mounted() {
    // Resolve the application theme BEFORE any async Mapbox / GIS startup.
    // When the app follows the browser/OS theme, Map.vue must not begin from
    // its historical hard-coded light value or the first Street basemap is
    // constructed with streets-v12 and can stay light until the user toggles
    // themes manually.
    this.theme = this.getInitialMapTheme();

    // Register before the first await so App.vue's startup change-mode event
    // cannot be missed while the Mapbox assets are loading.
    this.$root.$on("change-mode", this.handleRootThemeChange);

    // Keep complex Three.js objects outside Vue 2's reactive data observer.
    this.threeRenderer = null;
    this.threeScene = null;
    this.threeCamera = null;
    this.threeControls = null;
    this.threeParkGroup = null;
    this.threeParkModelData = null;
    this.threeLayerGroups = {
      terrain: null,
      terrainBefore: null,
      terrainAfter: null,
      paths: null,
      water: null,
      structures: null,
      vegetation: null,
      tse: null,
    };
    // Allocate every 3D-only cache on demand. Most Map.vue instances only ever
    // show Street/Satellite, so they should not fetch 3D catalogues or retain
    // cache containers that can never be used.
    this.threeProjectGisCache = null;
    this.threePathCatalogRows = [];
    this.threePathCatalogLoaded = false;
    this._threePathCatalogPromise = null;
    this._threePathCatalogMatchCache = null;
    this._threePathReferenceTextureCache = null;
    this._threeBuildingTextureCache = null;
    this._threeReferenceTextureCache = null;
    this._threeAssetCacheGeneration = 0;
    this._threeParkAbortController = null;
    this.threeProjectGisData = null;
    // Small derived GIS state retained while Terrain (After) builds. The full
    // combined GeoJSON is deliberately released before parsing a large LandXML
    // so CAD/GIS + XML DOM + Three.js terrain buffers do not peak together.
    this.threeProjectStairGisData = null;
    this.threePrecomputedLandXmlCadAlignment = null;
    this.threeProjectGisUrl = "";
    this.threeProjectGisFallbackLayer = "";
    this.threeVegetationLoadToken = 0;
    this.threeParkAnimationFrame = null;
    this.threeParkResizeObserver = null;
    this.threeCameraControls = null;
    this.threeParkBuildToken = 0;
    this.threeSatelliteGroundLoadToken = 0;
    this.threeSatelliteGroundTexture = null;
    this.threeCompactedGroundLoadToken = 0;
    this.threeCompactedGroundTexture = null;
    this.threeDefaultCameraState = null;
    this.threeLabelOverlayUpdateAt = 0;
    this.threeLabelOverlaySignature = "";
    this.threeTreeLabelOverlayUpdateAt = 0;
    this.threeTreeLabelOverlaySignature = "";
    this.threeShrubLabelOverlayUpdateAt = 0;
    this.threeShrubLabelOverlaySignature = "";
    this.threeGroundCoverLabelOverlayUpdateAt = 0;
    this.threeGroundCoverLabelOverlaySignature = "";
    this.standaloneBuildingFeatureCache = [];
    this.satelliteTerrainRestoreTimers = [];
    this.pendingSatelliteTerrainHardRefresh = false;
    this.lastStandaloneThreeResetMapViewState = null;
    // Preserve center/zoom/pitch/bearing while changing Street, Satellite and
    // the standalone Three.js 3D renderer. These are kept outside Vue 2's
    // reactive observer because they are transient renderer state.
    this.preservedMapViewState = null;
    this.pendingBaseMapCameraState = null;
    this.mapCameraRestoreTimers = [];
    this.isBaseMapStyleSwitching = false;
    this.mapboxRendererSuspended = false;
    this.suspendMapStyleRestoration = false;
    this.mapExpandedKeydownHandler = (event) => {
      if (event.key === "Escape" && this.isMapExpanded) {
        this.setMapExpanded(false);
      }
    };
    window.addEventListener("keydown", this.mapExpandedKeydownHandler);

    try {
      await this.ensureMapboxLoaded();
      await this.init_map();
      // Do not make fin_project.json part of the critical map-startup path.
      // Prime its compact tooltip-date lookup when the browser is idle instead.
      this.scheduleFinProjectTooltipDatePreload();
      this.startMapboxLanguageSync();
      this.updateMapOverlayControlPositions();
      this.mapOverlayResizeFrame = null;
      this.mapOverlayResizeHandler = () => {
        if (this.mapOverlayResizeFrame) {
          window.cancelAnimationFrame(this.mapOverlayResizeFrame);
        }
        this.mapOverlayResizeFrame = window.requestAnimationFrame(() => {
          this.mapOverlayResizeFrame = null;

          // A maximized browser can change viewport/sidebar dimensions when it
          // is moved between monitors. Recalculate the reserved sidebar width
          // every time instead of keeping the value captured on first expand.
          if (this.isMapExpanded) {
            const nextLeft = this.getExpandedMapLeftOffset();
            if (nextLeft !== this.mapExpandedLeft) {
              this.mapExpandedLeft = nextLeft;
            }
          }

          this.$nextTick(() => {
            this.updateMapOverlayControlPositions();
            this.syncThreeParkHostBounds();
            this.resizeStandaloneThreeRenderer();
            if (this.$map && typeof this.$map.resize === "function") {
              this.$map.resize();
            }
          });
        });
      };
      window.addEventListener("resize", this.mapOverlayResizeHandler);
      if (window.visualViewport) {
        window.visualViewport.addEventListener(
          "resize",
          this.mapOverlayResizeHandler,
        );
      }
      if (typeof ResizeObserver !== "undefined" && this.$refs.map) {
        this.mapOverlayResizeObserver = new ResizeObserver(
          this.mapOverlayResizeHandler,
        );
        this.mapOverlayResizeObserver.observe(this.$refs.map);
      }
    } catch (error) {
      console.error("Mapbox map could not be loaded:", error);
      this.locationErrorMessage = this.isArabicUI()
        ? "تعذر تحميل الخريطة. يرجى تحديث الصفحة أو التحقق من اتصال الشبكة."
        : "The map could not be loaded. Please refresh the page or check the network connection.";
    }
  },
  created() {
    this.$root.$on("load-project-map", (item) => {
      this.load_project(item);
    });
    this.$root.$on("load-dist-map", (item, district, action = true) => {
      this.load_near_projects(item, district, action);
    });
    this.$root.$on("set-map-zoom", (zoom) => {
      this.set_zoom(zoom);
    });
    this.$root.$on("pan-to", (latitude, longitude, zoom = 12) => {
      this.pan_to(latitude, longitude, zoom);
    });
    this.$root.$on("show-shapes", (category, backRouter) => {
      this.load_category(category, backRouter);
    });
    this.$root.$on("show-markers", (category, backRouter) => {
      this.load_markers(category, backRouter);
    });
    this.$root.$on("reset-main-map", async () => {
      this.mainMapView = "all";
      this.activeSearchProjectIds = null;
      this.clearSearchProjectHighlight();
      await this.load_markers("all", ["home", "نظرة عامة"]);
    });
    this.$root.$on("show-search-results", (projectIds) => {
      this.showOnlySearchResults(projectIds);
    });
    this.$root.$on("highlight-search-project", (projectId) => {
      this.highlightSearchProject(projectId);
    });
    this.$root.$on("clear-search-project-highlight", () => {
      this.clearSearchProjectHighlight();
    });
    this.$root.$on("clear-search-results", () => {
      this.clearSearchProjectHighlight();
      this.activeSearchProjectIds = null;
      this.activeViewMode = "all";
      this.currentProjectId = null;
      this.removeThreeParkLayer();
      this.ensureConceptModeAllowed();
      this.renderMapData();
    });
    this.$root.$on("set-contract-map-filter", (filter) => {
      this.contractMapFilter = filter || "all";
      this.refreshMapForCurrentFilters();
    });
    this.$root.$on("set-project-status-map-filter", (filter) => {
      this.contractMapFilter = filter || "all";
      this.refreshMapForCurrentFilters();
    });
    this.$root.$on("show-project-marker", (item, index, toggle) => {
      this.load_project_marker(item, index, toggle);
    });
    this.$root.$on("show-shapes-districts", (category, backRouter) => {
      this.load_districts(category, backRouter);
    });
  },
  beforeDestroy() {
    this.$root.$off("change-mode", this.handleRootThemeChange);
    this.stopMapboxLanguageSync();
    this.stopUserLocationTracking();

    if (this.locationMessageTimeout) {
      window.clearTimeout(this.locationMessageTimeout);
      this.locationMessageTimeout = null;
    }

    if (this.mapOverlayResizeObserver) {
      this.mapOverlayResizeObserver.disconnect();
      this.mapOverlayResizeObserver = null;
    }

    if (this.mapOverlayResizeHandler) {
      window.removeEventListener("resize", this.mapOverlayResizeHandler);
      if (window.visualViewport) {
        window.visualViewport.removeEventListener(
          "resize",
          this.mapOverlayResizeHandler,
        );
      }
      this.mapOverlayResizeHandler = null;
    }

    if (this.mapOverlayResizeFrame) {
      window.cancelAnimationFrame(this.mapOverlayResizeFrame);
      this.mapOverlayResizeFrame = null;
    }

    if (this.mapExpandedKeydownHandler) {
      window.removeEventListener("keydown", this.mapExpandedKeydownHandler);
      this.mapExpandedKeydownHandler = null;
    }
    document.documentElement.classList.remove("green-riyadh-map-expanded");
    document.body.classList.remove("green-riyadh-map-expanded");

    this.disableMiddleMousePanNavigation();
    this.clearMapCameraRestoreTimers();
    this.clearSatelliteTerrainRestoreTimers();
    this.removeConceptMapLayers();
    this.destroyStandaloneThreeScene();

    if (this.$map) {
      this.$map.off("style.load", this.handleMapStyleLoad);
    }
    this.removeThreeParkLayer();

    if (this.mapPopup) {
      this.mapPopup.remove();
      this.mapPopup = null;
    }

    if (this.$map) {
      this.$map.remove();
      this.$map = null;
    }
  },
  methods: {
    getInitialMapTheme() {
      // Always initialize the map in Light mode.
      // App.vue can still switch it to Dark later through the change-mode event.
      return "light";
    },

    handleRootThemeChange(type) {
      const nextTheme = type === "dark" ? "dark" : "light";
      this.theme = nextTheme;

      // If Mapbox already exists, update Street immediately. If startup is
      // still in progress, init_map() will read this.theme and construct the
      // first basemap with the correct dark/light Mapbox style.
      this.set_map_dark(nextTheme);
      this.$nextTick(() => {
        this.syncMapPopupTheme();
      });
    },

    isProjectDetailsRoute(route) {
      if (!route) return false;

      if (route.name === "projects" || route.name === "project_details") {
        return true;
      }

      const path = String(route.path || "");
      return (
        /^\/projects\/[^/]+(?:\/|$)/i.test(path) ||
        /^\/[^/]+\/[^/]+(?:\/|$)/i.test(path)
      );
    },

    getFullscreenRoutePageKey(route) {
      if (!route) return "";

      let path = String(route.path || "").trim();
      if (!path) return String(route.name || "").trim();

      // Locale-prefixed routes such as /en/projects/52 and /ar/projects/52
      // are the same page for fullscreen purposes.
      path = path.replace(/^\/(?:en|ar)(?:-[a-z]{2})?(?=\/|$)/i, "");
      path = path.replace(/\/+$/, "");
      return path || "/";
    },

    getFullscreenMeaningfulRouteParams(route) {
      const params = route && route.params ? route.params : {};
      const ignoredKeys = new Set([
        "lang",
        "language",
        "locale",
        "culture",
        "lng",
      ]);
      const meaningful = {};

      Object.keys(params)
        .sort()
        .forEach((key) => {
          if (!ignoredKeys.has(String(key).toLowerCase())) {
            meaningful[key] = params[key];
          }
        });

      return meaningful;
    },

    shouldPreserveFullscreenForRouteChange(to, from) {
      if (!to || !from) return false;

      const toPageKey = this.getFullscreenRoutePageKey(to);
      const fromPageKey = this.getFullscreenRoutePageKey(from);
      if (toPageKey && fromPageKey && toPageKey === fromPageKey) {
        return true;
      }

      // Some locale routers keep the same named route but expose the language
      // only as a route param. Preserve fullscreen only when every non-locale
      // route param is unchanged.
      if (to.name && from.name && to.name === from.name) {
        const toParams = this.getFullscreenMeaningfulRouteParams(to);
        const fromParams = this.getFullscreenMeaningfulRouteParams(from);
        return JSON.stringify(toParams) === JSON.stringify(fromParams);
      }

      return false;
    },

    getFullscreenRouteLocale(route) {
      if (!route) return "";

      const params = route.params || {};
      const query = route.query || {};
      const localeKeys = ["lang", "language", "locale", "culture", "lng"];

      for (const key of localeKeys) {
        if (params[key] != null && String(params[key]).trim()) {
          return String(params[key]).trim().toLowerCase();
        }
        if (query[key] != null && String(query[key]).trim()) {
          return String(query[key]).trim().toLowerCase();
        }
      }

      const path = String(route.path || "");
      const pathMatch = path.match(/^\/(en|ar)(?:-[a-z]{2})?(?=\/|$)/i);
      return pathMatch ? String(pathMatch[1]).toLowerCase() : "";
    },

    isFullscreenLocaleOnlyNavigation(to, from) {
      if (!to || !from) return false;

      const toPageKey = this.getFullscreenRoutePageKey(to);
      const fromPageKey = this.getFullscreenRoutePageKey(from);
      if (!toPageKey || !fromPageKey || toPageKey !== fromPageKey) {
        return false;
      }

      const toParams = this.getFullscreenMeaningfulRouteParams(to);
      const fromParams = this.getFullscreenMeaningfulRouteParams(from);
      if (JSON.stringify(toParams) !== JSON.stringify(fromParams)) {
        return false;
      }

      const toLocale = this.getFullscreenRouteLocale(to);
      const fromLocale = this.getFullscreenRouteLocale(from);
      return Boolean(toLocale && fromLocale && toLocale !== fromLocale);
    },

    isFullscreenPreferenceControl(element) {
      if (!element) return false;

      const control = element.closest(
        "[data-language], [data-locale], [data-theme], [data-mode], .language-switcher, .lang-switcher, .locale-switcher, .theme-switcher, .dark-mode, .dark-mode-toggle, .theme-toggle",
      );
      if (control) return true;

      const descriptor = [
        element.className,
        element.id,
        element.getAttribute && element.getAttribute("title"),
        element.getAttribute && element.getAttribute("aria-label"),
        element.getAttribute && element.getAttribute("data-testid"),
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();

      if (
        /(?:^|[\s_-])(language|locale|theme|appearance|dark|light)(?:$|[\s_-])/.test(
          descriptor,
        )
      ) {
        return true;
      }

      const text = String(element.textContent || "").trim();
      return /^(?:en|ar|english|arabic|العربية|ع)$/i.test(text);
    },

    handleFullscreenSidebarNavigationClick(event) {
      if (!this.isMapExpanded || !event) return;

      let target = event.target;
      if (target && target.nodeType !== 1) {
        target = target.parentElement;
      }
      if (!target || typeof target.closest !== "function") return;

      const sidebar = target.closest(
        "#sidebar, .sidebar, .main-sidebar, .left-sidebar, .side-menu, .sidebar-menu, aside",
      );
      if (!sidebar) return;

      // Vue Router links render as anchors. Restrict this handler to actual
      // navigation links so clicking the EN/Arabic or dark-mode controls in
      // the sidebar does not close fullscreen.
      const link = target.closest("a[href]");
      if (!link || !sidebar.contains(link)) return;
      if (this.isFullscreenPreferenceControl(link)) return;

      const href = String(link.getAttribute("href") || "").trim();
      if (!href || href === "#" || /^javascript:/i.test(href)) return;

      // A language switch may itself be rendered as a router-link. Resolve it
      // before closing fullscreen and preserve the expanded map when the only
      // change is EN <-> Arabic on the same page.
      if (this.$router && typeof this.$router.resolve === "function") {
        try {
          const resolved = this.$router.resolve(href);
          const targetRoute =
            resolved && resolved.route ? resolved.route : null;
          if (
            targetRoute &&
            this.isFullscreenLocaleOnlyNavigation(targetRoute, this.$route)
          ) {
            return;
          }
        } catch (error) {
          // If a custom/external sidebar link cannot be resolved, treat it as
          // navigation and close fullscreen, which matches sidebar behavior.
        }
      }

      this.setMapExpanded(false);
    },

    resetMapAfterProjectDetails() {
      // Always leave expanded mode first so the destination page gets its
      // normal layout and document scrolling back immediately.
      if (this.isMapExpanded) {
        this.setMapExpanded(false);
      } else {
        document.documentElement.classList.remove("green-riyadh-map-expanded");
        document.body.classList.remove("green-riyadh-map-expanded");
      }

      // Close ProjectDetails-only tools/panels and restore their defaults.
      this.$set(this.threeToolState, "structureLabels", false);
      this.$set(this.threeToolState, "conceptPaths", false);
      this.$set(this.threeToolState, "treeTypes", false);
      this.$set(this.threeToolState, "shrubTypes", false);
      this.$set(this.threeToolState, "groundCoverTypes", false);
      this.threeTreeTypeLoading = false;
      this.threeTreeTypeStats = [];
      this.closeStandalonePlantImageViewer();
      this.threeShrubTypeLoading = false;
      this.threeShrubTypeStats = [];
      this.threeGroundCoverTypeLoading = false;
      this.threeGroundCoverTypeStats = [];
      this.threeStructureAnnotations = [];
      this.threeVisibleStructureLabels = [];
      this.resetStandaloneThreeLayerFilters();

      // Cancel the standalone Three.js project scene and discard its camera
      // state so it can never leak into another page.
      this.exitStandaloneThreeMode();
      this.removeConceptMapLayers();
      this.clearMapCameraRestoreTimers();
      this.clearSatelliteTerrainRestoreTimers();
      this.preservedMapViewState = null;
      this.pendingBaseMapCameraState = null;
      this.lastStandaloneThreeResetMapViewState = null;
      this.isBaseMapStyleSwitching = false;
      this.suspendMapStyleRestoration = false;
      this.mapboxRendererSuspended = false;

      // Clear the ProjectDetails identity before the next page mounts. Its own
      // load event can then establish the appropriate category/search view.
      this.currentProjectId = null;
      this.nearProjectId = null;
      this.nearProjectCenter = null;
      this.activeViewMode = "all";
      this.activeBaseMapMode = "street";

      if (!this.$map) return;

      this.showMapboxRenderer();

      // Reset the camera immediately. Mapbox setStyle() preserves the camera,
      // so doing this before restoring Street also avoids an old project/3D
      // camera being re-applied after the style finishes loading.
      try {
        this.$map.jumpTo({
          center: this.getDefaultCenter(),
          zoom: Number(this.zoom || 10),
          pitch: 0,
          bearing: 0,
        });
      } catch (error) {
        console.warn(
          "Map camera could not be reset while leaving ProjectDetails:",
          error,
        );
      }

      // ProjectDetails may have been in Satellite or standalone 3D. Force the
      // shared map back to the normal Street basemap for the destination page.
      this.projectLayersReady = false;
      this.unbindProjectLayerEvents();
      try {
        this.$map.setStyle(this.getMapboxStyleForMode("street"));
        this.$map.once("idle", () => {
          if (!this.$map || this.activeBaseMapMode !== "street") return;
          this.restoreMapOverlaysAfterStyleChange({ moveCamera: false });
        });
      } catch (error) {
        console.warn(
          "Street map style could not be restored while leaving ProjectDetails:",
          error,
        );
      }
    },

    getExpandedMapLeftOffset() {
      const viewportWidth = Math.max(window.innerWidth || 0, 1);
      const preferredSelectors = [
        ".home",
        ".main-content",
        ".content-wrapper",
        "main",
        "#app main",
      ];

      for (const selector of preferredSelectors) {
        const element = document.querySelector(selector);
        if (!element || element === this.$el || this.$el.contains(element))
          continue;
        const rect = element.getBoundingClientRect();
        if (rect.left > 0 && rect.left < viewportWidth * 0.35) {
          return Math.round(rect.left);
        }
      }

      const sidebarSelectors = [
        "#sidebar",
        ".sidebar",
        ".main-sidebar",
        ".left-sidebar",
        ".side-menu",
        ".sidebar-menu",
        "aside",
      ];
      for (const selector of sidebarSelectors) {
        const element = document.querySelector(selector);
        if (!element) continue;
        const rect = element.getBoundingClientRect();
        if (
          rect.left <= 2 &&
          rect.right > 0 &&
          rect.width < viewportWidth * 0.35 &&
          rect.height > window.innerHeight * 0.5
        ) {
          return Math.round(rect.right);
        }
      }

      return 0;
    },

    toggleMapExpanded() {
      this.setMapExpanded(!this.isMapExpanded);
    },

    setMapExpanded(expanded) {
      this.isMapExpanded = Boolean(expanded);
      this.mapExpandedLeft = this.isMapExpanded
        ? this.getExpandedMapLeftOffset()
        : 0;
      // Lock the document itself as well as the body so no browser scrollbar
      // remains visible while the map is using the expanded workspace.
      document.documentElement.classList.toggle(
        "green-riyadh-map-expanded",
        this.isMapExpanded,
      );
      document.body.classList.toggle(
        "green-riyadh-map-expanded",
        this.isMapExpanded,
      );

      this.$nextTick(() => {
        this.syncThreeParkHostBounds();
        this.resizeStandaloneThreeRenderer();
        this.updateMapOverlayControlPositions();
        if (this.$map && typeof this.$map.resize === "function") {
          this.$map.resize();
        }
        const refreshExpandedViewport = () => {
          if (this.isMapExpanded) {
            this.mapExpandedLeft = this.getExpandedMapLeftOffset();
          }
          this.$nextTick(() => {
            this.syncThreeParkHostBounds();
            this.resizeStandaloneThreeRenderer();
            this.updateMapOverlayControlPositions();
            if (this.$map && typeof this.$map.resize === "function") {
              this.$map.resize();
            }
          });
        };

        window.setTimeout(refreshExpandedViewport, 80);
        window.setTimeout(refreshExpandedViewport, 260);
      });
    },

    configureMapboxScrollZoomSensitivity() {
      if (!this.$map || !this.$map.scrollZoom) return;

      try {
        if (typeof this.$map.scrollZoom.enable === "function") {
          this.$map.scrollZoom.enable();
        }
        if (typeof this.$map.scrollZoom.setWheelZoomRate === "function") {
          this.$map.scrollZoom.setWheelZoomRate(MAPBOX_MOUSE_WHEEL_ZOOM_RATE);
        }
        if (typeof this.$map.scrollZoom.setZoomRate === "function") {
          this.$map.scrollZoom.setZoomRate(MAPBOX_TRACKPAD_ZOOM_RATE);
        }
      } catch (error) {
        console.warn(
          "Mapbox scroll zoom sensitivity could not be configured:",
          error,
        );
      }
    },

    enableMiddleMousePanNavigation() {
      if (!this.$map || this.middleMousePanHandlers) return;

      const canvas = this.$map.getCanvas && this.$map.getCanvas();
      if (!canvas) return;

      const preventMiddleClickAutoscroll = (event) => {
        if (event && event.button === 1) {
          event.preventDefault();
          if (typeof event.stopPropagation === "function")
            event.stopPropagation();
          if (typeof event.stopImmediatePropagation === "function") {
            event.stopImmediatePropagation();
          }
        }
      };

      const onMouseMove = (event) => {
        const state = this.middleMousePanState;
        if (!state || !state.active || !this.$map) return;

        event.preventDefault();
        if (typeof event.stopPropagation === "function")
          event.stopPropagation();
        if (typeof event.stopImmediatePropagation === "function") {
          event.stopImmediatePropagation();
        }

        const dx = event.clientX - state.lastX;
        const dy = event.clientY - state.lastY;

        state.lastX = event.clientX;
        state.lastY = event.clientY;

        if (dx || dy) {
          // Middle-mouse drag should behave like a flat hand-pan.
          // It intentionally preserves the current pitch and bearing so users
          // can follow roads/paths without accidentally rotating or tilting 3D view.
          this.$map.panBy([-dx, -dy], { duration: 0, animate: false });
          if (typeof this.$map.setPitch === "function")
            this.$map.setPitch(state.pitch);
          if (typeof this.$map.setBearing === "function")
            this.$map.setBearing(state.bearing);
        }
      };

      const finishMiddleMousePan = (event) => {
        const state = this.middleMousePanState;
        if (!state || !state.active) return;

        if (event) {
          event.preventDefault();
          if (typeof event.stopPropagation === "function")
            event.stopPropagation();
          if (typeof event.stopImmediatePropagation === "function") {
            event.stopImmediatePropagation();
          }
        }

        this.middleMousePanState = null;
        canvas.classList.remove("is-middle-mouse-panning");

        if (this.$map) {
          if (typeof this.$map.setPitch === "function")
            this.$map.setPitch(state.pitch);
          if (typeof this.$map.setBearing === "function")
            this.$map.setBearing(state.bearing);
          if (
            this.$map.dragRotate &&
            typeof this.$map.dragRotate.enable === "function"
          ) {
            this.$map.dragRotate.enable();
          }
        }

        window.removeEventListener("mousemove", onMouseMove, true);
        window.removeEventListener("mouseup", finishMiddleMousePan, true);
        window.removeEventListener("blur", finishMiddleMousePan, true);
      };

      const onMouseDown = (event) => {
        if (!event || event.button !== 1 || !this.$map) return;

        event.preventDefault();
        if (typeof event.stopPropagation === "function")
          event.stopPropagation();
        if (typeof event.stopImmediatePropagation === "function") {
          event.stopImmediatePropagation();
        }

        if (
          this.$map.dragRotate &&
          typeof this.$map.dragRotate.disable === "function"
        ) {
          this.$map.dragRotate.disable();
        }

        this.middleMousePanState = {
          active: true,
          lastX: event.clientX,
          lastY: event.clientY,
          pitch:
            typeof this.$map.getPitch === "function" ? this.$map.getPitch() : 0,
          bearing:
            typeof this.$map.getBearing === "function"
              ? this.$map.getBearing()
              : 0,
        };

        canvas.classList.add("is-middle-mouse-panning");

        window.addEventListener("mousemove", onMouseMove, true);
        window.addEventListener("mouseup", finishMiddleMousePan, true);
        window.addEventListener("blur", finishMiddleMousePan, true);
      };

      canvas.addEventListener("mousedown", onMouseDown, true);
      canvas.addEventListener("auxclick", preventMiddleClickAutoscroll, true);
      canvas.addEventListener(
        "contextmenu",
        preventMiddleClickAutoscroll,
        true,
      );

      this.middleMousePanHandlers = {
        canvas,
        onMouseDown,
        preventMiddleClickAutoscroll,
        onMouseMove,
        finishMiddleMousePan,
      };
    },

    disableMiddleMousePanNavigation() {
      const handlers = this.middleMousePanHandlers;
      if (!handlers) return;

      if (handlers.canvas) {
        handlers.canvas.removeEventListener(
          "mousedown",
          handlers.onMouseDown,
          true,
        );
        handlers.canvas.removeEventListener(
          "auxclick",
          handlers.preventMiddleClickAutoscroll,
          true,
        );
        handlers.canvas.removeEventListener(
          "contextmenu",
          handlers.preventMiddleClickAutoscroll,
          true,
        );
        handlers.canvas.classList.remove("is-middle-mouse-panning");
      }

      window.removeEventListener("mousemove", handlers.onMouseMove, true);
      window.removeEventListener(
        "mouseup",
        handlers.finishMiddleMousePan,
        true,
      );
      window.removeEventListener("blur", handlers.finishMiddleMousePan, true);

      if (
        this.$map &&
        this.$map.dragRotate &&
        typeof this.$map.dragRotate.enable === "function"
      ) {
        this.$map.dragRotate.enable();
      }

      this.middleMousePanState = null;
      this.middleMousePanHandlers = null;
    },

    updateMapOverlayControlPositions() {
      if (typeof window === "undefined" || typeof document === "undefined")
        return;

      this.$nextTick(() => {
        const mapElement = this.$refs && this.$refs.map;
        if (
          !mapElement ||
          typeof mapElement.getBoundingClientRect !== "function"
        )
          return;

        const rect = mapElement.getBoundingClientRect();
        const style = document.documentElement.style;
        const threeHost = this.$refs ? this.$refs.threeParkHost : null;
        const overlaySelector = [
          ".main-map-style-switch",
          ".three-tree-type-panel",
          ".three-layer-filters",
          ".main-map-layer-switch",
          ".map-navigation-controls",
          ".map-location-message",
        ].join(", ");
        const overlayElements = this.$el
          ? Array.from(this.$el.querySelectorAll(overlaySelector))
          : [];

        // The legend is permanently anchored to the visible map bounds. Clear
        // any stale responsive-hide class that may have been applied by an
        // earlier render before the legend was removed from overlayElements.
        const tseLegendElement = this.$el
          ? this.$el.querySelector(".tse-map-legend--overlay")
          : null;
        if (tseLegendElement) {
          tseLegendElement.classList.remove("is-outside-visible-map");
        }

        // Temporarily hide every fixed map control while checking which part
        // of the map is genuinely visible. This prevents the controls
        // themselves from being mistaken for page content covering the map.
        const previousVisibilities = overlayElements.map((element) =>
          element.style.getPropertyValue("visibility"),
        );
        overlayElements.forEach((element) => {
          element.style.setProperty("visibility", "hidden", "important");
        });

        let visibleLeft = Math.max(0, Math.floor(rect.left));
        let visibleTop = Math.max(0, Math.floor(rect.top));
        let visibleRight = Math.min(window.innerWidth, Math.ceil(rect.right));
        let visibleBottom = Math.min(
          window.innerHeight,
          Math.ceil(rect.bottom),
        );
        let foundVisibleMapPoint = false;

        try {
          const startX = visibleLeft;
          const endX = Math.max(
            startX,
            Math.min(window.innerWidth - 1, visibleRight - 1),
          );
          const startY = visibleTop;
          const endY = Math.max(
            startY,
            Math.min(window.innerHeight - 1, visibleBottom - 1),
          );
          const step = 10;
          let minVisibleX = Infinity;
          let minVisibleY = Infinity;
          let maxVisibleX = -Infinity;
          let maxVisibleY = -Infinity;

          for (let y = startY; y <= endY; y += step) {
            for (let x = startX; x <= endX; x += step) {
              const elementAtPoint = document.elementFromPoint(x, y);
              const pointIsMap =
                elementAtPoint &&
                (elementAtPoint === mapElement ||
                  mapElement.contains(elementAtPoint) ||
                  (this.isStandaloneThreeMode &&
                    threeHost &&
                    (elementAtPoint === threeHost ||
                      threeHost.contains(elementAtPoint))));

              if (!pointIsMap) continue;

              foundVisibleMapPoint = true;
              minVisibleX = Math.min(minVisibleX, x);
              minVisibleY = Math.min(minVisibleY, y);
              maxVisibleX = Math.max(maxVisibleX, x);
              maxVisibleY = Math.max(maxVisibleY, y);
            }
          }

          if (foundVisibleMapPoint) {
            visibleLeft = Math.max(0, minVisibleX);
            visibleTop = Math.max(0, minVisibleY);
            visibleRight = Math.min(
              window.innerWidth,
              Math.min(rect.right, maxVisibleX + step),
            );
            visibleBottom = Math.min(
              window.innerHeight,
              Math.min(rect.bottom, maxVisibleY + step),
            );
          }
        } finally {
          overlayElements.forEach((element, index) => {
            const previousVisibility = previousVisibilities[index];
            if (previousVisibility) {
              element.style.setProperty("visibility", previousVisibility);
            } else {
              element.style.removeProperty("visibility");
            }
          });
        }

        // If the responsive page completely covers the map, hide its fixed
        // controls too. They will be restored automatically on the next
        // resize/Map resize when a visible map area exists again.
        if (!foundVisibleMapPoint) {
          overlayElements.forEach((element) => {
            element.classList.add("is-outside-visible-map");
          });
          return;
        }

        const edgePadding = 14;
        const top = Math.max(edgePadding, Math.round(visibleTop + edgePadding));
        const left = Math.max(
          edgePadding,
          Math.round(visibleLeft + edgePadding),
        );
        // Use the actual #map element right edge for right-anchored controls.
        // The visibility scan is still useful for the left/top/bottom bounds,
        // but on laptop layouts it can underestimate the visible right edge
        // and push Layer Filters too far inward.
        const mapRight = Math.max(
          visibleLeft,
          Math.min(window.innerWidth, Math.ceil(rect.right)),
        );
        const mapBottom = Math.max(visibleTop, visibleBottom);
        const navBottom = Math.max(
          70,
          Math.round(window.innerHeight - mapBottom + 70),
        );
        const overlayMaxHeight = Math.max(
          0,
          Math.floor(mapBottom - top - edgePadding),
        );
        const treePanelMaxHeight = Math.max(
          0,
          Math.floor(mapBottom - (top + 52) - edgePadding),
        );
        const styleMaxWidth = Math.max(
          0,
          Math.floor(mapRight - left - edgePadding),
        );

        const switchElement = this.$el
          ? this.$el.querySelector(".main-map-style-switch")
          : null;
        const styleSwitchRect = switchElement
          ? switchElement.getBoundingClientRect()
          : null;
        const styleSwitchWidth = styleSwitchRect ? styleSwitchRect.width : 0;

        // Keep Layer Filters visually symmetrical with the Street / Satellite /
        // 3D selector. The selector is 14px from the viewport's left edge, so
        // Layer Filters must be 14px from the viewport's right edge. Do not
        // derive this from #map.right here: #map can intentionally be 32%/64%
        // wide in the page layout, which created the large empty strip to the
        // right of the filter panel in 3D mode.
        const filterRight = edgePadding;

        const naturalLayerWidth = window.innerWidth <= 767 ? 214 : 244;
        const panelGap = 10;
        const filterRightEdge = Math.max(
          visibleLeft,
          Math.round(mapRight - edgePadding),
        );
        const styleSwitchRight = left + styleSwitchWidth;
        const availableLayerWidth = Math.max(
          0,
          Math.floor(filterRightEdge - styleSwitchRight - panelGap),
        );

        // Never fall back to the natural width when available width is 0.
        // The old `availableLayerWidth || naturalLayerWidth` fallback was the
        // reason the panels could still overlap on narrow laptop map columns.
        const layerFilterWidth = Math.max(
          0,
          Math.min(naturalLayerWidth, availableLayerWidth),
        );

        style.setProperty(
          "--green-riyadh-map-control-top",
          `${Math.round(top)}px`,
        );
        style.setProperty(
          "--green-riyadh-map-control-left",
          `${Math.round(left)}px`,
        );
        // Layer Filters uses the same top inset as the Street / Satellite /
        // 3D controls and the exact same 14px inset from the visible map edge.
        style.setProperty(
          "--green-riyadh-map-filter-top",
          `${Math.round(top)}px`,
        );
        style.setProperty(
          "--green-riyadh-map-filter-right",
          `${filterRight}px`,
        );
        style.setProperty("--green-riyadh-map-nav-bottom", `${navBottom}px`);

        // Anchor the TSE legend to the actual visible map bounds instead of
        // positioning it with viewport-width calculations. This keeps the
        // legend inside the map and prevents it from disappearing after a
        // browser resize.
        // Leave a little extra room above Mapbox's bottom-left attribution/logo
        // so the Legend never covers it.
        const mapboxAttributionClearance = 30;
        const legendBottom = Math.max(
          edgePadding + mapboxAttributionClearance,
          Math.round(
            window.innerHeight -
              mapBottom +
              edgePadding +
              mapboxAttributionClearance,
          ),
        );
        style.setProperty(
          "--green-riyadh-map-legend-left",
          `${Math.round(left)}px`,
        );
        style.setProperty(
          "--green-riyadh-map-legend-bottom",
          `${legendBottom}px`,
        );

        style.setProperty(
          "--green-riyadh-map-overlay-max-height",
          `${overlayMaxHeight}px`,
        );
        style.setProperty(
          "--green-riyadh-map-tree-panel-max-height",
          `${treePanelMaxHeight}px`,
        );
        style.setProperty(
          "--green-riyadh-map-style-max-width",
          `${styleMaxWidth}px`,
        );
        style.setProperty(
          "--green-riyadh-map-layer-filter-width",
          `${Math.max(0, layerFilterWidth)}px`,
        );

        // Keep every fixed panel/control completely inside the portion of the
        // map that is actually visible. On very small browser windows a panel
        // that cannot fit is hidden instead of floating over ProjectDetails.
        overlayElements.forEach((element) => {
          const elementRect = element.getBoundingClientRect();
          const fitsVisibleMap =
            elementRect.width > 0 &&
            elementRect.height > 0 &&
            elementRect.left >= visibleLeft - 1 &&
            elementRect.right <= mapRight + 1 &&
            elementRect.top >= visibleTop - 1 &&
            elementRect.bottom <= mapBottom + 1;

          element.classList.toggle("is-outside-visible-map", !fitsVisibleMap);
        });
      });
    },

    getAppLanguageCode() {
      const htmlElement =
        typeof document !== "undefined" ? document.documentElement : null;
      const storage =
        typeof window !== "undefined" ? window.localStorage : null;
      const possibleValues = [
        htmlElement ? htmlElement.lang : "",
        htmlElement && htmlElement.dir === "rtl" ? "ar" : "",
        this.$i18n?.locale,
        this.$root?.$i18n?.locale,
        this.$root?.$data?.locale,
        this.$root?.$data?.lang,
        this.$root?.$data?.language,
        storage ? storage.getItem("locale") : "",
        storage ? storage.getItem("lang") : "",
        storage ? storage.getItem("language") : "",
        storage ? storage.getItem("i18n_locale") : "",
      ];

      const matchedValue = possibleValues.find((value) => {
        const text = String(value || "")
          .trim()
          .toLowerCase();
        return text.startsWith("ar") || text.startsWith("en") || text === "rtl";
      });

      const text = String(matchedValue || "")
        .trim()
        .toLowerCase();
      return text.startsWith("ar") || text === "rtl"
        ? MAPBOX_LANGUAGE_ARABIC
        : MAPBOX_LANGUAGE_ENGLISH;
    },

    getMapboxLanguage() {
      return this.getAppLanguageCode() === MAPBOX_LANGUAGE_ARABIC
        ? MAPBOX_LANGUAGE_ARABIC
        : MAPBOX_LANGUAGE_ENGLISH;
    },

    applyMapboxLabelLanguage(force = false) {
      if (!this.$map || typeof this.$map.setLanguage !== "function") return;

      const nextLanguage = this.getMapboxLanguage();
      if (!force && this.currentMapboxLanguage === nextLanguage) return;

      this.currentMapboxLanguage = nextLanguage;

      try {
        this.$map.setLanguage(nextLanguage);
      } catch (error) {
        console.warn("Mapbox label language could not be updated:", error);
      }
    },

    startMapboxLanguageSync() {
      if (typeof window === "undefined" || typeof document === "undefined")
        return;

      this.applyMapboxLabelLanguage(true);

      const syncLanguage = () => {
        this.applyMapboxLabelLanguage(false);
      };

      if (
        typeof MutationObserver !== "undefined" &&
        !this.mapboxLanguageObserver
      ) {
        this.mapboxLanguageObserver = new MutationObserver(syncLanguage);
        this.mapboxLanguageObserver.observe(document.documentElement, {
          attributes: true,
          attributeFilter: ["lang", "dir", "class"],
        });
        if (document.body) {
          this.mapboxLanguageObserver.observe(document.body, {
            attributes: true,
            attributeFilter: ["lang", "dir", "class"],
          });
        }
      }

      const rootEvents = [
        "change-language",
        "change-lang",
        "language-changed",
        "locale-changed",
        "set-language",
        "set-locale",
      ];
      this.mapboxLanguageRootHandlers = rootEvents.map((eventName) => {
        const handler = () => this.$nextTick(syncLanguage);
        if (this.$root && typeof this.$root.$on === "function") {
          this.$root.$on(eventName, handler);
        }
        return { eventName, handler };
      });

      if (!this.mapboxLanguageSyncInterval) {
        this.mapboxLanguageSyncInterval = window.setInterval(
          syncLanguage,
          1000,
        );
      }
    },

    stopMapboxLanguageSync() {
      if (this.mapboxLanguageObserver) {
        this.mapboxLanguageObserver.disconnect();
        this.mapboxLanguageObserver = null;
      }

      if (this.mapboxLanguageSyncInterval) {
        window.clearInterval(this.mapboxLanguageSyncInterval);
        this.mapboxLanguageSyncInterval = null;
      }

      if (
        Array.isArray(this.mapboxLanguageRootHandlers) &&
        this.$root &&
        typeof this.$root.$off === "function"
      ) {
        this.mapboxLanguageRootHandlers.forEach(({ eventName, handler }) => {
          this.$root.$off(eventName, handler);
        });
      }
      this.mapboxLanguageRootHandlers = [];
    },

    hasMapbox() {
      return !!(
        this.mapboxgl &&
        this.$map &&
        typeof this.$map.getZoom === "function"
      );
    },

    async ensureMapboxLoaded() {
      if (!isMapboxTokenConfigured(MAPBOX_ACCESS_TOKEN)) {
        throw new Error(
          "Missing Mapbox public token. Add it to MAPBOX_ACCESS_TOKEN or VUE_APP_MAPBOX_ACCESS_TOKEN.",
        );
      }

      this.mapboxgl = await loadMapboxGL();
      this.mapboxgl.accessToken = MAPBOX_ACCESS_TOKEN.trim();
      ensureMapboxRtlTextPlugin(this.mapboxgl);
      return this.mapboxgl;
    },

    async waitForMapReady() {
      try {
        await this.ensureMapboxLoaded();
        if (!this.$map) {
          await this.init_map();
        }
        if (this.mapReadyPromise) {
          await this.mapReadyPromise;
        }
        return !!this.$map;
      } catch (error) {
        console.error("Map is not ready:", error);
        return false;
      }
    },

    async setMainMapView(view) {
      const filter = this.mainMapFilters.find((item) => item.value === view);
      if (!filter) return;

      this.mainMapView = filter.value;
      this.activeSearchProjectIds = null;
      this.clearSearchProjectHighlight();

      await this.load_markers(filter.category, [
        "home",
        this.mapUiText("Overview", "نظرة عامة", "Overview"),
      ]);
    },

    getMainMapViewByCategory(category) {
      const normalizedCategory = category || "all";
      const filter = this.mainMapFilters.find(
        (item) => item.category === normalizedCategory,
      );

      if (filter) return filter.value;
      return this.isTseTypology(normalizedCategory) ? "tse" : "all";
    },

    getDefaultCenter() {
      return [Number(this.longitude), Number(this.latitude)];
    },

    getMapboxStyleForMode(mode = this.activeBaseMapMode, theme = this.theme) {
      if (mode === "satellite") return MAPBOX_STYLE_SATELLITE;
      if (this.isThreeDimensionalMapMode(mode)) return MAPBOX_STYLE_3D;
      return theme === "dark" ? MAPBOX_STYLE_DARK : MAPBOX_STYLE_LIGHT;
    },

    isMapboxRoadLayer(layer) {
      if (!layer || layer.type !== "line" || !layer.id) return false;

      const id = String(layer.id).toLowerCase();
      const sourceId = String(layer.source || "").toLowerCase();
      const sourceLayer = String(layer["source-layer"] || "").toLowerCase();

      // Never touch Green Riyadh project/TSE/district layers. Only change the
      // Mapbox basemap road layers so the orange project geometry is not
      // confused with orange highway/major-road styling from the basemap.
      if (
        id.includes("green-riyadh") ||
        sourceId === PROJECT_SOURCE_ID ||
        sourceId === DISTRICT_SOURCE_ID
      ) {
        return false;
      }

      return (
        sourceLayer === "road" ||
        sourceLayer.includes("road") ||
        id.includes("road") ||
        id.includes("motorway") ||
        id.includes("trunk") ||
        id.includes("highway") ||
        id.includes("bridge") ||
        id.includes("tunnel")
      );
    },

    isMapboxRoadSymbolLayer(layer) {
      if (!layer || layer.type !== "symbol" || !layer.id) return false;

      const id = String(layer.id).toLowerCase();
      const sourceId = String(layer.source || "").toLowerCase();
      const sourceLayer = String(layer["source-layer"] || "").toLowerCase();

      // Keep Green Riyadh custom labels/icons untouched.
      if (
        id.includes("green-riyadh") ||
        sourceId === PROJECT_SOURCE_ID ||
        sourceId === DISTRICT_SOURCE_ID
      ) {
        return false;
      }

      return (
        sourceLayer === "road" ||
        sourceLayer.includes("road") ||
        id.includes("road") ||
        id.includes("motorway") ||
        id.includes("trunk") ||
        id.includes("highway") ||
        id.includes("route") ||
        id.includes("shield")
      );
    },

    isMapboxGreenAreaLayer(layer) {
      if (!layer || !layer.id) return false;
      if (!["fill", "line"].includes(layer.type)) return false;

      const id = String(layer.id).toLowerCase();
      const sourceId = String(layer.source || "").toLowerCase();
      const sourceLayer = String(layer["source-layer"] || "").toLowerCase();

      // Never touch Green Riyadh project/TSE/district layers. Only neutralize
      // Mapbox basemap parks/green-area layers so they do not look like
      // completed Green Riyadh project geometry.
      if (
        id.includes("green-riyadh") ||
        sourceId === PROJECT_SOURCE_ID ||
        sourceId === DISTRICT_SOURCE_ID
      ) {
        return false;
      }

      if (
        id.includes("water") ||
        sourceLayer.includes("water") ||
        id.includes("building") ||
        sourceLayer.includes("building") ||
        this.isMapboxRoadLayer(layer)
      ) {
        return false;
      }

      const greenAreaKeywords = [
        "park",
        "landuse",
        "land-use",
        "landcover",
        "land-cover",
        "natural",
        "wood",
        "forest",
        "grass",
        "vegetation",
        "greenspace",
        "green-space",
        "golf",
        "pitch",
        "recreation",
        "cemetery",
        "garden",
      ];

      return greenAreaKeywords.some(
        (keyword) => id.includes(keyword) || sourceLayer.includes(keyword),
      );
    },

    applyNeutralBaseRoadStyle() {
      if (!this.$map || !this.$map.isStyleLoaded()) return;

      const style = this.$map.getStyle && this.$map.getStyle();
      const layers = Array.isArray(style?.layers) ? style.layers : [];
      const isDark =
        this.theme === "dark" && this.activeBaseMapMode === "street";
      const roadColor = isDark
        ? MAPBOX_NEUTRAL_ROAD_COLOR_DARK
        : MAPBOX_NEUTRAL_ROAD_COLOR_LIGHT;
      const roadOutlineColor = isDark
        ? MAPBOX_NEUTRAL_ROAD_OUTLINE_DARK
        : MAPBOX_NEUTRAL_ROAD_OUTLINE_LIGHT;
      const roadOpacity = isDark
        ? MAPBOX_NEUTRAL_ROAD_OPACITY_DARK
        : MAPBOX_NEUTRAL_ROAD_OPACITY_LIGHT;
      const roadOutlineOpacity = isDark
        ? MAPBOX_NEUTRAL_ROAD_OUTLINE_OPACITY_DARK
        : MAPBOX_NEUTRAL_ROAD_OUTLINE_OPACITY_LIGHT;
      const roadLabelColor = isDark
        ? MAPBOX_NEUTRAL_ROAD_LABEL_DARK
        : MAPBOX_NEUTRAL_ROAD_LABEL_LIGHT;
      const roadLabelOpacity = isDark
        ? MAPBOX_NEUTRAL_ROAD_LABEL_OPACITY_DARK
        : MAPBOX_NEUTRAL_ROAD_LABEL_OPACITY_LIGHT;
      const roadShieldOpacity = isDark
        ? MAPBOX_NEUTRAL_ROAD_SHIELD_OPACITY_DARK
        : MAPBOX_NEUTRAL_ROAD_SHIELD_OPACITY_LIGHT;
      const parkFillColor = isDark
        ? MAPBOX_NEUTRAL_PARK_FILL_DARK
        : MAPBOX_NEUTRAL_PARK_FILL_LIGHT;
      const parkOutlineColor = isDark
        ? MAPBOX_NEUTRAL_PARK_OUTLINE_DARK
        : MAPBOX_NEUTRAL_PARK_OUTLINE_LIGHT;
      const parkFillOpacity = isDark
        ? MAPBOX_NEUTRAL_PARK_FILL_OPACITY_DARK
        : MAPBOX_NEUTRAL_PARK_FILL_OPACITY_LIGHT;
      const parkLineOpacity = isDark
        ? MAPBOX_NEUTRAL_PARK_LINE_OPACITY_DARK
        : MAPBOX_NEUTRAL_PARK_LINE_OPACITY_LIGHT;

      layers.forEach((layer) => {
        const layerId = layer.id;
        const id = String(layerId).toLowerCase();

        if (this.isMapboxRoadLayer(layer)) {
          const isOutlineLayer =
            id.includes("case") ||
            id.includes("casing") ||
            id.includes("outline") ||
            id.includes("border");
          const neutralColor = isOutlineLayer ? roadOutlineColor : roadColor;
          const neutralOpacity = isOutlineLayer
            ? roadOutlineOpacity
            : roadOpacity;

          try {
            this.$map.setPaintProperty(layerId, "line-color", neutralColor);
            this.$map.setPaintProperty(layerId, "line-opacity", neutralOpacity);
          } catch (error) {
            // Some imported Mapbox Standard layers may not allow this paint update.
          }

          return;
        }

        if (this.isMapboxRoadSymbolLayer(layer)) {
          const isShieldLayer =
            id.includes("shield") ||
            id.includes("number") ||
            id.includes("route");

          try {
            this.$map.setPaintProperty(layerId, "text-color", roadLabelColor);
            this.$map.setPaintProperty(
              layerId,
              "text-halo-color",
              isDark ? "#20272b" : "#f7f7f4",
            );
            this.$map.setPaintProperty(
              layerId,
              "text-opacity",
              isShieldLayer ? 0.5 : roadLabelOpacity,
            );
            this.$map.setPaintProperty(
              layerId,
              "icon-opacity",
              isShieldLayer ? roadShieldOpacity : 0.45,
            );
          } catch (error) {
            // Some imported Mapbox Standard layers may not allow this paint update.
          }

          return;
        }

        if (this.isMapboxGreenAreaLayer(layer)) {
          try {
            if (layer.type === "fill") {
              this.$map.setPaintProperty(layerId, "fill-color", parkFillColor);
              this.$map.setPaintProperty(
                layerId,
                "fill-outline-color",
                parkOutlineColor,
              );
              this.$map.setPaintProperty(
                layerId,
                "fill-opacity",
                parkFillOpacity,
              );
            } else if (layer.type === "line") {
              this.$map.setPaintProperty(
                layerId,
                "line-color",
                parkOutlineColor,
              );
              this.$map.setPaintProperty(
                layerId,
                "line-opacity",
                parkLineOpacity,
              );
            }
          } catch (error) {
            // Some imported Mapbox Standard layers may not allow this paint update.
          }
        }
      });
    },

    unbindProjectLayerEvents() {
      if (!this.$map || !this.mapLayerEventsBound) return;

      const layerHandlers = [
        [PROJECT_FILL_LAYER_ID, "mouseenter", this.onProjectMouseEnter],
        [PROJECT_LINE_LAYER_ID, "mouseenter", this.onProjectMouseEnter],
        [PROJECT_FACILITY_LAYER_ID, "mouseenter", this.onProjectMouseEnter],
        [PROJECT_FILL_LAYER_ID, "mousemove", this.onProjectMouseMove],
        [PROJECT_LINE_LAYER_ID, "mousemove", this.onProjectMouseMove],
        [PROJECT_FACILITY_LAYER_ID, "mousemove", this.onProjectMouseMove],
        [PROJECT_FILL_LAYER_ID, "mouseleave", this.onProjectMouseLeave],
        [PROJECT_LINE_LAYER_ID, "mouseleave", this.onProjectMouseLeave],
        [PROJECT_FACILITY_LAYER_ID, "mouseleave", this.onProjectMouseLeave],
        [PROJECT_FILL_LAYER_ID, "click", this.onProjectClick],
        [PROJECT_LINE_LAYER_ID, "click", this.onProjectClick],
        [PROJECT_FACILITY_LAYER_ID, "click", this.onProjectClick],
      ];

      layerHandlers.forEach(([layerId, eventName, handler]) => {
        try {
          this.$map.off(eventName, layerId, handler);
        } catch (error) {
          // The old style may have already removed the layer. That is fine.
        }
      });

      this.mapLayerEventsBound = false;
    },

    async handleMapStyleLoad() {
      if (this.suspendMapStyleRestoration) return;
      this.configureMapboxScrollZoomSensitivity();
      this.unbindProjectLayerEvents();
      await this.restoreMapOverlaysAfterStyleChange();
    },

    shouldShowThreeParkLayer() {
      return this.isStandaloneThreeMode;
    },

    getSelectedProjectCenter() {
      if (this.activeViewMode !== "project" || !this.currentProjectId) {
        return null;
      }

      const projectItem = this.getProjectItemById(this.currentProjectId);
      const savedCenter = this.getLngLatFromCenterValue(projectItem?.center);

      if (
        Array.isArray(savedCenter) &&
        savedCenter.length >= 2 &&
        savedCenter.every((value) => Number.isFinite(Number(value)))
      ) {
        return [Number(savedCenter[0]), Number(savedCenter[1])];
      }

      const projectFeatures = this.getProjectFeaturesForId(
        this.currentProjectId,
      );
      const bounds = this.getLngLatBoundsFromFeatures(projectFeatures);
      if (!bounds) return null;

      return [
        (Number(bounds.minLng) + Number(bounds.maxLng)) / 2,
        (Number(bounds.minLat) + Number(bounds.maxLat)) / 2,
      ];
    },

    normalizeTerrainRing(ring = []) {
      const normalized = (Array.isArray(ring) ? ring : [])
        .map((coordinate) => [
          Number(coordinate && coordinate[0]),
          Number(coordinate && coordinate[1]),
        ])
        .filter((coordinate) => coordinate.every(Number.isFinite));

      if (normalized.length > 1) {
        const first = normalized[0];
        const last = normalized[normalized.length - 1];
        if (
          Math.abs(first[0] - last[0]) < 1e-10 &&
          Math.abs(first[1] - last[1]) < 1e-10
        ) {
          normalized.pop();
        }
      }

      return normalized;
    },

    getProjectTerrainPolygonParts() {
      if (!this.currentProjectId) return [];

      const parts = [];
      const features = this.getProjectFeaturesForId(this.currentProjectId);

      const addPolygon = (polygonCoordinates) => {
        if (!Array.isArray(polygonCoordinates) || !polygonCoordinates.length) {
          return;
        }

        const outer = this.normalizeTerrainRing(polygonCoordinates[0]);
        if (outer.length < 3) return;

        const holes = polygonCoordinates
          .slice(1)
          .map((ring) => this.normalizeTerrainRing(ring))
          .filter((ring) => ring.length >= 3);

        parts.push({ outer, holes });
      };

      features.forEach((feature) => {
        const geometry = feature && feature.geometry;
        if (!geometry) return;

        if (geometry.type === "Polygon") {
          addPolygon(geometry.coordinates);
        } else if (geometry.type === "MultiPolygon") {
          geometry.coordinates.forEach(addPolygon);
        }
      });

      return parts;
    },

    getTerrainPartsBounds(parts = []) {
      const bounds = {
        minLng: Infinity,
        minLat: Infinity,
        maxLng: -Infinity,
        maxLat: -Infinity,
      };
      let hasCoordinates = false;

      parts.forEach((part) => {
        [part.outer, ...(part.holes || [])].forEach((ring) => {
          ring.forEach((coordinate) => {
            const lng = Number(coordinate[0]);
            const lat = Number(coordinate[1]);
            if (!Number.isFinite(lng) || !Number.isFinite(lat)) return;
            bounds.minLng = Math.min(bounds.minLng, lng);
            bounds.minLat = Math.min(bounds.minLat, lat);
            bounds.maxLng = Math.max(bounds.maxLng, lng);
            bounds.maxLat = Math.max(bounds.maxLat, lat);
            hasCoordinates = true;
          });
        });
      });

      return hasCoordinates ? bounds : null;
    },

    getTerrainOrigin(bounds) {
      if (!bounds) return null;
      return [
        (Number(bounds.minLng) + Number(bounds.maxLng)) / 2,
        (Number(bounds.minLat) + Number(bounds.maxLat)) / 2,
      ];
    },

    lngLatToTerrainMeters(coordinate, origin) {
      const lng = Number(coordinate[0]);
      const lat = Number(coordinate[1]);
      const originLng = Number(origin[0]);
      const originLat = Number(origin[1]);
      const latitudeScale = 111320;
      const longitudeScale =
        latitudeScale * Math.max(0.15, Math.cos((originLat * Math.PI) / 180));

      return {
        x: (lng - originLng) * longitudeScale,
        z: -(lat - originLat) * latitudeScale,
      };
    },

    terrainMetersToLngLat(point, origin) {
      const originLng = Number(origin[0]);
      const originLat = Number(origin[1]);
      const latitudeScale = 111320;
      const longitudeScale =
        latitudeScale * Math.max(0.15, Math.cos((originLat * Math.PI) / 180));

      return [
        originLng + Number(point.x) / longitudeScale,
        originLat - Number(point.z) / latitudeScale,
      ];
    },

    /**
     * Recover the CAD-coordinate -> standalone Three.js local-coordinate affine
     * transform from the enhanced GeoJSON itself.
     *
     * Munisiyah's LandXML stores Civil 3D northing/easting values, while the GIS
     * layers are WGS84 longitude/latitude. The old Terrain (after) loader simply
     * centered the LandXML on its own bounding-box center, which discarded its
     * real geographic offset and made the GIS appear shifted on the TIN.
     *
     * The enhanced CAD GeoJSON preserves both representations:
     *   - geometry coordinates in WGS84
     *   - cad_start_x/y, cad_end_x/y or cad_position_x/y in Civil 3D coordinates
     *
     * Fitting those pairs gives us an exact project-specific affine transform
     * without hard-coding a UTM zone or manually moving the GeoJSON.
     */
    getStandaloneLandXmlCadAlignment(
      origin,
      geojson = this.threeProjectGisData,
    ) {
      if (
        !Array.isArray(origin) ||
        origin.length < 2 ||
        !geojson ||
        !Array.isArray(geojson.features)
      ) {
        return null;
      }

      const pairs = [];
      const addPair = (eastingValue, northingValue, coordinate) => {
        const easting = Number(eastingValue);
        const northing = Number(northingValue);
        if (
          !Number.isFinite(easting) ||
          !Number.isFinite(northing) ||
          !Array.isArray(coordinate) ||
          coordinate.length < 2 ||
          !Number.isFinite(Number(coordinate[0])) ||
          !Number.isFinite(Number(coordinate[1]))
        ) {
          return;
        }

        const local = this.lngLatToTerrainMeters(coordinate, origin);
        if (
          !local ||
          !Number.isFinite(Number(local.x)) ||
          !Number.isFinite(Number(local.z))
        ) {
          return;
        }

        pairs.push({
          easting,
          northing,
          x: Number(local.x),
          z: Number(local.z),
        });
      };

      geojson.features.forEach((feature) => {
        const geometry = feature && feature.geometry;
        const properties = (feature && feature.properties) || {};
        if (!geometry) return;

        if (
          geometry.type === "LineString" &&
          Array.isArray(geometry.coordinates) &&
          geometry.coordinates.length >= 2
        ) {
          const first = geometry.coordinates[0];
          const last = geometry.coordinates[geometry.coordinates.length - 1];

          addPair(properties.cad_start_x, properties.cad_start_y, first);
          addPair(properties.cad_end_x, properties.cad_end_y, last);
          return;
        }

        if (geometry.type === "Point" && Array.isArray(geometry.coordinates)) {
          if (
            Number.isFinite(Number(properties.cad_position_x)) &&
            Number.isFinite(Number(properties.cad_position_y))
          ) {
            addPair(
              properties.cad_position_x,
              properties.cad_position_y,
              geometry.coordinates,
            );
          } else {
            addPair(
              properties.cad_center_x,
              properties.cad_center_y,
              geometry.coordinates,
            );
          }
        }
      });

      if (pairs.length < 6) return null;

      let meanEasting = 0;
      let meanNorthing = 0;
      let meanX = 0;
      let meanZ = 0;
      pairs.forEach((pair) => {
        meanEasting += pair.easting;
        meanNorthing += pair.northing;
        meanX += pair.x;
        meanZ += pair.z;
      });
      meanEasting /= pairs.length;
      meanNorthing /= pairs.length;
      meanX /= pairs.length;
      meanZ /= pairs.length;

      let sumEE = 0;
      let sumEN = 0;
      let sumNN = 0;
      let sumEX = 0;
      let sumNX = 0;
      let sumEZ = 0;
      let sumNZ = 0;

      pairs.forEach((pair) => {
        const de = pair.easting - meanEasting;
        const dn = pair.northing - meanNorthing;
        const dx = pair.x - meanX;
        const dz = pair.z - meanZ;

        sumEE += de * de;
        sumEN += de * dn;
        sumNN += dn * dn;
        sumEX += de * dx;
        sumNX += dn * dx;
        sumEZ += de * dz;
        sumNZ += dn * dz;
      });

      const determinant = sumEE * sumNN - sumEN * sumEN;
      if (!Number.isFinite(determinant) || Math.abs(determinant) < 1e-6) {
        return null;
      }

      const xFromEasting = (sumEX * sumNN - sumNX * sumEN) / determinant;
      const xFromNorthing = (sumNX * sumEE - sumEX * sumEN) / determinant;
      const zFromEasting = (sumEZ * sumNN - sumNZ * sumEN) / determinant;
      const zFromNorthing = (sumNZ * sumEE - sumEZ * sumEN) / determinant;

      const eastingScale = Math.hypot(xFromEasting, zFromEasting);
      const northingScale = Math.hypot(xFromNorthing, zFromNorthing);
      if (
        !Number.isFinite(eastingScale) ||
        !Number.isFinite(northingScale) ||
        eastingScale < 0.8 ||
        eastingScale > 1.2 ||
        northingScale < 0.8 ||
        northingScale > 1.2
      ) {
        return null;
      }

      let squaredError = 0;
      pairs.forEach((pair) => {
        const de = pair.easting - meanEasting;
        const dn = pair.northing - meanNorthing;
        const predictedX = meanX + xFromEasting * de + xFromNorthing * dn;
        const predictedZ = meanZ + zFromEasting * de + zFromNorthing * dn;
        const errorX = predictedX - pair.x;
        const errorZ = predictedZ - pair.z;
        squaredError += errorX * errorX + errorZ * errorZ;
      });

      const rmsError = Math.sqrt(squaredError / pairs.length);
      // A project-specific transform should normally be sub-metre. If an older
      // GeoJSON lacks matching CAD metadata, reject a poor fit and keep the
      // legacy centered-TIN fallback rather than applying a bad offset.
      if (!Number.isFinite(rmsError) || rmsError > 2.5) return null;

      return {
        sampleCount: pairs.length,
        rmsError,
        meanEasting,
        meanNorthing,
        meanX,
        meanZ,
        xFromEasting,
        xFromNorthing,
        zFromEasting,
        zFromNorthing,
      };
    },

    transformStandaloneLandXmlCadPoint(eastingValue, northingValue, alignment) {
      if (!alignment) return null;

      const easting = Number(eastingValue);
      const northing = Number(northingValue);
      if (!Number.isFinite(easting) || !Number.isFinite(northing)) {
        return null;
      }

      const de = easting - Number(alignment.meanEasting);
      const dn = northing - Number(alignment.meanNorthing);
      return {
        x:
          Number(alignment.meanX) +
          Number(alignment.xFromEasting) * de +
          Number(alignment.xFromNorthing) * dn,
        z:
          Number(alignment.meanZ) +
          Number(alignment.zFromEasting) * de +
          Number(alignment.zFromNorthing) * dn,
      };
    },

    getTerrainPointKey(point) {
      return `${Number(point.x).toFixed(3)}|${Number(point.z).toFixed(3)}`;
    },

    getTerrainSubdivisionLevel(faceCount, maxDimension) {
      const safeFaceCount = Math.max(1, Number(faceCount) || 1);
      const byTriangleBudget = Math.floor(
        Math.sqrt(THREE_PARK_MAX_TRIANGLES / safeFaceCount),
      );
      const byPhysicalSize = Math.ceil(
        Math.max(1, Number(maxDimension) || 1) / 35,
      );

      return Math.max(
        THREE_PARK_MIN_SUBDIVISIONS,
        Math.min(THREE_PARK_MAX_SUBDIVISIONS, byTriangleBudget, byPhysicalSize),
      );
    },

    densifyTerrainRing(ring = [], maximumSegmentLength = 24) {
      if (!Array.isArray(ring) || ring.length < 2) return ring || [];

      const safeSegmentLength = Math.max(1, Number(maximumSegmentLength) || 24);
      const denseRing = [];

      for (let index = 0; index < ring.length; index += 1) {
        const current = ring[index];
        const next = ring[(index + 1) % ring.length];
        const dx = Number(next.x) - Number(current.x);
        const dz = Number(next.z) - Number(current.z);
        const distance = Math.sqrt(dx * dx + dz * dz);
        const steps = Math.max(1, Math.ceil(distance / safeSegmentLength));

        for (let step = 0; step < steps; step += 1) {
          const t = step / steps;
          denseRing.push({
            x: Number(current.x) + dx * t,
            z: Number(current.z) + dz * t,
          });
        }
      }

      return denseRing;
    },

    getStandaloneSatelliteTextureDimensions(bounds) {
      const centerLatitude =
        (Number(bounds.minLat) + Number(bounds.maxLat)) / 2;
      const widthMeters =
        (Number(bounds.maxLng) - Number(bounds.minLng)) *
        111320 *
        Math.max(0.15, Math.cos((centerLatitude * Math.PI) / 180));
      const heightMeters =
        (Number(bounds.maxLat) - Number(bounds.minLat)) * 111320;
      const safeWidth = Math.max(1, widthMeters);
      const safeHeight = Math.max(1, heightMeters);
      const maximum = THREE_PARK_STATIC_TEXTURE_MAX_DIMENSION;
      const minimum = THREE_PARK_STATIC_TEXTURE_MIN_DIMENSION;

      if (safeWidth >= safeHeight) {
        return {
          width: maximum,
          height: Math.max(
            minimum,
            Math.min(maximum, Math.round(maximum * (safeHeight / safeWidth))),
          ),
        };
      }

      return {
        width: Math.max(
          minimum,
          Math.min(maximum, Math.round(maximum * (safeWidth / safeHeight))),
        ),
        height: maximum,
      };
    },

    getMapboxSatelliteTextureUrl(bounds) {
      if (!bounds || !isMapboxTokenConfigured(MAPBOX_ACCESS_TOKEN)) return "";

      const dimensions = this.getStandaloneSatelliteTextureDimensions(bounds);
      const bbox = [
        Number(bounds.minLng).toFixed(6),
        Number(bounds.minLat).toFixed(6),
        Number(bounds.maxLng).toFixed(6),
        Number(bounds.maxLat).toFixed(6),
      ].join(",");

      // The Static Images API currently does not support Mapbox Standard
      // Satellite, so use the raster-only satellite-v9 style for the terrain
      // color texture. The interactive Satellite button still uses Standard
      // Satellite with 3D buildings and terrain.
      return (
        `https://api.mapbox.com/styles/v1/mapbox/satellite-v9/static/` +
        `[${bbox}]/${dimensions.width}x${dimensions.height}@2x` +
        `?logo=false&attribution=false&padding=0` +
        `&access_token=${encodeURIComponent(MAPBOX_ACCESS_TOKEN)}`
      );
    },

    loadStandaloneSatelliteTexture(bounds) {
      const url = this.getMapboxSatelliteTextureUrl(bounds);
      if (!url) return Promise.resolve(null);

      return new Promise((resolve) => {
        const loader = new THREE.TextureLoader();
        if (typeof loader.setCrossOrigin === "function") {
          loader.setCrossOrigin("anonymous");
        }

        let settled = false;
        let timer = null;
        const finish = (texture) => {
          if (settled) {
            if (texture && texture.dispose) texture.dispose();
            return;
          }
          settled = true;
          window.clearTimeout(timer);
          resolve(texture || null);
        };

        timer = window.setTimeout(() => {
          console.warn(
            "The Mapbox satellite texture timed out; using the dark terrain fallback.",
          );
          finish(null);
        }, THREE_PARK_STATIC_TEXTURE_TIMEOUT_MS);

        loader.load(
          url,
          (texture) => {
            texture.wrapS = THREE.ClampToEdgeWrapping;
            texture.wrapT = THREE.ClampToEdgeWrapping;
            texture.magFilter = THREE.LinearFilter;
            texture.minFilter = THREE.LinearMipmapLinearFilter;
            texture.generateMipmaps = true;
            if (THREE.SRGBColorSpace && "colorSpace" in texture) {
              texture.colorSpace = THREE.SRGBColorSpace;
            } else if (THREE.sRGBEncoding) {
              texture.encoding = THREE.sRGBEncoding;
            }
            texture.needsUpdate = true;
            finish(texture);
          },
          undefined,
          (error) => {
            console.warn(
              "The Mapbox satellite texture could not be loaded; using the dark terrain fallback.",
              error,
            );
            finish(null);
          },
        );
      });
    },

    loadStandaloneCompactedGroundTexture() {
      return new Promise((resolve) => {
        const loader = new THREE.TextureLoader();
        let settled = false;
        let timer = null;

        const finish = (texture) => {
          if (settled) {
            if (texture && texture.dispose) texture.dispose();
            return;
          }
          settled = true;
          window.clearTimeout(timer);
          resolve(texture || null);
        };

        timer = window.setTimeout(() => {
          console.warn(
            "The SEALED GROUND texture timed out. Check /public/images/sealed_ground.png.",
          );
          finish(null);
        }, THREE_PARK_STATIC_TEXTURE_TIMEOUT_MS);

        loader.load(
          THREE_PARK_COMPACTED_GROUND_TEXTURE_URL,
          (texture) => {
            // Repeat the material instead of stretching one photo across the
            // full park. The shader controls the repeat count from the terrain
            // size so the soil/stone scale stays believable.
            texture.wrapS = THREE.RepeatWrapping;
            texture.wrapT = THREE.RepeatWrapping;
            texture.magFilter = THREE.LinearFilter;
            texture.minFilter = THREE.LinearMipmapLinearFilter;
            texture.generateMipmaps = true;
            if (THREE.SRGBColorSpace && "colorSpace" in texture) {
              texture.colorSpace = THREE.SRGBColorSpace;
            } else if (THREE.sRGBEncoding) {
              texture.encoding = THREE.sRGBEncoding;
            }
            texture.needsUpdate = true;
            finish(texture);
          },
          undefined,
          (error) => {
            console.warn(
              "The SEALED GROUND texture could not be loaded. Check /public/images/sealed_ground.png.",
              error,
            );
            finish(null);
          },
        );
      });
    },

    createStandaloneFallbackTexture() {
      const pixel = new Uint8Array([2, 8, 11, 255]);
      const texture = new THREE.DataTexture(pixel, 1, 1, THREE.RGBAFormat);
      texture.needsUpdate = true;
      return texture;
    },

    getBarycentricTerrainPoint(a, b, c, u, v) {
      return {
        x: a.x + (b.x - a.x) * u + (c.x - a.x) * v,
        z: a.z + (b.z - a.z) * u + (c.z - a.z) * v,
      };
    },

    waitForMapEvent(eventName, timeout = THREE_PARK_IDLE_TIMEOUT_MS) {
      if (!this.$map) return Promise.resolve(false);

      return new Promise((resolve) => {
        let finished = false;
        const complete = (value) => {
          if (finished) return;
          finished = true;
          window.clearTimeout(timer);
          resolve(value);
        };
        const timer = window.setTimeout(() => complete(false), timeout);
        this.$map.once(eventName, () => complete(true));
      });
    },

    showMapboxRenderer() {
      const mapElement = this.$refs.map;
      if (mapElement) {
        mapElement.style.visibility = "visible";
        mapElement.style.pointerEvents = "auto";
      }
      if (this.$map && typeof this.$map.resize === "function") {
        this.$map.resize();
      }
    },

    async ensureTerrainSamplingReady(bounds) {
      if (!this.$map || !this.mapboxgl || !bounds) {
        throw new Error("The Mapbox terrain source is not available.");
      }

      this.showMapboxRenderer();

      if (this.mapboxRendererSuspended) {
        this.showMapboxRenderer();
        this.suspendMapStyleRestoration = false;
        this.mapboxRendererSuspended = false;
        const style = this.$map.getStyle && this.$map.getStyle();
        const styleName = String(
          (style && (style.name || style.sprite)) || "",
        ).toLowerCase();
        if (!styleName.includes("satellite")) {
          const styleLoaded = this.waitForMapEvent("style.load");
          this.$map.setStyle(MAPBOX_STYLE_SATELLITE);
          await styleLoaded;
        }
      }

      if (!this.$map.isStyleLoaded()) {
        await this.waitForMapEvent("style.load");
      }

      if (!this.$map.getSource(MAPBOX_TERRAIN_SOURCE_ID)) {
        this.$map.addSource(MAPBOX_TERRAIN_SOURCE_ID, {
          type: "raster-dem",
          url: "mapbox://mapbox.mapbox-terrain-dem-v1",
          tileSize: 512,
          maxzoom: 14,
        });
      }

      this.$map.setTerrain({
        source: MAPBOX_TERRAIN_SOURCE_ID,
        // Keep the hidden Mapbox sampler on the same terrain exaggeration as
        // Satellite. queryTerrainElevation(..., { exaggerated: false }) still
        // returns raw meters, but this prevents the sampler from leaving the
        // visible Satellite map in a flat/low-terrain state after 3D reset or
        // after switching back from the standalone Three.js view.
        exaggeration: MAPBOX_3D_TERRAIN_EXAGGERATION,
      });

      this.ensureStandaloneBuildingSource();
      this.addCustom3DBuildingsLayer();

      this.$map.fitBounds(
        [
          [Number(bounds.minLng), Number(bounds.minLat)],
          [Number(bounds.maxLng), Number(bounds.maxLat)],
        ],
        {
          padding: 56,
          duration: 0,
          maxZoom: THREE_PARK_BUILDING_QUERY_MAX_ZOOM,
          pitch: 0,
          bearing: 0,
        },
      );

      await this.waitForMapEvent("idle");
      await new Promise((resolve) =>
        window.setTimeout(resolve, THREE_PARK_BUILDING_TILE_SETTLE_MS),
      );
      await this.waitForStandaloneBuildingTiles();
    },

    waitForStandaloneBuildingTiles(timeout = THREE_PARK_IDLE_TIMEOUT_MS) {
      if (!this.$map) return Promise.resolve(false);

      return new Promise((resolve) => {
        let settled = false;
        let timer = null;

        const cleanup = () => {
          if (timer != null) window.clearTimeout(timer);
          try {
            this.$map.off("sourcedata", handleSourceData);
          } catch (error) {
            // The style/source may have been replaced while 3D was loading.
          }
        };

        const complete = (value) => {
          if (settled) return;
          settled = true;
          cleanup();
          resolve(value);
        };

        const isBuildingSourceLoaded = () => {
          try {
            return (
              this.$map.getSource(MAPBOX_3D_BUILDINGS_SOURCE_ID) &&
              typeof this.$map.isSourceLoaded === "function" &&
              this.$map.isSourceLoaded(MAPBOX_3D_BUILDINGS_SOURCE_ID)
            );
          } catch (error) {
            return false;
          }
        };

        const handleSourceData = (event) => {
          if (
            event &&
            event.sourceId &&
            event.sourceId !== MAPBOX_3D_BUILDINGS_SOURCE_ID
          ) {
            return;
          }

          if (isBuildingSourceLoaded()) complete(true);
        };

        if (isBuildingSourceLoaded()) {
          complete(true);
          return;
        }

        try {
          this.$map.on("sourcedata", handleSourceData);
        } catch (error) {
          complete(false);
          return;
        }

        timer = window.setTimeout(() => complete(false), timeout);
      });
    },

    queryStandaloneTerrainElevation(lngLat) {
      if (!this.$map || typeof this.$map.queryTerrainElevation !== "function") {
        return null;
      }

      try {
        const elevation = this.$map.queryTerrainElevation(
          {
            lng: Number(lngLat[0]),
            lat: Number(lngLat[1]),
          },
          {
            exaggerated: false,
          },
        );

        return Number.isFinite(Number(elevation)) ? Number(elevation) : null;
      } catch (error) {
        return null;
      }
    },

    getStandaloneProjectLandscapeUrls(projectItem = null) {
      const item =
        projectItem ||
        (this.currentProjectId
          ? this.getProjectItemById(this.currentProjectId)
          : null);

      if (!item || !item.landscape) return [];

      const values = Array.isArray(item.landscape)
        ? item.landscape
        : [item.landscape];

      return values.map((value) => String(value || "").trim()).filter(Boolean);
    },

    getStandaloneProjectLandscapeUrl(projectItem = null) {
      // Backward-compatible helper for code that only needs to know whether
      // landscape data exists. Multi-zone projects are represented by the
      // first URL here; terrain loading itself uses the complete URL array.
      return this.getStandaloneProjectLandscapeUrls(projectItem)[0] || "";
    },

    hasStandaloneProjectLandscapeData() {
      const afterData =
        this.threeParkModelData && this.threeParkModelData.terrainAfterData;

      // Once the 3D scene has been built, trust the actual LandXML load result.
      // This also covers a non-empty landscape column whose XML failed to load.
      if (
        afterData &&
        Object.prototype.hasOwnProperty.call(afterData, "hasLandscapeData")
      ) {
        return Boolean(afterData.hasLandscapeData);
      }

      return Boolean(this.getStandaloneProjectLandscapeUrl());
    },

    getStandaloneMissingLandscapeMessage(layerKey = "") {
      const normalizedKey = String(layerKey || "").trim();

      if (normalizedKey === "terrainAfter") {
        return this.mapUiText(
          "TERRAIN (After) has no ground surface because this project does not have landscape data.",
          "لا يحتوي التضاريس (بعد) على سطح أرضي لأن هذا المشروع لا يحتوي على بيانات اللاندسكيب.",
          "TERRAIN (After) has no ground surface because this project does not have landscape data.",
        );
      }

      return this.mapUiText(
        "This layer cannot be rendered because this project does not have landscape data.",
        "لا يمكن عرض هذه الطبقة لأن هذا المشروع لا يحتوي على بيانات اللاندسكيب.",
        "This layer cannot be rendered because this project does not have landscape data.",
      );
    },

    async loadStandaloneLandXmlText(url) {
      const response = await fetch(url, {
        cache: "default",
        signal: this.getStandaloneThreeLoadSignal(),
      });
      if (!response.ok) {
        throw new Error(
          `Unable to load LandXML terrain (${response.status} ${response.statusText}).`,
        );
      }

      return response.text();
    },

    getStandaloneLandXmlAttribute(attributeText, attributeName) {
      const source = String(attributeText || "");
      const name = String(attributeName || "").replace(
        /[.*+?^${}()|[\]\\]/g,
        "\\$&",
      );
      if (!name) return "";
      const match = source.match(
        new RegExp(
          `(?:^|\\s)(?:[A-Za-z_][\\w.-]*:)?${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)')`,
          "i",
        ),
      );
      return match ? String(match[1] ?? match[2] ?? "").trim() : "";
    },

    async parseStandaloneLandXmlSurfaces(
      xmlText,
      fileIndex,
      globalPointOffset,
      buildToken,
    ) {
      const source = String(xmlText || "");
      if (!/\S/.test(source)) {
        throw new Error("The project's landscape file is empty.");
      }

      const surfaces = [];
      let nextGlobalPointIndex = Math.max(
        0,
        Math.floor(Number(globalPointOffset) || 0),
      );
      let parsedElementCount = 0;
      const assertBuildActive = async () => {
        if (!(await this.yieldStandaloneThreeBuildFrame(buildToken))) {
          throw new Error("The 3D terrain build was cancelled.");
        }
      };

      const parseSurface = async (
        surfaceBody,
        surfaceAttributes,
        surfaceIndex,
      ) => {
        const pointIndexBySourceId = new Map();
        const pointCoordinates = [];
        const pointPattern =
          /<(?:[A-Za-z_][\w.-]*:)?P\b([^>]*)>([\s\S]*?)<\/(?:[A-Za-z_][\w.-]*:)?P\s*>/gi;
        let pointMatch;

        while ((pointMatch = pointPattern.exec(surfaceBody))) {
          const sourceId = this.getStandaloneLandXmlAttribute(
            pointMatch[1],
            "id",
          );
          const values = String(pointMatch[2] || "")
            .trim()
            .split(/\s+/);
          const northing = Number(values[0]);
          const easting = Number(values[1]);
          const elevation = Number(values[2]);
          if (
            sourceId &&
            Number.isFinite(northing) &&
            Number.isFinite(easting) &&
            Number.isFinite(elevation)
          ) {
            const terrainIndex =
              nextGlobalPointIndex + Math.floor(pointCoordinates.length / 3);
            pointIndexBySourceId.set(sourceId, terrainIndex);
            pointCoordinates.push(northing, easting, elevation);
          }

          parsedElementCount += 1;
          if (parsedElementCount % 4000 === 0) {
            await assertBuildActive();
          }
        }

        if (!pointCoordinates.length) return;

        // Keep face topology as flat integers from the beginning. The previous
        // DOM path retained three large namespaced strings and one JS array per
        // TIN face until the GPU index buffer was created.
        const faceIndices = [];
        const facePattern =
          /<(?:[A-Za-z_][\w.-]*:)?F\b[^>]*>([\s\S]*?)<\/(?:[A-Za-z_][\w.-]*:)?F\s*>/gi;
        let faceMatch;
        while ((faceMatch = facePattern.exec(surfaceBody))) {
          const values = String(faceMatch[1] || "")
            .trim()
            .split(/\s+/);
          const a = pointIndexBySourceId.get(values[0]);
          const b = pointIndexBySourceId.get(values[1]);
          const c = pointIndexBySourceId.get(values[2]);
          if (
            Number.isInteger(a) &&
            Number.isInteger(b) &&
            Number.isInteger(c)
          ) {
            faceIndices.push(a, b, c);
          }

          parsedElementCount += 1;
          if (parsedElementCount % 4000 === 0) {
            await assertBuildActive();
          }
        }

        if (!faceIndices.length) return;
        const pointCount = Math.floor(pointCoordinates.length / 3);
        surfaces.push({
          fileIndex,
          surfaceIndex,
          surfaceName: this.getStandaloneLandXmlAttribute(
            surfaceAttributes,
            "name",
          ),
          pointCoordinates,
          faceIndices: new Uint32Array(faceIndices),
        });
        nextGlobalPointIndex += pointCount;
      };

      // Civil 3D can emit an optional namespace prefix on every LandXML tag.
      // Parse only the numeric P/F payloads needed by this renderer instead of
      // materialising a full DOM tree for a 20-40 MB survey file.
      const surfacePattern =
        /<(?:[A-Za-z_][\w.-]*:)?Surface\b([^>]*)>([\s\S]*?)<\/(?:[A-Za-z_][\w.-]*:)?Surface\s*>/gi;
      let surfaceMatch;
      let surfaceIndex = 0;
      while ((surfaceMatch = surfacePattern.exec(source))) {
        await parseSurface(surfaceMatch[2], surfaceMatch[1], surfaceIndex);
        surfaceIndex += 1;
        await assertBuildActive();
      }

      // Some minimal LandXML exporters omit the Surface wrapper. Preserve the
      // former whole-document fallback for those files.
      if (!surfaceIndex) {
        await parseSurface(source, "", 0);
      }

      if (!surfaces.length) {
        throw new Error("This file does not contain a usable TIN surface.");
      }
      return surfaces;
    },

    async buildLandXmlBoundaryLoops(
      pointById,
      faces,
      buildToken = null,
      terrainVertexRecords = [],
    ) {
      const edgeCounts = new Map();
      const pointsByTerrainIndex = Array.isArray(terrainVertexRecords)
        ? terrainVertexRecords
        : [];
      if (!pointsByTerrainIndex.length && pointById) {
        pointById.forEach((point) => {
          const index = Number(point && point.terrainIndex);
          if (Number.isInteger(index) && index >= 0) {
            pointsByTerrainIndex[index] = point;
          }
        });
      }
      const edgeKeyStride = Math.max(
        1,
        pointsByTerrainIndex.length + 1,
        Number(pointById && pointById.size) + 1 || 1,
      );
      const resolveTerrainIndex = (value) => {
        const directIndex = Number(value);
        if (
          Number.isInteger(directIndex) &&
          directIndex >= 0 &&
          directIndex < pointsByTerrainIndex.length
        ) {
          return directIndex;
        }
        const point =
          pointById && typeof pointById.get === "function"
            ? pointById.get(String(value))
            : null;
        return Number(point && point.terrainIndex);
      };
      const addEdge = (startId, endId) => {
        const startIndex = resolveTerrainIndex(startId);
        const endIndex = resolveTerrainIndex(endId);
        if (!Number.isInteger(startIndex) || !Number.isInteger(endIndex)) {
          return;
        }
        const a = Math.min(startIndex, endIndex);
        const b = Math.max(startIndex, endIndex);
        // A numeric pair key avoids retaining up to millions of large
        // "file:surface:id|file:surface:id" strings for survey-dense TINs.
        const key = a * edgeKeyStride + b;
        const existing = edgeCounts.get(key);
        if (existing) {
          existing.count += 1;
        } else {
          edgeCounts.set(key, { count: 1, a, b });
        }
      };

      const usesFlatFaceIndices =
        faces instanceof Uint32Array ||
        (Array.isArray(faces) &&
          (!faces.length || typeof faces[0] === "number"));
      const faceCount = usesFlatFaceIndices
        ? Math.floor(faces.length / 3)
        : faces.length;
      for (let faceIndex = 0; faceIndex < faceCount; faceIndex += 1) {
        if (faceIndex > 0 && faceIndex % 12000 === 0) {
          const shouldContinue =
            await this.yieldStandaloneThreeBuildFrame(buildToken);
          if (!shouldContinue) {
            throw new Error("The 3D terrain build was cancelled.");
          }
        }
        if (usesFlatFaceIndices) {
          const faceOffset = faceIndex * 3;
          const a = faces[faceOffset];
          const b = faces[faceOffset + 1];
          const c = faces[faceOffset + 2];
          addEdge(a, b);
          addEdge(b, c);
          addEdge(c, a);
        } else {
          const face = faces[faceIndex];
          addEdge(face[0], face[1]);
          addEdge(face[1], face[2]);
          addEdge(face[2], face[0]);
        }
      }

      const adjacency = new Map();
      const unusedEdges = new Set();
      let edgeRecordIndex = 0;
      for (const [key, edge] of edgeCounts.entries()) {
        if (edgeRecordIndex > 0 && edgeRecordIndex % 12000 === 0) {
          const shouldContinue =
            await this.yieldStandaloneThreeBuildFrame(buildToken);
          if (!shouldContinue) {
            throw new Error("The 3D terrain build was cancelled.");
          }
        }
        edgeRecordIndex += 1;
        if (edge.count !== 1) continue;
        unusedEdges.add(key);
        if (!adjacency.has(edge.a)) adjacency.set(edge.a, []);
        if (!adjacency.has(edge.b)) adjacency.set(edge.b, []);
        adjacency.get(edge.a).push(edge.b);
        adjacency.get(edge.b).push(edge.a);
      }

      const edgeKey = (a, b) =>
        Math.min(Number(a), Number(b)) * edgeKeyStride +
        Math.max(Number(a), Number(b));
      const loops = [];

      while (unusedEdges.size) {
        const firstKey = unusedEdges.values().next().value;
        const firstEdge = edgeCounts.get(firstKey);
        if (!firstEdge) {
          unusedEdges.delete(firstKey);
          continue;
        }
        const startId = firstEdge.a;
        const firstNextId = firstEdge.b;
        const loopIds = [startId];
        let previousId = startId;
        let currentId = firstNextId;
        unusedEdges.delete(firstKey);

        let guard = 0;
        while (guard < edgeCounts.size + 5) {
          guard += 1;
          loopIds.push(currentId);
          if (currentId === startId) break;

          const candidates = (adjacency.get(currentId) || []).filter((nextId) =>
            unusedEdges.has(edgeKey(currentId, nextId)),
          );
          if (!candidates.length) break;

          const nextId =
            candidates.find((candidate) => candidate !== previousId) ||
            candidates[0];
          unusedEdges.delete(edgeKey(currentId, nextId));
          previousId = currentId;
          currentId = nextId;
        }

        if (loopIds.length > 3 && loopIds[loopIds.length - 1] === startId) {
          loopIds.pop();
          const ring = loopIds
            .map((id) => pointsByTerrainIndex[Number(id)])
            .filter(Boolean)
            .map((point) => ({
              x: point.x,
              z: point.z,
              elevation: point.elevation,
              terrainIndex: point.terrainIndex,
            }));
          if (ring.length >= 3) loops.push(ring);
        }
      }

      return loops;
    },

    getTerrainRingSignedArea(ring = []) {
      let area = 0;
      for (let index = 0; index < ring.length; index += 1) {
        const current = ring[index];
        const next = ring[(index + 1) % ring.length];
        area += Number(current.x) * Number(next.z);
        area -= Number(next.x) * Number(current.z);
      }
      return area / 2;
    },

    async buildStandaloneTerrainDataFromLandXml(
      landscapeUrl,
      origin,
      bounds,
      buildToken,
    ) {
      const landscapeUrls = Array.isArray(landscapeUrl)
        ? landscapeUrl.filter(Boolean)
        : landscapeUrl
          ? [landscapeUrl]
          : [];
      if (!landscapeUrls.length) {
        throw new Error("No LandXML terrain files were provided.");
      }

      // Process every LandXML zone independently. A bad/missing zone must not
      // discard the valid terrain from the other zones. Raw coordinates remain
      // in one packed numeric array until they are aligned; face references are
      // compact Uint32 arrays from the moment each surface is parsed.
      const zoneFaceGroups = [];
      const loadedLandscapeUrls = [];
      const failedLandscapeZones = [];
      const sourceBounds = {
        minEasting: Infinity,
        maxEasting: -Infinity,
        minNorthing: Infinity,
        maxNorthing: -Infinity,
      };
      let totalPointCount = 0;
      let totalFaceCount = 0;

      for (
        let fileIndex = 0;
        fileIndex < landscapeUrls.length;
        fileIndex += 1
      ) {
        const zoneUrl = landscapeUrls[fileIndex];
        try {
          let xmlText = await this.loadStandaloneLandXmlText(zoneUrl);
          if (buildToken !== this.threeParkBuildToken) {
            throw new Error("The 3D terrain build was cancelled.");
          }

          const parsedSurfaces = await this.parseStandaloneLandXmlSurfaces(
            xmlText,
            fileIndex,
            totalPointCount,
            buildToken,
          );
          // The parser result contains no references to the XML source. Release
          // the large text before copying numeric data into the accumulated TIN.
          xmlText = "";
          const loadedSurfaceCount = parsedSurfaces.length;
          let filePointCount = 0;
          let fileFaceCount = 0;

          for (const parsedSurface of parsedSurfaces) {
            const surfacePoints = parsedSurface.pointCoordinates;
            const surfaceFaceIndices = parsedSurface.faceIndices;
            for (
              let coordinateOffset = 0;
              coordinateOffset + 2 < surfacePoints.length;
              coordinateOffset += 3
            ) {
              if (coordinateOffset > 0 && coordinateOffset % 36000 === 0) {
                const shouldContinue =
                  await this.yieldStandaloneThreeBuildFrame(buildToken);
                if (!shouldContinue) {
                  throw new Error("The 3D terrain build was cancelled.");
                }
              }
              const northing = Number(surfacePoints[coordinateOffset]);
              const easting = Number(surfacePoints[coordinateOffset + 1]);
              sourceBounds.minEasting = Math.min(
                sourceBounds.minEasting,
                easting,
              );
              sourceBounds.maxEasting = Math.max(
                sourceBounds.maxEasting,
                easting,
              );
              sourceBounds.minNorthing = Math.min(
                sourceBounds.minNorthing,
                northing,
              );
              sourceBounds.maxNorthing = Math.max(
                sourceBounds.maxNorthing,
                northing,
              );
            }
            zoneFaceGroups.push({
              fileIndex,
              surfaceIndex: parsedSurface.surfaceIndex,
              surfaceName: parsedSurface.surfaceName,
              zoneUrl,
              pointCoordinates: surfacePoints,
              faceIndices: surfaceFaceIndices,
            });
            const surfacePointCount = Math.floor(surfacePoints.length / 3);
            const surfaceFaceCount = Math.floor(surfaceFaceIndices.length / 3);
            filePointCount += surfacePointCount;
            fileFaceCount += surfaceFaceCount;
            totalPointCount += surfacePointCount;
            totalFaceCount += surfaceFaceCount;
          }

          // The zone groups now own the numeric point chunks and packed face
          // buffers. Drop the parser's wrapper array before fetching the next
          // file; each point chunk will be released progressively while it is
          // converted to aligned terrain records below.
          parsedSurfaces.length = 0;

          if (!loadedSurfaceCount) {
            throw new Error("This file does not contain a usable TIN surface.");
          }

          loadedLandscapeUrls.push(zoneUrl);
          console.info(
            `Loaded LandXML file ${fileIndex + 1}/${landscapeUrls.length}: ${zoneUrl} (${loadedSurfaceCount} surfaces, ${filePointCount} points, ${fileFaceCount} faces)`,
          );
        } catch (error) {
          // Cancellation is intentional and must still abort the whole build.
          if (buildToken !== this.threeParkBuildToken) throw error;

          const message =
            error && error.message ? error.message : String(error);
          failedLandscapeZones.push({
            fileIndex,
            zoneNumber: fileIndex + 1,
            url: zoneUrl,
            message,
          });
          console.warn(
            `Skipping LandXML zone ${fileIndex + 1}/${landscapeUrls.length}: ${zoneUrl}`,
            error,
          );
        }

        // Give the browser a rendering/GC opportunity before fetching the next
        // large XML zone. This keeps all files strictly sequential instead of
        // creating a sustained parse/allocation spike.
        await new Promise((resolve) => setTimeout(resolve, 16));
      }

      if (!totalPointCount || !totalFaceCount || !loadedLandscapeUrls.length) {
        const details = failedLandscapeZones
          .map((zone) => `Zone ${zone.zoneNumber}: ${zone.message}`)
          .join(" | ");
        throw new Error(
          details
            ? `None of the LandXML zones could be used. ${details}`
            : "The LandXML TIN vertices or faces are invalid.",
        );
      }

      const sourceCenterEasting =
        (sourceBounds.minEasting + sourceBounds.maxEasting) / 2;
      const sourceCenterNorthing =
        (sourceBounds.minNorthing + sourceBounds.maxNorthing) / 2;

      // Align the Civil 3D LandXML to the same geographic/local coordinate
      // frame used by the GeoJSON. Munisiyah's enhanced GeoJSON contains raw
      // CAD XY values beside WGS84 geometry, so use those matching pairs to fit
      // the transform. This fixes the ~park-scale horizontal offset that occurs
      // when the LandXML is centered independently of the GIS.
      const cadAlignment =
        this.threePrecomputedLandXmlCadAlignment ||
        this.getStandaloneLandXmlCadAlignment(origin);
      if (cadAlignment) {
        console.info("LandXML/GIS CAD alignment:", {
          samples: cadAlignment.sampleCount,
          rmsErrorMeters: Number(cadAlignment.rmsError.toFixed(4)),
        });
      }

      // LandXML vertices are shared by many TIN faces. Keep one point object per
      // Civil 3D vertex and let faces reference it with compact Uint32 indices.
      const terrainVertexRecords = [];
      const alignedLocalBounds = {
        minX: Infinity,
        maxX: -Infinity,
        minZ: Infinity,
        maxZ: -Infinity,
      };
      let minimumElevation = Infinity;
      let maximumElevation = -Infinity;

      let convertedPointCount = 0;
      for (const zoneGroup of zoneFaceGroups) {
        const pointCoordinates = zoneGroup.pointCoordinates;
        for (
          let rawOffset = 0;
          rawOffset + 2 < pointCoordinates.length;
          rawOffset += 3
        ) {
          if (convertedPointCount > 0 && convertedPointCount % 12000 === 0) {
            const shouldContinue =
              await this.yieldStandaloneThreeBuildFrame(buildToken);
            if (!shouldContinue) {
              throw new Error("The 3D terrain build was cancelled.");
            }
          }
          const northing = Number(pointCoordinates[rawOffset]);
          const easting = Number(pointCoordinates[rawOffset + 1]);
          const elevation = Number(pointCoordinates[rawOffset + 2]);
          const aligned = this.transformStandaloneLandXmlCadPoint(
            easting,
            northing,
            cadAlignment,
          );
          const point = {
            x: aligned ? aligned.x : easting - sourceCenterEasting,
            z: aligned ? aligned.z : -(northing - sourceCenterNorthing),
            elevation,
            terrainIndex: terrainVertexRecords.length,
          };
          terrainVertexRecords.push(point);
          convertedPointCount += 1;

          if (Number.isFinite(elevation)) {
            if (elevation < minimumElevation) minimumElevation = elevation;
            if (elevation > maximumElevation) maximumElevation = elevation;
          }

          alignedLocalBounds.minX = Math.min(alignedLocalBounds.minX, point.x);
          alignedLocalBounds.maxX = Math.max(alignedLocalBounds.maxX, point.x);
          alignedLocalBounds.minZ = Math.min(alignedLocalBounds.minZ, point.z);
          alignedLocalBounds.maxZ = Math.max(alignedLocalBounds.maxZ, point.z);
        }

        // The aligned record array now owns this chunk's coordinates. Remove
        // both references before converting the next surface so the browser can
        // reclaim raw survey memory incrementally instead of at the end.
        pointCoordinates.length = 0;
        zoneGroup.pointCoordinates = null;
      }

      // Keep the original TIN topology in a compact typed index buffer. KAP has
      // ~365k faces, so this stores ~1.1m references in ~4.4 MB. Geometry
      // remains exact while temporary per-face objects and strings are avoided.
      const baseTriangles = [];
      const triangleVertexIndices = new Uint32Array(totalFaceCount * 3);
      let triangleIndexOffset = 0;
      let processedFaceCount = 0;
      let correctedTerrainFaceWindingCount = 0;
      for (const zoneGroup of zoneFaceGroups) {
        const faceIndices = zoneGroup.faceIndices;
        for (
          let faceOffset = 0;
          faceOffset + 2 < faceIndices.length;
          faceOffset += 3
        ) {
          if (processedFaceCount > 0 && processedFaceCount % 12000 === 0) {
            const shouldContinue =
              await this.yieldStandaloneThreeBuildFrame(buildToken);
            if (!shouldContinue) {
              throw new Error("The 3D terrain build was cancelled.");
            }
          }
          processedFaceCount += 1;
          const indexA = Number(faceIndices[faceOffset]);
          const indexB = Number(faceIndices[faceOffset + 1]);
          const indexC = Number(faceIndices[faceOffset + 2]);
          const pointA = terrainVertexRecords[indexA];
          const pointB = terrainVertexRecords[indexB];
          const pointC = terrainVertexRecords[indexC];
          if (!pointA || !pointB || !pointC) {
            triangleVertexIndices[triangleIndexOffset++] = 0;
            triangleVertexIndices[triangleIndexOffset++] = 0;
            triangleVertexIndices[triangleIndexOffset++] = 0;
            continue;
          }

          // Civil 3D LandXML exports can contain a small number of TIN faces
          // with the opposite winding. Normalize the integer order only; the
          // surveyed XYZ coordinates and elevations remain untouched.
          const crossXZ =
            (Number(pointB.x) - Number(pointA.x)) *
              (Number(pointC.z) - Number(pointA.z)) -
            (Number(pointB.z) - Number(pointA.z)) *
              (Number(pointC.x) - Number(pointA.x));
          triangleVertexIndices[triangleIndexOffset++] = indexA;
          if (crossXZ > 0) {
            triangleVertexIndices[triangleIndexOffset++] = indexC;
            triangleVertexIndices[triangleIndexOffset++] = indexB;
            correctedTerrainFaceWindingCount += 1;
          } else {
            triangleVertexIndices[triangleIndexOffset++] = indexB;
            triangleVertexIndices[triangleIndexOffset++] = indexC;
          }
        }
      }
      if (correctedTerrainFaceWindingCount) {
        console.info("Normalized LandXML TIN face winding:", {
          correctedFaceCount: correctedTerrainFaceWindingCount,
          totalFaceCount,
        });
      }

      // Build a separate boundary part for every successfully loaded zone.
      // Treating Zones B/C/D as holes inside the largest Zone A loop would make
      // a multi-zone park render incorrectly even when all four files are valid.
      const localParts = [];
      for (
        let zoneGroupIndex = 0;
        zoneGroupIndex < zoneFaceGroups.length;
        zoneGroupIndex += 1
      ) {
        const zoneGroup = zoneFaceGroups[zoneGroupIndex];
        const boundaryLoops = await this.buildLandXmlBoundaryLoops(
          null,
          zoneGroup.faceIndices,
          buildToken,
          terrainVertexRecords,
        );
        zoneGroup.faceIndices = null;
        boundaryLoops.sort(
          (a, b) =>
            Math.abs(this.getTerrainRingSignedArea(b)) -
            Math.abs(this.getTerrainRingSignedArea(a)),
        );
        if (boundaryLoops.length) {
          localParts.push({
            outer: boundaryLoops[0],
            holes: boundaryLoops.slice(1),
          });
        }
      }

      if (!localParts.length) {
        localParts.push({
          outer: [
            {
              x: alignedLocalBounds.minX,
              z: alignedLocalBounds.maxZ,
            },
            {
              x: alignedLocalBounds.maxX,
              z: alignedLocalBounds.maxZ,
            },
            {
              x: alignedLocalBounds.maxX,
              z: alignedLocalBounds.minZ,
            },
            {
              x: alignedLocalBounds.minX,
              z: alignedLocalBounds.minZ,
            },
          ],
          holes: [],
        });
      }

      if (
        !Number.isFinite(minimumElevation) ||
        !Number.isFinite(maximumElevation)
      ) {
        throw new Error("The LandXML terrain elevations are invalid.");
      }

      const landXmlSurfaceCount = zoneFaceGroups.length;
      // Boundary extraction and the Uint32 topology buffer are complete.
      // Release per-zone parse topology before constructing WebGL buffers.
      zoneFaceGroups.length = 0;
      if (!(await this.yieldStandaloneThreeBuildFrame(buildToken))) {
        throw new Error("The 3D terrain build was cancelled.");
      }

      const rawElevationRange = Math.max(
        0,
        maximumElevation - minimumElevation,
      );
      const verticalExaggeration =
        rawElevationRange > 0.05
          ? Math.max(
              THREE_PARK_MIN_VERTICAL_EXAGGERATION,
              Math.min(
                THREE_PARK_MAX_VERTICAL_EXAGGERATION,
                MAPBOX_3D_TERRAIN_EXAGGERATION,
              ),
            )
          : 1;
      const maxDimension = Math.max(
        sourceBounds.maxEasting - sourceBounds.minEasting,
        sourceBounds.maxNorthing - sourceBounds.minNorthing,
        1,
      );
      const islandWallDepth = Math.max(
        THREE_PARK_MIN_ISLAND_WALL_DEPTH_METERS,
        Math.min(
          THREE_PARK_MAX_ISLAND_WALL_DEPTH_METERS,
          maxDimension * THREE_PARK_ISLAND_WALL_DEPTH_RATIO,
        ),
      );
      const boundarySampleSpacing = Math.max(
        THREE_PARK_MIN_BOUNDARY_SAMPLE_SPACING_METERS,
        Math.min(
          THREE_PARK_MAX_BOUNDARY_SAMPLE_SPACING_METERS,
          maxDimension / THREE_PARK_BOUNDARY_SAMPLE_DIVISIONS,
        ),
      );
      const gridSpacing = Math.max(
        THREE_PARK_MIN_GRID_SPACING,
        Math.min(
          THREE_PARK_MAX_GRID_SPACING,
          maxDimension / THREE_PARK_GRID_DIVISIONS,
        ),
      );
      const localBounds = {
        minX: alignedLocalBounds.minX,
        maxX: alignedLocalBounds.maxX,
        minZ: alignedLocalBounds.minZ,
        maxZ: alignedLocalBounds.maxZ,
      };

      await this.ensureStandaloneBuildingTilesForPark(
        bounds,
        origin,
        localParts,
      );
      const buildingFootprints = this.queryStandaloneBuildingFootprints(
        bounds,
        origin,
        localParts,
        terrainVertexRecords,
        minimumElevation,
        verticalExaggeration,
      );

      return {
        localParts,
        baseTriangles,
        triangleVertexKeys: [],
        triangleVertexIndices,
        terrainVertexRecords,
        // Indexed LandXML consumers use terrainVertexRecords directly. Avoid a
        // second Map containing a long coordinate string for every TIN vertex.
        pointMap: null,
        minimumElevation,
        maximumElevation,
        rawElevationRange,
        verticalExaggeration,
        visibleElevationRange: rawElevationRange * verticalExaggeration,
        maxDimension,
        islandWallDepth,
        boundarySampleSpacing,
        gridSpacing,
        localBounds,
        geographicBounds: { ...bounds },
        origin: origin.slice(),
        satelliteTexture: null,
        buildingFootprints,
        hasTerrainData: true,
        terrainSource: "landxml",
        cadAlignment: cadAlignment
          ? {
              sampleCount: cadAlignment.sampleCount,
              rmsError: cadAlignment.rmsError,
            }
          : null,
        landscapeUrl:
          loadedLandscapeUrls.length === 1
            ? loadedLandscapeUrls[0]
            : loadedLandscapeUrls,
        configuredLandscapeUrls: landscapeUrls.slice(),
        loadedLandscapeUrls: loadedLandscapeUrls.slice(),
        failedLandscapeZones: failedLandscapeZones.slice(),
        hasPartialLandscapeData: failedLandscapeZones.length > 0,
        // Preserve how many independent Civil 3D surfaces were loaded. Multi-surface
        // LandXML projects (for example KAP Zones A-D in one XML) use Terrain
        // (After) as the authoritative object-support surface. Single-surface
        // projects keep their legacy fallback behavior to avoid changing parks
        // that already render correctly.
        landXmlSurfaceCount,
      };
    },

    async buildStandaloneTerrainData(
      parts,
      origin,
      bounds,
      buildToken,
      useLandscape = true,
    ) {
      const landscapeUrls = useLandscape
        ? this.getStandaloneProjectLandscapeUrls()
        : [];
      if (landscapeUrls.length) {
        try {
          return await this.buildStandaloneTerrainDataFromLandXml(
            landscapeUrls,
            origin,
            bounds,
            buildToken,
          );
        } catch (error) {
          console.warn(
            "LandXML terrain could not be used; falling back to Mapbox terrain.",
            error,
          );
        }
      }

      const localParts = [];
      const baseTriangles = [];
      let faceCount = 0;

      parts.forEach((part) => {
        const outer = part.outer.map((coordinate) =>
          this.lngLatToTerrainMeters(coordinate, origin),
        );
        const holes = (part.holes || []).map((ring) =>
          ring.map((coordinate) =>
            this.lngLatToTerrainMeters(coordinate, origin),
          ),
        );

        let contour = outer.map((point) => new THREE.Vector2(point.x, point.z));
        const holeVectors = holes.map((ring) =>
          ring.map((point) => new THREE.Vector2(point.x, point.z)),
        );
        let faces = THREE.ShapeUtils.triangulateShape(contour, holeVectors);

        if (!faces.length) {
          contour = contour.slice().reverse();
          faces = THREE.ShapeUtils.triangulateShape(contour, holeVectors);
        }

        const flattened = contour.concat(...holeVectors);

        faces.forEach((face) => {
          const triangle = face.map((index) => ({
            x: flattened[index].x,
            z: flattened[index].y,
          }));
          if (triangle.length === 3) {
            baseTriangles.push(triangle);
            faceCount += 1;
          }
        });

        localParts.push({ outer, holes });
      });

      if (!baseTriangles.length) {
        throw new Error("The project geometry could not be triangulated.");
      }

      const widthMeters =
        (Number(bounds.maxLng) - Number(bounds.minLng)) *
        111320 *
        Math.max(
          0.15,
          Math.cos(
            (((Number(bounds.minLat) + Number(bounds.maxLat)) / 2) * Math.PI) /
              180,
          ),
        );
      const depthMeters =
        (Number(bounds.maxLat) - Number(bounds.minLat)) * 111320;
      const maxDimension = Math.max(widthMeters, depthMeters, 1);
      const subdivisions = this.getTerrainSubdivisionLevel(
        faceCount,
        maxDimension,
      );
      const boundarySampleSpacing = Math.max(
        THREE_PARK_MIN_BOUNDARY_SAMPLE_SPACING_METERS,
        Math.min(
          THREE_PARK_MAX_BOUNDARY_SAMPLE_SPACING_METERS,
          maxDimension / THREE_PARK_BOUNDARY_SAMPLE_DIVISIONS,
        ),
      );
      const sampledLocalParts = localParts.map((part) => ({
        outer: this.densifyTerrainRing(part.outer, boundarySampleSpacing),
        holes: (part.holes || []).map((ring) =>
          this.densifyTerrainRing(ring, boundarySampleSpacing),
        ),
      }));

      const uniquePoints = new Map();
      const triangleVertexKeys = [];

      const registerPoint = (point) => {
        const key = this.getTerrainPointKey(point);
        if (!uniquePoints.has(key)) {
          uniquePoints.set(key, {
            key,
            x: Number(point.x),
            z: Number(point.z),
            elevation: null,
          });
        }
        return key;
      };

      const pushTriangle = (a, b, c) => {
        triangleVertexKeys.push(
          registerPoint(a),
          registerPoint(b),
          registerPoint(c),
        );
      };

      baseTriangles.forEach(([a, b, c]) => {
        for (let row = 0; row < subdivisions; row += 1) {
          for (let column = 0; column < subdivisions - row; column += 1) {
            const u = row / subdivisions;
            const v = column / subdivisions;
            const nextU = (row + 1) / subdivisions;
            const nextV = (column + 1) / subdivisions;

            const p0 = this.getBarycentricTerrainPoint(a, b, c, u, v);
            const p1 = this.getBarycentricTerrainPoint(a, b, c, nextU, v);
            const p2 = this.getBarycentricTerrainPoint(a, b, c, u, nextV);

            pushTriangle(p0, p1, p2);

            if (column < subdivisions - row - 1) {
              const p3 = this.getBarycentricTerrainPoint(a, b, c, nextU, nextV);
              pushTriangle(p1, p3, p2);
            }
          }
        }
      });

      sampledLocalParts.forEach((part) => {
        [part.outer, ...(part.holes || [])].forEach((ring) => {
          ring.forEach(registerPoint);
        });
      });

      const points = Array.from(uniquePoints.values());
      const validElevations = [];

      for (let index = 0; index < points.length; index += 1) {
        if (buildToken !== this.threeParkBuildToken) {
          throw new Error("The 3D terrain build was cancelled.");
        }

        const point = points[index];
        const lngLat = this.terrainMetersToLngLat(point, origin);
        const elevation = this.queryStandaloneTerrainElevation(lngLat);
        point.elevation = elevation;

        if (Number.isFinite(Number(elevation))) {
          validElevations.push(Number(elevation));
        }

        if (index > 0 && index % 250 === 0) {
          await new Promise((resolve) => window.requestAnimationFrame(resolve));
        }
      }

      const fallbackElevation = validElevations.length
        ? validElevations.reduce((sum, value) => sum + value, 0) /
          validElevations.length
        : 0;

      points.forEach((point) => {
        if (!Number.isFinite(Number(point.elevation))) {
          point.elevation = fallbackElevation;
        }
      });

      const elevations = points.map((point) => Number(point.elevation));
      const minimumElevation = Math.min(...elevations);
      const maximumElevation = Math.max(...elevations);
      const rawElevationRange = Math.max(
        0,
        Number(maximumElevation) - Number(minimumElevation),
      );
      const verticalExaggeration =
        validElevations.length > 0 && rawElevationRange > 0.05
          ? Math.max(
              THREE_PARK_MIN_VERTICAL_EXAGGERATION,
              Math.min(
                THREE_PARK_MAX_VERTICAL_EXAGGERATION,
                MAPBOX_3D_TERRAIN_EXAGGERATION,
              ),
            )
          : 1;
      const islandWallDepth = Math.max(
        THREE_PARK_MIN_ISLAND_WALL_DEPTH_METERS,
        Math.min(
          THREE_PARK_MAX_ISLAND_WALL_DEPTH_METERS,
          maxDimension * THREE_PARK_ISLAND_WALL_DEPTH_RATIO,
        ),
      );
      const gridSpacing = Math.max(
        THREE_PARK_MIN_GRID_SPACING,
        Math.min(
          THREE_PARK_MAX_GRID_SPACING,
          maxDimension / THREE_PARK_GRID_DIVISIONS,
        ),
      );

      const pointXs = points.map((point) => Number(point.x));
      const pointZs = points.map((point) => Number(point.z));
      const localBounds = {
        minX: Math.min(...pointXs),
        maxX: Math.max(...pointXs),
        minZ: Math.min(...pointZs),
        maxZ: Math.max(...pointZs),
      };

      await this.ensureStandaloneBuildingTilesForPark(
        bounds,
        origin,
        sampledLocalParts,
      );

      const buildingFootprints = this.queryStandaloneBuildingFootprints(
        bounds,
        origin,
        sampledLocalParts,
        uniquePoints,
        minimumElevation,
        verticalExaggeration,
      );

      return {
        localParts: sampledLocalParts,
        baseTriangles,
        triangleVertexKeys,
        pointMap: uniquePoints,
        minimumElevation,
        maximumElevation,
        rawElevationRange,
        verticalExaggeration,
        visibleElevationRange: rawElevationRange * verticalExaggeration,
        maxDimension,
        islandWallDepth,
        boundarySampleSpacing,
        gridSpacing,
        localBounds,
        geographicBounds: { ...bounds },
        origin: origin.slice(),
        satelliteTexture: null,
        buildingFootprints,
        hasTerrainData: validElevations.length > 0,
        terrainSource: "mapbox",
        landscapeUrl: "",
      };
    },

    isTerrainPointInsideRing(point, ring = []) {
      if (!point || !Array.isArray(ring) || ring.length < 3) return false;

      let inside = false;
      const x = Number(point.x);
      const z = Number(point.z);

      for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
        const xi = Number(ring[i].x);
        const zi = Number(ring[i].z);
        const xj = Number(ring[j].x);
        const zj = Number(ring[j].z);
        const intersects =
          zi > z !== zj > z &&
          x < ((xj - xi) * (z - zi)) / Math.max(1e-9, zj - zi) + xi;
        if (intersects) inside = !inside;
      }

      return inside;
    },

    isTerrainPointInsidePart(point, part) {
      if (!part || !this.isTerrainPointInsideRing(point, part.outer)) {
        return false;
      }

      return !(part.holes || []).some((hole) =>
        this.isTerrainPointInsideRing(point, hole),
      );
    },

    isLngLatInsideTerrainParts(coordinate, origin, localParts = []) {
      if (!Array.isArray(coordinate) || coordinate.length < 2 || !origin) {
        return false;
      }

      const point = this.lngLatToTerrainMeters(coordinate, origin);
      return localParts.some((part) =>
        this.isTerrainPointInsidePart(point, part),
      );
    },

    isTerrainPointInsideAnyPart(point, localParts = []) {
      if (!point || !Array.isArray(localParts) || !localParts.length) {
        return false;
      }

      return localParts.some((part) =>
        this.isTerrainPointInsidePart(point, part),
      );
    },

    isTerrainPointSafelyInsideAnyPart(
      point,
      localParts = [],
      clearanceMeters = 0,
    ) {
      if (!this.isTerrainPointInsideAnyPart(point, localParts)) return false;

      const clearance = Math.max(0, Number(clearanceMeters) || 0);
      if (clearance <= 0.001) return true;

      // A point can technically be inside the project polygon while most of a
      // tree crown or pole base hangs beyond the clipped floating-island edge.
      // Require a small circular footprint around the object to remain inside.
      const samples = 12;
      for (let index = 0; index < samples; index += 1) {
        const angle = (index / samples) * Math.PI * 2;
        const sample = {
          x: Number(point.x) + Math.cos(angle) * clearance,
          z: Number(point.z) + Math.sin(angle) * clearance,
        };
        if (!this.isTerrainPointInsideAnyPart(sample, localParts)) {
          return false;
        }
      }

      return true;
    },

    getTerrainRingInsideRatio(localRing = [], localParts = []) {
      if (
        !Array.isArray(localRing) ||
        !localRing.length ||
        !Array.isArray(localParts) ||
        !localParts.length
      ) {
        return 0;
      }

      let tested = 0;
      let inside = 0;

      localRing.forEach((point) => {
        if (
          !point ||
          !Number.isFinite(Number(point.x)) ||
          !Number.isFinite(Number(point.z))
        ) {
          return;
        }

        tested += 1;
        if (this.isTerrainPointInsideAnyPart(point, localParts)) inside += 1;
      });

      return tested > 0 ? inside / tested : 0;
    },

    getTerrainSegmentOrientation(a, b, c) {
      return (
        (Number(b.z) - Number(a.z)) * (Number(c.x) - Number(b.x)) -
        (Number(b.x) - Number(a.x)) * (Number(c.z) - Number(b.z))
      );
    },

    isTerrainPointOnSegment(point, a, b, tolerance = 1e-6) {
      if (!point || !a || !b) return false;

      const cross =
        (Number(point.z) - Number(a.z)) * (Number(b.x) - Number(a.x)) -
        (Number(point.x) - Number(a.x)) * (Number(b.z) - Number(a.z));
      if (Math.abs(cross) > tolerance) return false;

      return (
        Number(point.x) <= Math.max(Number(a.x), Number(b.x)) + tolerance &&
        Number(point.x) >= Math.min(Number(a.x), Number(b.x)) - tolerance &&
        Number(point.z) <= Math.max(Number(a.z), Number(b.z)) + tolerance &&
        Number(point.z) >= Math.min(Number(a.z), Number(b.z)) - tolerance
      );
    },

    doTerrainSegmentsIntersect(a, b, c, d) {
      if (!a || !b || !c || !d) return false;

      const o1 = this.getTerrainSegmentOrientation(a, b, c);
      const o2 = this.getTerrainSegmentOrientation(a, b, d);
      const o3 = this.getTerrainSegmentOrientation(c, d, a);
      const o4 = this.getTerrainSegmentOrientation(c, d, b);
      const tolerance = 1e-6;

      if (Math.abs(o1) <= tolerance && this.isTerrainPointOnSegment(c, a, b))
        return true;
      if (Math.abs(o2) <= tolerance && this.isTerrainPointOnSegment(d, a, b))
        return true;
      if (Math.abs(o3) <= tolerance && this.isTerrainPointOnSegment(a, c, d))
        return true;
      if (Math.abs(o4) <= tolerance && this.isTerrainPointOnSegment(b, c, d))
        return true;

      return o1 > 0 !== o2 > 0 && o3 > 0 !== o4 > 0;
    },

    getTerrainRingEdges(ring = []) {
      const points = (Array.isArray(ring) ? ring : []).filter(
        (point) =>
          point &&
          Number.isFinite(Number(point.x)) &&
          Number.isFinite(Number(point.z)),
      );
      if (points.length < 2) return [];

      return points.map((point, index) => [
        point,
        points[(index + 1) % points.length],
      ]);
    },

    doTerrainRingsHaveIntersectingEdges(ringA = [], ringB = []) {
      const edgesA = this.getTerrainRingEdges(ringA);
      const edgesB = this.getTerrainRingEdges(ringB);
      if (!edgesA.length || !edgesB.length) return false;

      return edgesA.some(([a, b]) =>
        edgesB.some(([c, d]) => this.doTerrainSegmentsIntersect(a, b, c, d)),
      );
    },

    getStandaloneBuildingParkAnchor(
      localOuterRing = [],
      localCentroid,
      localParts = [],
    ) {
      if (
        !Array.isArray(localOuterRing) ||
        localOuterRing.length < 3 ||
        !Array.isArray(localParts) ||
        !localParts.length
      ) {
        return null;
      }

      if (
        localCentroid &&
        this.isTerrainPointInsideAnyPart(localCentroid, localParts)
      ) {
        return localCentroid;
      }

      const insideVertex = localOuterRing.find((point) =>
        this.isTerrainPointInsideAnyPart(point, localParts),
      );
      if (insideVertex) return insideVertex;

      const insideEdgeMidpoint = this.getTerrainRingEdges(localOuterRing)
        .map(([a, b]) => ({
          x: (Number(a.x) + Number(b.x)) / 2,
          z: (Number(a.z) + Number(b.z)) / 2,
        }))
        .find((point) => this.isTerrainPointInsideAnyPart(point, localParts));
      if (insideEdgeMidpoint) return insideEdgeMidpoint;

      const buildingRing = localOuterRing;
      for (const part of localParts) {
        const parkRings = [part.outer, ...(part.holes || [])];
        const parkVertexInsideBuilding = (part.outer || []).find((point) =>
          this.isTerrainPointInsideRing(point, buildingRing),
        );
        if (parkVertexInsideBuilding) return parkVertexInsideBuilding;

        const hasBoundaryIntersection = parkRings.some((ring) =>
          this.doTerrainRingsHaveIntersectingEdges(buildingRing, ring),
        );
        if (hasBoundaryIntersection) {
          for (const [buildingA, buildingB] of this.getTerrainRingEdges(
            buildingRing,
          )) {
            const midpoint = {
              x: (Number(buildingA.x) + Number(buildingB.x)) / 2,
              z: (Number(buildingA.z) + Number(buildingB.z)) / 2,
            };
            if (this.isTerrainPointInsideAnyPart(midpoint, localParts)) {
              return midpoint;
            }
          }
          if (
            localCentroid &&
            this.isTerrainPointInsideRing(localCentroid, part.outer)
          ) {
            return localCentroid;
          }
        }
      }

      return null;
    },

    doesStandaloneBuildingBelongToPark(
      localOuterRing = [],
      localCentroid,
      localParts = [],
    ) {
      if (!Array.isArray(localParts) || !localParts.length) return false;

      const centroidInside =
        localCentroid &&
        this.isTerrainPointInsideAnyPart(localCentroid, localParts);
      const insideRatio = this.getTerrainRingInsideRatio(
        localOuterRing,
        localParts,
      );
      const footprintFullyInside = (
        Array.isArray(localOuterRing) ? localOuterRing : []
      ).every((point) => this.isTerrainPointInsideAnyPart(point, localParts));

      // Final rule: 3D view must never show Mapbox buildings outside the park.
      // Therefore we only render buildings whose footprint is fully inside the
      // current project GIS polygon. If a Mapbox tile returns a clipped or
      // boundary-crossing footprint, skip it instead of shrinking/snapping it to
      // the island edge.
      return Boolean(
        centroidInside &&
        footprintFullyInside &&
        insideRatio >= THREE_PARK_BUILDING_MIN_INSIDE_RATIO,
      );
    },
    getLngLatOffsetCoordinate(coordinate, eastMeters = 0, northMeters = 0) {
      const lng = Number(coordinate && coordinate[0]);
      const lat = Number(coordinate && coordinate[1]);
      if (!Number.isFinite(lng) || !Number.isFinite(lat)) return null;

      const latitudeScale = 111320;
      const longitudeScale =
        latitudeScale * Math.max(0.15, Math.cos((lat * Math.PI) / 180));

      return [
        lng + Number(eastMeters || 0) / longitudeScale,
        lat + Number(northMeters || 0) / latitudeScale,
      ];
    },

    createPointBuildingFootprint(
      coordinate,
      sizeMeters = MAPBOX_BUILDING_POINT_FOOTPRINT_METERS,
    ) {
      const half =
        Math.max(
          3,
          Number(sizeMeters) || MAPBOX_BUILDING_POINT_FOOTPRINT_METERS,
        ) / 2;
      const corners = [
        this.getLngLatOffsetCoordinate(coordinate, -half, -half),
        this.getLngLatOffsetCoordinate(coordinate, half, -half),
        this.getLngLatOffsetCoordinate(coordinate, half, half),
        this.getLngLatOffsetCoordinate(coordinate, -half, half),
      ].filter(Boolean);

      return corners.length === 4 ? [[...corners, corners[0]]] : null;
    },

    getFeatureCoordinateRings(featureOrGeometry) {
      const geometry =
        featureOrGeometry && featureOrGeometry.geometry
          ? featureOrGeometry.geometry
          : featureOrGeometry;
      const properties =
        featureOrGeometry && featureOrGeometry.properties
          ? featureOrGeometry.properties
          : {};
      if (!geometry || !Array.isArray(geometry.coordinates)) return [];

      if (geometry.type === "Polygon") {
        return [geometry.coordinates];
      }

      if (geometry.type === "MultiPolygon") {
        return geometry.coordinates;
      }

      // Some Mapbox Standard 3D objects / landmarks can be returned as points
      // instead of polygon footprints. Satellite can still draw them as 3D
      // objects, so approximate them as small footprint boxes and then run the
      // same strict inside-park filter before adding them to the island.
      if (geometry.type === "Point") {
        const height = this.getBuildingHeightFromProperties(properties);
        const size = Math.max(
          8,
          Math.min(32, Math.sqrt(Math.max(16, height * 5))),
        );
        const footprint = this.createPointBuildingFootprint(
          geometry.coordinates,
          size,
        );
        return footprint ? [footprint] : [];
      }

      if (geometry.type === "MultiPoint") {
        return geometry.coordinates
          .map((coordinate) => {
            const footprint = this.createPointBuildingFootprint(coordinate);
            return footprint;
          })
          .filter(Boolean);
      }

      return [];
    },

    getRingCentroid(coordinates = []) {
      const valid = (Array.isArray(coordinates) ? coordinates : [])
        .map((coordinate) => [
          Number(coordinate && coordinate[0]),
          Number(coordinate && coordinate[1]),
        ])
        .filter((coordinate) => coordinate.every(Number.isFinite));

      if (!valid.length) return null;

      const sum = valid.reduce(
        (accumulator, coordinate) => {
          accumulator[0] += coordinate[0];
          accumulator[1] += coordinate[1];
          return accumulator;
        },
        [0, 0],
      );

      return [sum[0] / valid.length, sum[1] / valid.length];
    },

    getBuildingHeightFromProperties(properties = {}) {
      const readNumber = (...keys) => {
        for (const key of keys) {
          const value = Number(properties && properties[key]);
          if (Number.isFinite(value) && value > 0) return value;
        }
        return null;
      };

      const explicitHeight = readNumber("height", "render_height");
      if (explicitHeight) return explicitHeight;

      const levels = readNumber("levels", "building:levels");
      if (levels) return levels * 3.5;

      return 10;
    },

    getBuildingMinHeightFromProperties(properties = {}) {
      const minHeight = Number(
        properties.min_height ?? properties.render_min_height ?? 0,
      );
      return Number.isFinite(minHeight) && minHeight > 0 ? minHeight : 0;
    },
    getLocalRingBounds(localRing = []) {
      const valid = (Array.isArray(localRing) ? localRing : []).filter(
        (point) =>
          point &&
          Number.isFinite(Number(point.x)) &&
          Number.isFinite(Number(point.z)),
      );
      if (!valid.length) return null;

      const xs = valid.map((point) => Number(point.x));
      const zs = valid.map((point) => Number(point.z));
      return {
        minX: Math.min(...xs),
        maxX: Math.max(...xs),
        minZ: Math.min(...zs),
        maxZ: Math.max(...zs),
      };
    },

    getLocalRingArea(localRing = []) {
      const ring = Array.isArray(localRing) ? localRing : [];
      if (ring.length < 3) return 0;

      let area = 0;
      for (let index = 0; index < ring.length; index += 1) {
        const current = ring[index];
        const next = ring[(index + 1) % ring.length];
        area +=
          Number(current.x) * Number(next.z) -
          Number(next.x) * Number(current.z);
      }
      return Math.abs(area) / 2;
    },

    isStandaloneBuildingFootprintReasonable(localOuterRing = []) {
      const footprintBounds = this.getLocalRingBounds(localOuterRing);
      if (!footprintBounds) return false;

      const width = Math.abs(
        Number(footprintBounds.maxX) - Number(footprintBounds.minX),
      );
      const depth = Math.abs(
        Number(footprintBounds.maxZ) - Number(footprintBounds.minZ),
      );
      const maximumDimension = Math.max(width, depth);
      const area = this.getLocalRingArea(localOuterRing);

      return (
        maximumDimension <=
          THREE_PARK_BUILDING_MAX_FOOTPRINT_DIMENSION_METERS &&
        area <= THREE_PARK_BUILDING_MAX_FOOTPRINT_AREA_SQUARE_METERS
      );
    },

    createInternalBuildingBoxFootprint(
      localCentroid,
      localOuterRing = [],
      localParts = [],
    ) {
      if (
        !localCentroid ||
        !this.isTerrainPointInsideAnyPart(localCentroid, localParts)
      ) {
        return null;
      }

      const footprintBounds = this.getLocalRingBounds(localOuterRing);
      const width = footprintBounds
        ? Math.abs(Number(footprintBounds.maxX) - Number(footprintBounds.minX))
        : MAPBOX_BUILDING_POINT_FOOTPRINT_METERS;
      const depth = footprintBounds
        ? Math.abs(Number(footprintBounds.maxZ) - Number(footprintBounds.minZ))
        : MAPBOX_BUILDING_POINT_FOOTPRINT_METERS;
      const halfWidth = Math.max(4, Math.min(22, width / 2 || 9));
      const halfDepth = Math.max(4, Math.min(22, depth / 2 || 9));
      let scale = 1;

      for (let attempt = 0; attempt < 7; attempt += 1) {
        const ring = [
          {
            x: Number(localCentroid.x) - halfWidth * scale,
            z: Number(localCentroid.z) - halfDepth * scale,
          },
          {
            x: Number(localCentroid.x) + halfWidth * scale,
            z: Number(localCentroid.z) - halfDepth * scale,
          },
          {
            x: Number(localCentroid.x) + halfWidth * scale,
            z: Number(localCentroid.z) + halfDepth * scale,
          },
          {
            x: Number(localCentroid.x) - halfWidth * scale,
            z: Number(localCentroid.z) + halfDepth * scale,
          },
        ];

        if (
          ring.every((point) =>
            this.isTerrainPointInsideAnyPart(point, localParts),
          )
        ) {
          return ring;
        }

        scale *= 0.68;
      }

      return [
        { x: Number(localCentroid.x) - 3, z: Number(localCentroid.z) - 3 },
        { x: Number(localCentroid.x) + 3, z: Number(localCentroid.z) - 3 },
        { x: Number(localCentroid.x) + 3, z: Number(localCentroid.z) + 3 },
        { x: Number(localCentroid.x) - 3, z: Number(localCentroid.z) + 3 },
      ];
    },

    getNearestTerrainHeight(
      pointMap,
      point,
      minimumElevation,
      verticalExaggeration,
    ) {
      if (!pointMap || !point) return 0;

      let nearest = null;
      let nearestDistance = Infinity;
      pointMap.forEach((record) => {
        const dx = Number(record.x) - Number(point.x);
        const dz = Number(record.z) - Number(point.z);
        const distance = dx * dx + dz * dz;
        if (distance < nearestDistance) {
          nearestDistance = distance;
          nearest = record;
        }
      });

      const elevation =
        nearest && Number.isFinite(Number(nearest.elevation))
          ? Number(nearest.elevation)
          : minimumElevation;

      return (
        (elevation - minimumElevation) *
        Math.max(1, Number(verticalExaggeration) || 1)
      );
    },

    getStandaloneBuildingBaseTerrainHeight(
      pointMap,
      localOuterRing = [],
      parkAnchor,
      minimumElevation,
      verticalExaggeration,
      localParts = [],
    ) {
      const samples = [];
      const pushSample = (point) => {
        if (
          !point ||
          !Number.isFinite(Number(point.x)) ||
          !Number.isFinite(Number(point.z))
        ) {
          return;
        }
        if (
          Array.isArray(localParts) &&
          localParts.length &&
          !this.isTerrainPointInsideAnyPart(point, localParts)
        ) {
          return;
        }
        samples.push(point);
      };

      pushSample(parkAnchor);
      (Array.isArray(localOuterRing) ? localOuterRing : []).forEach(pushSample);
      this.getTerrainRingEdges(localOuterRing).forEach(([a, b]) => {
        pushSample({
          x: (Number(a.x) + Number(b.x)) / 2,
          z: (Number(a.z) + Number(b.z)) / 2,
        });
      });

      let highest = -Infinity;
      samples.forEach((point) => {
        const terrainY = this.getNearestTerrainHeight(
          pointMap,
          point,
          minimumElevation,
          verticalExaggeration,
        );
        if (Number.isFinite(Number(terrainY))) {
          highest = Math.max(highest, Number(terrainY));
        }
      });

      if (Number.isFinite(highest)) return highest;
      return this.getNearestTerrainHeight(
        pointMap,
        parkAnchor,
        minimumElevation,
        verticalExaggeration,
      );
    },

    getSourceFeatureUniqueKey(feature, centroid, height) {
      return [
        feature && (feature.id || feature.properties?.id)
          ? String(feature.id || feature.properties.id)
          : "building",
        Number(centroid && centroid[0]).toFixed(6),
        Number(centroid && centroid[1]).toFixed(6),
        Number(height || 0).toFixed(1),
      ].join("|");
    },

    getBuildingLayerIdsForStandaloneQuery() {
      if (!this.$map) return [];

      // Use only the custom Mapbox Streets building layers that we control.
      // Dynamic Mapbox Standard layers can include buildings from surrounding
      // tiles, which caused white blocks to appear outside the park island.
      return [
        MAPBOX_3D_BUILDINGS_LAYER_ID,
        MAPBOX_3D_BUILDINGS_SAMPLING_LAYER_ID,
      ].filter((layerId) => this.$map.getLayer(layerId));
    },
    getStandaloneBuildingQueryGeometry(origin, localParts = []) {
      if (!origin || !Array.isArray(localParts) || !localParts.length)
        return null;

      const closeRing = (ring = []) => {
        const coordinates = (Array.isArray(ring) ? ring : [])
          .map((point) => this.terrainMetersToLngLat(point, origin))
          .filter(
            (coordinate) =>
              Array.isArray(coordinate) &&
              coordinate.length >= 2 &&
              coordinate.every((value) => Number.isFinite(Number(value))),
          );
        if (coordinates.length < 3) return null;

        const first = coordinates[0];
        const last = coordinates[coordinates.length - 1];
        if (
          Math.abs(Number(first[0]) - Number(last[0])) > 1e-10 ||
          Math.abs(Number(first[1]) - Number(last[1])) > 1e-10
        ) {
          coordinates.push([...first]);
        }
        return coordinates;
      };

      const polygons = localParts
        .map((part) => {
          const outer = closeRing(part.outer);
          if (!outer) return null;
          const holes = (part.holes || []).map(closeRing).filter(Boolean);
          return [outer, ...holes];
        })
        .filter(Boolean);

      if (!polygons.length) return null;
      return polygons.length === 1
        ? { type: "Polygon", coordinates: polygons[0] }
        : { type: "MultiPolygon", coordinates: polygons };
    },

    getStandaloneBuildingLayerFilter(origin, localParts = []) {
      const geometry = this.getStandaloneBuildingQueryGeometry(
        origin,
        localParts,
      );
      return geometry ? ["within", geometry] : null;
    },

    applyStandaloneBuildingSamplingFilter(origin, localParts = []) {
      if (
        !this.$map ||
        !this.$map.getLayer(MAPBOX_3D_BUILDINGS_SAMPLING_LAYER_ID)
      ) {
        return null;
      }

      const filter = this.getStandaloneBuildingLayerFilter(origin, localParts);
      try {
        this.$map.setFilter(
          MAPBOX_3D_BUILDINGS_SAMPLING_LAYER_ID,
          filter || null,
        );
      } catch (error) {
        return null;
      }
      return filter;
    },

    getScreenQueryBoxForBounds(bounds, padding = 96) {
      if (!this.$map || !bounds) return null;

      try {
        const corners = [
          [bounds.minLng, bounds.minLat],
          [bounds.minLng, bounds.maxLat],
          [bounds.maxLng, bounds.minLat],
          [bounds.maxLng, bounds.maxLat],
        ]
          .map((coordinate) => this.$map.project(coordinate))
          .filter(
            (point) =>
              point &&
              Number.isFinite(Number(point.x)) &&
              Number.isFinite(Number(point.y)),
          );

        const canvas = this.$map.getCanvas();
        if (!corners.length || !canvas) return null;

        const xs = corners.map((point) => Number(point.x));
        const ys = corners.map((point) => Number(point.y));
        const minX = Math.max(0, Math.floor(Math.min(...xs) - padding));
        const minY = Math.max(0, Math.floor(Math.min(...ys) - padding));
        const maxX = Math.min(
          canvas.clientWidth,
          Math.ceil(Math.max(...xs) + padding),
        );
        const maxY = Math.min(
          canvas.clientHeight,
          Math.ceil(Math.max(...ys) + padding),
        );

        if (maxX <= minX || maxY <= minY) return null;
        return [
          [minX, minY],
          [maxX, maxY],
        ];
      } catch (error) {
        return null;
      }
    },

    getStandaloneBuildingScreenSampleBoxes(
      bounds,
      origin = null,
      localParts = [],
      pixelRadius = 72,
    ) {
      if (!this.$map || !bounds || !origin || !Array.isArray(localParts)) {
        return [];
      }

      const samples = this.getStandaloneBuildingTilequerySampleCoordinates(
        bounds,
        origin,
        localParts,
      );
      const boxes = [];
      const seen = new Set();
      const canvas = this.$map.getCanvas && this.$map.getCanvas();
      const width = Number(canvas && canvas.clientWidth) || 0;
      const height = Number(canvas && canvas.clientHeight) || 0;
      if (!width || !height) return [];

      samples.forEach((coordinate) => {
        try {
          const point = this.$map.project(coordinate);
          if (
            !point ||
            !Number.isFinite(Number(point.x)) ||
            !Number.isFinite(Number(point.y))
          ) {
            return;
          }

          const minX = Math.max(0, Math.floor(Number(point.x) - pixelRadius));
          const minY = Math.max(0, Math.floor(Number(point.y) - pixelRadius));
          const maxX = Math.min(
            width,
            Math.ceil(Number(point.x) + pixelRadius),
          );
          const maxY = Math.min(
            height,
            Math.ceil(Number(point.y) + pixelRadius),
          );
          if (maxX <= minX || maxY <= minY) return;

          const key = `${minX}|${minY}|${maxX}|${maxY}`;
          if (seen.has(key)) return;
          seen.add(key);
          boxes.push([
            [minX, minY],
            [maxX, maxY],
          ]);
        } catch (error) {
          // Ignore samples that cannot be projected with the current map camera.
        }
      });

      return boxes;
    },

    getStandaloneBuildingSamplingCenters(
      bounds,
      origin = null,
      localParts = [],
    ) {
      if (!bounds) return [];

      const minLng = Number(bounds.minLng);
      const maxLng = Number(bounds.maxLng);
      const minLat = Number(bounds.minLat);
      const maxLat = Number(bounds.maxLat);
      if (![minLng, maxLng, minLat, maxLat].every(Number.isFinite)) return [];

      const centerLng = (minLng + maxLng) / 2;
      const centerLat = (minLat + maxLat) / 2;
      const latitudeScale = 111320;
      const longitudeScale =
        latitudeScale * Math.max(0.15, Math.cos((centerLat * Math.PI) / 180));
      const widthMeters = Math.max(1, (maxLng - minLng) * longitudeScale);
      const heightMeters = Math.max(1, (maxLat - minLat) * latitudeScale);
      const canvas = this.$map && this.$map.getCanvas && this.$map.getCanvas();
      const canvasWidth = Math.max(
        320,
        Number(canvas && canvas.clientWidth) || 900,
      );
      const canvasHeight = Math.max(
        320,
        Number(canvas && canvas.clientHeight) || 700,
      );
      const metersPerPixel =
        (156543.03392 * Math.max(0.15, Math.cos((centerLat * Math.PI) / 180))) /
        Math.pow(2, MAPBOX_3D_BUILDINGS_CAMERA_ZOOM);
      const sampleWidthMeters = Math.max(
        120,
        canvasWidth *
          metersPerPixel *
          THREE_PARK_BUILDING_QUERY_VIEWPORT_COVERAGE_RATIO,
      );
      const sampleHeightMeters = Math.max(
        120,
        canvasHeight *
          metersPerPixel *
          THREE_PARK_BUILDING_QUERY_VIEWPORT_COVERAGE_RATIO,
      );
      const columns = Math.max(
        1,
        Math.min(
          THREE_PARK_BUILDING_QUERY_GRID_MAX_COLUMNS,
          Math.ceil(widthMeters / sampleWidthMeters),
        ),
      );
      const rows = Math.max(
        1,
        Math.min(
          THREE_PARK_BUILDING_QUERY_GRID_MAX_ROWS,
          Math.ceil(heightMeters / sampleHeightMeters),
        ),
      );
      const centers = [];
      const seen = new Set();
      const canFilterByPark =
        origin && Array.isArray(localParts) && localParts.length > 0;
      const pushCenter = (lng, lat, { allowOutsideFallback = false } = {}) => {
        const safeLng = Math.max(minLng, Math.min(maxLng, Number(lng)));
        const safeLat = Math.max(minLat, Math.min(maxLat, Number(lat)));
        if (
          canFilterByPark &&
          !allowOutsideFallback &&
          !this.isLngLatInsideTerrainParts(
            [safeLng, safeLat],
            origin,
            localParts,
          )
        ) {
          return;
        }
        const key = `${safeLng.toFixed(7)}|${safeLat.toFixed(7)}`;
        if (seen.has(key)) return;
        seen.add(key);
        centers.push([safeLng, safeLat]);
      };

      pushCenter(centerLng, centerLat);

      for (let row = 0; row < rows; row += 1) {
        const lat =
          rows === 1
            ? centerLat
            : minLat + ((row + 0.5) / rows) * (maxLat - minLat);
        for (let column = 0; column < columns; column += 1) {
          const lng =
            columns === 1
              ? centerLng
              : minLng + ((column + 0.5) / columns) * (maxLng - minLng);
          pushCenter(lng, lat);
        }
      }

      if (canFilterByPark) {
        this.getStandaloneBuildingTilequerySampleCoordinates(
          bounds,
          origin,
          localParts,
        ).forEach(([lng, lat]) => pushCenter(lng, lat));
      }

      if (!centers.length) {
        pushCenter(centerLng, centerLat, { allowOutsideFallback: true });
      }

      return centers;
    },

    getStandaloneBuildingTilequerySampleCoordinates(
      bounds,
      origin,
      localParts = [],
    ) {
      if (
        !bounds ||
        !origin ||
        !Array.isArray(localParts) ||
        !localParts.length
      ) {
        return [];
      }

      const allPoints = [];
      localParts.forEach((part) => {
        [part.outer, ...(part.holes || [])].forEach((ring) => {
          (Array.isArray(ring) ? ring : []).forEach((point) => {
            if (
              point &&
              Number.isFinite(Number(point.x)) &&
              Number.isFinite(Number(point.z))
            ) {
              allPoints.push(point);
            }
          });
        });
      });
      if (!allPoints.length) return [];

      const xs = allPoints.map((point) => Number(point.x));
      const zs = allPoints.map((point) => Number(point.z));
      const minX = Math.min(...xs);
      const maxX = Math.max(...xs);
      const minZ = Math.min(...zs);
      const maxZ = Math.max(...zs);
      const width = Math.max(1, maxX - minX);
      const depth = Math.max(1, maxZ - minZ);
      const columns = Math.max(
        4,
        Math.min(
          THREE_PARK_BUILDING_QUERY_GRID_MAX_COLUMNS,
          Math.ceil(width / 85),
        ),
      );
      const rows = Math.max(
        4,
        Math.min(
          THREE_PARK_BUILDING_QUERY_GRID_MAX_ROWS,
          Math.ceil(depth / 85),
        ),
      );
      const samples = [];
      const seen = new Set();
      const addLocalPoint = (point) => {
        if (!this.isTerrainPointInsideAnyPart(point, localParts)) return;
        const lngLat = this.terrainMetersToLngLat(point, origin);
        if (
          !Array.isArray(lngLat) ||
          lngLat.length < 2 ||
          !lngLat.every((value) => Number.isFinite(Number(value)))
        ) {
          return;
        }
        if (
          lngLat[0] < bounds.minLng ||
          lngLat[0] > bounds.maxLng ||
          lngLat[1] < bounds.minLat ||
          lngLat[1] > bounds.maxLat
        ) {
          return;
        }
        const key = `${Number(lngLat[0]).toFixed(6)}|${Number(lngLat[1]).toFixed(6)}`;
        if (seen.has(key)) return;
        seen.add(key);
        samples.push(lngLat);
      };

      localParts.forEach((part) => {
        const boundsForPart = this.getLocalRingBounds(part.outer);
        if (!boundsForPart) return;
        addLocalPoint({
          x: (boundsForPart.minX + boundsForPart.maxX) / 2,
          z: (boundsForPart.minZ + boundsForPart.maxZ) / 2,
        });

        this.getTerrainRingEdges(part.outer).forEach(([a, b], index) => {
          if (index % 3 === 0) addLocalPoint(a);
          addLocalPoint({
            x: (Number(a.x) + Number(b.x)) / 2,
            z: (Number(a.z) + Number(b.z)) / 2,
          });
        });
      });

      for (let row = 0; row < rows; row += 1) {
        const z = minZ + ((row + 0.5) / rows) * (maxZ - minZ);
        for (let column = 0; column < columns; column += 1) {
          const x = minX + ((column + 0.5) / columns) * (maxX - minX);
          addLocalPoint({ x, z });
        }
      }

      return samples.slice(0, THREE_PARK_BUILDING_TILEQUERY_MAX_POINTS);
    },

    async fetchMapboxBuildingTilequeryFeatures(coordinate) {
      if (
        typeof fetch !== "function" ||
        !Array.isArray(coordinate) ||
        coordinate.length < 2
      ) {
        return [];
      }

      const lng = Number(coordinate[0]);
      const lat = Number(coordinate[1]);
      if (!Number.isFinite(lng) || !Number.isFinite(lat)) return [];

      const params = new URLSearchParams({
        access_token: MAPBOX_ACCESS_TOKEN,
        layers: MAPBOX_BUILDING_QUERY_SOURCE_LAYERS.join(","),
        radius: String(THREE_PARK_BUILDING_TILEQUERY_RADIUS_METERS),
        limit: String(THREE_PARK_BUILDING_TILEQUERY_LIMIT),
      });
      const url = `https://api.mapbox.com/v4/${MAPBOX_BUILDING_TILEQUERY_TILESET_ID}/tilequery/${lng},${lat}.json?${params.toString()}`;
      const controller =
        typeof AbortController !== "undefined" ? new AbortController() : null;
      const timeoutId = controller
        ? window.setTimeout(
            () => controller.abort(),
            THREE_PARK_BUILDING_TILEQUERY_TIMEOUT_MS,
          )
        : null;

      try {
        const response = await fetch(url, {
          signal: controller ? controller.signal : undefined,
        });
        if (!response || !response.ok) return [];
        const data = await response.json();
        return Array.isArray(data && data.features) ? data.features : [];
      } catch (error) {
        return [];
      } finally {
        if (timeoutId != null) window.clearTimeout(timeoutId);
      }
    },

    async queryMapboxTilequeryBuildingFeaturesForPark(
      bounds,
      origin,
      localParts = [],
    ) {
      const samples = this.getStandaloneBuildingTilequerySampleCoordinates(
        bounds,
        origin,
        localParts,
      );
      if (!samples.length) return [];

      const collected = [];
      for (
        let index = 0;
        index < samples.length;
        index += THREE_PARK_BUILDING_TILEQUERY_BATCH_SIZE
      ) {
        if (!this.$map || !this.shouldShowThreeParkLayer()) break;

        const batch = samples.slice(
          index,
          index + THREE_PARK_BUILDING_TILEQUERY_BATCH_SIZE,
        );
        const batchResults = await Promise.all(
          batch.map((coordinate) =>
            this.fetchMapboxBuildingTilequeryFeatures(coordinate),
          ),
        );
        batchResults.forEach((features) => {
          (Array.isArray(features) ? features : []).forEach((feature) => {
            if (feature && feature.geometry) collected.push(feature);
          });
        });
      }

      return collected;
    },

    queryCurrentMapboxBuildingFeaturesForStandalone3D(
      bounds = null,
      origin = null,
      localParts = [],
    ) {
      if (!this.$map) return [];

      this.ensureStandaloneBuildingSource();
      this.addCustom3DBuildingsLayer();
      const buildingFilter = this.applyStandaloneBuildingSamplingFilter(
        origin,
        localParts,
      );

      const collected = [];
      const addFeatures = (features) => {
        (Array.isArray(features) ? features : []).forEach((feature) => {
          if (feature && feature.geometry) collected.push(feature);
        });
      };

      // Source-feature query from the custom Mapbox Streets building source.
      // It is much faster than camera-scanning the whole park and avoids pulling
      // buildings from unrelated Mapbox Standard 3D layers.
      if (this.$map.getSource(MAPBOX_3D_BUILDINGS_SOURCE_ID)) {
        try {
          const queryOptions = { sourceLayer: "building" };
          if (buildingFilter) queryOptions.filter = buildingFilter;
          addFeatures(
            this.$map.querySourceFeatures(
              MAPBOX_3D_BUILDINGS_SOURCE_ID,
              queryOptions,
            ),
          );
        } catch (error) {
          // Rendered feature query below is used as a fallback.
        }
      }

      try {
        const layers = this.getBuildingLayerIdsForStandaloneQuery();
        const queryBox = this.getScreenQueryBoxForBounds(bounds, 48);
        if (layers.length && queryBox) {
          addFeatures(
            this.$map.queryRenderedFeatures(queryBox, {
              layers,
            }),
          );
        }
      } catch (error) {
        // Some Mapbox styles/layers may not support rendered feature querying.
      }

      return collected;
    },
    async ensureStandaloneBuildingTilesForPark(
      bounds,
      origin = null,
      localParts = [],
    ) {
      if (!this.$map || !bounds) return;

      this.standaloneBuildingFeatureCache = [];
      this.ensureStandaloneBuildingSource();
      this.addCustom3DBuildingsLayer();
      this.applyStandaloneBuildingSamplingFilter(origin, localParts);

      // Keep this fast: do not pan/zoom the hidden Mapbox camera across the
      // whole project and do not call Tilequery. The previous deep scan made
      // "Building 3D Terrain" take several minutes and still captured exterior
      // buildings. One loaded-tile pass is enough; the strict polygon filter in
      // queryStandaloneBuildingFootprints removes anything outside the park.
      try {
        await this.waitForStandaloneBuildingTiles(900);
        await new Promise((resolve) =>
          window.setTimeout(resolve, THREE_PARK_BUILDING_TILE_SETTLE_MS),
        );
        const features = this.queryCurrentMapboxBuildingFeaturesForStandalone3D(
          bounds,
          origin,
          localParts,
        );
        if (features.length) {
          this.standaloneBuildingFeatureCache.push(...features);
        }
      } catch (error) {
        // Building capture is optional. The terrain island should still render
        // quickly even when Mapbox building tiles are unavailable.
      }
    },
    getBuildingSourceFeaturesForStandalone3D(
      bounds = null,
      origin = null,
      localParts = [],
    ) {
      const cached = Array.isArray(this.standaloneBuildingFeatureCache)
        ? this.standaloneBuildingFeatureCache
        : [];
      const current = this.queryCurrentMapboxBuildingFeaturesForStandalone3D(
        bounds,
        origin,
        localParts,
      );
      return cached.concat(current);
    },

    queryStandaloneBuildingFootprints(
      bounds,
      origin,
      localParts,
      pointMap,
      minimumElevation,
      verticalExaggeration,
    ) {
      if (
        !bounds ||
        !origin ||
        !Array.isArray(localParts) ||
        !localParts.length
      ) {
        return [];
      }

      const features = this.getBuildingSourceFeaturesForStandalone3D(
        bounds,
        origin,
        localParts,
      );
      const buildings = [];
      const seen = new Set();

      features.forEach((feature) => {
        const properties = feature.properties || {};
        const polygons = this.getFeatureCoordinateRings(feature);
        if (!polygons.length) return;

        const height = this.getBuildingHeightFromProperties(properties);
        const minHeight = this.getBuildingMinHeightFromProperties(properties);
        const exaggeratedHeight = Math.max(
          MAPBOX_3D_BUILDING_MIN_HEIGHT,
          height * MAPBOX_3D_BUILDING_HEIGHT_EXAGGERATION,
        );

        polygons.forEach((polygon) => {
          const outerCoordinates = this.normalizeTerrainRing(polygon[0]);
          if (outerCoordinates.length < 3) return;

          const centroid = this.getRingCentroid(outerCoordinates);
          if (!centroid) return;

          if (
            centroid[0] < bounds.minLng ||
            centroid[0] > bounds.maxLng ||
            centroid[1] < bounds.minLat ||
            centroid[1] > bounds.maxLat
          ) {
            return;
          }

          let outer = outerCoordinates.map((coordinate) =>
            this.lngLatToTerrainMeters(coordinate, origin),
          );
          if (!this.isStandaloneBuildingFootprintReasonable(outer)) return;

          const localCentroid = this.lngLatToTerrainMeters(centroid, origin);
          const parkAnchor = this.getStandaloneBuildingParkAnchor(
            outer,
            localCentroid,
            localParts,
          );

          // Only keep buildings whose Mapbox footprint intersects the current
          // project polygon. The anchor is the point used to place the building
          // on the island terrain when Mapbox returns a clipped footprint.
          if (
            !parkAnchor ||
            !this.doesStandaloneBuildingBelongToPark(
              outer,
              localCentroid,
              localParts,
            )
          ) {
            return;
          }

          const insideRatio = this.getTerrainRingInsideRatio(outer, localParts);
          const footprintFullyInside = outer.every((point) =>
            this.isTerrainPointInsideAnyPart(point, localParts),
          );

          // Do not snap exterior/boundary buildings onto the floating island.
          // If Mapbox returns a building that is not fully inside the park GIS
          // geometry, skip it so no outside buildings appear in 3D view.
          if (
            !footprintFullyInside ||
            insideRatio < THREE_PARK_BUILDING_MIN_INSIDE_RATIO
          ) {
            return;
          }

          const uniqueKey = this.getSourceFeatureUniqueKey(
            feature,
            centroid,
            exaggeratedHeight,
          );
          if (seen.has(uniqueKey)) return;
          seen.add(uniqueKey);

          const holes = (polygon || [])
            .slice(1)
            .map((ring) => this.normalizeTerrainRing(ring))
            .filter((ring) => ring.length >= 3)
            .map((ring) =>
              ring.map((coordinate) =>
                this.lngLatToTerrainMeters(coordinate, origin),
              ),
            );
          const terrainY = this.getStandaloneBuildingBaseTerrainHeight(
            pointMap,
            outer,
            parkAnchor,
            minimumElevation,
            verticalExaggeration,
            localParts,
          );
          const baseY =
            terrainY + minHeight * MAPBOX_3D_BUILDING_HEIGHT_EXAGGERATION + 0.7;

          buildings.push({
            outer,
            holes,
            baseY,
            topY: baseY + exaggeratedHeight,
            height: exaggeratedHeight,
            properties: { ...properties },
            label:
              properties.name_en ||
              properties.name ||
              properties.Name ||
              properties.type ||
              properties.class ||
              "Building",
          });
        });
      });

      return buildings
        .sort((a, b) => Number(b.height) - Number(a.height))
        .slice(0, 350);
    },

    addStandaloneBuildingMeshes(group, buildingFootprints = []) {
      if (
        !group ||
        !Array.isArray(buildingFootprints) ||
        !buildingFootprints.length
      ) {
        return;
      }

      const positions = [];
      const linePositions = [];

      const pushVertex = (point, y) => {
        positions.push(Number(point.x), Number(y), Number(point.z));
      };

      const pushLine = (a, ay, b, by) => {
        linePositions.push(Number(a.x), Number(ay), Number(a.z));
        linePositions.push(Number(b.x), Number(by), Number(b.z));
      };

      buildingFootprints.forEach((building) => {
        const outer = Array.isArray(building.outer) ? building.outer : [];
        if (outer.length < 3) return;

        const holes = Array.isArray(building.holes) ? building.holes : [];
        const contour = outer.map(
          (point) => new THREE.Vector2(point.x, point.z),
        );
        const holeVectors = holes.map((ring) =>
          ring.map((point) => new THREE.Vector2(point.x, point.z)),
        );
        const flattened = contour.concat(...holeVectors);
        let faces = THREE.ShapeUtils.triangulateShape(contour, holeVectors);

        if (!faces.length) {
          const reversedContour = contour.slice().reverse();
          faces = THREE.ShapeUtils.triangulateShape(
            reversedContour,
            holeVectors,
          );
        }

        faces.forEach((face) => {
          face.forEach((index) => {
            const point = flattened[index];
            if (point) positions.push(point.x, building.topY, point.y);
          });
        });

        const addWallRing = (ring) => {
          for (let index = 0; index < ring.length; index += 1) {
            const current = ring[index];
            const next = ring[(index + 1) % ring.length];

            pushVertex(current, building.baseY);
            pushVertex(next, building.baseY);
            pushVertex(current, building.topY);

            pushVertex(next, building.baseY);
            pushVertex(next, building.topY);
            pushVertex(current, building.topY);

            pushLine(current, building.baseY, next, building.baseY);
            pushLine(current, building.topY, next, building.topY);
            pushLine(current, building.baseY, current, building.topY);
          }
        };

        addWallRing(outer);
        holes.forEach(addWallRing);
      });

      if (positions.length) {
        const geometry = new THREE.BufferGeometry();
        geometry.setAttribute(
          "position",
          new THREE.Float32BufferAttribute(positions, 3),
        );
        geometry.computeVertexNormals();
        const material = new THREE.MeshStandardMaterial({
          color: 0x26383f,
          emissive: 0x07171c,
          emissiveIntensity: 0.2,
          roughness: 0.86,
          metalness: 0.02,
          transparent: false,
          opacity: 1,
          side: THREE.DoubleSide,
        });
        const mesh = new THREE.Mesh(geometry, material);
        mesh.renderOrder = 5;
        group.add(mesh);
      }

      if (linePositions.length) {
        const lineGeometry = new THREE.BufferGeometry();
        lineGeometry.setAttribute(
          "position",
          new THREE.Float32BufferAttribute(linePositions, 3),
        );
        const lineMaterial = new THREE.LineBasicMaterial({
          color: 0x63dce4,
          transparent: true,
          opacity: 0.18,
        });
        const outlines = new THREE.LineSegments(lineGeometry, lineMaterial);
        outlines.renderOrder = 6;
        group.add(outlines);
      }
    },

    getTerrainPointHeight(
      pointMap,
      point,
      minimumElevation,
      verticalExaggeration = 1,
    ) {
      const pointElevation =
        point && point.elevation != null ? Number(point.elevation) : NaN;
      const key = this.getTerrainPointKey(point);
      const record =
        pointMap && typeof pointMap.get === "function"
          ? pointMap.get(key)
          : null;
      const elevation = Number.isFinite(pointElevation)
        ? pointElevation
        : record && Number.isFinite(Number(record.elevation))
          ? Number(record.elevation)
          : minimumElevation;

      return (
        (elevation - minimumElevation) *
        Math.max(1, Number(verticalExaggeration) || 1)
      );
    },

    async createStandaloneTerrainGroup(
      modelData,
      buildToken = this.threeParkBuildToken,
    ) {
      const {
        localParts,
        baseTriangles,
        triangleVertexKeys,
        triangleVertexIndices,
        terrainVertexRecords,
        pointMap,
        minimumElevation,
        maximumElevation,
        maxDimension,
        islandWallDepth,
        gridSpacing,
        verticalExaggeration,
        localBounds,
        satelliteTexture,
        buildingFootprints,
      } = modelData;
      const group = new THREE.Group();
      const shouldRenderTopSurface = modelData.showTopSurface !== false;
      const stairCutoutUniformData =
        this.getStandaloneStairSurfaceCutoutUniformData(modelData);
      const stairCutoutMaskTexture =
        modelData && modelData.stairCutoutMaskTexture
          ? modelData.stairCutoutMaskTexture
          : null;
      const stairCutoutMaskBounds =
        modelData && modelData.stairCutoutMaskBounds
          ? modelData.stairCutoutMaskBounds
          : null;
      const terrainTexture =
        satelliteTexture || this.createStandaloneFallbackTexture();
      const shouldUseSatelliteGround = Boolean(
        satelliteTexture && this.threeLayerVisibility.satelliteGround,
      );
      const textureWidth = Math.max(
        0.0001,
        Number(localBounds.maxX) - Number(localBounds.minX),
      );
      const textureDepth = Math.max(
        0.0001,
        Number(localBounds.maxZ) - Number(localBounds.minZ),
      );

      // LandXML is naturally an indexed TIN. Preserve that topology instead of
      // duplicating each shared Civil 3D vertex once per face. This cuts KAP's
      // Terrain (After) CPU/GPU buffers dramatically with zero geometric loss.
      const hasIndexedTerrain =
        triangleVertexIndices instanceof Uint32Array &&
        Array.isArray(terrainVertexRecords) &&
        terrainVertexRecords.length > 0;
      const surfaceVertexCount = hasIndexedTerrain
        ? terrainVertexRecords.length
        : triangleVertexKeys.length;
      const surfacePositions = new Float32Array(surfaceVertexCount * 3);
      const surfaceUvs = new Float32Array(surfaceVertexCount * 2);
      for (
        let vertexIndex = 0;
        vertexIndex < surfaceVertexCount;
        vertexIndex += 1
      ) {
        if (vertexIndex > 0 && vertexIndex % 12000 === 0) {
          const shouldContinue =
            await this.yieldStandaloneThreeBuildFrame(buildToken);
          if (!shouldContinue) {
            throw new Error("The 3D terrain build was cancelled.");
          }
        }
        const point = hasIndexedTerrain
          ? terrainVertexRecords[vertexIndex]
          : pointMap.get(triangleVertexKeys[vertexIndex]);
        if (!point) continue;
        const height =
          (Number(point.elevation) - minimumElevation) * verticalExaggeration;
        const positionOffset = vertexIndex * 3;
        surfacePositions[positionOffset] = Number(point.x);
        surfacePositions[positionOffset + 1] = height;
        surfacePositions[positionOffset + 2] = Number(point.z);

        const u = (Number(point.x) - Number(localBounds.minX)) / textureWidth;
        const v = (Number(localBounds.maxZ) - Number(point.z)) / textureDepth;
        const uvOffset = vertexIndex * 2;
        surfaceUvs[uvOffset] = Math.max(0, Math.min(1, u));
        surfaceUvs[uvOffset + 1] = Math.max(0, Math.min(1, v));
      }

      const surfaceGeometry = new THREE.BufferGeometry();
      surfaceGeometry.setAttribute(
        "position",
        new THREE.BufferAttribute(surfacePositions, 3),
      );
      surfaceGeometry.setAttribute(
        "uv",
        new THREE.BufferAttribute(surfaceUvs, 2),
      );
      if (hasIndexedTerrain) {
        surfaceGeometry.setIndex(
          new THREE.BufferAttribute(triangleVertexIndices, 1),
        );
      }

      // Keep a direct reference to this already-allocated terrain vertex buffer.
      // Pedestrian Space can borrow Terrain (After)'s exact geometry instead of
      // creating millions of separate 1.25 m drape vertices. The terrain group
      // remains the owner of this BufferGeometry; PATHS only borrows it.
      modelData.terrainTopSurfaceGeometry = surfaceGeometry;
      surfaceGeometry.userData.isStandaloneTerrainTopSurface = true;

      // Render the selected terrain elevation with the existing holographic
      // rectangle grid. Satellite Ground changes only the colour texture; it
      // never changes Terrain (before)/(after) geometry or elevation.
      const surfaceMaterial = new THREE.ShaderMaterial({
        uniforms: {
          uSatelliteMap: { value: terrainTexture },
          uUseSatellite: { value: shouldUseSatelliteGround ? 1 : 0 },
          uGroundTextureRepeat: { value: new THREE.Vector2(1, 1) },
          uBaseColor: {
            value: new THREE.Color(THREE_PARK_SURFACE_COLOR),
          },
          uGridColor: {
            value: new THREE.Color(THREE_PARK_WIREFRAME_COLOR),
          },
          uGridSpacing: {
            value: Math.max(1, Number(gridSpacing) || 25),
          },
          uGridIntensity: {
            value: shouldUseSatelliteGround ? 0.24 : 0.18,
          },
          uSatelliteBrightness: {
            value: shouldUseSatelliteGround ? 1.0 : 0.0,
          },
          uStairCutoutCount: { value: stairCutoutUniformData.count },
          uStairCutoutProjection: { value: stairCutoutUniformData.projections },
          uStairCutoutBounds: { value: stairCutoutUniformData.bounds },
          uStairCutoutMask: { value: stairCutoutMaskTexture },
          uUseStairCutoutMask: { value: stairCutoutMaskTexture ? 1 : 0 },
          uStairCutoutMaskBounds: {
            value: stairCutoutMaskBounds
              ? new THREE.Vector4(
                  Number(stairCutoutMaskBounds.minX),
                  Number(stairCutoutMaskBounds.maxX),
                  Number(stairCutoutMaskBounds.minZ),
                  Number(stairCutoutMaskBounds.maxZ),
                )
              : new THREE.Vector4(0, 1, 0, 1),
          },
        },
        vertexShader: `
          varying vec2 vUv;
          varying vec3 vLocalPosition;
          varying vec3 vWorldPosition;

          void main() {
            vec4 worldPosition = modelMatrix * vec4(position, 1.0);
            vec4 viewPosition = modelViewMatrix * vec4(position, 1.0);
            vUv = uv;
            vLocalPosition = position;
            vWorldPosition = worldPosition.xyz;
            gl_Position = projectionMatrix * viewPosition;
          }
        `,
        fragmentShader: `
          uniform sampler2D uSatelliteMap;
          uniform float uUseSatellite;
          uniform vec2 uGroundTextureRepeat;
          uniform vec3 uBaseColor;
          uniform vec3 uGridColor;
          uniform float uGridSpacing;
          uniform float uGridIntensity;
          uniform float uSatelliteBrightness;
          uniform int uStairCutoutCount;
          uniform vec4 uStairCutoutProjection[64];
          uniform vec4 uStairCutoutBounds[64];
          uniform sampler2D uStairCutoutMask;
          uniform float uUseStairCutoutMask;
          uniform vec4 uStairCutoutMaskBounds;

          varying vec2 vUv;
          varying vec3 vLocalPosition;
          varying vec3 vWorldPosition;

          void main() {
            // Full staircase mask: unlike the old 64-vector uniform limit, this
            // texture contains EVERY reconstructed stair section.
            if (uUseStairCutoutMask > 0.5) {
              float maskWidth = max(
                0.001,
                uStairCutoutMaskBounds.y - uStairCutoutMaskBounds.x
              );
              float maskDepth = max(
                0.001,
                uStairCutoutMaskBounds.w - uStairCutoutMaskBounds.z
              );
              vec2 stairMaskUv = vec2(
                (vLocalPosition.x - uStairCutoutMaskBounds.x) / maskWidth,
                (vLocalPosition.z - uStairCutoutMaskBounds.z) / maskDepth
              );
              if (
                stairMaskUv.x >= 0.0 &&
                stairMaskUv.x <= 1.0 &&
                stairMaskUv.y >= 0.0 &&
                stairMaskUv.y <= 1.0 &&
                texture2D(uStairCutoutMask, stairMaskUv).r > 0.5
              ) {
                discard;
              }
            } else {
              // Fallback for projects without the texture mask.
              for (int stairIndex = 0; stairIndex < 64; stairIndex++) {
                if (stairIndex >= uStairCutoutCount) break;
                vec4 projection = uStairCutoutProjection[stairIndex];
                vec4 maskBounds = uStairCutoutBounds[stairIndex];
                float along =
                  vLocalPosition.x * projection.x +
                  vLocalPosition.z * projection.y;
                float normal =
                  vLocalPosition.x * projection.z +
                  vLocalPosition.z * projection.w;
                if (
                  along >= maskBounds.x &&
                  along <= maskBounds.y &&
                  normal >= maskBounds.z &&
                  normal <= maskBounds.w
                ) {
                  discard;
                }
              }
            }

            vec3 satelliteColor = texture2D(
              uSatelliteMap,
              vUv * uGroundTextureRepeat
            ).rgb;
            float luminance = dot(
              satelliteColor,
              vec3(0.2126, 0.7152, 0.0722)
            );
            satelliteColor = mix(
              vec3(luminance),
              satelliteColor,
              0.92
            ) * uSatelliteBrightness;

            vec3 baseColor = mix(
              uBaseColor,
              satelliteColor,
              clamp(uUseSatellite, 0.0, 1.0)
            );

            vec2 scaled = vWorldPosition.xz / uGridSpacing;
            vec2 derivativeWidth = max(fwidth(scaled), vec2(0.0001));
            vec2 gridDistance =
              abs(fract(scaled - 0.5) - 0.5) /
              (derivativeWidth * 0.38);
            float gridLine =
              1.0 - clamp(min(gridDistance.x, gridDistance.y), 0.0, 1.0);
            gridLine = smoothstep(0.12, 0.9, gridLine);

            // Derive the Terrain normal from screen-space position changes.
            // This preserves slope shading without allocating and calculating a
            // full normal buffer for every Civil 3D vertex during startup.
            vec3 normalDirection = normalize(
              cross(dFdx(vWorldPosition), dFdy(vWorldPosition))
            );
            if (normalDirection.y < 0.0) {
              normalDirection = -normalDirection;
            }
            vec3 viewDirection = normalize(cameraPosition - vWorldPosition);
            float facing = max(
              0.0,
              dot(normalDirection, normalize(vec3(0.32, 0.86, 0.38)))
            );
            float fresnel = pow(
              1.0 - abs(dot(normalDirection, viewDirection)),
              2.2
            );

            vec3 shadedBase = baseColor * (0.78 + facing * 0.22);
            vec3 finalColor = mix(
              shadedBase,
              uGridColor,
              gridLine * uGridIntensity
            );
            finalColor += uGridColor * fresnel * 0.04;
            gl_FragColor = vec4(finalColor, 1.0);
          }
        `,
        side: THREE.DoubleSide,
        extensions: {
          derivatives: true,
        },
      });
      const terrainStairCutoutMaskBoundsVector = stairCutoutMaskBounds
        ? new THREE.Vector4(
            Number(stairCutoutMaskBounds.minX),
            Number(stairCutoutMaskBounds.maxX),
            Number(stairCutoutMaskBounds.minZ),
            Number(stairCutoutMaskBounds.maxZ),
          )
        : new THREE.Vector4(0, 1, 0, 1);
      surfaceMaterial.userData = {
        ...(surfaceMaterial.userData || {}),
        stairCutoutShader: { uniforms: surfaceMaterial.uniforms },
        stairCutoutState: {
          count: stairCutoutUniformData.count,
          projections: stairCutoutUniformData.projections,
          bounds: stairCutoutUniformData.bounds,
          maskTexture: stairCutoutMaskTexture || null,
          useMask: Boolean(stairCutoutMaskTexture),
          maskBoundsVector: terrainStairCutoutMaskBoundsVector.clone(),
          emptyMaskBoundsVector: new THREE.Vector4(0, 1, 0, 1),
        },
      };
      this.applyStandaloneStairCutoutStateToMaterial(
        surfaceMaterial,
        this.isStandalonePathStairSubLayerVisible(),
      );

      const surfaceMesh = new THREE.Mesh(surfaceGeometry, surfaceMaterial);
      surfaceMesh.name = "terrain-top-surface";
      surfaceMesh.userData.baseGridSpacing = Math.max(
        1,
        Number(gridSpacing) || 25,
      );
      surfaceMesh.renderOrder = 1;
      surfaceMesh.visible = shouldRenderTopSurface;
      group.add(surfaceMesh);

      // WireframeGeometry duplicates every TIN edge. That is extremely expensive
      // for King Abdulaziz Park's survey-dense LandXML and was a major source of
      // startup lag / memory pressure. The shader already draws the visible
      // rectangular terrain grid, so omit topology wireframe on large surfaces.
      const surfaceTriangleCount = hasIndexedTerrain
        ? Math.floor(triangleVertexIndices.length / 3)
        : Math.floor(surfaceVertexCount / 3);
      // Terrain (After) cutouts are fragment-shader holes. Do not overlay the
      // optional TIN wireframe across those holes, otherwise faint triangle
      // edges could still appear where the stairs are supposed to be clear.
      const renderTinTopology =
        surfaceTriangleCount <= 20000 && stairCutoutUniformData.count === 0;
      if (renderTinTopology) {
        const terrainTopology = new THREE.LineSegments(
          new THREE.WireframeGeometry(surfaceGeometry),
          new THREE.LineBasicMaterial({
            color: THREE_PARK_WIREFRAME_COLOR,
            transparent: true,
            opacity: 0.008,
          }),
        );
        terrainTopology.name = "terrain-top-grid";
        terrainTopology.renderOrder = 2;
        terrainTopology.visible = shouldRenderTopSurface;
        group.add(terrainTopology);
      }

      // Use a shared lower plane so the perimeter becomes a floating-island
      // cutaway. Every wall's upper edge is sampled densely from the DEM, so
      // the outline follows the visible landscape elevation instead of drawing
      // one straight line between only the original GIS corner coordinates.
      const baseY = -Math.max(1, Number(islandWallDepth) || 12);
      const wallPositions = [];
      const wallGridPositions = [];
      const bottomOutlinePositions = [];
      const horizontalWallFractions = Array.from(
        { length: Math.max(1, THREE_PARK_WALL_GRID_HORIZONTAL_DIVISIONS - 1) },
        (_, index) =>
          (index + 1) / Math.max(2, THREE_PARK_WALL_GRID_HORIZONTAL_DIVISIONS),
      );

      localParts.forEach((part) => {
        [part.outer, ...(part.holes || [])].forEach((ring) => {
          const topHeights = ring.map((point) =>
            this.getTerrainPointHeight(
              pointMap,
              point,
              minimumElevation,
              verticalExaggeration,
            ),
          );
          const verticalLineStep = Math.max(
            1,
            THREE_PARK_WALL_GRID_VERTICAL_SAMPLE_STEP,
          );

          for (let index = 0; index < ring.length; index += 1) {
            const nextIndex = (index + 1) % ring.length;
            const current = ring[index];
            const next = ring[nextIndex];
            const currentY = topHeights[index];
            const nextY = topHeights[nextIndex];

            wallPositions.push(
              current.x,
              currentY,
              current.z,
              next.x,
              nextY,
              next.z,
              current.x,
              baseY,
              current.z,

              next.x,
              nextY,
              next.z,
              next.x,
              baseY,
              next.z,
              current.x,
              baseY,
              current.z,
            );

            bottomOutlinePositions.push(
              current.x,
              baseY,
              current.z,
              next.x,
              baseY,
              next.z,
            );

            if (index % verticalLineStep === 0) {
              wallGridPositions.push(
                current.x,
                currentY,
                current.z,
                current.x,
                baseY,
                current.z,
              );
            }

            horizontalWallFractions.forEach((fraction) => {
              const currentGridY = currentY + (baseY - currentY) * fraction;
              const nextGridY = nextY + (baseY - nextY) * fraction;
              wallGridPositions.push(
                current.x,
                currentGridY,
                current.z,
                next.x,
                nextGridY,
                next.z,
              );
            });
          }
        });
      });

      const wallGeometry = new THREE.BufferGeometry();
      wallGeometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(wallPositions, 3),
      );
      wallPositions.length = 0;
      const wallMaterial = new THREE.MeshStandardMaterial({
        color: THREE_PARK_SIDE_COLOR,
        roughness: 0.98,
        metalness: 0,
        transparent: true,
        opacity: 0.9,
        side: THREE.DoubleSide,
      });
      const wallMesh = new THREE.Mesh(wallGeometry, wallMaterial);
      wallMesh.name = "terrain-island-walls";
      wallMesh.renderOrder = 0;
      group.add(wallMesh);

      const wallGridGeometry = new THREE.BufferGeometry();
      wallGridGeometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(wallGridPositions, 3),
      );
      wallGridPositions.length = 0;
      const wallGrid = new THREE.LineSegments(
        wallGridGeometry,
        new THREE.LineBasicMaterial({
          color: THREE_PARK_WIREFRAME_COLOR,
          transparent: true,
          opacity: 0.22,
        }),
      );
      wallGrid.name = "terrain-island-wall-grid";
      wallGrid.renderOrder = 2;
      group.add(wallGrid);

      const bottomOutlineGeometry = new THREE.BufferGeometry();
      bottomOutlineGeometry.setAttribute(
        "position",
        new THREE.Float32BufferAttribute(bottomOutlinePositions, 3),
      );
      bottomOutlinePositions.length = 0;
      const bottomOutline = new THREE.LineSegments(
        bottomOutlineGeometry,
        new THREE.LineBasicMaterial({
          color: THREE_PARK_WIREFRAME_COLOR,
          transparent: true,
          opacity: 0.52,
        }),
      );
      bottomOutline.renderOrder = 3;
      group.add(bottomOutline);

      // For LandXML, avoid duplicating the complete TIN just to draw the flat
      // underside. Build the underside from each zone boundary instead. Older
      // Mapbox-derived terrain still supplies baseTriangles and keeps its path.
      if (Array.isArray(baseTriangles) && baseTriangles.length) {
        const basePositions = [];
        baseTriangles.forEach((triangle) => {
          triangle.forEach((point) => {
            basePositions.push(point.x, baseY, point.z);
          });
        });
        const baseGeometry = new THREE.BufferGeometry();
        baseGeometry.setAttribute(
          "position",
          new THREE.Float32BufferAttribute(basePositions, 3),
        );
        basePositions.length = 0;
        const baseMesh = new THREE.Mesh(
          baseGeometry,
          new THREE.MeshBasicMaterial({
            color: THREE_PARK_BASE_COLOR,
            transparent: true,
            opacity: 0.96,
            side: THREE.DoubleSide,
          }),
        );
        baseMesh.name = "terrain-island-base";
        group.add(baseMesh);
      } else {
        localParts.forEach((part) => {
          if (!part || !Array.isArray(part.outer) || part.outer.length < 3)
            return;
          const shape = new THREE.Shape();
          part.outer.forEach((point, index) => {
            if (index === 0) shape.moveTo(point.x, point.z);
            else shape.lineTo(point.x, point.z);
          });
          shape.closePath();
          (part.holes || []).forEach((holeRing) => {
            if (!Array.isArray(holeRing) || holeRing.length < 3) return;
            const hole = new THREE.Path();
            holeRing.forEach((point, index) => {
              if (index === 0) hole.moveTo(point.x, point.z);
              else hole.lineTo(point.x, point.z);
            });
            hole.closePath();
            shape.holes.push(hole);
          });
          const baseGeometry = new THREE.ShapeGeometry(shape);
          const position = baseGeometry.getAttribute("position");
          for (let index = 0; index < position.count; index += 1) {
            const x = position.getX(index);
            const z = position.getY(index);
            position.setXYZ(index, x, baseY, z);
          }
          position.needsUpdate = true;
          const baseMesh = new THREE.Mesh(
            baseGeometry,
            new THREE.MeshBasicMaterial({
              color: THREE_PARK_BASE_COLOR,
              transparent: true,
              opacity: 0.96,
              side: THREE.DoubleSide,
            }),
          );
          baseMesh.name = "terrain-island-base";
          group.add(baseMesh);
        });
      }

      this.addStandaloneBuildingMeshes(group, buildingFootprints || []);

      localParts.forEach((part) => {
        [part.outer, ...(part.holes || [])].forEach((ring, ringIndex) => {
          const linePoints = ring.map((point) => {
            const y = this.getTerrainPointHeight(
              pointMap,
              point,
              minimumElevation,
              verticalExaggeration,
            );
            return new THREE.Vector3(point.x, y + 0.1, point.z);
          });
          if (linePoints.length) linePoints.push(linePoints[0].clone());

          const lineGeometry = new THREE.BufferGeometry().setFromPoints(
            linePoints,
          );
          const lineMaterial = new THREE.LineBasicMaterial({
            color:
              ringIndex === 0
                ? THREE_PARK_BOUNDARY_COLOR
                : THREE_PARK_WIREFRAME_COLOR,
            transparent: true,
            opacity: ringIndex === 0 ? 0.78 : 0.42,
          });
          const line = new THREE.Line(lineGeometry, lineMaterial);
          line.renderOrder = 4;
          group.add(line);
        });
      });

      group.userData.maxDimension = maxDimension;
      group.userData.verticalExaggeration = verticalExaggeration;
      group.userData.rawElevationRange =
        Number(maximumElevation) - Number(minimumElevation);
      group.userData.islandWallDepth = islandWallDepth;
      group.userData.hasSatelliteTexture = false;
      group.userData.hasLandscapeData = modelData.hasLandscapeData !== false;
      group.userData.showTopSurface = shouldRenderTopSurface;
      return group;
    },

    syncThreeParkHostBounds() {
      const host = this.$refs.threeParkHost;
      const mapElement = this.$refs.map;
      if (!host || !mapElement) return;

      const rect = mapElement.getBoundingClientRect();
      host.style.left = `${rect.left}px`;
      host.style.top = `${rect.top}px`;
      host.style.width = `${rect.width}px`;
      host.style.height = `${rect.height}px`;
    },

    resizeStandaloneThreeRenderer() {
      if (
        !this.threeRenderer ||
        !this.threeCamera ||
        !this.$refs.threeParkHost
      ) {
        return;
      }

      const host = this.$refs.threeParkHost;
      const width = Math.max(1, host.clientWidth);
      const height = Math.max(1, host.clientHeight);
      this.threeRenderer.setSize(width, height, false);
      this.threeCamera.aspect = width / height;
      this.threeCamera.updateProjectionMatrix();
    },

    normaliseMapBearing(value) {
      const bearing = Number(value) || 0;
      return ((((bearing + 180) % 360) + 360) % 360) - 180;
    },

    captureMapboxViewState() {
      if (!this.$map) return null;

      try {
        const center = this.$map.getCenter();
        return {
          center: [Number(center.lng), Number(center.lat)],
          zoom: Number(this.$map.getZoom()),
          pitch: Number(this.$map.getPitch()),
          bearing: this.normaliseMapBearing(this.$map.getBearing()),
        };
      } catch (error) {
        return null;
      }
    },

    captureStandaloneThreeViewState() {
      if (!this.threeCamera || !this.threeControls) return null;

      const offset = this.threeCamera.position
        .clone()
        .sub(this.threeControls.target);
      const horizontalDistance = Math.hypot(offset.x, offset.z);
      const pitch = THREE.MathUtils.radToDeg(
        Math.atan2(horizontalDistance, Math.max(0.0001, offset.y)),
      );
      const bearing = THREE.MathUtils.radToDeg(Math.atan2(-offset.x, offset.z));
      const base = this.preservedMapViewState || {};

      return {
        ...base,
        pitch: Math.max(0, Math.min(85, pitch)),
        bearing: this.normaliseMapBearing(bearing),
      };
    },

    updateStandaloneThreeCompass() {
      const rose = this.$refs.threeCompassRose;
      if (!rose || !this.threeCamera || !this.threeControls) return;

      const state = this.captureStandaloneThreeViewState();
      const bearing = this.normaliseMapBearing(state ? state.bearing : 0);

      // Map bearing rotates the scene clockwise. Rotate the compass rose in the
      // opposite direction so its N arrow always points toward geographic north
      // on screen, regardless of how the user orbits the floating island.
      rose.style.transform = `rotate(${-bearing}deg)`;
    },

    preserveCurrentViewState() {
      const state = this.isStandaloneThreeMode
        ? this.captureStandaloneThreeViewState()
        : this.captureMapboxViewState();

      if (state) this.preservedMapViewState = state;
      return state;
    },

    getThreeCameraDirectionFromMapView(state, fallbackDirection) {
      if (!state) return fallbackDirection.clone().normalize();

      const pitch = THREE.MathUtils.degToRad(
        Math.max(1, Math.min(85, Number(state.pitch) || 0)),
      );
      const bearing = THREE.MathUtils.degToRad(
        this.normaliseMapBearing(state.bearing),
      );
      const horizontal = Math.sin(pitch);

      return new THREE.Vector3(
        -Math.sin(bearing) * horizontal,
        Math.cos(pitch),
        Math.cos(bearing) * horizontal,
      ).normalize();
    },

    applyMapboxViewState(state = this.preservedMapViewState, duration = 0) {
      if (!this.$map || !state) return;

      const options = {
        pitch: Math.max(0, Math.min(85, Number(state.pitch) || 0)),
        bearing: this.normaliseMapBearing(state.bearing),
        duration,
      };

      if (
        Array.isArray(state.center) &&
        state.center.length >= 2 &&
        state.center.every((value) => Number.isFinite(Number(value)))
      ) {
        options.center = [Number(state.center[0]), Number(state.center[1])];
      }
      if (Number.isFinite(Number(state.zoom))) {
        options.zoom = Number(state.zoom);
      }

      this.$map.easeTo(options);
    },

    getMapboxCameraStateForFeatures(features, maxZoom = 13) {
      if (
        !this.$map ||
        !this.mapboxgl ||
        !Array.isArray(features) ||
        !features.length ||
        typeof this.$map.cameraForBounds !== "function"
      ) {
        return null;
      }

      const bounds = new this.mapboxgl.LngLatBounds();
      let hasBounds = false;
      features.forEach((feature) => {
        if (!feature || !feature.geometry) return;
        this.eachCoordinate(feature.geometry.coordinates, (coord) => {
          if (
            Array.isArray(coord) &&
            coord.length >= 2 &&
            Number.isFinite(Number(coord[0])) &&
            Number.isFinite(Number(coord[1]))
          ) {
            bounds.extend([Number(coord[0]), Number(coord[1])]);
            hasBounds = true;
          }
        });
      });
      if (!hasBounds) return null;

      try {
        const camera = this.$map.cameraForBounds(bounds, {
          padding: 40,
          maxZoom,
          pitch: 0,
          bearing: 0,
        });
        if (!camera) return null;

        const center = camera.center || bounds.getCenter();
        return {
          center: [Number(center.lng), Number(center.lat)],
          zoom: Number.isFinite(Number(camera.zoom))
            ? Number(camera.zoom)
            : Number(maxZoom),
          pitch: 0,
          bearing: 0,
        };
      } catch (error) {
        return null;
      }
    },

    getDefaultResetCameraStateForCurrentMapContext() {
      if (this.activeViewMode === "project" && this.currentProjectId) {
        return this.getMapboxCameraStateForFeatures(
          this.getProjectFeaturesForId(this.currentProjectId),
          14,
        );
      }

      if (
        this.hasActiveSearchFilter() &&
        Array.isArray(this.activeSearchProjectIds) &&
        this.activeSearchProjectIds.length
      ) {
        const ids = this.activeSearchProjectIds
          .map((id) => this.normalizeProjectId(id))
          .filter(Boolean);
        const features = this.allProjectFeatures.filter((feature) =>
          ids.includes(
            this.normalizeProjectId(
              feature.properties.parent_id ?? feature.properties.id,
            ),
          ),
        );
        return this.getMapboxCameraStateForFeatures(features, 13);
      }

      if (this.activeViewMode === "near" && this.nearProjectId) {
        return this.getMapboxCameraStateForFeatures(
          this.getProjectFeaturesForId(this.nearProjectId),
          13,
        );
      }

      return {
        center: this.getDefaultCenter(),
        zoom: Number(this.zoom || 10),
        pitch: 0,
        bearing: 0,
      };
    },

    clearMapCameraRestoreTimers() {
      if (!Array.isArray(this.mapCameraRestoreTimers)) {
        this.mapCameraRestoreTimers = [];
        return;
      }

      this.mapCameraRestoreTimers.forEach((timerId) => {
        window.clearTimeout(timerId);
      });
      this.mapCameraRestoreTimers = [];
    },

    clearSatelliteTerrainRestoreTimers() {
      if (!Array.isArray(this.satelliteTerrainRestoreTimers)) {
        this.satelliteTerrainRestoreTimers = [];
        return;
      }

      this.satelliteTerrainRestoreTimers.forEach((timerId) => {
        window.clearTimeout(timerId);
      });
      this.satelliteTerrainRestoreTimers = [];
    },

    hardRefreshSatelliteTerrain3D() {
      if (
        !this.$map ||
        this.activeBaseMapMode !== "satellite" ||
        this.isStandaloneThreeMode ||
        !this.$map.isStyleLoaded ||
        !this.$map.isStyleLoaded()
      ) {
        return;
      }

      try {
        this.showMapboxRenderer();
        if (typeof this.$map.resize === "function") this.$map.resize();

        if (!this.$map.getSource(MAPBOX_TERRAIN_SOURCE_ID)) {
          this.$map.addSource(MAPBOX_TERRAIN_SOURCE_ID, {
            type: "raster-dem",
            url: "mapbox://mapbox.mapbox-terrain-dem-v1",
            tileSize: 512,
            maxzoom: 14,
          });
        }

        // Force Mapbox to rebuild the terrain mesh. This fixes the state where
        // returning from the standalone 3D reset could leave Satellite imagery
        // draped on a visually flat plane even though buildings were still 3D.
        try {
          this.$map.setTerrain(null);
        } catch (error) {
          // Some style states reject clearing terrain briefly while loading.
        }

        this.$map.setTerrain({
          source: MAPBOX_TERRAIN_SOURCE_ID,
          exaggeration: MAPBOX_3D_TERRAIN_EXAGGERATION,
        });
        this.setMapboxStandard3DOptions();
        this.addCustom3DBuildingsLayer();
        if (typeof this.$map.triggerRepaint === "function") {
          this.$map.triggerRepaint();
        }
      } catch (error) {
        console.warn("Satellite 3D terrain could not be refreshed:", error);
      }
    },

    scheduleSatelliteTerrainRestore({ hardRefresh = false } = {}) {
      this.clearSatelliteTerrainRestoreTimers();
      if (hardRefresh) this.pendingSatelliteTerrainHardRefresh = true;

      [0, 120, 360, 760, 1400, 2300].forEach((delay, index, delays) => {
        const timerId = window.setTimeout(() => {
          if (
            this.activeBaseMapMode === "satellite" &&
            !this.isStandaloneThreeMode &&
            this.$map &&
            this.$map.isStyleLoaded &&
            this.$map.isStyleLoaded()
          ) {
            if (this.pendingSatelliteTerrainHardRefresh || hardRefresh) {
              this.hardRefreshSatelliteTerrain3D();
            } else {
              this.applyThreeDimensionalMapSettings();
            }
          }

          if (index === delays.length - 1) {
            this.pendingSatelliteTerrainHardRefresh = false;
          }
        }, delay);
        this.satelliteTerrainRestoreTimers.push(timerId);
      });
    },

    restoreMapCameraStateImmediately(state = this.pendingBaseMapCameraState) {
      if (!this.$map || !state) return;

      const options = {
        pitch: Math.max(0, Math.min(85, Number(state.pitch) || 0)),
        bearing: this.normaliseMapBearing(state.bearing),
      };

      if (
        Array.isArray(state.center) &&
        state.center.length >= 2 &&
        state.center.every((value) => Number.isFinite(Number(value)))
      ) {
        options.center = [Number(state.center[0]), Number(state.center[1])];
      }
      if (Number.isFinite(Number(state.zoom))) {
        options.zoom = Number(state.zoom);
      }

      try {
        this.$map.stop();
        this.$map.jumpTo(options);
      } catch (error) {
        // The style may still be replacing its internal camera transform. A
        // later scheduled restore will apply the same state again.
      }
    },

    lockCameraAcrossBaseMapStyleChange(state) {
      if (!state) return;

      this.pendingBaseMapCameraState = {
        ...state,
        center: Array.isArray(state.center) ? [...state.center] : state.center,
      };
      this.preservedMapViewState = this.pendingBaseMapCameraState;
      this.isBaseMapStyleSwitching = true;
      this.clearMapCameraRestoreTimers();

      const restore = () => {
        this.restoreMapCameraStateImmediately(this.pendingBaseMapCameraState);
      };

      restore();
      window.requestAnimationFrame(() => {
        restore();
        window.requestAnimationFrame(restore);
      });

      [60, 180, 420, 850].forEach((delay, index, delays) => {
        const timerId = window.setTimeout(() => {
          restore();
          if (index === delays.length - 1) {
            this.isBaseMapStyleSwitching = false;
            this.pendingBaseMapCameraState = null;
            this.clearMapCameraRestoreTimers();
          }
        }, delay);
        this.mapCameraRestoreTimers.push(timerId);
      });
    },

    fitStandaloneThreeCamera() {
      if (!this.threeParkGroup || !this.threeCamera || !this.threeControls) {
        return;
      }

      const box = new THREE.Box3().setFromObject(this.threeParkGroup);
      const sphere = new THREE.Sphere();
      box.getBoundingSphere(sphere);
      const radius = Math.max(18, sphere.radius);
      const verticalFov = (Number(this.threeCamera.fov) * Math.PI) / 180;
      const distance =
        (radius / Math.sin(Math.max(0.2, verticalFov / 2))) * 0.9;
      const defaultDirection = new THREE.Vector3(1, 0.9, 1).normalize();
      const direction = this.getThreeCameraDirectionFromMapView(
        this.preservedMapViewState,
        defaultDirection,
      );
      const resetMapViewState =
        this.getDefaultResetCameraStateForCurrentMapContext() || {
          pitch: 0,
          bearing: 0,
        };
      const resetDirection = this.getThreeCameraDirectionFromMapView(
        resetMapViewState,
        defaultDirection,
      );
      const target = sphere.center.clone();
      target.y += radius * 0.03;

      this.threeCamera.near = Math.max(0.02, Math.min(0.2, radius / 4000));
      this.threeCamera.far = Math.max(3000, distance + radius * 12);
      this.threeCamera.position.copy(
        target.clone().add(direction.multiplyScalar(distance)),
      );
      this.threeCamera.updateProjectionMatrix();

      this.threeControls.target.copy(target);
      // The former radius * 0.28 limit stopped users far above the park. This
      // much smaller limit allows wheel-zooming down to an individual tree.
      this.threeControls.minDistance = Math.max(0.9, radius * 0.006);
      this.threeControls.maxDistance = radius * 6;
      this.threeControls.update();

      this.threeDefaultCameraState = {
        position: target.clone().add(resetDirection.multiplyScalar(distance)),
        target: target.clone(),
        mapViewState: resetMapViewState,
      };
    },

    resetThreeParkCamera() {
      if (
        !this.threeDefaultCameraState ||
        !this.threeCamera ||
        !this.threeControls
      ) {
        return;
      }

      this.threeCamera.position.copy(this.threeDefaultCameraState.position);
      this.threeControls.target.copy(this.threeDefaultCameraState.target);
      this.threeControls.update();

      if (this.threeDefaultCameraState.mapViewState) {
        this.preservedMapViewState = {
          ...this.threeDefaultCameraState.mapViewState,
        };
        this.lastStandaloneThreeResetMapViewState = {
          ...this.threeDefaultCameraState.mapViewState,
        };
      }

      // When the user returns to Satellite after resetting the standalone 3D
      // camera, refresh the Mapbox terrain mesh at the configured exaggeration.
      this.pendingSatelliteTerrainHardRefresh = true;
    },

    zoomStandaloneThree(factor) {
      if (!this.threeCamera || !this.threeControls) return;

      const offset = this.threeCamera.position
        .clone()
        .sub(this.threeControls.target)
        .multiplyScalar(factor);
      const distance = offset.length();
      const minimum = Number(this.threeControls.minDistance || 1);
      const maximum = Number(this.threeControls.maxDistance || Infinity);
      const clampedDistance = Math.min(maximum, Math.max(minimum, distance));
      offset.setLength(clampedDistance);
      this.threeCamera.position.copy(
        this.threeControls.target.clone().add(offset),
      );
      this.threeControls.update();
    },

    makeStandaloneGroupUnlitExactColors(group) {
      if (!group || typeof group.traverse !== "function") return;
      const converted = new Map();

      const convertMaterial = (material) => {
        if (!material) return material;
        if (Array.isArray(material)) {
          return material.map((item) => convertMaterial(item));
        }
        if (
          material.isMeshBasicMaterial ||
          material.isLineBasicMaterial ||
          material.isLineDashedMaterial ||
          material.isPointsMaterial ||
          material.isSpriteMaterial ||
          material.isShaderMaterial
        ) {
          return material;
        }
        if (!material.isMaterial) return material;
        if (converted.has(material.uuid)) return converted.get(material.uuid);

        const basic = new THREE.MeshBasicMaterial({
          color: material.color
            ? material.color.clone()
            : new THREE.Color(0xffffff),
          map: material.map || null,
          alphaMap: material.alphaMap || null,
          transparent: Boolean(material.transparent),
          opacity: Number.isFinite(Number(material.opacity))
            ? Number(material.opacity)
            : 1,
          alphaTest: Number.isFinite(Number(material.alphaTest))
            ? Number(material.alphaTest)
            : 0,
          side: material.side,
          depthTest: material.depthTest !== false,
          depthWrite: material.depthWrite !== false,
          blending: material.blending,
          vertexColors: Boolean(material.vertexColors),
          wireframe: Boolean(material.wireframe),
          fog: Boolean(material.fog),
        });
        basic.name = `${material.name || material.type || "material"}-unlit`;
        basic.visible = material.visible !== false;
        basic.colorWrite = material.colorWrite !== false;
        basic.polygonOffset = Boolean(material.polygonOffset);
        basic.polygonOffsetFactor = Number(material.polygonOffsetFactor || 0);
        basic.polygonOffsetUnits = Number(material.polygonOffsetUnits || 0);
        basic.dithering = false;
        basic.toneMapped = false;
        converted.set(material.uuid, basic);
        return basic;
      };

      group.traverse((object) => {
        if (!object || !object.material) return;
        object.material = convertMaterial(object.material);
        object.castShadow = false;
        object.receiveShadow = false;
      });
    },

    async initialiseStandaloneThreeScene(modelData) {
      this.destroyStandaloneThreeScene();
      this.beginStandaloneThreeLoadSession();
      this.syncThreeParkHostBounds();

      const host = this.$refs.threeParkHost;
      if (!host) {
        throw new Error("The 3D terrain container is unavailable.");
      }

      const reportedDeviceMemory =
        typeof navigator !== "undefined"
          ? Number(navigator.deviceMemory) || 0
          : 0;
      const preferLowMemoryRenderer =
        reportedDeviceMemory > 0 && reportedDeviceMemory <= 8;
      const renderer = new THREE.WebGLRenderer({
        // Chrome reports deviceMemory in coarse buckets (commonly capped at
        // 8 GB). On those devices MSAA can multiply the standalone framebuffer
        // allocation, so prefer the lower-memory canvas configuration.
        antialias: !preferLowMemoryRenderer,
        alpha: false,
        powerPreference: "high-performance",
      });
      renderer.domElement.className = "three-park-canvas";
      renderer.setClearColor(THREE_PARK_BACKGROUND, 1);
      // A 2x drawing buffer uses four times the framebuffer memory of 1x and
      // provides little benefit for this dense, line-heavy GIS scene. Cap the
      // standalone renderer at 1.25x to reduce GPU memory and fill-rate without
      // making labels or close-up path details visibly soft.
      renderer.setPixelRatio(
        Math.min(Number(window.devicePixelRatio) || 1, 1.25),
      );
      if (THREE.SRGBColorSpace) {
        renderer.outputColorSpace = THREE.SRGBColorSpace;
      } else if (THREE.sRGBEncoding) {
        renderer.outputEncoding = THREE.sRGBEncoding;
      }
      if (THREE.NoToneMapping !== undefined) {
        renderer.toneMapping = THREE.NoToneMapping;
      }
      renderer.toneMappingExposure = 1;
      if (renderer.shadowMap) {
        renderer.shadowMap.enabled = false;
      }

      const scene = new THREE.Scene();
      scene.background = new THREE.Color(THREE_PARK_BACKGROUND);

      const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 10000);
      const controls = new OrbitControls(camera, renderer.domElement);
      controls.enableDamping = true;
      controls.dampingFactor = 0.08;
      controls.zoomSpeed = THREE_PARK_MOUSE_WHEEL_ZOOM_SPEED;
      controls.zoomToCursor = true;
      controls.enablePan = true;
      // World-plane panning keeps camera/target elevation fixed while the
      // left mouse button navigates horizontally across the park.
      controls.screenSpacePanning = false;
      controls.minPolarAngle = 0.02;
      controls.maxPolarAngle = Math.PI * 0.49;
      controls.mouseButtons = {
        LEFT: THREE.MOUSE.PAN,
        // Middle/right mouse input belongs exclusively to threeCameraControls.js.
        // Keeping OrbitControls disabled for these buttons prevents the legacy
        // orbit/drag behaviour from fighting the custom fixed-position camera.
        MIDDLE: null,
        RIGHT: null,
      };
      controls.touches = {
        ONE: THREE.TOUCH.PAN,
        TWO: THREE.TOUCH.DOLLY_ROTATE,
      };
      controls.addEventListener("start", () => {
        this.lastStandaloneThreeResetMapViewState = null;
      });

      const terrainContainer = new THREE.Group();
      terrainContainer.name = "standalone-terrain-container";

      const beforeModelData = modelData.terrainBeforeData || modelData;
      const afterModelData = modelData.terrainAfterData || modelData;

      // Only allocate the terrain that is initially visible. Terrain (Before)
      // and Terrain (After) can each contain hundreds of thousands of indexed
      // triangles; constructing both duplicated position/UV/normal GPU buffers
      // and ran computeVertexNormals() twice before the first frame. The other
      // terrain remains selectable and is created lazily on its first click.
      const initialTerrainMode =
        this.threeTerrainMode === "before" ? "before" : "after";
      const initialTerrainGroup = await this.createStandaloneTerrainGroup(
        initialTerrainMode === "before" ? beforeModelData : afterModelData,
        this.threeParkBuildToken,
      );
      initialTerrainGroup.name = `standalone-terrain-${initialTerrainMode}`;
      terrainContainer.add(initialTerrainGroup);
      this.makeStandaloneGroupUnlitExactColors(terrainContainer);
      scene.add(terrainContainer);

      host.appendChild(renderer.domElement);

      this.threeRenderer = renderer;
      this.threeScene = scene;
      this.threeCamera = camera;
      this.threeControls = controls;
      this.threeParkGroup = terrainContainer;
      this.threeParkModelData = modelData;
      // All standalone 3D keyboard/right-mouse/middle-mouse camera input is
      // handled by this module. Map.vue must not install a second keyboard
      // listener for WASD/QE/arrow keys.
      this.threeCameraControls = createThreeCameraControls({
        camera,
        controls,
        domElement: renderer.domElement,
        onCameraChanged: () => {
          this.lastStandaloneThreeResetMapViewState = null;
        },
      });
      // Structure labels are populated from the ArcGIS GeoJSON when the
      // Structures layer loads. The GIS department's labels are authoritative.
      this.threeStructureAnnotations = [];
      this.threeLayerGroups = {
        terrain: terrainContainer,
        terrainBefore:
          initialTerrainMode === "before" ? initialTerrainGroup : null,
        terrainAfter:
          initialTerrainMode === "after" ? initialTerrainGroup : null,
        paths: null,
        water: null,
        structures: null,
        vegetation: null,
        tse: null,
      };
      this.applyStandaloneTerrainDisplayMode(
        this.threeTerrainMode,
        this.threeLayerVisibility.terrain,
      );

      this.resizeStandaloneThreeRenderer();
      this.fitStandaloneThreeCamera();
      this.$nextTick(() => this.updateStandaloneThreeCompass());

      let previousFrameTime = null;
      const animate = (frameTime) => {
        if (!this.threeRenderer || !this.threeScene || !this.threeCamera) {
          return;
        }

        const currentFrameTime = Number.isFinite(Number(frameTime))
          ? Number(frameTime)
          : typeof performance !== "undefined"
            ? performance.now()
            : Date.now();
        const deltaSeconds =
          previousFrameTime == null
            ? 0
            : Math.max(0, (currentFrameTime - previousFrameTime) / 1000);
        previousFrameTime = currentFrameTime;

        this.threeParkAnimationFrame = window.requestAnimationFrame(animate);
        if (this.threeCameraControls) {
          this.threeCameraControls.update(deltaSeconds);
        }
        if (this.threeControls) this.threeControls.update();
        this.updateStandaloneThreeCompass();
        this.updateStandaloneStructureLabelOverlay();
        this.updateStandaloneTreeLabelOverlay();
        this.updateStandaloneShrubLabelOverlay();
        this.updateStandaloneGroundCoverLabelOverlay();
        this.updateStandaloneVegetationLineLod();
        this.threeRenderer.render(this.threeScene, this.threeCamera);
      };
      animate();

      if (typeof ResizeObserver !== "undefined") {
        this.threeParkResizeObserver = new ResizeObserver(() => {
          this.syncThreeParkHostBounds();
          this.resizeStandaloneThreeRenderer();
        });
        this.threeParkResizeObserver.observe(host);
      }
    },

    beginStandaloneThreeLoadSession() {
      if (this._threeParkAbortController) {
        this._threeParkAbortController.abort();
      }
      this._threeParkAbortController =
        typeof AbortController !== "undefined" ? new AbortController() : null;
      if (!this.threeProjectGisCache) {
        this.threeProjectGisCache = new Map();
      }
    },

    getStandaloneThreeLoadSignal() {
      return this._threeParkAbortController
        ? this._threeParkAbortController.signal
        : undefined;
    },

    disposeStandaloneThreeTextureCache(cache) {
      if (!cache || typeof cache.forEach !== "function") return;

      const disposeTexture = (value) => {
        const texture = value && value.texture ? value.texture : value;
        if (texture && texture.isTexture && texture.dispose) {
          texture.dispose();
        }
      };

      cache.forEach((value) => {
        if (value && typeof value.then === "function") {
          // Reference images can still be decoding when the user leaves 3D.
          // Dispose the eventual texture as soon as that pending load settles.
          value.then(disposeTexture).catch(() => {});
        } else {
          disposeTexture(value);
        }
      });
      if (typeof cache.clear === "function") cache.clear();
    },

    releaseStandaloneThreeSessionAssets() {
      this._threeAssetCacheGeneration =
        (Number(this._threeAssetCacheGeneration) || 0) + 1;

      this.disposeStandaloneThreeTextureCache(
        this._threePathReferenceTextureCache,
      );
      this.disposeStandaloneThreeTextureCache(this._threeBuildingTextureCache);
      this.disposeStandaloneThreeTextureCache(this._threeReferenceTextureCache);
      this._threePathReferenceTextureCache = null;
      this._threeBuildingTextureCache = null;
      this._threeReferenceTextureCache = null;

      // Catalogue rows can contain many image paths and metadata records. They
      // are cheap to reload on the next 3D session and should not remain on a
      // Street/Satellite map after the WebGL scene has been released.
      this.threePathCatalogRows = [];
      this.threePathCatalogLoaded = false;
      this._threePathCatalogPromise = null;
      this._threePathCatalogMatchCache = null;
      this.threePlantCatalogRows = [];
      this.threePlantCatalogLoaded = false;
      this.threePlantCatalogLoading = false;
      this._threePlantCatalogPromise = null;
      this.threeBuildingCatalogRows = [];
      this.threeBuildingCatalogLoaded = false;
      this.threeBuildingCatalogLoading = false;
      this._threeBuildingCatalogPromise = null;
    },

    destroyStandaloneThreeScene() {
      if (this._threeParkAbortController) {
        this._threeParkAbortController.abort();
        this._threeParkAbortController = null;
      }

      if (this.threeParkAnimationFrame != null) {
        window.cancelAnimationFrame(this.threeParkAnimationFrame);
        this.threeParkAnimationFrame = null;
      }

      if (this.threeParkResizeObserver) {
        this.threeParkResizeObserver.disconnect();
        this.threeParkResizeObserver = null;
      }

      if (this.threeCameraControls) {
        this.threeCameraControls.dispose();
        this.threeCameraControls = null;
      }

      if (this.threeControls) {
        this.threeControls.dispose();
        this.threeControls = null;
      }

      if (this.threeScene) {
        const disposedSceneGeometries = new Set();
        const disposedSceneMaterials = new Set();
        const disposedSceneTextures = new Set();
        this.threeScene.traverse((object) => {
          if (
            object.geometry &&
            object.geometry.dispose &&
            !disposedSceneGeometries.has(object.geometry)
          ) {
            disposedSceneGeometries.add(object.geometry);
            object.geometry.dispose();
          }

          const materials = Array.isArray(object.material)
            ? object.material
            : object.material
              ? [object.material]
              : [];

          materials.forEach((material) => {
            Object.keys(material || {}).forEach((key) => {
              const value = material[key];
              if (
                value &&
                value.isTexture &&
                value.dispose &&
                !disposedSceneTextures.has(value)
              ) {
                disposedSceneTextures.add(value);
                value.dispose();
              }
            });

            if (material && material.uniforms) {
              Object.keys(material.uniforms).forEach((uniformKey) => {
                const uniform = material.uniforms[uniformKey];
                const value = uniform && uniform.value;
                if (
                  value &&
                  value.isTexture &&
                  value.dispose &&
                  !disposedSceneTextures.has(value)
                ) {
                  disposedSceneTextures.add(value);
                  value.dispose();
                }
              });
            }

            if (
              material &&
              material.dispose &&
              !disposedSceneMaterials.has(material)
            ) {
              disposedSceneMaterials.add(material);
              material.dispose();
            }
          });
        });
      }

      if (this.threeRenderer) {
        const canvas = this.threeRenderer.domElement;
        if (
          this.threeRenderer.renderLists &&
          typeof this.threeRenderer.renderLists.dispose === "function"
        ) {
          this.threeRenderer.renderLists.dispose();
        }
        this.threeRenderer.dispose();
        if (typeof this.threeRenderer.forceContextLoss === "function") {
          this.threeRenderer.forceContextLoss();
        }
        if (canvas && canvas.parentNode) {
          canvas.parentNode.removeChild(canvas);
        }
      }

      this.releaseStandaloneThreeSessionAssets();

      const stairMaskTexture =
        this.threeParkModelData &&
        this.threeParkModelData.terrainAfterData &&
        this.threeParkModelData.terrainAfterData.stairCutoutMaskTexture
          ? this.threeParkModelData.terrainAfterData.stairCutoutMaskTexture
          : this.threeParkModelData &&
              this.threeParkModelData.stairCutoutMaskTexture
            ? this.threeParkModelData.stairCutoutMaskTexture
            : null;
      if (stairMaskTexture && typeof stairMaskTexture.dispose === "function") {
        stairMaskTexture.dispose();
      }

      const pedestrianApronMaskTexture =
        this.threeParkModelData &&
        this.threeParkModelData.terrainAfterData &&
        this.threeParkModelData.terrainAfterData
          .muanisiyahPedestrianApronMaskTexture
          ? this.threeParkModelData.terrainAfterData
              .muanisiyahPedestrianApronMaskTexture
          : this.threeParkModelData &&
              this.threeParkModelData.muanisiyahPedestrianApronMaskTexture
            ? this.threeParkModelData.muanisiyahPedestrianApronMaskTexture
            : null;
      if (
        pedestrianApronMaskTexture &&
        typeof pedestrianApronMaskTexture.dispose === "function"
      ) {
        pedestrianApronMaskTexture.dispose();
      }

      this.threeVegetationLoadToken += 1;
      this.threeSatelliteGroundLoadToken += 1;
      this.threeCompactedGroundLoadToken += 1;
      if (
        this.threeSatelliteGroundTexture &&
        typeof this.threeSatelliteGroundTexture.dispose === "function"
      ) {
        this.threeSatelliteGroundTexture.dispose();
      }
      if (
        this.threeCompactedGroundTexture &&
        typeof this.threeCompactedGroundTexture.dispose === "function"
      ) {
        this.threeCompactedGroundTexture.dispose();
      }
      this.threeSatelliteGroundTexture = null;
      this.threeCompactedGroundTexture = null;
      this.threeStructureAnnotations = [];
      this.threeVisibleStructureLabels = [];
      this.threeTreeAnnotations = [];
      this.threeVisibleTreeLabels = [];
      this.threeTreeLabelVisibility = {};
      this.threeTreeLabelOverlaySignature = "";
      this.threeShrubAnnotations = [];
      this.threeVisibleShrubLabels = [];
      this.threeShrubLabelVisibility = {};
      this.threeShrubLabelOverlaySignature = "";
      this.threeGroundCoverAnnotations = [];
      this.threeVisibleGroundCoverLabels = [];
      this.threeGroundCoverLabelVisibility = {};
      this.threeGroundCoverLabelOverlaySignature = "";
      this.threeToolState.structureLabels = false;
      this.threeToolState.conceptPaths = false;
      this.threeToolState.treeTypes = false;
      this.threeToolState.shrubTypes = false;
      this.threeToolState.groundCoverTypes = false;
      this.threeTreeTypeLoading = false;
      this.threeTreeTypeStats = [];
      this.closeStandalonePlantImageViewer();
      this.threeShrubTypeLoading = false;
      this.threeShrubTypeStats = [];
      this.threeGroundCoverTypeLoading = false;
      this.threeGroundCoverTypeStats = [];
      this.threeRenderer = null;
      this.threeScene = null;
      this.threeCamera = null;
      this.threeParkGroup = null;
      this.threeParkModelData = null;
      this.threeLayerGroups = {
        terrain: null,
        terrainBefore: null,
        terrainAfter: null,
        paths: null,
        water: null,
        structures: null,
        vegetation: null,
        tse: null,
      };
      this.threeDefaultCameraState = null;
      this.threeProjectGisData = null;
      this.threeProjectStairGisData = null;
      this.threePrecomputedLandXmlCadAlignment = null;
      // Do not retain a previous park's parsed combined GeoJSON after leaving
      // standalone 3D. Large CAD-derived park files can otherwise stay alive in
      // memory through this Map even after all Three.js GPU resources are gone.
      // The active 3D session still reuses the cache while its layer checkboxes
      // are being toggled; it is cleared only when the scene is destroyed.
      if (
        this.threeProjectGisCache &&
        typeof this.threeProjectGisCache.clear === "function"
      ) {
        this.threeProjectGisCache.clear();
      }
      this.threeProjectGisCache = null;
      this.threeProjectGisUrl = "";
      this.threeProjectGisFallbackLayer = "";
      this.threeProjectGisLoadError = "";
    },

    suspendMapboxRendererForStandaloneThree() {
      if (!this.$map) return;

      this.suspendMapStyleRestoration = true;
      this.mapboxRendererSuspended = true;
      this.unbindProjectLayerEvents();

      // Do not call map.stop() here. Stopping the hidden Mapbox renderer while
      // terrain tiles are active can leave Satellite mode visually flat after
      // returning from the standalone Three.js view. Hiding the map element is
      // enough because the Three.js canvas receives all pointer events in 3D.

      // Do not remove Mapbox terrain or replace the style with a blank style.
      // Keeping the Satellite style alive prevents the Satellite terrain from
      // returning flat after the user resets the standalone Three.js 3D view.
      const mapElement = this.$refs.map;
      if (mapElement) {
        mapElement.style.visibility = "hidden";
        mapElement.style.pointerEvents = "none";
      }
    },

    async enterStandaloneThreeMode() {
      if (!this.shouldShowThreeParkLayer()) return;

      this.resetStandaloneThreeLayerFilters();

      const existingThreeState = this.captureStandaloneThreeViewState();
      if (existingThreeState) {
        this.preservedMapViewState = existingThreeState;
      }

      const buildToken = this.threeParkBuildToken + 1;
      this.threeParkBuildToken = buildToken;
      this.threeParkLoading = true;
      this.threeParkError = "";
      this.destroyStandaloneThreeScene();
      this.beginStandaloneThreeLoadSession();

      await new Promise((resolve) => this.$nextTick(resolve));
      this.syncThreeParkHostBounds();

      try {
        // Heavy Three.js code is intentionally fetched only now, after the user
        // has selected the 3D button. Street/Satellite pages never execute this.
        await loadStandaloneThreeRuntimeDependencies();

        if (
          buildToken !== this.threeParkBuildToken ||
          !this.shouldShowThreeParkLayer()
        ) {
          return;
        }

        // GIS content is optional for constructing the base terrain shell. If
        // the GIS URL is temporarily unavailable, keep building Terrain
        // (before)/(after) instead of replacing the whole 3D view with an error.
        try {
          await this.prepareStandaloneProjectGis();
        } catch (gisError) {
          this.threeProjectGisLoadError =
            gisError && gisError.message
              ? String(gisError.message)
              : "The configured GIS data could not be loaded.";
          console.warn(
            "Standalone GIS data could not be prepared; continuing with the terrain shell.",
            gisError,
          );
        }
        if (
          buildToken !== this.threeParkBuildToken ||
          !this.shouldShowThreeParkLayer()
        ) {
          return;
        }

        const parts = this.getProjectTerrainPolygonParts();
        if (!parts.length) {
          throw new Error(
            "This project does not contain a polygon geometry that can be rendered in 3D.",
          );
        }

        const bounds = this.getTerrainPartsBounds(parts);
        const origin = this.getTerrainOrigin(bounds);
        if (!bounds || !origin) {
          throw new Error("The project geometry coordinates are invalid.");
        }

        // The combined park GeoJSON is useful here only for CAD<->WGS84 alignment,
        // sub-layer discovery and the tiny subset of stair lines used by the terrain
        // cut-out pre-pass. Do NOT keep the entire parsed GeoJSON alive while a
        // 20-40 MB Civil 3D LandXML DOM and million-vertex terrain are allocated.
        // This is especially important for King Abdullah Park's four-zone surface.
        this.threePrecomputedLandXmlCadAlignment =
          this.getStandaloneLandXmlCadAlignment(
            origin,
            this.threeProjectGisData,
          );

        if (
          this.threeProjectGisData &&
          Array.isArray(this.threeProjectGisData.features)
        ) {
          const stairFeatures = this.threeProjectGisData.features.filter(
            (feature) => this.isStandaloneActualPathStairFeature(feature),
          );
          this.threeProjectStairGisData = stairFeatures.length
            ? { type: "FeatureCollection", features: stairFeatures }
            : null;
        } else {
          this.threeProjectStairGisData = null;
        }

        // Sub-layer availability has already been derived by prepareStandaloneProjectGis().
        // Release both references to the large FeatureCollection before LandXML parsing.
        this.threeProjectGisData = null;
        if (
          this.threeProjectGisCache &&
          typeof this.threeProjectGisCache.clear === "function"
        ) {
          this.threeProjectGisCache.clear();
        }
        // Give the browser a real event-loop/GC opportunity before allocating the TIN.
        await new Promise((resolve) => setTimeout(resolve, 32));

        // Mapbox DEM sampling improves Terrain (before), but it is not a
        // requirement for opening the 3D project. If DEM setup is unavailable,
        // buildStandaloneTerrainData() below already falls back to a flat shell.
        try {
          await this.ensureTerrainSamplingReady(bounds);
        } catch (terrainSamplingError) {
          console.warn(
            "Mapbox terrain sampling was unavailable; continuing with the flat terrain fallback.",
            terrainSamplingError,
          );
        }
        if (
          buildToken !== this.threeParkBuildToken ||
          !this.shouldShowThreeParkLayer()
        ) {
          return;
        }

        // Build two genuinely different terrain models:
        // - Terrain (before): Mapbox's existing-ground elevation model.
        // - Terrain (after): the Civil 3D LandXML design/as-built surface.
        // Previously buildStandaloneTerrainData() automatically preferred
        // LandXML, so both checkboxes pointed at the same model.
        const terrainBeforeData = await this.buildStandaloneTerrainData(
          parts,
          origin,
          bounds,
          buildToken,
          false,
        );
        if (
          buildToken !== this.threeParkBuildToken ||
          !this.shouldShowThreeParkLayer()
        ) {
          return;
        }

        const landscapeUrls = this.getStandaloneProjectLandscapeUrls();

        // Keep Terrain (after) selectable even when the project has no
        // landscape value, but do not copy the Terrain (before) floor into it.
        // The open top makes the missing proposed/as-built surface obvious to
        // the viewer instead of incorrectly suggesting that after data exists.
        let terrainAfterData = {
          ...terrainBeforeData,
          landscapeUrl: "",
          hasLandscapeData: false,
          showTopSurface: false,
        };

        if (landscapeUrls.length) {
          try {
            const loadedTerrainAfterData =
              await this.buildStandaloneTerrainDataFromLandXml(
                landscapeUrls,
                origin,
                bounds,
                buildToken,
              );

            terrainAfterData = {
              ...loadedTerrainAfterData,
              hasLandscapeData: true,
              showTopSurface: true,
            };
          } catch (error) {
            console.warn(
              "LandXML Terrain (after) could not be used; showing an open Terrain (after) model because no valid after surface is available.",
              error,
            );
          }
        }

        terrainBeforeData.hasLandscapeData = true;
        terrainBeforeData.showTopSurface = true;

        // Mapbox buildings must use the project-polygon clipping produced by
        // Terrain (before). The LandXML boundary can be larger than the park and
        // must never be used to admit surrounding Mapbox buildings.
        terrainAfterData.buildingFootprints = Array.isArray(
          terrainBeforeData.buildingFootprints,
        )
          ? terrainBeforeData.buildingFootprints
          : [];

        // Authored parks immediately construct several draped GIS layers and
        // stair profiles. Build their shared elevation lookup cooperatively now
        // so the first layer cannot trigger one long synchronous TIN-index pass.
        if (
          this.threeProjectStairGisData ||
          this.isStandaloneDefaultLayersParkActive()
        ) {
          await this.prepareStandaloneTerrainHeightIndex(
            terrainAfterData,
            buildToken,
          );
        }

        // Stair clearance is handled as a VISUAL CUTOUT only. Never deform the
        // Civil 3D LandXML/TIN to match the stair renderer: changing those TIN
        // vertices can pull large connected terrain triangles up/down and make
        // the whole park look torn or earthquake-damaged.
        //
        // Instead, reconstruct each stair run once and keep the original
        // Terrain (After) elevations completely untouched. A Terrain/Path cutout
        // is created from every tread rectangle actually emitted by the stair
        // renderer. Handrail eligibility is a separate rule (>=10 steps) and must
        // never suppress the Terrain (After) / Pedestrian Space hole for a short
        // real staircase such as the six-step Muanisiyah runs.
        delete terrainAfterData.stairTerrainAdjustmentProfiles;
        terrainAfterData.stairSurfaceCutoutProfiles =
          this.buildStandaloneStairTerrainAdjustmentProfiles(
            this.threeProjectStairGisData || this.threeProjectGisData,
            terrainAfterData,
            terrainBeforeData,
          );
        terrainAfterData.stairCutoutMaskTexture =
          this.createStandaloneStairCutoutMaskTexture(terrainAfterData);
        terrainAfterData.stairCutoutMaskBounds =
          terrainAfterData.stairCutoutMaskTexture &&
          terrainAfterData.stairCutoutMaskTexture.userData
            ? terrainAfterData.stairCutoutMaskTexture.userData.stairMaskBounds
            : null;
        // Profiles and the compact mask now contain everything the renderer
        // needs. Do not retain the duplicate stair-only GeoJSON coordinates.
        this.threeProjectStairGisData = null;
        console.info("Terrain (After) stair surface cutouts:", {
          staircaseProfileCount: Array.isArray(
            terrainAfterData.stairSurfaceCutoutProfiles,
          )
            ? terrainAfterData.stairSurfaceCutoutProfiles.length
            : 0,
          textureMaskBytes:
            terrainAfterData.stairCutoutMaskTexture &&
            terrainAfterData.stairCutoutMaskTexture.userData
              ? Number(
                  terrainAfterData.stairCutoutMaskTexture.userData.byteLength ||
                    0,
                )
              : 0,
        });

        const modelData = terrainAfterData;
        modelData.terrainBeforeData = terrainBeforeData;
        modelData.terrainAfterData = terrainAfterData;

        // Satellite Ground is loaded lazily only when its Layer Filters
        // checkbox is enabled. This keeps the normal 3D build fast and leaves
        // Terrain (before)/(after) elevation data completely unchanged.
        terrainBeforeData.satelliteTexture = null;
        terrainAfterData.satelliteTexture = null;
        modelData.satelliteTexture = null;
        if (
          buildToken !== this.threeParkBuildToken ||
          !this.shouldShowThreeParkLayer()
        ) {
          return;
        }

        // Default terrain on map load:
        // - valid landscape/LandXML data -> TERRAIN (After)
        // - no usable after surface       -> TERRAIN (Before)
        // This is resolved from the actual load result so a broken XML file
        // cannot leave the map starting on an empty proposed-ground shell.
        const hasUsableTerrainAfter = Boolean(
          terrainAfterData.hasLandscapeData &&
          terrainAfterData.showTopSurface !== false,
        );
        console.info("3D object elevation support policy:", {
          landXmlSurfaceCount: Number(
            terrainAfterData.landXmlSurfaceCount || 0,
          ),
          terrainAfterAuthoritativeForObjects: Boolean(
            hasUsableTerrainAfter &&
            String(terrainAfterData.terrainSource || "").toLowerCase() ===
              "landxml" &&
            Number(terrainAfterData.landXmlSurfaceCount || 0) > 1,
          ),
        });
        this.threeTerrainMode = hasUsableTerrainAfter ? "after" : "before";
        this.$set(this.threeLayerVisibility, "terrain", true);

        await this.initialiseStandaloneThreeScene(modelData);

        // Only Muanisiyah and Qadisiyah 3 start with the authored GIS/design
        // parent layers enabled. This deliberately runs through the exact same
        // parent-layer visibility method used by a user click, preserving child
        // layers that are intentionally opt-in instead of forcing every child on.
        await this.enableStandaloneDefaultParkLayers();
        if (
          buildToken !== this.threeParkBuildToken ||
          !this.shouldShowThreeParkLayer()
        ) {
          return;
        }

        console.info("3D park terrain diagnostics:", {
          hasTerrainData: modelData.hasTerrainData,
          terrainSource: modelData.terrainSource || "mapbox",
          terrainBeforeSource:
            modelData.terrainBeforeData &&
            modelData.terrainBeforeData.terrainSource
              ? modelData.terrainBeforeData.terrainSource
              : "mapbox",
          terrainAfterSource:
            modelData.terrainAfterData &&
            modelData.terrainAfterData.terrainSource
              ? modelData.terrainAfterData.terrainSource
              : modelData.terrainSource || "mapbox",
          landscapeUrl: modelData.landscapeUrl || "",
          hasLandscapeData: Boolean(
            modelData.terrainAfterData &&
            modelData.terrainAfterData.hasLandscapeData,
          ),
          terrainAfterHasTopSurface: Boolean(
            modelData.terrainAfterData &&
            modelData.terrainAfterData.showTopSurface !== false,
          ),
          minimumElevation: modelData.minimumElevation,
          maximumElevation: modelData.maximumElevation,
          rawElevationRange: modelData.rawElevationRange,
          verticalExaggeration: modelData.verticalExaggeration,
          visibleElevationRange: modelData.visibleElevationRange,
          parkMaximumDimensionMeters: modelData.maxDimension,
          islandWallDepthMeters: modelData.islandWallDepth,
          boundarySampleSpacingMeters: modelData.boundarySampleSpacing,
          gridSpacingMeters: modelData.gridSpacing,
          hasSatelliteTexture: false,
          buildingCount: Array.isArray(modelData.buildingFootprints)
            ? modelData.buildingFootprints.length
            : 0,
        });
        this.suspendMapboxRendererForStandaloneThree();
        this.threeParkLoading = false;

        if (!modelData.hasTerrainData) {
          console.warn(
            "Mapbox elevation tiles were unavailable, so the park cutout was rendered with a flat terrain fallback.",
          );
        }
      } catch (error) {
        if (buildToken !== this.threeParkBuildToken) return;
        console.error("Standalone Three.js park terrain failed:", error);
        this.threeParkLoading = false;
        this.threeParkError = this.isArabicUI()
          ? "تعذر إنشاء نموذج التضاريس ثلاثي الأبعاد لهذه الحديقة."
          : "The 3D terrain model could not be created for this park.";
      }
    },

    exitStandaloneThreeMode() {
      this.threeParkBuildToken += 1;
      this.threeVegetationLoadToken += 1;
      this.threeParkLoading = false;
      this.threeParkError = "";
      this.threeLayerLoadingKey = "";
      this.threeLayerError = "";
      this.standaloneBuildingFeatureCache = [];
      this.destroyStandaloneThreeScene();
      this.suspendMapStyleRestoration = false;
      this.mapboxRendererSuspended = false;
      this.showMapboxRenderer();
      if (this.activeBaseMapMode === "satellite") {
        if (this.$map && this.$map.isStyleLoaded && this.$map.isStyleLoaded()) {
          this.applyThreeDimensionalMapSettings();
        }
        this.scheduleSatelliteTerrainRestore({
          hardRefresh: this.pendingSatelliteTerrainHardRefresh,
        });
      }
    },

    addThreeParkLayer() {
      this.enterStandaloneThreeMode();
    },

    removeThreeParkLayer() {
      this.exitStandaloneThreeMode();
    },

    rebuildThreeParkLayer() {
      if (this.shouldShowThreeParkLayer()) {
        this.enterStandaloneThreeMode();
      } else {
        this.exitStandaloneThreeMode();
      }
    },

    syncThreeParkLayer() {
      if (this.shouldShowThreeParkLayer()) {
        this.enterStandaloneThreeMode();
      } else {
        this.exitStandaloneThreeMode();
      }
    },

    async restoreMapOverlaysAfterStyleChange({ moveCamera = true } = {}) {
      if (!this.$map || this.suspendMapStyleRestoration) return;

      this.projectLayersReady = false;
      this.applyThreeDimensionalMapSettings();
      this.applyMapboxLabelLanguage(false);
      this.applyNeutralBaseRoadStyle();
      if (moveCamera) this.applyBaseMapCamera();

      await this.addProjectLayers();
      this.ensureDistrictLayers();
      this.setDistrictSourceData();
      this.renderMapData();
      this.applyNeutralBaseRoadStyle();
      if (this.isThreeDimensionalMapMode()) {
        this.applyThreeDimensionalMapSettings();
      }
      await this.syncConceptMapLayers();
      this.syncThreeParkLayer();

      // setStyle() can briefly report a style before all runtime layers/sources
      // are accepted. Try once more on the next idle frame so highlighted
      // project geometry stays visible after Street/Satellite/3D switches.
      if (!this.$map.getSource(PROJECT_SOURCE_ID)) {
        this.$map.once("idle", () => {
          this.restoreMapOverlaysAfterStyleChange({ moveCamera: false });
        });
      }
    },

    async setBaseMapMode(mode) {
      if (!this.baseMapModes.some((item) => item.value === mode)) return;
      if (mode === "3d" && !this.isProjectDetailsMap) return;

      // Fullscreen belongs to the ProjectDetails map, not to one basemap mode.
      // Keep the expanded layout while switching Street / Satellite / 3D.
      const previousMode = this.activeBaseMapMode;
      const resetStateFromStandaloneThree =
        previousMode === "3d" && this.lastStandaloneThreeResetMapViewState
          ? { ...this.lastStandaloneThreeResetMapViewState }
          : null;
      const viewState =
        resetStateFromStandaloneThree || this.preserveCurrentViewState();
      if (resetStateFromStandaloneThree) {
        this.preservedMapViewState = { ...resetStateFromStandaloneThree };
      }

      // Pressing the already active button should not reset the user's camera.
      if (previousMode === mode) {
        if (mode === "3d" && !this.threeRenderer && !this.threeParkLoading) {
          await this.enterStandaloneThreeMode();
        }
        return;
      }

      if (mode === "3d") {
        this.clearMapCameraRestoreTimers();
        this.isBaseMapStyleSwitching = false;
        this.pendingBaseMapCameraState = null;
        this.activeBaseMapMode = "3d";
        if (viewState) this.preservedMapViewState = viewState;
        await this.enterStandaloneThreeMode();
        return;
      }

      this.activeBaseMapMode = mode;
      this.exitStandaloneThreeMode();
      this.scheduleFinProjectTooltipDatePreload();
      if (previousMode === "3d") {
        this.lastStandaloneThreeResetMapViewState = null;
      }

      if (!this.$map) return;

      const cameraState = viewState || this.preservedMapViewState;
      if (cameraState) {
        this.lockCameraAcrossBaseMapStyleChange(cameraState);
      }

      this.suspendMapStyleRestoration = false;
      this.mapboxRendererSuspended = false;
      this.projectLayersReady = false;
      this.unbindProjectLayerEvents();
      this.$map.setStyle(this.getMapboxStyleForMode(mode));

      this.$map.once("style.load", () => {
        this.restoreMapCameraStateImmediately(cameraState);
      });

      this.$map.once("idle", async () => {
        await this.restoreMapOverlaysAfterStyleChange({
          moveCamera: false,
        });
        this.restoreMapCameraStateImmediately(cameraState);
        if (this.isThreeDimensionalMapMode(mode)) {
          this.applyThreeDimensionalMapSettings();
          if (mode === "satellite") {
            this.scheduleSatelliteTerrainRestore({
              hardRefresh:
                previousMode === "3d" ||
                this.pendingSatelliteTerrainHardRefresh,
            });
          }
          window.setTimeout(() => {
            if (this.activeBaseMapMode === mode) {
              this.applyThreeDimensionalMapSettings();
            }
          }, 300);
        }
      });
    },

    applyBaseMapCamera(duration = 0) {
      if (this.isStandaloneThreeMode) return;
      if (!this.$map) return;

      // Style changes must not force a preset pitch/bearing. Restore the exact
      // camera state captured before the user changed view modes.
      if (this.preservedMapViewState) {
        this.applyMapboxViewState(this.preservedMapViewState, duration);
      }
    },

    removeCustom3DBuildingsLayer() {
      if (!this.$map) return;

      [
        MAPBOX_3D_BUILDINGS_LAYER_ID,
        MAPBOX_3D_BUILDINGS_SAMPLING_LAYER_ID,
      ].forEach((layerId) => {
        try {
          if (this.$map.getLayer(layerId)) {
            this.$map.removeLayer(layerId);
          }
        } catch (error) {
          console.warn("3D building layer could not be removed:", error);
        }
      });
    },

    setMapboxStandard3DOptions() {
      if (!this.$map || typeof this.$map.setConfigProperty !== "function") {
        return;
      }

      const options = [
        ["basemap", "show3dObjects", true],
        ["basemap", "showBuildings", true],
        ["basemap", "showLandmarkIcons", true],
        ["basemap", "showRoadLabels", true],
        ["basemap", "showPlaceLabels", true],
        ["basemap", "showPointOfInterestLabels", true],
        ["basemap", "showTransitLabels", true],
        ["basemap", "lightPreset", "day"],
      ];

      options.forEach(([fragmentId, propertyName, value]) => {
        try {
          this.$map.setConfigProperty(fragmentId, propertyName, value);
        } catch (error) {
          // Some Mapbox styles do not support every Standard basemap option.
        }
      });
    },

    getMapboxBuildingVectorSourceId() {
      if (!this.$map || typeof this.$map.getStyle !== "function") return null;

      const style = this.$map.getStyle();
      const sources = style && style.sources ? style.sources : {};
      const preferredSourceIds = ["composite", "mapbox"];

      const preferredSourceId = preferredSourceIds.find(
        (sourceId) => sources[sourceId] && sources[sourceId].type === "vector",
      );

      if (preferredSourceId) return preferredSourceId;

      return (
        Object.keys(sources).find(
          (sourceId) =>
            sources[sourceId] && sources[sourceId].type === "vector",
        ) || null
      );
    },

    ensureStandaloneBuildingSource() {
      if (!this.$map || !this.$map.isStyleLoaded()) return;

      try {
        if (!this.$map.getSource(MAPBOX_3D_BUILDINGS_SOURCE_ID)) {
          this.$map.addSource(MAPBOX_3D_BUILDINGS_SOURCE_ID, {
            type: "vector",
            url: "mapbox://mapbox.mapbox-streets-v8",
          });
        }

        if (!this.$map.getLayer(MAPBOX_3D_BUILDINGS_SAMPLING_LAYER_ID)) {
          const samplingLayer = {
            id: MAPBOX_3D_BUILDINGS_SAMPLING_LAYER_ID,
            type: "fill",
            source: MAPBOX_3D_BUILDINGS_SOURCE_ID,
            "source-layer": "building",
            minzoom: MAPBOX_3D_BUILDINGS_MIN_ZOOM,
            paint: {
              "fill-color": "#ffffff",
              "fill-opacity": 0,
            },
          };

          try {
            this.$map.addLayer({ ...samplingLayer, slot: "top" });
          } catch (slotError) {
            this.$map.addLayer(samplingLayer);
          }
        }
      } catch (error) {
        console.warn("3D building sampling source could not be added:", error);
      }
    },

    addCustom3DBuildingsLayer() {
      if (!this.$map || !this.$map.isStyleLoaded()) return;
      if (this.$map.getLayer(MAPBOX_3D_BUILDINGS_LAYER_ID)) return;

      try {
        if (!this.$map.getSource(MAPBOX_3D_BUILDINGS_SOURCE_ID)) {
          this.$map.addSource(MAPBOX_3D_BUILDINGS_SOURCE_ID, {
            type: "vector",
            url: "mapbox://mapbox.mapbox-streets-v8",
          });
        }

        const layerDefinition = {
          id: MAPBOX_3D_BUILDINGS_LAYER_ID,
          type: "fill-extrusion",
          source: MAPBOX_3D_BUILDINGS_SOURCE_ID,
          "source-layer": "building",
          minzoom: MAPBOX_3D_BUILDINGS_MIN_ZOOM,
          paint: {
            "fill-extrusion-color": [
              "case",
              ["has", "height"],
              "#d4d8df",
              "#c9ced6",
            ],
            "fill-extrusion-height": [
              "interpolate",
              ["linear"],
              ["zoom"],
              MAPBOX_3D_BUILDINGS_MIN_ZOOM,
              0,
              MAPBOX_3D_BUILDINGS_MIN_ZOOM + 0.8,
              [
                "max",
                MAPBOX_3D_BUILDING_MIN_HEIGHT,
                [
                  "*",
                  MAPBOX_3D_BUILDING_HEIGHT_EXAGGERATION,
                  [
                    "coalesce",
                    ["to-number", ["get", "height"]],
                    ["to-number", ["get", "render_height"]],
                    ["*", 3.5, ["to-number", ["get", "levels"]]],
                    10,
                  ],
                ],
              ],
            ],
            "fill-extrusion-base": [
              "*",
              MAPBOX_3D_BUILDING_HEIGHT_EXAGGERATION,
              [
                "coalesce",
                ["to-number", ["get", "min_height"]],
                ["to-number", ["get", "render_min_height"]],
                0,
              ],
            ],
            "fill-extrusion-opacity": 0.86,
            "fill-extrusion-vertical-gradient": true,
          },
        };

        // In Mapbox Standard/Standard Satellite, putting the custom layer in the
        // "top" slot keeps it above the satellite terrain. In older styles the
        // slot property is harmless; if unsupported, retry without it.
        try {
          this.$map.addLayer({ ...layerDefinition, slot: "top" });
        } catch (slotError) {
          this.$map.addLayer(layerDefinition);
        }
      } catch (error) {
        console.warn("3D building layer could not be added:", error);
      }
    },

    applyThreeDimensionalMapSettings() {
      if (!this.$map || !this.$map.isStyleLoaded()) return;

      // ProjectDetails 3D is rendered by the standalone Three.js canvas.
      // Keep Mapbox in a lightweight/non-3D state for Street/Satellite only.
      if (this.activeBaseMapMode === "3d") {
        return;
      }

      if (!this.isThreeDimensionalMapMode()) {
        this.removeCustom3DBuildingsLayer();
        this.removeThreeParkLayer();
        try {
          this.$map.setTerrain(null);
        } catch (error) {
          // Some styles may not have terrain active yet.
        }
        return;
      }

      try {
        if (!this.$map.getSource(MAPBOX_TERRAIN_SOURCE_ID)) {
          this.$map.addSource(MAPBOX_TERRAIN_SOURCE_ID, {
            type: "raster-dem",
            url: "mapbox://mapbox.mapbox-terrain-dem-v1",
            tileSize: 512,
            maxzoom: 14,
          });
        }

        this.$map.setTerrain({
          source: MAPBOX_TERRAIN_SOURCE_ID,
          // Same terrain exaggeration for Main page, ProjectDetails,
          // ProjectType, Search, and every project category.
          exaggeration: MAPBOX_3D_TERRAIN_EXAGGERATION,
        });

        // Keep native Standard-style 3D options on where available, but do not
        // rely on them. The custom building layer below is what guarantees
        // buildings remain extruded in Satellite 3D mode.
        this.setMapboxStandard3DOptions();
        this.addCustom3DBuildingsLayer();

        // Style/source loading can briefly remove or hide custom layers. Recheck
        // on idle and add the building layer again if Mapbox dropped it.
        this.$map.once("idle", () => {
          if (this.isThreeDimensionalMapMode()) {
            this.addCustom3DBuildingsLayer();
          }
        });

        if (typeof this.$map.setMaxPitch === "function") {
          this.$map.setMaxPitch(85);
        }

        if (typeof this.$map.triggerRepaint === "function") {
          this.$map.triggerRepaint();
        }

        if (typeof this.$map.setFog === "function") {
          this.$map.setFog({
            color: "rgb(245, 246, 250)",
            "high-color": "rgb(205, 218, 235)",
            "horizon-blend": 0.18,
            "space-color": "rgb(230, 234, 240)",
            "star-intensity": 0.0,
          });
        }
      } catch (error) {
        console.warn("3D map settings could not be applied:", error);
      }
    },

    zoomMapIn() {
      if (this.isStandaloneThreeMode) {
        this.zoomStandaloneThree(0.82);
        return;
      }

      if (!this.$map) return;
      const currentZoom = Number(this.$map.getZoom() || this.zoom || 10);
      this.$map.easeTo({ zoom: Math.min(currentZoom + 1, 18), duration: 250 });
    },

    zoomMapOut() {
      if (this.isStandaloneThreeMode) {
        this.zoomStandaloneThree(1.22);
        return;
      }

      if (!this.$map) return;
      const currentZoom = Number(this.$map.getZoom() || this.zoom || 10);
      this.$map.easeTo({ zoom: Math.max(currentZoom - 1, 1), duration: 250 });
    },

    resetMapPositionFromControl() {
      if (this.isStandaloneThreeMode) {
        this.resetThreeParkCamera();
        return;
      }

      this.resetToDefaultMapView();
    },

    showLocationMessage(message) {
      this.locationErrorMessage = message;

      if (this.locationMessageTimeout) {
        window.clearTimeout(this.locationMessageTimeout);
      }

      this.locationMessageTimeout = window.setTimeout(() => {
        this.locationErrorMessage = "";
        this.locationMessageTimeout = null;
      }, 5000);
    },

    createUserLocationMarkerElement() {
      const element = document.createElement("div");
      element.className = "mapbox-user-location-marker";
      element.innerHTML = '<span class="mapbox-user-location-arrow"></span>';
      return element;
    },

    updateUserLocationMarker(position) {
      if (!this.$map || !position || !position.coords) return null;

      const lat = Number(position.coords.latitude);
      const lng = Number(position.coords.longitude);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

      if (
        Number.isFinite(position.coords.heading) &&
        position.coords.heading >= 0
      ) {
        this.userHeading = position.coords.heading;
      }

      const lngLat = [lng, lat];

      if (!this.userLocationMarker) {
        this.userLocationMarker = new this.mapboxgl.Marker({
          element: this.createUserLocationMarkerElement(),
          rotationAlignment: "map",
          pitchAlignment: "map",
        })
          .setLngLat(lngLat)
          .addTo(this.$map);
      } else {
        this.userLocationMarker.setLngLat(lngLat);
      }

      this.updateUserHeading(this.userHeading);
      this.hasUserLocation = true;
      this.isLocatingUser = false;
      return lngLat;
    },

    updateUserHeading(heading) {
      const normalizedHeading = Number(heading);
      if (!Number.isFinite(normalizedHeading)) return;

      this.userHeading = (normalizedHeading + 360) % 360;
      if (this.userLocationMarker && this.userLocationMarker.getElement) {
        const arrow = this.userLocationMarker
          .getElement()
          .querySelector(".mapbox-user-location-arrow");
        if (arrow) {
          arrow.style.transform = `rotate(${this.userHeading + 42}deg)`;
        }
      }
    },

    handleDeviceOrientation(event) {
      let heading = null;

      if (Number.isFinite(event.webkitCompassHeading)) {
        heading = event.webkitCompassHeading;
      } else if (Number.isFinite(event.alpha)) {
        const screenAngle = Number(
          window.screen?.orientation?.angle ?? window.orientation ?? 0,
        );
        heading = 360 - event.alpha + screenAngle;
      }

      this.updateUserHeading(heading);
    },

    async startDeviceOrientationTracking() {
      if (this.deviceOrientationHandler || typeof window === "undefined")
        return;
      if (!("DeviceOrientationEvent" in window)) return;

      try {
        if (
          typeof window.DeviceOrientationEvent.requestPermission === "function"
        ) {
          const permission =
            await window.DeviceOrientationEvent.requestPermission();
          if (permission !== "granted") return;
        }

        this.deviceOrientationHandler = (event) =>
          this.handleDeviceOrientation(event);
        window.addEventListener(
          "deviceorientationabsolute",
          this.deviceOrientationHandler,
          true,
        );
        window.addEventListener(
          "deviceorientation",
          this.deviceOrientationHandler,
          true,
        );
      } catch (error) {
        console.warn("Device direction permission was not granted:", error);
      }
    },

    startUserLocationWatch() {
      if (this.userLocationWatchId != null || !navigator.geolocation) return;

      this.userLocationWatchId = navigator.geolocation.watchPosition(
        (position) => this.updateUserLocationMarker(position),
        (error) => {
          this.isLocatingUser = false;
          console.warn("Unable to update current location:", error);
        },
        {
          enableHighAccuracy: true,
          maximumAge: 3000,
          timeout: 15000,
        },
      );
    },

    resetToDefaultMapView() {
      if (this.isStandaloneThreeMode) {
        this.resetThreeParkCamera();
        return;
      }

      if (!this.$map) return;

      this.isUserLocationViewActive = false;
      this.isLocatingUser = false;

      // On ProjectDetails pages the map's default view is the fitted geometry
      // for that one project, not the main overview center/zoom. Keep reset
      // scoped to the current page/view so it does not jump back to Main.
      if (this.activeViewMode === "project" && this.currentProjectId) {
        if (this.isConceptMapMode()) {
          this.applyConceptMapCamera(300);
        } else {
          this.fitMapToProjectIds([this.currentProjectId], 14, {
            forceStreetCamera: true,
          });
        }
        return;
      }

      // Search pages also have their own fitted default view.
      if (
        this.hasActiveSearchFilter() &&
        Array.isArray(this.activeSearchProjectIds) &&
        this.activeSearchProjectIds.length
      ) {
        this.fitMapToProjectIds(this.activeSearchProjectIds, 13, {
          forceStreetCamera: true,
        });
        return;
      }

      // Near-project views should reset to the currently focused project area.
      if (this.activeViewMode === "near" && this.nearProjectId) {
        this.fitMapToProjectIds([this.nearProjectId], 13, {
          forceStreetCamera: true,
        });
        return;
      }

      // Main page reset should return to the same camera angle as Street view
      // for every map mode. Keeping pitch/bearing at zero also prevents the
      // hidden 3D sampling map from leaving Satellite terrain in a flat state.
      this.$map.easeTo({
        center: this.getDefaultCenter(),
        zoom: Number(this.zoom || 10),
        pitch: 0,
        bearing: 0,
        duration: 300,
      });

      window.setTimeout(() => {
        if (this.isThreeDimensionalMapMode()) {
          this.applyThreeDimensionalMapSettings();
        }
      }, 360);
    },

    focusMapOnUserLocation(lngLat) {
      if (!this.$map || !lngLat) return;

      const lng = Number(Array.isArray(lngLat) ? lngLat[0] : lngLat.lng);
      const lat = Number(Array.isArray(lngLat) ? lngLat[1] : lngLat.lat);
      if (!Number.isFinite(lng) || !Number.isFinite(lat)) return;

      // Match the familiar Google Maps locate-button behaviour: centre the
      // map on the user and move to a useful close-up zoom in both Street and
      // Satellite view. Preserve the current pitch/bearing so Satellite keeps
      // its 3D presentation instead of unexpectedly flattening.
      this.$map.easeTo({
        center: [lng, lat],
        zoom: this.activeBaseMapMode === "satellite" ? 17 : 16,
        pitch: this.$map.getPitch(),
        bearing: this.$map.getBearing(),
        duration: 650,
        essential: true,
      });
      this.isUserLocationViewActive = true;
    },

    async goToUserLocation() {
      if (!this.$map) return;

      if (!navigator.geolocation) {
        this.showLocationMessage(
          this.isArabicUI()
            ? "المتصفح لا يدعم تحديد الموقع."
            : "Location services are not supported by this browser.",
        );
        return;
      }

      this.isLocatingUser = true;
      this.locationErrorMessage = "";
      this.startDeviceOrientationTracking();

      // If a previous GPS reading is available, respond to the click
      // immediately. getCurrentPosition below will refine the centre with a
      // fresh high-accuracy reading when it arrives.
      if (this.userLocationMarker && this.userLocationMarker.getLngLat) {
        this.focusMapOnUserLocation(this.userLocationMarker.getLngLat());
      }

      navigator.geolocation.getCurrentPosition(
        (position) => {
          const lngLat = this.updateUserLocationMarker(position);
          if (!lngLat) return;

          this.focusMapOnUserLocation(lngLat);
          this.startUserLocationWatch();
        },
        (error) => {
          this.isLocatingUser = false;

          let message = this.isArabicUI()
            ? "تعذر الوصول إلى موقعك الحالي."
            : "Unable to access your current location.";

          if (error && error.code === 1) {
            message = this.isArabicUI()
              ? "يرجى السماح للموقع بالوصول إلى موقعك."
              : "Please allow this site to access your location.";
          }

          this.showLocationMessage(message);
        },
        {
          enableHighAccuracy: true,
          maximumAge: 0,
          timeout: 15000,
        },
      );
    },

    stopUserLocationTracking() {
      if (this.userLocationWatchId != null && navigator.geolocation) {
        navigator.geolocation.clearWatch(this.userLocationWatchId);
        this.userLocationWatchId = null;
      }

      if (this.deviceOrientationHandler) {
        window.removeEventListener(
          "deviceorientationabsolute",
          this.deviceOrientationHandler,
          true,
        );
        window.removeEventListener(
          "deviceorientation",
          this.deviceOrientationHandler,
          true,
        );
        this.deviceOrientationHandler = null;
      }

      if (this.userLocationMarker) {
        this.userLocationMarker.remove();
        this.userLocationMarker = null;
      }
    },

    highlightSearchProject(projectId) {
      if (!this.$map || !projectId) return;
      this.highlightedProjectId = this.normalizeProjectId(projectId);
      this.renderMapData();
    },

    clearSearchProjectHighlight() {
      this.highlightedProjectId = null;
      this.hoveredFeatureKey = null;
      this.renderMapData();
    },

    normalizeProgressValue(value) {
      const num = Number(String(value ?? "").replace(/[^\d.]/g, ""));
      return Number.isFinite(num) ? num : 0;
    },

    mapUiText(key, fallbackAr = "", fallbackEn = "") {
      const isArabic = this.isArabicUI();
      const fallback = isArabic
        ? fallbackAr || fallbackEn || key
        : fallbackEn || key;
      const translate =
        typeof this.$t === "function"
          ? this.$t
          : typeof this.$root?.$t === "function"
            ? this.$root.$t
            : null;
      const translateContext =
        typeof this.$t === "function" ? this : this.$root || this;

      if (translate) {
        try {
          const translated = translate.call(translateContext, key);
          if (translated && translated !== key) return translated;
        } catch (error) {
          // Fall back to the local label if the i18n plugin is unavailable here.
        }
      }

      return fallback;
    },

    mapUiLabel(item) {
      if (!item) return "";
      return this.mapUiText(
        item.labelKey || item.labelEn || item.value,
        item.labelAr || item.labelEn || item.value,
        item.labelEn || item.labelAr || item.value,
      );
    },

    isThreeDimensionalMapMode(mode = this.activeBaseMapMode) {
      // Satellite is the full Mapbox 3D environment: satellite imagery,
      // terrain, atmosphere and extruded buildings. The ProjectDetails-only
      // 3D mode remains the isolated standalone Three.js park cutout.
      return mode === "satellite" || mode === "3d";
    },

    isConceptMapMode(mode = this.activeBaseMapMode) {
      return mode === "3d-concept";
    },

    normalizeProjectText(value) {
      return String(value || "")
        .trim()
        .toLowerCase()
        .replace(/[\-_]+/g, " ")
        .replace(/\s+/g, " ");
    },

    parseImagePathList(value) {
      if (!value) return [];
      if (Array.isArray(value)) {
        return value
          .flatMap((item) => this.parseImagePathList(item))
          .map((item) => String(item || "").trim())
          .filter(Boolean);
      }

      if (typeof value === "string") {
        const trimmed = value.trim();
        if (!trimmed) return [];

        try {
          const parsed = JSON.parse(trimmed);
          if (Array.isArray(parsed)) return this.parseImagePathList(parsed);
        } catch (error) {
          // Keep parsing as a comma-separated string below.
        }

        return trimmed
          .replace(/[\r\n;|]+/g, ",")
          .split(",")
          .map((item) => item.trim().replace(/^['"]|['"]$/g, ""))
          .filter(Boolean);
      }

      return [];
    },

    isQadisiyah3ProjectItem(item = {}) {
      const id = this.normalizeProjectId(item.id);
      const projectId = this.normalizeProjectText(item.project_id);
      const nameEn = this.normalizeProjectText(item.name_en);
      const nameAr = String(item.name_ar || "").trim();

      return (
        id === QADISIYAH_3_PROJECT_ID ||
        projectId === this.normalizeProjectText(QADISIYAH_3_PROJECT_CODE) ||
        nameEn === QADISIYAH_3_PROJECT_NAME ||
        nameAr === "حديقة القادسية 3"
      );
    },

    getProjectItemById(projectId) {
      const id = this.normalizeProjectId(projectId);
      const rows = Array.isArray(this.$root?.data_src)
        ? this.$root.data_src
        : [];
      return (
        rows.find((item) => this.normalizeProjectId(item.id) === id) || null
      );
    },

    parseProjectGisValue(value) {
      if (!value) return [];

      if (Array.isArray(value)) {
        return value.flatMap((item) => this.parseProjectGisValue(item));
      }

      if (typeof value === "object") {
        return Object.keys(value).flatMap((key) => {
          const item = value[key];
          if (Array.isArray(item)) {
            return item.flatMap((entry) => {
              if (typeof entry === "string") {
                return [{ type: key, url: entry }];
              }
              if (entry && typeof entry === "object") {
                return [
                  {
                    type: entry.type || entry.layer || key,
                    url: entry.url || entry.path || entry.file || "",
                  },
                ];
              }
              return [];
            });
          }

          if (typeof item === "string") {
            return [{ type: key, url: item }];
          }

          if (item && typeof item === "object") {
            return [
              {
                type: item.type || item.layer || key,
                url: item.url || item.path || item.file || "",
              },
            ];
          }

          return [];
        });
      }

      const textValue = String(value || "").trim();
      if (!textValue) return [];

      if (
        (textValue.startsWith("{") && textValue.endsWith("}")) ||
        (textValue.startsWith("[") && textValue.endsWith("]"))
      ) {
        try {
          return this.parseProjectGisValue(JSON.parse(textValue));
        } catch (error) {
          // Continue with normal path parsing below.
        }
      }

      return textValue
        .replace(/[\r\n;|]+/g, ",")
        .split(",")
        .map((item) => item.trim().replace(/^['"]|['"]$/g, ""))
        .filter(Boolean)
        .map((url) => ({ type: "", url }));
    },

    normalizeStandaloneLayerFilter(value) {
      const text = String(value || "")
        .trim()
        .toLowerCase()
        .replace(/[\s_-]+/g, "");

      if (["vegetation", "plants", "planting"].includes(text)) {
        return "vegetation";
      }
      if (["paths", "path", "roads", "road", "paving"].includes(text)) {
        return "paths";
      }
      if (["water", "waterbody", "waters"].includes(text)) {
        return "water";
      }
      if (
        [
          "structures",
          "structure",
          "buildings",
          "building",
          "furniture",
        ].includes(text)
      ) {
        return "structures";
      }
      if (
        [
          "tse",
          "tseprimary",
          "tseprimarymains",
          "utility",
          "utilities",
          "lighting",
          "electricmanhole",
          "electricalmanhole",
          "electricpole",
          "electricalpole",
          "utilitypole",
          "powerline",
          "powerlines",
        ].includes(text)
      ) {
        return "tse";
      }
      return "";
    },

    getStandaloneThreeSubLayerOptions(layerKey) {
      const available = Array.isArray(this.threeSubLayerAvailability[layerKey])
        ? this.threeSubLayerAvailability[layerKey]
        : [];
      const visibility = this.threeSubLayerVisibility[layerKey] || {};

      // Vegetation is intentionally different from the other expandable
      // categories: always show Trees, Shrubs and GroundCover so the panel also
      // communicates which vegetation datasets are MISSING for the current park.
      // Example: Munisiyah currently has Trees data, while Shrubs and GroundCover
      // remain visible but disabled/unchecked.
      if (layerKey === "vegetation") {
        const canonical = [
          { key: "trees", label: "Trees" },
          { key: "shrubs", label: "Shrubs" },
          { key: "groundcover", label: "GroundCover" },
        ];
        const byKey = new Map(available.map((item) => [item.key, item]));
        const canonicalKeys = new Set(canonical.map((item) => item.key));

        const core = canonical.map((definition) => {
          const item = byKey.get(definition.key);
          const hasData = Boolean(item);
          return {
            key: definition.key,
            label: definition.label,
            available: hasData,
            active: hasData && visibility[definition.key] !== false,
          };
        });

        // Preserve any legitimate vegetation category outside the three core
        // buckets (for example "Other Vegetation") after the standard rows.
        const extras = available
          .filter((item) => !canonicalKeys.has(item.key))
          .map((item) => ({
            key: item.key,
            label: item.label,
            available: true,
            active: visibility[item.key] !== false,
          }));

        return [...core, ...extras];
      }

      // UTILITY (internally "tse") is dynamic. Do not hide park-specific
      // datasets merely because they are not one of the historic four rows.
      // updateStandaloneThreeSubLayerAvailability() has already sorted them.
      if (layerKey === "tse") {
        return available.map((item) => ({
          key: item.key,
          label: item.label,
          available: true,
          active: visibility[item.key] !== false,
        }));
      }

      return available.map((item) => ({
        key: item.key,
        label: item.label,
        available: true,
        active: visibility[item.key] !== false,
      }));
    },

    isStandaloneThreeParentLayerActive(layerKey) {
      if (!this.threeLayerVisibility[layerKey]) return false;
      const children = this.getStandaloneThreeSubLayerOptions(layerKey);
      const dataChildren = children.filter(
        (child) => child.available !== false,
      );
      return !dataChildren.length || dataChildren.some((child) => child.active);
    },

    isStandaloneThreeParentLayerPartiallyActive(layerKey) {
      if (!this.threeLayerVisibility[layerKey]) return false;
      const children = this.getStandaloneThreeSubLayerOptions(layerKey).filter(
        (child) => child.available !== false,
      );
      if (children.length < 2) return false;
      const activeCount = children.filter((child) => child.active).length;
      return activeCount > 0 && activeCount < children.length;
    },

    getStandaloneFeatureSubLayerSource(feature) {
      const properties = (feature && feature.properties) || {};
      const lookup = new Map(
        Object.entries(properties).map(([key, value]) => [
          String(key).toLowerCase(),
          value,
        ]),
      );
      const candidates = [
        "sourcelayer",
        "source_layer",
        "_source_layer",
        "layername",
        "layer_name",
        "dataset",
        "dataset_name",
        "featureclass",
        "feature_class",
      ];

      for (const key of candidates) {
        const value = lookup.get(key);
        if (value == null) continue;
        const label = String(value)
          .replace(/\.(?:geojson|json|shp)$/i, "")
          .trim();
        if (label) return label;
      }

      return "";
    },

    getStandaloneUtilitySubLayerLabel(feature) {
      const properties = (feature && feature.properties) || {};
      const source = this.getStandaloneFeatureSubLayerSource(feature);
      const featureType = this.getStandaloneFeatureType(feature);
      const descriptor = [
        source,
        featureType,
        properties.category,
        properties.subtype,
        properties.Type,
        properties.type,
        properties.Remarks,
        properties.QC_REMARKS,
        properties.DC_REMARK,
        properties.APP_MODEL,
        properties.APP_3D_MODEL,
        properties.app_3d_model,
        properties["App 3D Model"],
        properties.APP_DISPLAY_LABEL,
        properties["App Display Label"],
        properties.APP_LABEL,
      ]
        .filter((value) => value != null && String(value).trim())
        .join(" ")
        .toLowerCase()
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();

      if (!descriptor) return "";

      // Muanisiyah 5105 hydronic/MEP data: keep the pressurized supply pipes,
      // gravity return pipes, underground tank and submersible pump bank under
      // one user-facing UTILITY row. The geometry is source-derived from the
      // 5105 vector plan and georeferenced to the four matching water features.
      const explicitUtilitySubLayer = String(
        properties.APP_UTILITY_SUBLAYER ||
          properties.app_utility_sublayer ||
          properties.utility_sub_layer ||
          "",
      ).trim();
      const explicitUtilitySubLayerKey = explicitUtilitySubLayer
        .toLowerCase()
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      const explicitUtilitySubLayerMap = {
        irrigation: "Irrigation",
        "potable water": "Potable Water",
        sewage: "Sewage",
        "storm water": "Storm Water",
        electrical: "Electrical",
        lighting: "Lighting",
        hvac: "HVAC",
        "water feature system": "Water Feature System",
      };
      if (explicitUtilitySubLayerMap[explicitUtilitySubLayerKey]) {
        return explicitUtilitySubLayerMap[explicitUtilitySubLayerKey];
      }
      if (
        /water\s*feature.*(?:supply|return|pipe|pipeline|tank|pump|hydronic)|(?:supply|return).*water\s*feature|water\s*tank.*pump/.test(
          descriptor,
        )
      ) {
        return "Water Feature System";
      }

      // Prefer the authoritative source layer before descriptive remarks. For
      // example Qadisiyah powerline records contain the words "LIGHTING
      // NETWORK" in Remarks, but they still belong under the Powerline row.
      const normalizedSource = String(source || "")
        .toLowerCase()
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      if (/\bpower\s*line(?:s)?\b|\bpowerline(?:s)?\b/.test(normalizedSource)) {
        return "Powerline";
      }
      if (/\b(?:electric(?:al)?\s*)?manhole(?:s)?\b/.test(normalizedSource)) {
        return "Electric Manhole";
      }
      if (
        /\b(?:lighting|light\s*(?:post|pole|fixture))\b/.test(normalizedSource)
      ) {
        return "Lighting";
      }
      // Qadisiyah's electrical_poles source is specifically populated with
      // lighting-fixture poles. Keep those under the single Lighting row shown
      // in the requested UI instead of exposing an extra Electric Pole filter.
      if (/\belectrical?\s*poles?\b/.test(normalizedSource)) {
        return "Lighting";
      }

      if (
        /\b(irri|irrigation|sprinkler|bubbler|drip\s*line|valve)\b/.test(
          descriptor,
        )
      ) {
        return "Irrigation";
      }
      if (
        /\b(potable\s*water|hydrant|hidrante|c\s*watr|water\s*pipe)\b/.test(
          descriptor,
        )
      ) {
        return "Potable Water";
      }
      if (/\b(sewage|sanitary|swg|pozo|grease\s*trap)\b/.test(descriptor)) {
        return "Sewage";
      }
      if (
        /\b(storm\s*water|drain|drainage|culvert|catch\s*basin|dra)\b/.test(
          descriptor,
        )
      ) {
        return "Storm Water";
      }
      if (
        /\b(hvac|hvc|duct|ventilation|air\s*handling|ahu|vav|exhaust)\b/.test(
          descriptor,
        )
      ) {
        return "HVAC";
      }
      if (
        /\b(electrical|distribution\s*board|grounding|cable|conduit|car\s*charger)\b/.test(
          descriptor,
        )
      ) {
        return "Electrical";
      }
      if (
        /\b(lighting|light\s*(?:post|pole|fixture)|luminaire|lamp)\b/.test(
          descriptor,
        )
      ) {
        return "Lighting";
      }
      if (/\b(?:electric(?:al)?\s*)?manhole(?:s)?\b/.test(descriptor)) {
        return "Electric Manhole";
      }
      if (/\bpower\s*line(?:s)?\b|\bpowerline(?:s)?\b/.test(descriptor)) {
        return "Powerline";
      }
      if (/\b(?:electric(?:al)?|utility)\s*pole(?:s)?\b/.test(descriptor)) {
        return "Lighting";
      }
      return "";
    },

    formatStandaloneSubLayerLabel(value, fallback = "Layer") {
      const cleaned = String(value || "")
        .replace(/\.(?:geojson|json|shp)$/i, "")
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ")
        .trim();
      if (!cleaned) return fallback;

      return cleaned
        .split(" ")
        .map((word) => {
          if (/^tse$/i.test(word)) return "TSE";
          if (/^hv$/i.test(word)) return "HV";
          if (/^lv$/i.test(word)) return "LV";
          return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
        })
        .join(" ");
    },

    getStandaloneSubLayerDefinition(layerKey, feature) {
      const properties = (feature && feature.properties) || {};
      const source = this.getStandaloneFeatureSubLayerSource(feature);
      const featureType = this.getStandaloneFeatureType(feature);

      // Handrails are a dedicated PATHS child. Resolve this before an exported
      // APP_SUB_LAYER value so a legacy source label such as "Furniture" cannot
      // place the rail back under STRUCTURES or give it the wrong PATHS label.
      const handrailDescriptor = [
        source,
        featureType,
        properties.APP_MODEL,
        properties.APP_DISPLAY_LABEL,
        properties["App Display Label"],
        properties.Type,
        properties.type,
        properties.Remarks,
        properties.QC_REMARKS,
      ]
        .filter((value) => value != null && String(value).trim())
        .join(" ")
        .toLowerCase()
        .replace(/[_-]+/g, " ");
      const isHandrailFeature =
        String(properties.APP_MODEL || "")
          .trim()
          .toLowerCase() === "cad_handrail" ||
        properties.APP_CAD_RAILING_CENTERLINE === true ||
        /\b(handrail|handrails|railing|railings)\b/.test(handrailDescriptor);
      if (layerKey === "paths" && isHandrailFeature) {
        return { key: "handrails", label: "Handrails" };
      }

      // Combined park GeoJSON files can define their own natural sub-filters.
      // Prefer this explicit label over legacy heuristics so a park such as KAP
      // can expose Wadi Channels, Swales, Walking Trails, Boardwalks, TSE Pipes,
      // etc. without being forced into another park's canonical buckets.
      const explicitSubLayer = [
        properties.subLayer,
        properties.sub_layer,
        properties.sublayer,
        properties.APP_SUB_LAYER,
        properties.app_sub_layer,
        properties._sub_layer,
      ].find((value) => value != null && String(value).trim());
      if (explicitSubLayer != null) {
        const label = String(explicitSubLayer).replace(/\s+/g, " ").trim();
        const key =
          String(label || "layer")
            .trim()
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, "-")
            .replace(/^-+|-+$/g, "") || "layer";
        return { key, label };
      }
      const geometryType = String(
        feature && feature.geometry && feature.geometry.type,
      ).toLowerCase();
      const descriptor = [
        source,
        featureType,
        properties.CL_LAND_COVER_DETAILED,
        properties.CL_LANDUSE_DETAILED,
        properties.CL_ROAD_TYPE,
        properties.ROAD_TYPE,
        properties.category,
        properties.subtype,
        properties.Type,
        properties.type,
        properties.Remarks,
        properties.QC_REMARKS,
        properties.DC_REMARK,
        properties.APP_MODEL,
        properties.APP_3D_MODEL,
        properties.app_3d_model,
        properties["App 3D Model"],
        properties.APP_DISPLAY_LABEL,
        properties["App Display Label"],
        properties.APP_LABEL,
      ]
        .filter((value) => value != null && String(value).trim())
        .join(" ")
        .toLowerCase()
        .replace(/[_-]+/g, " ");

      let label = "";

      if (layerKey === "vegetation") {
        if (/planting\s*callout\s*leader/.test(descriptor)) {
          label = "Planting Callout Leaders";
        } else if (/planting\s*callout\s*sign/.test(descriptor)) {
          label = "Planting Callout Signs";
        } else if (/planting\s*symbol\s*marker/.test(descriptor)) {
          label = "Planting Symbol Markers";
        } else if (/planting\s*grid/.test(descriptor)) {
          label = "Planting Grid";
        } else if (/flower\s*bed\s*boundar/.test(descriptor)) {
          label = "Flower Bed Boundaries";
        } else if (/ground\s*cover\s*boundar|lawn\s*boundar/.test(descriptor)) {
          label = "GroundCover Boundaries";
        } else if (
          /\b(ground\s*cover|groundcover|lawn|turf|grass)\b/.test(descriptor)
        ) {
          label = "GroundCover";
        } else if (/\b(shrub|shrubs|bush|bushes)\b/.test(descriptor)) {
          label = "Shrubs";
        } else if (
          /\b(tree|trees|palm|palms)\b/.test(descriptor) ||
          geometryType === "point" ||
          geometryType === "multipoint"
        ) {
          label = "Trees";
        } else {
          label = this.formatStandaloneSubLayerLabel(
            source || featureType,
            "Other Vegetation",
          );
        }
      } else if (layerKey === "structures") {
        label = this.formatStandaloneSubLayerLabel(
          source || featureType,
          "Structures",
        );
      } else if (layerKey === "paths") {
        if (
          /\b(car\s*parking|carpark|parking(?:\s+(?:lot|area))?)\b/.test(
            descriptor,
          )
        ) {
          label = "Car Parking";
        } else if (/\b(bridge|footbridge)\b/.test(descriptor)) {
          label = "Bridges";
        } else if (
          /\b(stair|stairs|staircase|step|steps|building\s*stairs)\b/.test(
            descriptor,
          )
        ) {
          label = "Stairs";
        } else if (/\b(sidewalk|footpath|foot\s*path)\b/.test(descriptor)) {
          label = "Sidewalk";
        } else if (
          /\b(road|roadway|carriageway|street|vehicular|driveway|asphalt|median)\b/.test(
            descriptor,
          )
        ) {
          label = "Roads";
        } else {
          // Walking/cycle paths and other on-grade path features share the
          // Pedestrian Space row. Stairs and Bridges stay independently toggleable.
          label = "Pedestrian Space";
        }
      } else if (layerKey === "water") {
        if (/\bwater\s*feature\b|\bwaterfeature\b/.test(descriptor)) {
          label = "Water Features";
        } else if (
          /\b(jumping\s*fountain|fountain|water\s*jet)\b/.test(descriptor)
        ) {
          label = "Fountains";
        } else if (/\b(pool|swimming)\b/.test(descriptor)) {
          label = "Pools";
        } else if (/\b(channel|canal|stream|river)\b/.test(descriptor)) {
          label = "Channels";
        } else if (/\b(pond|lake)\b/.test(descriptor)) {
          label = "Ponds";
        } else {
          label = this.formatStandaloneSubLayerLabel(
            source || featureType,
            "Water Features",
          );
        }
      } else if (layerKey === "structures") {
        if (/\b(covered\s*pergola|pergola|canopy\s*cover)\b/.test(descriptor)) {
          label = "Covered Pergolas";
        } else if (
          /\b(sport|court|playground|outdoor\s*gym|petanque|skatepark|muga|basketball|football|soccer|running\s*track)\b/.test(
            descriptor,
          )
        ) {
          label = "Sports & Recreation";
        } else if (
          /\b(bench|bin|rack|bollard|furniture|seat|seating|chair|table)\b/.test(
            descriptor,
          ) ||
          /\bfurniture\b/.test(String(source || "").toLowerCase())
        ) {
          label = "Street Furniture";
        } else {
          // Visitor/Cycle centres, prayer rooms, restaurants, kiosks,
          // bathrooms, electrical/O&M/water-tank buildings and any other
          // built facility share one Buildings & Facilities checkbox.
          label = "Buildings & Facilities";
        }
      } else if (layerKey === "tse") {
        const utilityLabel = this.getStandaloneUtilitySubLayerLabel(feature);
        if (utilityLabel) label = utilityLabel;
        else if (/\bsecondary\b/.test(descriptor)) label = "TSE Secondary";
        else if (/\bprimary\b/.test(descriptor)) label = "TSE Primary";
        else
          label = this.formatStandaloneSubLayerLabel(
            source || featureType,
            "TSE Network",
          );
      } else {
        label = this.formatStandaloneSubLayerLabel(
          source || featureType,
          "Layer",
        );
      }

      const key =
        String(label || "layer")
          .trim()
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, "-")
          .replace(/^-+|-+$/g, "") || "layer";

      return { key, label };
    },

    getStandaloneSubLayerSortIndex(layerKey, label) {
      const orders = {
        vegetation: [
          "Trees",
          "Shrubs",
          "GroundCover",
          "Flower Bed Boundaries",
          "GroundCover Boundaries",
          "Other Vegetation",
          "Cad Annotation Fill",
          "Planting Callout Leaders",
          "Planting Callout Signs",
          "Planting Symbol Markers",
          "Planting Grid",
        ],
        paths: [
          // User-facing PATHS order, top -> bottom.
          "Pedestrian Space",
          "Handrails",
          "Stairs",
          "Sidewalk",
          "Car Parking",
          "Roads",
          // Optional/legacy path categories follow the six primary rows.
          "Bridges",
          "TRAILS",
          "CORE TRAILS",
          "SECONDARY NODE TRAILS",
          "BOARDWALK",
          "BIKE PATH",
          "ARRIVAL PLAZA (PRIMARY NODES)",
          "SECONDARY NODE PAVING",
          "WADI BANKS & TERRACES & RAMPS",
          "WALK BRIDGE",
          "PARKING WALK",
          "HANDICAP PARKING",
          "ROADS & PARKING",
          "SERVICE AREA ESG",
          "ACCESS FROM ROADS TO BUILDINGS",
          "Walking Trails",
          "Boardwalks",
          "Cycle Paths",
          "Pedestrian Areas",
          "Pedestrian Plazas",
          "Ramps",
          "Parking Walkways",
          "Accessible Parking",
        ],
        structures: [
          "Sports & Recreation",
          "Buildings & Facilities",
          "Covered Pergolas",
          "Street Furniture",
        ],
        water: [
          // Muanisiyah uses the architect's native DXF layer names verbatim.
          "02-L-Waterfeatures 01",
          "02-L-Waterfeatures 02",
          "02-L-Waterfeatures 03",
          // Other parks can still expose their own natural Water sub-layers.
          "WATER FEATURES",
          "FOUNTAINS",
          "WTC_FITTINGS",
          "WADI STREAMS",
          "CHANNEL BANKS",
          "WADI BANKS",
          "WADI OUTLINE",
          "SWALE 2M",
          "SWALE 4M",
          "SECONDARY NODE SWALE",
          "CATCHMENT BASINS",
          "HEADPOOL BASINS",
          "CULVERT",
          "SECONDARY CULVERT",
          "ROADS & PARKING CULVERT",
          "CORE BOTANIC ZONE BANK",
          "Water Features",
          "Fountains",
          "Wadi Channels",
          "Swales",
          "Culverts",
          "Drains",
          "Pools",
          "Channels",
          "Ponds",
        ],
        tse: [
          "HV",
          "EX-AAR-PIPE",
          "SERVICE CHAMBER",
          "Powerlines",
          "TSE Pipes",
          "Service Chambers",
          "Lighting",
          "Electrical",
          "Irrigation",
          "Potable Water",
          "Sewage",
          "Storm Water",
          "HVAC",
          "Water Feature System",
          "Powerline",
          "Electric Manhole",
          "TSE Primary",
          "Electric Pole",
          "TSE Secondary",
          "TSE Network",
        ],
      };
      const order = orders[layerKey] || [];
      const index = order.indexOf(label);
      return index >= 0 ? index : order.length + 100;
    },

    clearStandaloneThreeSubLayers() {
      ["paths", "water", "structures", "vegetation", "tse"].forEach(
        (layerKey) => {
          this.$set(this.threeSubLayerAvailability, layerKey, []);
          this.$set(this.threeSubLayerVisibility, layerKey, {});
          // Clearing/reloading GIS data must not silently reopen categories.
          this.$set(this.threeLayerExpanded, layerKey, false);
        },
      );
      this.$set(this, "threeStructureLabelVisibility", {});
      this.$set(this.threeToolState, "structureLabels", false);
      this.$set(this.threeToolState, "treeTypes", false);
      this.$set(this.threeToolState, "shrubTypes", false);
      this.$set(this.threeToolState, "groundCoverTypes", false);
      this.threeVisibleStructureLabels = [];
      this.threeLabelOverlaySignature = "";
      this.$set(this, "threeTreeLabelVisibility", {});
      this.threeTreeAnnotations = [];
      this.threeVisibleTreeLabels = [];
      this.threeTreeLabelOverlaySignature = "";
      this.$set(this, "threeShrubLabelVisibility", {});
      this.threeShrubAnnotations = [];
      this.threeVisibleShrubLabels = [];
      this.threeShrubLabelOverlaySignature = "";
      this.$set(this, "threeGroundCoverLabelVisibility", {});
      this.threeGroundCoverAnnotations = [];
      this.threeVisibleGroundCoverLabels = [];
      this.threeGroundCoverLabelOverlaySignature = "";
    },

    updateStandaloneThreeSubLayerAvailability(geojson) {
      const layerKeys = ["paths", "water", "structures", "vegetation", "tse"];
      const buckets = new Map(layerKeys.map((key) => [key, new Map()]));
      const fallback = this.normalizeStandaloneLayerFilter(
        this.threeProjectGisFallbackLayer,
      );
      const features =
        geojson && Array.isArray(geojson.features) ? geojson.features : [];

      features.forEach((feature) => {
        const explicit = this.getStandaloneFeatureLayer(feature);
        const layerKey = explicit || fallback;
        if (!buckets.has(layerKey)) return;
        const definition = this.getStandaloneSubLayerDefinition(
          layerKey,
          feature,
        );
        buckets.get(layerKey).set(definition.key, definition);
      });

      layerKeys.forEach((layerKey) => {
        const definitions = Array.from(buckets.get(layerKey).values()).sort(
          (first, second) =>
            this.getStandaloneSubLayerSortIndex(layerKey, first.label) -
              this.getStandaloneSubLayerSortIndex(layerKey, second.label) ||
            first.label.localeCompare(second.label),
        );
        const previousVisibility = this.threeSubLayerVisibility[layerKey] || {};
        const nextVisibility = {};
        definitions.forEach((definition) => {
          const hasPreviousValue = Object.prototype.hasOwnProperty.call(
            previousVisibility,
            definition.key,
          );
          const autoEnabled =
            layerKey === "paths"
              ? false
              : layerKey === "tse" && this.isStandaloneMuanisiyahProjectActive()
                ? String(definition.label || "")
                    .trim()
                    .toLowerCase() === "lighting"
                : !(
                    layerKey === "vegetation" &&
                    String(definition.label || "").toLowerCase() ===
                      "planting grid"
                  );

          nextVisibility[definition.key] = hasPreviousValue
            ? previousVisibility[definition.key] !== false
            : autoEnabled;
        });
        this.$set(this.threeSubLayerAvailability, layerKey, definitions);
        this.$set(this.threeSubLayerVisibility, layerKey, nextVisibility);

        if (layerKey === "structures") {
          const previousLabelVisibility =
            this.threeStructureLabelVisibility || {};
          const nextLabelVisibility = {};
          definitions.forEach((definition) => {
            nextLabelVisibility[definition.key] =
              previousLabelVisibility[definition.key] === true;
          });
          this.$set(this, "threeStructureLabelVisibility", nextLabelVisibility);
          this.$set(
            this.threeToolState,
            "structureLabels",
            Object.values(nextLabelVisibility).some(Boolean),
          );
        }

        if (!definitions.length) {
          this.$set(this.threeLayerExpanded, layerKey, false);
        }
      });
    },

    filterStandaloneGeoJsonBySubLayer(geojson, layerKey, subLayerKey) {
      return {
        type: "FeatureCollection",
        properties: (geojson && geojson.properties) || {},
        features:
          geojson && Array.isArray(geojson.features)
            ? geojson.features.filter((feature) => {
                const definition = this.getStandaloneSubLayerDefinition(
                  layerKey,
                  feature,
                );
                return definition.key === subLayerKey;
              })
            : [],
      };
    },

    getStandalonePathSemanticPaletteKey(label = "") {
      const text = String(label || "")
        .trim()
        .toLowerCase();
      if (!text) return "";
      if (/bridge/.test(text)) return "path-bridge";
      if (/stair|step/.test(text)) return "path-stairs";
      if (/parking\s+walk|sidewalk/.test(text)) return "path-sidewalk";
      if (
        /handicap\s+parking|accessible\s+parking|car\s+parking|roads\s*&\s*parking/.test(
          text,
        )
      ) {
        return "path-car-parking";
      }
      if (/^roads?$|access\s+from\s+roads/.test(text)) return "path-road";
      if (
        /trail|boardwalk|bike\s+path|cycle\s+path|pedestrian|plaza|ramp|secondary\s+node|arrival\s+plaza|wadi\s+banks|service\s+area/.test(
          text,
        )
      ) {
        return "path-pedestrian";
      }
      return "";
    },

    applyStandalonePathSubLayerStacking(group, definition = {}) {
      if (!group) return;

      const subLayerKey = String(definition.key || "").toLowerCase();
      const subLayerLabel = String(definition.label || "").toLowerCase();

      const semanticPathKey =
        this.getStandalonePathSemanticPaletteKey(subLayerLabel) ||
        this.getStandalonePathSemanticPaletteKey(subLayerKey);
      const isPedestrianSpace = semanticPathKey === "path-pedestrian";
      const isSidewalk = semanticPathKey === "path-sidewalk";
      const isCarParking = semanticPathKey === "path-car-parking";
      const isRoads = semanticPathKey === "path-road";

      // PATHS overlap hierarchy, lowest -> highest:
      // Sidewalk < Pedestrian Space < Car Parking < Roads.
      //
      // The overlap hierarchy must remain stable at every camera distance.
      // Lower-priority surfaces are pushed back in the depth buffer, while
      // higher-priority surfaces are physically raised and pulled forward.
      // This avoids the zoom-dependent Sidewalk-over-Car-Parking artifact.
      let stackOffset = 0;
      let stackPriority = 1;
      let fillRenderOrder = 6;
      let lineRenderOrder = 7;
      let polygonOffsetFactor = -1;
      let polygonOffsetUnits = -2;

      if (isSidewalk) {
        stackOffset = 0;
        stackPriority = 0;
        fillRenderOrder = 4;
        lineRenderOrder = 5;
        polygonOffsetFactor = 4;
        polygonOffsetUnits = 8;
      } else if (isPedestrianSpace) {
        stackOffset = 0;
        stackPriority = 1;
        fillRenderOrder = 8;
        lineRenderOrder = 9;
        // Pedestrian Space is physically above Sidewalk. Pull it slightly
        // FORWARD in the depth buffer as well so Terrain (After) can never
        // swallow the colored fill at far/default camera distances.
        // Car Parking and Roads still use stronger forward offsets, so the
        // intended PATH hierarchy remains:
        // Sidewalk < Pedestrian Space < Car Parking < Roads.
        polygonOffsetFactor = -6;
        polygonOffsetUnits = -12;
      } else if (isCarParking) {
        // Car Parking must ALWAYS win over Sidewalk, even at close/grazing zooms.
        // The source polygons can sit on slightly different sampled TIN faces, so
        // renderOrder/polygonOffset alone is not sufficient. Give Parking a small
        // REAL vertical stack lift in addition to its existing drape clearance.
        // This keeps the hierarchy deterministic without disabling depth testing.
        stackOffset = 0.08;
        stackPriority = 2;
        fillRenderOrder = 20;
        lineRenderOrder = 21;
        polygonOffsetFactor = -18;
        polygonOffsetUnits = -48;
      } else if (isRoads) {
        // Roads stay above Car Parking after Parking receives its real stack lift.
        stackOffset = 0.11;
        stackPriority = 3;
        fillRenderOrder = 24;
        lineRenderOrder = 25;
        polygonOffsetFactor = -22;
        polygonOffsetUnits = -64;
      } else {
        // Stairs, Bridges and any other specialized path objects retain their
        // existing geometry/render-order logic.
        return;
      }

      group.position.y += stackOffset;
      group.userData.pathStackPriority = stackPriority;

      group.traverse((object) => {
        if (!object || object === group) return;

        const isLineObject = Boolean(
          object.isLine || object.isLineSegments || object.isLineLoop,
        );

        if (object.isMesh) {
          object.renderOrder = fillRenderOrder;
        } else if (isLineObject || object.isPoints) {
          object.renderOrder = lineRenderOrder;
        }

        if (!object.isMesh || !object.material) return;
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        materials.forEach((material) => {
          if (!material || !material.isMaterial) return;
          material.polygonOffset = true;
          material.polygonOffsetFactor = polygonOffsetFactor;
          material.polygonOffsetUnits = polygonOffsetUnits;
          material.depthTest = true;
          material.depthWrite = true;
          // Keep normal depth testing. Render order/polygon offset resolve only
          // coplanar PATHS surfaces; they must never draw through tree canopies,
          // trunks, furniture, structures or other nearer 3D objects.
          material.needsUpdate = true;
        });
      });
    },

    async ensureStandalonePathSubLayerLoaded(definition) {
      if (
        !definition ||
        !definition.key ||
        !this.threeScene ||
        !this.threeParkModelData
      ) {
        return null;
      }

      const parent = this.threeLayerGroups && this.threeLayerGroups.paths;
      if (!parent) return null;

      const existing = parent.children.find(
        (child) =>
          child &&
          child.userData &&
          child.userData.subLayerKey === definition.key,
      );
      if (existing) return existing;

      // Build Stairs before Pedestrian Space so both layers use the same final
      // DXF-derived tread profiles and cutout mask when PATHS is loaded lazily.
      const requestedSemanticKey =
        this.getStandalonePathSemanticPaletteKey(definition.label) ||
        this.getStandalonePathSemanticPaletteKey(definition.key);
      if (
        requestedSemanticKey === "path-pedestrian" &&
        this.isStandaloneMuanisiyahProjectActive()
      ) {
        const stairDefinition = (
          this.getStandaloneThreeSubLayerOptions("paths") || []
        ).find(
          (option) =>
            this.getStandalonePathSemanticPaletteKey(option.label) ===
            "path-stairs",
        );
        const stairSelected = Boolean(
          stairDefinition &&
          (this.threeSubLayerVisibility.paths || {})[stairDefinition.key] ===
            true,
        );
        const stairAlreadyLoaded = Boolean(
          stairDefinition &&
          parent.children.some(
            (child) =>
              child &&
              child.userData &&
              child.userData.subLayerKey === stairDefinition.key,
          ),
        );
        if (stairSelected && !stairAlreadyLoaded) {
          await this.ensureStandalonePathSubLayerLoaded(stairDefinition);
        }
      }

      const urls = this.getStandaloneThreeLayerUrls();
      const url = urls.paths || urls.combined;
      if (!url) return null;

      const sourceGeoJson = await this.getStandaloneCachedGeoJson(url);
      const pathsGeoJson = this.filterStandaloneGeoJsonByLayer(
        sourceGeoJson,
        "paths",
      );
      const childGeoJson = this.filterStandaloneGeoJsonBySubLayer(
        pathsGeoJson,
        "paths",
        definition.key,
      );
      if (!childGeoJson.features.length) return null;

      // Give the browser one frame before a potentially large triangulation so
      // checkbox/UI painting is not blocked by the same event that requested it.
      if (
        typeof window !== "undefined" &&
        typeof window.requestAnimationFrame === "function"
      ) {
        await new Promise((resolve) =>
          window.requestAnimationFrame(() => resolve()),
        );
      }

      const child = await this.createStandaloneGenericFeatureGroup(
        "paths",
        childGeoJson,
        this.threeParkModelData,
        pathsGeoJson,
      );
      child.name = `standalone-paths-${definition.key}`;
      child.userData.subLayerKey = definition.key;
      child.userData.subLayerLabel = definition.label;
      this.applyStandalonePathSubLayerStacking(child, definition);
      this.makeStandaloneLayerGroupOpaque(child);
      this.makeStandaloneGroupUnlitExactColors(child);
      child.visible =
        Boolean(this.threeLayerVisibility.paths) &&
        (this.threeSubLayerVisibility.paths || {})[definition.key] === true;
      parent.add(child);

      parent.userData.featureCount =
        Number(parent.userData.featureCount || 0) +
        Number(child.userData.featureCount || 0);
      parent.userData.polygonCount =
        Number(parent.userData.polygonCount || 0) +
        Number(child.userData.polygonCount || 0);
      parent.userData.pointCount =
        Number(parent.userData.pointCount || 0) +
        Number(child.userData.pointCount || 0);
      parent.userData.segmentCount =
        Number(parent.userData.segmentCount || 0) +
        Number(child.userData.segmentCount || 0);

      this.applyStandaloneConceptPathMode(this.threeToolState.conceptPaths);
      return child;
    },

    async ensureStandaloneUtilitySubLayerLoaded(definition) {
      if (
        !definition ||
        !definition.key ||
        !this.threeScene ||
        !this.threeParkModelData
      ) {
        return null;
      }

      const layerKey = "tse";
      const parent = this.threeLayerGroups && this.threeLayerGroups[layerKey];
      if (!parent) return null;

      const existing = parent.children.find(
        (child) =>
          child &&
          child.userData &&
          child.userData.subLayerKey === definition.key,
      );
      if (existing) return existing;

      const urls = this.getStandaloneThreeLayerUrls();
      const url = urls[layerKey] || urls.combined;
      if (!url) return null;

      const previousLoadingKey = this.threeLayerLoadingKey;
      this.threeLayerLoadingKey = layerKey;
      this.threeLayerError = "";

      try {
        const sourceGeoJson = await this.getStandaloneCachedGeoJson(url);
        const utilityGeoJson = this.filterStandaloneGeoJsonByLayer(
          sourceGeoJson,
          layerKey,
        );
        const childGeoJson = this.filterStandaloneGeoJsonBySubLayer(
          utilityGeoJson,
          layerKey,
          definition.key,
        );
        if (!childGeoJson.features.length) return null;

        // Let the checked state paint before building a potentially large
        // Utility child. Do not build unrelated TSE, irrigation or electrical
        // geometry when only Lighting was selected.
        if (
          typeof window !== "undefined" &&
          typeof window.requestAnimationFrame === "function"
        ) {
          await new Promise((resolve) =>
            window.requestAnimationFrame(() => resolve()),
          );
        }

        const child = await this.createStandaloneGenericFeatureGroup(
          layerKey,
          childGeoJson,
          this.threeParkModelData,
          utilityGeoJson,
        );
        child.name = `standalone-${layerKey}-${definition.key}`;
        child.userData.subLayerKey = definition.key;
        child.userData.subLayerLabel = definition.label;
        this.makeStandaloneLayerGroupOpaque(child);
        this.makeStandaloneGroupUnlitExactColors(child);
        child.visible =
          Boolean(this.threeLayerVisibility[layerKey]) &&
          (this.threeSubLayerVisibility[layerKey] || {})[definition.key] ===
            true;
        parent.add(child);

        parent.userData.featureCount =
          Number(parent.userData.featureCount || 0) +
          Number(child.userData.featureCount || 0);
        parent.userData.polygonCount =
          Number(parent.userData.polygonCount || 0) +
          Number(child.userData.polygonCount || 0);
        parent.userData.pointCount =
          Number(parent.userData.pointCount || 0) +
          Number(child.userData.pointCount || 0);
        parent.userData.segmentCount =
          Number(parent.userData.segmentCount || 0) +
          Number(child.userData.segmentCount || 0);

        return child;
      } catch (error) {
        console.error(
          `The 3D UTILITY ${definition.label || definition.key} sub-layer could not be created:`,
          error,
        );
        const visibility = {
          ...(this.threeSubLayerVisibility[layerKey] || {}),
          [definition.key]: false,
        };
        this.$set(this.threeSubLayerVisibility, layerKey, visibility);
        if (!Object.values(visibility).some(Boolean)) {
          this.$set(this.threeLayerVisibility, layerKey, false);
          parent.visible = false;
        }
        this.threeLayerError = this.isArabicUI()
          ? "تعذر تحميل طبقة المرافق ثلاثية الأبعاد."
          : `The 3D UTILITY ${definition.label || definition.key} sub-layer could not be loaded.`;
        return null;
      } finally {
        if (this.threeLayerLoadingKey === layerKey) {
          this.threeLayerLoadingKey = previousLoadingKey;
        }
      }
    },

    async createStandaloneSubLayeredGenericFeatureGroup(
      layerKey,
      geojson,
      modelData,
      contextGeoJson = geojson,
    ) {
      const parent = new THREE.Group();
      parent.name = `standalone-${layerKey}`;
      parent.userData.hasSubLayers = true;
      const definitions = this.getStandaloneThreeSubLayerOptions(layerKey);
      const requestedDefinitions = definitions.length
        ? definitions
        : [
            {
              key: `${layerKey}-all`,
              label: this.formatStandaloneSubLayerLabel(layerKey),
            },
          ];
      const selectedVisibility = this.threeSubLayerVisibility[layerKey] || {};
      const loadsSelectedChildrenOnly = ["paths", "tse"].includes(layerKey);
      const activeDefinitions =
        loadsSelectedChildrenOnly && definitions.length
          ? requestedDefinitions.filter(
              (definition) => selectedVisibility[definition.key] === true,
            )
          : requestedDefinitions;
      // Keep the Layer Filters UI order unchanged, but construct Muanisiyah's
      // selected Stairs before Pedestrian Space. The visible stair renderer then
      // supplies the exact synchronized top/bottom profiles used by PATHS.
      const buildDefinitions =
        layerKey === "paths" && this.isStandaloneMuanisiyahProjectActive()
          ? activeDefinitions
              .map((definition, originalIndex) => ({
                definition,
                originalIndex,
                priority:
                  this.getStandalonePathSemanticPaletteKey(definition.label) ===
                  "path-stairs"
                    ? 0
                    : this.getStandalonePathSemanticPaletteKey(
                          definition.label,
                        ) === "path-pedestrian"
                      ? 1
                      : 2,
              }))
              .sort(
                (a, b) =>
                  a.priority - b.priority || a.originalIndex - b.originalIndex,
              )
              .map((entry) => entry.definition)
          : activeDefinitions;
      let featureCount = 0;
      let polygonCount = 0;
      let halfBasketballCourtCount = 0;
      let fullBasketballCourtCount = 0;
      let mugaCourtCount = 0;
      let skateparkCount = 0;
      let detailedModularBuildingCount = 0;
      let pointCount = 0;
      let segmentCount = 0;
      let borrowedTerrainAfterSurfaceCount = 0;
      let pedestrianMaskTextureBytes = 0;

      for (const definition of buildDefinitions) {
        await this.yieldStandaloneThreeBuildFrame();
        const childGeoJson = definitions.length
          ? this.filterStandaloneGeoJsonBySubLayer(
              geojson,
              layerKey,
              definition.key,
            )
          : geojson;
        if (!childGeoJson.features.length) continue;

        const child = await this.createStandaloneGenericFeatureGroup(
          layerKey,
          childGeoJson,
          modelData,
          contextGeoJson,
        );
        child.name = `standalone-${layerKey}-${definition.key}`;
        child.userData.subLayerKey = definition.key;
        child.userData.subLayerLabel = definition.label;
        if (layerKey === "paths") {
          this.applyStandalonePathSubLayerStacking(child, definition);
        }
        child.visible =
          !definitions.length ||
          (this.threeSubLayerVisibility[layerKey] || {})[definition.key] !==
            false;
        parent.add(child);
        featureCount += child.userData.featureCount || 0;
        polygonCount += child.userData.polygonCount || 0;
        halfBasketballCourtCount +=
          child.userData.halfBasketballCourtCount || 0;
        fullBasketballCourtCount +=
          child.userData.fullBasketballCourtCount || 0;
        mugaCourtCount += child.userData.mugaCourtCount || 0;
        skateparkCount += child.userData.skateparkCount || 0;
        detailedModularBuildingCount +=
          child.userData.detailedModularBuildingCount || 0;
        pointCount += child.userData.pointCount || 0;
        segmentCount += child.userData.segmentCount || 0;
        borrowedTerrainAfterSurfaceCount +=
          child.userData.borrowedTerrainAfterSurfaceCount || 0;
        pedestrianMaskTextureBytes +=
          child.userData.pedestrianMaskTextureBytes || 0;
      }

      parent.userData.featureCount = featureCount;
      parent.userData.polygonCount = polygonCount;
      parent.userData.halfBasketballCourtCount = halfBasketballCourtCount;
      parent.userData.fullBasketballCourtCount = fullBasketballCourtCount;
      parent.userData.mugaCourtCount = mugaCourtCount;
      parent.userData.skateparkCount = skateparkCount;
      parent.userData.detailedModularBuildingCount =
        detailedModularBuildingCount;
      parent.userData.pointCount = pointCount;
      parent.userData.segmentCount = segmentCount;
      parent.userData.borrowedTerrainAfterSurfaceCount =
        borrowedTerrainAfterSurfaceCount;
      parent.userData.pedestrianMaskTextureBytes = pedestrianMaskTextureBytes;
      return parent;
    },

    async createStandaloneSubLayeredVegetationGroup(
      geojson,
      modelData,
      loadToken,
    ) {
      const parent = new THREE.Group();
      parent.name = "standalone-vegetation";
      parent.userData.hasSubLayers = true;
      const definitions = this.getStandaloneThreeSubLayerOptions("vegetation");
      const activeDefinitions = definitions.length
        ? definitions
        : [{ key: "vegetation-all", label: "Vegetation" }];
      let treeCount = 0;
      let speciesCount = 0;
      let bucketCount = 0;

      for (const definition of activeDefinitions) {
        await this.yieldStandaloneThreeBuildFrame();
        const childGeoJson = definitions.length
          ? this.filterStandaloneGeoJsonBySubLayer(
              geojson,
              "vegetation",
              definition.key,
            )
          : geojson;
        if (!childGeoJson.features.length) continue;

        let child = null;
        try {
          child = await this.createStandaloneVegetationGroup(
            childGeoJson,
            modelData,
            loadToken,
          );
        } catch (error) {
          // One malformed/unsupported CAD vegetation sub-layer must not disable
          // Trees, Shrubs, GroundCover and every other valid Vegetation child.
          // Log the exact child for debugging and continue building the rest.
          console.warn(
            `Skipping failed Vegetation sub-layer ${definition.label || definition.key}:`,
            error,
          );
          continue;
        }
        if (!child) continue;
        child.name = `standalone-vegetation-${definition.key}`;
        child.userData.subLayerKey = definition.key;
        child.userData.subLayerLabel = definition.label;
        child.visible =
          !definitions.length ||
          (this.threeSubLayerVisibility.vegetation || {})[definition.key] !==
            false;
        parent.add(child);
        treeCount += child.userData.treeCount || 0;
        speciesCount += child.userData.speciesCount || 0;
        bucketCount += child.userData.bucketCount || 0;
      }

      parent.userData.treeCount = treeCount;
      parent.userData.speciesCount = speciesCount;
      parent.userData.bucketCount = bucketCount;
      return parent;
    },

    getStandaloneStructureLabelDefinitions() {
      return Array.isArray(this.threeSubLayerAvailability.structures)
        ? this.threeSubLayerAvailability.structures
        : [];
    },

    isStandaloneStructureSubLayerLabelActive(subLayerKey) {
      return Boolean(
        subLayerKey &&
        this.threeStructureLabelVisibility &&
        this.threeStructureLabelVisibility[subLayerKey] === true,
      );
    },

    isStandaloneStructureLabelParentActive() {
      const definitions = this.getStandaloneStructureLabelDefinitions();
      if (!definitions.length) return false;
      return definitions.every((definition) =>
        this.isStandaloneStructureSubLayerLabelActive(definition.key),
      );
    },

    isStandaloneStructureLabelParentPartiallyActive() {
      const definitions = this.getStandaloneStructureLabelDefinitions();
      if (definitions.length < 2) return false;
      const activeCount = definitions.filter((definition) =>
        this.isStandaloneStructureSubLayerLabelActive(definition.key),
      ).length;
      return activeCount > 0 && activeCount < definitions.length;
    },

    setStandaloneAllStructureLabelVisibility(enabled) {
      const definitions = this.getStandaloneStructureLabelDefinitions();
      const nextVisibility = {
        ...(this.threeStructureLabelVisibility || {}),
      };
      definitions.forEach((definition) => {
        nextVisibility[definition.key] = Boolean(enabled);
      });

      this.$set(this, "threeStructureLabelVisibility", nextVisibility);
      const anyEnabled = definitions.some(
        (definition) => nextVisibility[definition.key] === true,
      );
      this.$set(this.threeToolState, "structureLabels", anyEnabled);

      if (!anyEnabled) {
        this.threeVisibleStructureLabels = [];
        this.threeLabelOverlaySignature = "";
      } else {
        this.updateStandaloneStructureLabelOverlay(true);
      }
    },

    handleStandaloneStructureLabelParentCheckboxChange(event) {
      const enabled = Boolean(event && event.target && event.target.checked);
      this.setStandaloneAllStructureLabelVisibility(enabled);
    },

    handleStandaloneStructureSubLayerLabelCheckboxChange(child, event) {
      if (!child || !child.key) return;
      const enabled = Boolean(event && event.target && event.target.checked);
      const nextVisibility = {
        ...(this.threeStructureLabelVisibility || {}),
        [child.key]: enabled,
      };
      this.$set(this, "threeStructureLabelVisibility", nextVisibility);

      const anyEnabled = Object.values(nextVisibility).some(Boolean);
      this.$set(this.threeToolState, "structureLabels", anyEnabled);

      if (!anyEnabled) {
        this.threeVisibleStructureLabels = [];
        this.threeLabelOverlaySignature = "";
      } else {
        this.updateStandaloneStructureLabelOverlay(true);
      }
    },

    setStandaloneAllSubLayerVisibility(layerKey, enabled) {
      const visibility = { ...(this.threeSubLayerVisibility[layerKey] || {}) };
      const definitions = Array.isArray(
        this.threeSubLayerAvailability[layerKey],
      )
        ? this.threeSubLayerAvailability[layerKey]
        : [];
      definitions.forEach((definition) => {
        const isPlantingGrid =
          layerKey === "vegetation" &&
          String(definition.label || "").toLowerCase() === "planting grid";
        const isMuanisiyahUtilityLighting =
          layerKey === "tse" &&
          this.isStandaloneMuanisiyahProjectActive() &&
          String(definition.label || "")
            .trim()
            .toLowerCase() === "lighting";

        // Muanisiyah UTILITY behaves the same when manually re-enabled as it
        // does on initial load: the parent checkbox enables Lighting only.
        // The remaining Utility sub-layers stay opt-in and can still be turned
        // on individually from the expanded UTILITY list.
        if (layerKey === "tse" && this.isStandaloneMuanisiyahProjectActive()) {
          visibility[definition.key] =
            Boolean(enabled) && isMuanisiyahUtilityLighting;
          return;
        }

        // Only Planting Grid is an optional drafting overlay. Planting
        // Callout Leaders, Callout Signs and Symbol Markers behave like normal
        // Vegetation sub-layers and activate with the parent Vegetation layer.
        visibility[definition.key] = Boolean(enabled) && !isPlantingGrid;
      });
      this.$set(this.threeSubLayerVisibility, layerKey, visibility);
    },

    applyStandaloneSubLayerVisibility(layerKey) {
      const parent = this.threeLayerGroups && this.threeLayerGroups[layerKey];
      if (!parent) return;
      const parentVisible = Boolean(this.threeLayerVisibility[layerKey]);
      const visibility = this.threeSubLayerVisibility[layerKey] || {};

      parent.visible = parentVisible;
      parent.children.forEach((child) => {
        const subLayerKey =
          child && child.userData && child.userData.subLayerKey;
        if (!subLayerKey) return;
        child.visible = parentVisible && visibility[subLayerKey] !== false;
      });

      if (layerKey === "paths") {
        this.applyStandaloneConceptPathMode(this.threeToolState.conceptPaths);
      }
      if (layerKey === "structures") {
        this.updateStandaloneStructureLabelOverlay(true);
      }
      if (
        layerKey === "paths" ||
        layerKey === "terrainAfter" ||
        layerKey === "terrainBefore"
      ) {
        this.refreshStandaloneStairCutoutMaterialState();
      }
    },

    isStandalonePathStairSubLayerVisible() {
      if (!this.threeLayerVisibility || !this.threeLayerVisibility.paths) {
        return false;
      }
      // Muanisiyah uses real staircase voids in both Terrain (After) and the
      // Pedestrian Space skin. If PATHS is visible, keep those voids active even
      // while a Stairs checkbox is being lazy-loaded/rebuilt. This prevents the
      // white PATHS slab or Terrain (After) from covering the real stair mesh.
      if (this.isStandaloneMuanisiyahProjectActive()) return true;
      const pathVisibility = this.threeSubLayerVisibility.paths || {};
      return pathVisibility.stairs !== false;
    },

    applyStandaloneStairCutoutStateToMaterial(
      material,
      active = this.isStandalonePathStairSubLayerVisible(),
    ) {
      if (!material) return;
      const userData = material.userData || {};
      const state = userData.stairCutoutState || null;
      const shader = userData.stairCutoutShader || null;
      const uniforms =
        shader && shader.uniforms ? shader.uniforms : material.uniforms;
      if (!state || !uniforms) return;

      const useMask = Boolean(active && state.useMask && state.maskTexture);
      if (uniforms.uStairCutoutCount) {
        uniforms.uStairCutoutCount.value = active ? state.count : 0;
      }
      if (uniforms.uStairCutoutProjection) {
        uniforms.uStairCutoutProjection.value = state.projections;
      }
      if (uniforms.uStairCutoutBounds) {
        uniforms.uStairCutoutBounds.value = state.bounds;
      }
      if (uniforms.uStairCutoutMask) {
        uniforms.uStairCutoutMask.value = useMask ? state.maskTexture : null;
      }
      if (uniforms.uUseStairCutoutMask) {
        uniforms.uUseStairCutoutMask.value = useMask ? 1 : 0;
      }
      if (uniforms.uStairCutoutMaskBounds) {
        const sourceBounds = useMask
          ? state.maskBoundsVector
          : state.emptyMaskBoundsVector;
        const targetBounds = uniforms.uStairCutoutMaskBounds.value;
        if (
          targetBounds &&
          sourceBounds &&
          typeof targetBounds.copy === "function"
        ) {
          targetBounds.copy(sourceBounds);
        } else if (sourceBounds && typeof sourceBounds.clone === "function") {
          uniforms.uStairCutoutMaskBounds.value = sourceBounds.clone();
        } else {
          uniforms.uStairCutoutMaskBounds.value = sourceBounds;
        }
      }

      material.uniformsNeedUpdate = true;
      material.needsUpdate = true;
    },

    refreshStandaloneStairCutoutMaterialState() {
      const active = this.isStandalonePathStairSubLayerVisible();
      const groups = [
        this.threeLayerGroups && this.threeLayerGroups.terrainAfter,
        this.threeLayerGroups && this.threeLayerGroups.paths,
      ];

      groups.forEach((group) => {
        if (!group || typeof group.traverse !== "function") return;
        group.traverse((child) => {
          const materials = Array.isArray(child && child.material)
            ? child.material
            : child && child.material
              ? [child.material]
              : [];
          materials.forEach((material) =>
            this.applyStandaloneStairCutoutStateToMaterial(material, active),
          );
        });
      });
    },

    toggleStandaloneThreeLayerExpanded(layerKey) {
      const isTerrainLayer = ["terrainBefore", "terrainAfter"].includes(
        layerKey,
      );
      if (!isTerrainLayer && !this.threeLayerAvailability[layerKey]) return;
      this.$set(
        this.threeLayerExpanded,
        layerKey,
        !Boolean(this.threeLayerExpanded[layerKey]),
      );
    },

    async handleStandaloneThreeChildLayerCheckboxChange(
      layerKey,
      child,
      event,
    ) {
      if (!child) return;
      const enabled = Boolean(event && event.target && event.target.checked);

      if (child.key === "satelliteGround") {
        await this.setStandaloneSatelliteGroundVisibility(enabled);
        return;
      }
      if (child.key === "compactedGround") {
        await this.setStandaloneCompactedGroundVisibility(enabled);
        return;
      }

      await this.handleStandaloneThreeSubLayerCheckboxChange(
        layerKey,
        child,
        event,
      );
    },

    async handleStandaloneThreeSubLayerCheckboxChange(layerKey, child, event) {
      if (!child || !this.threeLayerAvailability[layerKey]) return;
      const enabled = Boolean(event && event.target && event.target.checked);

      if (enabled && !this.hasStandaloneProjectLandscapeData()) {
        const visibility = {
          ...(this.threeSubLayerVisibility[layerKey] || {}),
          [child.key]: false,
        };
        this.$set(this.threeSubLayerVisibility, layerKey, visibility);
        this.$set(this.threeLayerVisibility, layerKey, false);
        this.threeLayerError =
          this.getStandaloneMissingLandscapeMessage(layerKey);
        return;
      }

      const visibility = { ...(this.threeSubLayerVisibility[layerKey] || {}) };
      visibility[child.key] = enabled;
      this.$set(this.threeSubLayerVisibility, layerKey, visibility);

      if (enabled) {
        if (!this.threeLayerVisibility[layerKey]) {
          await this.setStandaloneThreeLayerVisibility(layerKey, true, {
            preserveSubLayers: true,
          });
        }

        if (layerKey === "paths") {
          await this.ensureStandalonePathSubLayerLoaded(child);
        }
        if (layerKey === "tse") {
          await this.ensureStandaloneUtilitySubLayerLoaded(child);
        }

        this.applyStandaloneSubLayerVisibility(layerKey);
      } else {
        const anyEnabled = Object.values(visibility).some(Boolean);
        if (!anyEnabled) {
          this.$set(this.threeLayerVisibility, layerKey, false);
        }
        this.applyStandaloneSubLayerVisibility(layerKey);
      }
    },

    inferStandaloneThreeLayerType(typeValue, urlValue) {
      const direct = this.normalizeStandaloneLayerFilter(typeValue);
      if (direct) return direct;

      const text = `${String(typeValue || "")} ${String(urlValue || "")}`
        .trim()
        .toLowerCase()
        .replace(/[_-]+/g, " ");

      if (
        /\b(tree|trees|shrub|shrubs|groundcover|ground[_ -]?cover|vegetation|plant|plants)\b/.test(
          text,
        )
      ) {
        return "vegetation";
      }

      if (
        /\b(path|paths|walkway|walkways|trail|trails|cycle|road|parking|pedestrian)\b/.test(
          text,
        )
      ) {
        return "paths";
      }

      if (/\b(water|pond|lake|stream|river|fountain|canal)\b/.test(text)) {
        return "water";
      }

      if (
        /\b(tse|treated sewage effluent|utility|utilities|lighting|light\s*(?:post|pole|fixture)|luminaire|lamp|electric(?:al)?\s*manhole|electric(?:al)?\s*pole|utility\s*pole|power\s*line|powerline)\b/.test(
          text,
        )
      ) {
        return "tse";
      }

      if (
        /\b(structure|structures|building|buildings|facility|facilities|pavilion|kiosk|furniture)\b/.test(
          text,
        )
      ) {
        return "structures";
      }

      return "";
    },

    getStandaloneProjectGisUrl(projectItem = null) {
      const item =
        projectItem ||
        (this.currentProjectId
          ? this.getProjectItemById(this.currentProjectId)
          : null);
      if (!item) return "";

      const entries = this.parseProjectGisValue(item.gis);
      const first = entries.find((entry) =>
        Boolean(String(entry && entry.url ? entry.url : "").trim()),
      );
      return first ? String(first.url).trim() : "";
    },

    getStandaloneThreeLayerUrls(projectItem = null) {
      const item =
        projectItem ||
        (this.currentProjectId
          ? this.getProjectItemById(this.currentProjectId)
          : null);
      const output = {
        combined: "",
        paths: "",
        water: "",
        structures: "",
        vegetation: "",
        tse: "",
      };
      if (!item) return output;

      const entries = this.parseProjectGisValue(item.gis);
      entries.forEach((entry) => {
        const url = String(entry && entry.url ? entry.url : "").trim();
        if (!url) return;

        const layerType = this.inferStandaloneThreeLayerType(
          entry && entry.type,
          url,
        );
        if (layerType && !output[layerType]) {
          output[layerType] = url;
        } else if (!layerType && !output.combined) {
          output.combined = url;
        }
      });

      // A single combined park FeatureCollection is used by every discovered
      // filter. Availability is determined from each feature's layerFilter
      // property after the file is loaded.
      if (output.combined) {
        ["paths", "water", "structures", "vegetation", "tse"].forEach((key) => {
          if (!output[key] && this.threeLayerAvailability[key]) {
            output[key] = output.combined;
          }
        });
      }

      return output;
    },

    getStandaloneFeatureLayer(feature) {
      const properties = (feature && feature.properties) || {};
      const plantingDescriptor = [
        properties._source_layer,
        properties.featureType,
        properties.APP_DISPLAY_LABEL,
        properties["App Display Label"],
        properties.Type,
        properties.type,
      ]
        .filter((value) => value != null && String(value).trim())
        .join(" ")
        .toLowerCase()
        .replace(/[_-]+/g, " ");

      // Planting annotations/markers are vegetation-design data. Keep them
      // under VEGETATION even when the source GeoJSON originally tagged them
      // as STRUCTURES.
      if (/\bplanting\b/.test(plantingDescriptor)) {
        return "vegetation";
      }

      // Handrails are part of the pedestrian circulation system, not a
      // STRUCTURES category. This override intentionally runs BEFORE the
      // exported layerFilter/category value so legacy GeoJSON that still tags
      // Furniture & Equipment railings as STRUCTURES is presented under PATHS.
      const isHandrailFeature =
        String(properties.APP_MODEL || "")
          .trim()
          .toLowerCase() === "cad_handrail" ||
        properties.APP_CAD_RAILING_CENTERLINE === true ||
        /\b(handrail|handrails|railing|railings)\b/.test(plantingDescriptor);
      if (isHandrailFeature) {
        return "paths";
      }

      const explicitLayer = this.normalizeStandaloneLayerFilter(
        properties.layerFilter ||
          properties.layer_filter ||
          properties.appLayer ||
          properties.app_layer ||
          properties.category,
      );
      if (explicitLayer) return explicitLayer;

      // Combined park files can preserve the original exported filename in
      // _source_layer instead of carrying an explicit layerFilter property.
      // Infer the app layer so those combined files remain immediately usable.
      const source = this.getStandaloneFeatureSubLayerSource(feature)
        .trim()
        .toLowerCase()
        .replace(/[\s_-]+/g, "");

      if (
        ["trees", "tree", "shrubs", "shrub", "groundcover"].includes(source)
      ) {
        return "vegetation";
      }
      if (
        [
          "roads",
          "road",
          "paths",
          "path",
          "stairs",
          "stair",
          "staircase",
          "steps",
        ].includes(source)
      ) {
        return "paths";
      }
      if (
        [
          "tseprimary",
          "tseprimarymains",
          "tse",
          "electricpole",
          "electricalpole",
          "manhole",
          "electricmanhole",
          "electricalmanhole",
          "lighting",
          "powerline",
          "powerlines",
        ].includes(source)
      ) {
        return "tse";
      }
      if (
        ["furniture", "structures", "structure", "buildings"].includes(source)
      ) {
        return "structures";
      }
      if (["water", "waters"].includes(source)) return "water";

      if (source === "landcover") {
        const descriptor = [
          properties.QC_REMARKS,
          properties.DC_REMARK,
          properties.APP_MODEL,
          properties.APP_LABEL,
          properties.CL_LAND_COVER_DETAILED,
          properties.CL_LANDUSE_DETAILED,
          properties.Type,
          properties.type,
        ]
          .filter((value) => value != null && String(value).trim())
          .join(" ")
          .toLowerCase()
          .replace(/[_-]+/g, " ");

        if (
          /\bwater\s*feature\b|\bwaterfeature\b|fountain|pond|pool|lake|channel|canal\b/.test(
            descriptor,
          )
        ) {
          return "water";
        }
        if (
          /\bpedestrian\s*space|sidewalk|foot\s*path|footpath|walkway|road|parking\b/.test(
            descriptor,
          )
        ) {
          return "paths";
        }

        // The remaining land-cover polygons in the ArcGIS export are built
        // facilities such as sports courts, pergolas, kiosks and buildings.
        return "structures";
      }

      return this.normalizeStandaloneLayerFilter(source);
    },

    isStandaloneMuanisiyahProjectActive() {
      if (this.activeViewMode !== "project" || !this.currentProjectId)
        return false;
      const item = this.getProjectItemById(this.currentProjectId) || {};
      const descriptor = [
        item.project_id,
        item.name_en,
        item.name_ar,
        item.name,
        this.threeProjectGisUrl,
      ]
        .filter((value) => value != null && String(value).trim())
        .join(" ")
        .toLowerCase();
      return (
        String(item.project_id || "")
          .trim()
          .toUpperCase() === "GP.PK.CP.139" ||
        /muanisiyah|muanisiya|munisiyah|monasya|monas[iy]a/.test(descriptor)
      );
    },

    isStandaloneDefaultLayersParkActive() {
      if (this.activeViewMode !== "project" || !this.currentProjectId) {
        return false;
      }

      const item = this.getProjectItemById(this.currentProjectId) || {};
      return (
        this.isStandaloneMuanisiyahProjectActive() ||
        this.isQadisiyah3ProjectItem(item)
      );
    },

    async enableStandaloneDefaultParkLayers() {
      // Muanisiyah and Qadisiyah 3 are the two authored park models that should
      // open with their design/GIS content visible immediately. Use the same
      // parent-layer code path as a manual checkbox click so any intentionally
      // opt-in child layer (for example Vegetation > Planting Grid) remains off.
      if (!this.isStandaloneDefaultLayersParkActive()) return;

      // Muanisiyah Water depends on the final elevations emitted by the VISIBLE
      // stair-connected PATHS renderer. Build PATHS first there, then Water can
      // use those exact stair/landing profiles instead of the earlier mask-only
      // pre-pass. Qadisiyah retains its established layer build order.
      const defaultLayerKeys = this.isStandaloneMuanisiyahProjectActive()
        ? [
            "paths",
            "water",
            "structures",
            "tse", // displayed as UTILITY in the Layer Filters panel
            "vegetation",
          ]
        : [
            "water",
            "paths",
            "structures",
            "tse", // displayed as UTILITY in the Layer Filters panel
            "vegetation",
          ];

      for (const layerKey of defaultLayerKeys) {
        if (!this.threeLayerAvailability[layerKey]) continue;

        // Create a real browser task boundary between large CAD/GIS layers.
        // Without this, all five default layers monopolize the main thread and
        // Chrome can show its inactive-page dialog before the first frame.
        await this.yieldStandaloneThreeBuildFrame();

        // Muanisiyah opens with the UTILITY parent enabled, but only the
        // architect's Lighting sub-layer should be visible initially. All other
        // Utility datasets remain available in the Layer Filters panel and can
        // still be enabled manually by the user.
        if (layerKey === "tse" && this.isStandaloneMuanisiyahProjectActive()) {
          const utilityVisibility = {};
          const utilityDefinitions = Array.isArray(
            this.threeSubLayerAvailability.tse,
          )
            ? this.threeSubLayerAvailability.tse
            : [];
          utilityDefinitions.forEach((definition) => {
            utilityVisibility[definition.key] =
              String(definition.label || "")
                .trim()
                .toLowerCase() === "lighting";
          });
          this.$set(this.threeSubLayerVisibility, "tse", utilityVisibility);
          await this.setStandaloneThreeLayerVisibility("tse", true, {
            preserveSubLayers: true,
          });
          continue;
        }

        await this.setStandaloneThreeLayerVisibility(layerKey, true);
      }

      // Geometry and annotations no longer need the full source collection.
      // Release it after all default layers have reused the one parsed copy.
      this.threeProjectGisData = null;
      if (
        this.threeProjectGisCache &&
        typeof this.threeProjectGisCache.clear === "function"
      ) {
        this.threeProjectGisCache.clear();
      }
      await this.yieldStandaloneThreeBuildFrame();
    },
    isStandaloneAuthoritativeMuanisiyahWaterFeature(feature) {
      if (!feature || !feature.geometry) return false;
      const geometryType = String(feature.geometry.type || "").toLowerCase();
      if (geometryType !== "polygon" && geometryType !== "multipolygon") {
        return false;
      }

      const properties = feature.properties || {};
      const layerFilter = String(properties.layerFilter || "")
        .trim()
        .toLowerCase();
      if (layerFilter !== "water") return false;

      // Muanisiyah Water is rebuilt directly from the architect's bound DXF.
      // No semantic Supply/Drain/Cascade labels are inferred in Map.vue. Only
      // polygons extracted from the three native 02-L-Waterfeatures layers are
      // accepted by this renderer.
      if (properties.APP_WATER_RAW_DXF_DIRECT !== true) return false;
      const nativeLayer = String(
        properties.CAD_SOURCE_LAYER_NATIVE || properties.APP_SUB_LAYER || "",
      ).trim();
      return [
        "02-L-Waterfeatures 01",
        "02-L-Waterfeatures 02",
        "02-L-Waterfeatures 03",
      ].includes(nativeLayer);
    },

    filterStandaloneGeoJsonByLayer(geojson, layerKey) {
      const normalized = this.normalizeStandaloneLayerFilter(layerKey);
      const fallback = this.normalizeStandaloneLayerFilter(
        this.threeProjectGisFallbackLayer,
      );
      const enforceMuanisiyahCadWater =
        normalized === "water" && this.isStandaloneMuanisiyahProjectActive();

      return {
        type: "FeatureCollection",
        properties: (geojson && geojson.properties) || {},
        features:
          geojson && Array.isArray(geojson.features)
            ? geojson.features.filter((feature) => {
                const explicitLayer = this.getStandaloneFeatureLayer(feature);
                const belongsToLayer = explicitLayer
                  ? explicitLayer === normalized
                  : Boolean(fallback && fallback === normalized);
                if (!belongsToLayer) return false;

                // Muanisiyah WATER is DXF-authoritative. The exported combined
                // file contains General Layout / Buildings / Pavement / Trees and
                // CAD detail blocks as context. None of those may become WATER.
                // Only the real plan polygons carried into GeoJSON with
                // QC_REMARKS=WATERFEATURE are rendered by the WATER layer.
                if (enforceMuanisiyahCadWater) {
                  return this.isStandaloneAuthoritativeMuanisiyahWaterFeature(
                    feature,
                  );
                }
                return true;
              })
            : [],
      };
    },

    async prepareStandaloneProjectGis(projectItem = null) {
      if (!this.threeProjectGisCache) {
        this.threeProjectGisCache = new Map();
      }
      const item =
        projectItem ||
        (this.currentProjectId
          ? this.getProjectItemById(this.currentProjectId)
          : null);
      const entries = item ? this.parseProjectGisValue(item.gis) : [];
      const first = entries.find((entry) =>
        Boolean(String(entry && entry.url ? entry.url : "").trim()),
      );
      const url = first ? String(first.url).trim() : "";
      const fallbackLayer = first
        ? this.inferStandaloneThreeLayerType(first.type, first.url)
        : "";

      this.threeProjectGisUrl = url;
      this.threeProjectGisData = null;
      this.threeProjectGisFallbackLayer = fallbackLayer;
      this.threeProjectGisLoadError = "";

      this.$set(this.threeLayerAvailability, "terrainAfter", true);

      // Prime the UI from the GIS column before fetching the file. This keeps
      // configured GIS filters looking clickable even when Landscape/LandXML is
      // missing, and also prevents a transient GIS fetch problem from greying
      // every filter out. Once the GeoJSON loads, the exact feature contents
      // below refine these optimistic values.
      const configuredAvailability = new Set();
      let hasCombinedGisEntry = false;
      entries.forEach((entry) => {
        const entryUrl = String(entry && entry.url ? entry.url : "").trim();
        if (!entryUrl) return;
        const inferred = this.inferStandaloneThreeLayerType(
          entry && entry.type,
          entryUrl,
        );
        if (inferred) configuredAvailability.add(inferred);
        else hasCombinedGisEntry = true;
      });
      if (hasCombinedGisEntry) {
        ["paths", "water", "structures", "vegetation", "tse"].forEach((key) =>
          configuredAvailability.add(key),
        );
      }
      ["paths", "water", "structures", "vegetation", "tse"].forEach((key) => {
        this.$set(
          this.threeLayerAvailability,
          key,
          configuredAvailability.has(key),
        );
      });
      this.clearStandaloneThreeSubLayers();

      if (!url) return null;

      let geojson = this.threeProjectGisCache.get(url);
      if (!geojson) {
        geojson = await this.loadStandaloneGeoJson(url);
        this.threeProjectGisCache.set(url, geojson);
      }

      this.threeProjectGisData = geojson;
      const available = new Set();
      const metadataLayers =
        geojson &&
        geojson.properties &&
        Array.isArray(geojson.properties.availableLayerFilters)
          ? geojson.properties.availableLayerFilters
          : [];

      metadataLayers.forEach((value) => {
        const key = this.normalizeStandaloneLayerFilter(value);
        if (key) available.add(key);
      });

      geojson.features.forEach((feature) => {
        const key = this.getStandaloneFeatureLayer(feature);
        if (key) available.add(key);
      });

      // Backwards compatibility for an older project whose gis value points
      // directly to trees.geojson, paths.geojson, etc. The new combined park
      // files should contain layerFilter on every feature and do not depend on
      // their filename.
      if (!available.size && fallbackLayer) {
        available.add(fallbackLayer);
      }

      ["paths", "water", "structures", "vegetation", "tse"].forEach((key) => {
        this.$set(this.threeLayerAvailability, key, available.has(key));
      });
      this.updateStandaloneThreeSubLayerAvailability(geojson);

      return geojson;
    },

    applyStandaloneSatelliteGroundDisplay(
      enabled = this.threeLayerVisibility.satelliteGround,
      texture = this.threeSatelliteGroundTexture,
      textureRepeat = { x: 1, y: 1 },
    ) {
      const requestedTexture = Boolean(enabled && texture && texture.isTexture);
      const isSealedGroundTexture = Boolean(
        requestedTexture &&
        this.threeLayerVisibility.compactedGround &&
        this.threeCompactedGroundTexture &&
        texture === this.threeCompactedGroundTexture,
      );
      const repeatX = Math.max(
        1,
        Number(textureRepeat && textureRepeat.x) || 1,
      );
      const repeatY = Math.max(
        1,
        Number(textureRepeat && textureRepeat.y) || 1,
      );
      const groups = this.threeLayerGroups || {};
      const activeTerrainGroupKey =
        this.threeTerrainMode === "after" ? "terrainAfter" : "terrainBefore";
      const terrainVisible = Boolean(this.threeLayerVisibility.terrain);

      ["terrainBefore", "terrainAfter"].forEach((groupKey) => {
        const terrainGroup = groups[groupKey];
        if (
          !terrainGroup ||
          typeof terrainGroup.getObjectByName !== "function"
        ) {
          return;
        }

        const surfaceMesh = terrainGroup.getObjectByName("terrain-top-surface");
        const material = surfaceMesh && surfaceMesh.material;
        const uniforms = material && material.uniforms;
        if (!uniforms) return;

        // Satellite Ground and Sealed Ground are optional texture overrides for
        // whichever terrain elevation surface is ACTIVE. They are not tied to
        // Terrain (Before) or Terrain (After) geometry. This is what allows, for
        // example, Satellite Ground to texture the Civil 3D Terrain (After).
        const useTextureOnThisTerrain = Boolean(
          requestedTexture &&
          terrainVisible &&
          groupKey === activeTerrainGroupKey,
        );
        const useSealedGroundOnThisTerrain = Boolean(
          useTextureOnThisTerrain && isSealedGroundTexture,
        );

        if (
          useTextureOnThisTerrain &&
          texture &&
          texture.isTexture &&
          uniforms.uSatelliteMap &&
          uniforms.uSatelliteMap.value !== texture
        ) {
          const previousTexture = uniforms.uSatelliteMap.value;
          uniforms.uSatelliteMap.value = texture;

          // Each terrain group starts with its own 1x1 fallback texture. Once
          // a real ground texture is assigned to that terrain, the tiny fallback
          // is no longer needed. The same loaded texture object can later be
          // reused when switching between Before and After without duplicating it.
          if (
            previousTexture &&
            previousTexture !== texture &&
            previousTexture.isDataTexture &&
            typeof previousTexture.dispose === "function"
          ) {
            previousTexture.dispose();
          }
        }

        if (uniforms.uUseSatellite) {
          uniforms.uUseSatellite.value = useTextureOnThisTerrain ? 1 : 0;
        }
        if (uniforms.uGroundTextureRepeat) {
          uniforms.uGroundTextureRepeat.value.set(
            useTextureOnThisTerrain ? repeatX : 1,
            useTextureOnThisTerrain ? repeatY : 1,
          );
        }
        if (uniforms.uSatelliteBrightness) {
          uniforms.uSatelliteBrightness.value = useTextureOnThisTerrain
            ? 1.0
            : 0.0;
        }
        if (uniforms.uGridSpacing) {
          const baseGridSpacing = Math.max(
            1,
            Number(surfaceMesh.userData.baseGridSpacing) ||
              Number(uniforms.uGridSpacing.value) ||
              4,
          );
          uniforms.uGridSpacing.value = useSealedGroundOnThisTerrain
            ? THREE_SEALED_GROUND_GRID_CELL_METERS
            : baseGridSpacing;
        }
        if (uniforms.uGridIntensity) {
          // SEALED GROUND needs stronger, tighter cells because the photo
          // texture is visually busy. Satellite Ground stays subtler.
          uniforms.uGridIntensity.value = useSealedGroundOnThisTerrain
            ? THREE_SEALED_GROUND_GRID_OPACITY
            : useTextureOnThisTerrain
              ? 0.24
              : 0.18;
        }
      });
    },

    refreshStandaloneActiveGroundTextureDisplay() {
      // Both texture checkboxes are OFF by default. If the user has explicitly
      // enabled one, preserve that choice while Terrain (Before)/(After) changes
      // and apply the texture only to the newly active terrain surface.
      if (
        this.threeLayerVisibility.compactedGround &&
        this.threeCompactedGroundTexture &&
        this.threeCompactedGroundTexture.isTexture
      ) {
        this.applyStandaloneSatelliteGroundDisplay(
          true,
          this.threeCompactedGroundTexture,
          this.getStandaloneCompactedGroundTextureRepeat(),
        );
        return;
      }

      if (
        this.threeLayerVisibility.satelliteGround &&
        this.threeSatelliteGroundTexture &&
        this.threeSatelliteGroundTexture.isTexture
      ) {
        this.applyStandaloneSatelliteGroundDisplay(
          true,
          this.threeSatelliteGroundTexture,
        );
        return;
      }

      this.applyStandaloneSatelliteGroundDisplay(false);
    },

    getStandaloneSatelliteGroundBounds() {
      const modelData = this.threeParkModelData;
      if (!modelData) return null;

      const beforeData = modelData.terrainBeforeData || modelData;
      return beforeData.geographicBounds || modelData.geographicBounds || null;
    },

    async setStandaloneSatelliteGroundVisibility(enabled) {
      const nextEnabled = Boolean(enabled);
      if (nextEnabled && !this.threeLayerVisibility.terrain) return;

      this.$set(this.threeLayerVisibility, "satelliteGround", nextEnabled);

      if (nextEnabled && this.threeLayerVisibility.compactedGround) {
        this.$set(this.threeLayerVisibility, "compactedGround", false);
        this.threeCompactedGroundLoadToken += 1;
      }

      if (!nextEnabled) {
        this.threeSatelliteGroundLoadToken += 1;
        if (this.threeLayerLoadingKey === "satelliteGround") {
          this.threeLayerLoadingKey = "";
        }
        this.applyStandaloneSatelliteGroundDisplay(false);
        return;
      }

      if (
        this.threeSatelliteGroundTexture &&
        this.threeSatelliteGroundTexture.isTexture
      ) {
        this.applyStandaloneSatelliteGroundDisplay(
          true,
          this.threeSatelliteGroundTexture,
        );
        return;
      }

      const bounds = this.getStandaloneSatelliteGroundBounds();
      if (!bounds) {
        this.$set(this.threeLayerVisibility, "satelliteGround", false);
        this.threeLayerError = this.mapUiText(
          "Satellite Ground is unavailable for this project.",
          "أرضية القمر الصناعي غير متاحة لهذا المشروع.",
          "Satellite Ground is unavailable for this project.",
        );
        return;
      }

      const loadToken = this.threeSatelliteGroundLoadToken + 1;
      this.threeSatelliteGroundLoadToken = loadToken;
      this.threeLayerLoadingKey = "satelliteGround";
      this.threeLayerError = "";

      try {
        const texture = await this.loadStandaloneSatelliteTexture(bounds);

        if (
          loadToken !== this.threeSatelliteGroundLoadToken ||
          !this.threeLayerVisibility.satelliteGround ||
          !this.threeScene
        ) {
          if (texture && typeof texture.dispose === "function") {
            texture.dispose();
          }
          return;
        }

        if (!texture) {
          throw new Error("Satellite texture unavailable.");
        }

        if (
          this.threeRenderer &&
          this.threeRenderer.capabilities &&
          typeof this.threeRenderer.capabilities.getMaxAnisotropy === "function"
        ) {
          texture.anisotropy = Math.min(
            8,
            this.threeRenderer.capabilities.getMaxAnisotropy(),
          );
          texture.needsUpdate = true;
        }

        this.threeSatelliteGroundTexture = texture;
        this.applyStandaloneSatelliteGroundDisplay(true, texture);
      } catch (error) {
        if (loadToken !== this.threeSatelliteGroundLoadToken) return;

        console.warn("Satellite Ground could not be loaded.", error);
        this.$set(this.threeLayerVisibility, "satelliteGround", false);
        this.applyStandaloneSatelliteGroundDisplay(false);
        this.threeLayerError = this.mapUiText(
          "Satellite Ground could not be loaded. Check the Mapbox connection and try again.",
          "تعذر تحميل أرضية القمر الصناعي. تحقق من اتصال Mapbox ثم حاول مرة أخرى.",
          "Satellite Ground could not be loaded. Check the Mapbox connection and try again.",
        );
      } finally {
        if (
          loadToken === this.threeSatelliteGroundLoadToken &&
          this.threeLayerLoadingKey === "satelliteGround"
        ) {
          this.threeLayerLoadingKey = "";
        }
      }
    },

    getStandaloneCompactedGroundTextureRepeat() {
      const modelData = this.threeParkModelData;
      const beforeData =
        modelData && (modelData.terrainBeforeData || modelData);
      const localBounds = beforeData && beforeData.localBounds;
      if (!localBounds) return { x: 1, y: 1 };

      const width = Math.max(
        1,
        Number(localBounds.maxX) - Number(localBounds.minX),
      );
      const depth = Math.max(
        1,
        Number(localBounds.maxZ) - Number(localBounds.minZ),
      );
      const tileMeters = Math.max(4, THREE_PARK_COMPACTED_GROUND_TILE_METERS);

      return {
        x: Math.max(1, Math.min(64, width / tileMeters)),
        y: Math.max(1, Math.min(64, depth / tileMeters)),
      };
    },

    async setStandaloneCompactedGroundVisibility(enabled) {
      const nextEnabled = Boolean(enabled);
      if (nextEnabled && !this.threeLayerVisibility.terrain) return;

      this.$set(this.threeLayerVisibility, "compactedGround", nextEnabled);

      if (!nextEnabled) {
        this.threeCompactedGroundLoadToken += 1;
        if (this.threeLayerLoadingKey === "compactedGround") {
          this.threeLayerLoadingKey = "";
        }

        if (this.threeLayerVisibility.satelliteGround) {
          this.applyStandaloneSatelliteGroundDisplay(
            true,
            this.threeSatelliteGroundTexture,
          );
        } else {
          this.applyStandaloneSatelliteGroundDisplay(false);
        }
        return;
      }

      // Satellite Ground and Sealed Ground are alternate colour textures
      // for the same terrain surface, so only one can be active at a time.
      if (this.threeLayerVisibility.satelliteGround) {
        this.$set(this.threeLayerVisibility, "satelliteGround", false);
        this.threeSatelliteGroundLoadToken += 1;
      }

      const repeat = this.getStandaloneCompactedGroundTextureRepeat();
      if (
        this.threeCompactedGroundTexture &&
        this.threeCompactedGroundTexture.isTexture
      ) {
        this.applyStandaloneSatelliteGroundDisplay(
          true,
          this.threeCompactedGroundTexture,
          repeat,
        );
        return;
      }

      const loadToken = this.threeCompactedGroundLoadToken + 1;
      this.threeCompactedGroundLoadToken = loadToken;
      this.threeLayerLoadingKey = "compactedGround";
      this.threeLayerError = "";

      try {
        const texture = await this.loadStandaloneCompactedGroundTexture();

        if (
          loadToken !== this.threeCompactedGroundLoadToken ||
          !this.threeLayerVisibility.compactedGround ||
          !this.threeScene
        ) {
          if (texture && typeof texture.dispose === "function") {
            texture.dispose();
          }
          return;
        }

        if (!texture) {
          throw new Error("Sealed Ground texture unavailable.");
        }

        if (
          this.threeRenderer &&
          this.threeRenderer.capabilities &&
          typeof this.threeRenderer.capabilities.getMaxAnisotropy === "function"
        ) {
          texture.anisotropy = Math.min(
            8,
            this.threeRenderer.capabilities.getMaxAnisotropy(),
          );
          texture.needsUpdate = true;
        }

        this.threeCompactedGroundTexture = texture;
        this.applyStandaloneSatelliteGroundDisplay(true, texture, repeat);
      } catch (error) {
        if (loadToken !== this.threeCompactedGroundLoadToken) return;

        console.warn("Sealed Ground could not be loaded.", error);
        this.$set(this.threeLayerVisibility, "compactedGround", false);
        this.applyStandaloneSatelliteGroundDisplay(false);
        this.threeLayerError = this.mapUiText(
          "Sealed Ground could not be loaded. Add sealed_ground.png to public/images.",
          "تعذر تحميل الأرضية المختومة. أضف sealed_ground.png إلى public/images.",
          "Sealed Ground could not be loaded. Add sealed_ground.png to public/images.",
        );
      } finally {
        if (
          loadToken === this.threeCompactedGroundLoadToken &&
          this.threeLayerLoadingKey === "compactedGround"
        ) {
          this.threeLayerLoadingKey = "";
        }
      }
    },

    async ensureStandaloneTerrainDisplayGroup(mode = this.threeTerrainMode) {
      const normalizedMode = mode === "before" ? "before" : "after";
      const groupKey =
        normalizedMode === "before" ? "terrainBefore" : "terrainAfter";
      const groups = this.threeLayerGroups || {};
      if (groups[groupKey]) return groups[groupKey];

      const terrainContainer = groups.terrain;
      const rootData = this.threeParkModelData;
      const terrainData =
        rootData && normalizedMode === "before"
          ? rootData.terrainBeforeData || rootData
          : rootData && (rootData.terrainAfterData || rootData);
      if (!terrainContainer || !terrainData) return null;

      const terrainGroup = await this.createStandaloneTerrainGroup(
        terrainData,
        this.threeParkBuildToken,
      );
      terrainGroup.name = `standalone-terrain-${normalizedMode}`;
      terrainGroup.visible = false;
      this.makeStandaloneGroupUnlitExactColors(terrainGroup);
      terrainContainer.add(terrainGroup);
      this.threeLayerGroups[groupKey] = terrainGroup;

      if (normalizedMode === "after") {
        this.refreshStandaloneStairCutoutMaterialState();
      }
      return terrainGroup;
    },

    applyStandaloneTerrainDisplayMode(
      mode = this.threeTerrainMode,
      visible = this.threeLayerVisibility.terrain,
    ) {
      const groups = this.threeLayerGroups || {};
      const terrainContainer = groups.terrain;
      const terrainBeforeGroup = groups.terrainBefore;
      const terrainAfterGroup = groups.terrainAfter;
      if (!terrainContainer) return;

      const shouldShow = Boolean(visible);
      terrainContainer.visible = shouldShow;

      // Terrain (before) and Terrain (after) are separate Three.js groups.
      // "before" uses Mapbox existing-ground elevations; "after" uses the
      // Civil 3D LandXML TIN. Only the selected group is visible.
      if (terrainBeforeGroup) {
        terrainBeforeGroup.visible = shouldShow && mode === "before";
      }
      if (terrainAfterGroup) {
        terrainAfterGroup.visible = shouldShow && mode === "after";
      }

      // Ground textures are independent of the elevation source. Preserve an
      // explicitly selected Satellite/Sealed Ground texture when switching
      // Terrain (Before) <-> Terrain (After), but never auto-enable a texture.
      this.refreshStandaloneActiveGroundTextureDisplay();
    },

    resetStandaloneThreeLayerFilters() {
      this.threeLayerLoadingKey = "";
      this.threeLayerError = "";

      // Prefer the proposed/as-built LandXML surface on project entry whenever
      // the project's landscape column is populated. Once LandXML finishes
      // loading, rebuildStandaloneThreePark() below verifies that the data is
      // actually usable and falls back to Before if necessary.
      const preferTerrainAfter = Boolean(
        this.getStandaloneProjectLandscapeUrl(),
      );
      this.threeTerrainMode = preferTerrainAfter ? "after" : "before";
      this.threeLayerVisibility.terrain = true;
      // Texture sub-layers are always opt-in on map load, even when Terrain
      // (Before) or Terrain (After) itself starts enabled.
      this.threeLayerVisibility.satelliteGround = false;
      this.threeLayerVisibility.compactedGround = false;
      this.threeLayerVisibility.paths = false;
      this.threeLayerVisibility.water = false;
      this.threeLayerVisibility.structures = false;
      this.threeLayerVisibility.vegetation = false;
      this.threeLayerVisibility.tse = false;
      this.threeToolState.structureLabels = false;
      this.threeToolState.conceptPaths = false;
      this.threeToolState.treeTypes = false;
      this.threeToolState.shrubTypes = false;
      this.threeToolState.groundCoverTypes = false;

      // Do not reopen every category whenever the map/project resets.
      // The selected terrain can be active while its row remains collapsed.
      [
        "terrainBefore",
        "terrainAfter",
        "water",
        "paths",
        "structures",
        "vegetation",
        "tse",
      ].forEach((key) => {
        this.$set(this.threeLayerExpanded, key, false);
      });

      this.threeVisibleStructureLabels = [];
      this.$set(this, "threeTreeLabelVisibility", {});
      this.threeTreeAnnotations = [];
      this.threeVisibleTreeLabels = [];
      this.threeTreeLabelOverlaySignature = "";
      this.$set(this, "threeShrubLabelVisibility", {});
      this.threeShrubAnnotations = [];
      this.threeVisibleShrubLabels = [];
      this.threeShrubLabelOverlaySignature = "";
      this.$set(this, "threeGroundCoverLabelVisibility", {});
      this.threeGroundCoverAnnotations = [];
      this.threeVisibleGroundCoverLabels = [];
      this.threeGroundCoverLabelOverlaySignature = "";
      this.threeVegetationLoadToken += 1;
      this.threeSatelliteGroundLoadToken += 1;
      this.threeCompactedGroundLoadToken += 1;

      if (this.threeLayerGroups) {
        this.applyStandaloneTerrainDisplayMode(this.threeTerrainMode, true);
        this.applyStandaloneSatelliteGroundDisplay(false);

        ["paths", "water", "structures", "vegetation", "tse"].forEach((key) => {
          const group = this.threeLayerGroups[key];
          if (group) group.visible = false;
        });
      }
    },

    clearStandaloneVegetationTypeLabels(panelKey) {
      if (panelKey === "treeTypes") {
        this.$set(this, "threeTreeLabelVisibility", {});
        this.updateStandaloneTreeLabelOverlay(true);
        return;
      }

      if (panelKey === "shrubTypes") {
        this.$set(this, "threeShrubLabelVisibility", {});
        this.updateStandaloneShrubLabelOverlay(true);
        return;
      }

      if (panelKey === "groundCoverTypes") {
        this.$set(this, "threeGroundCoverLabelVisibility", {});
        this.updateStandaloneGroundCoverLabelOverlay(true);
      }
    },

    setStandaloneVegetationTypePanel(panelKey, enabled) {
      const panelKeys = ["treeTypes", "shrubTypes", "groundCoverTypes"];
      const requestedEnabled = Boolean(enabled);

      if (panelKey === "treeTypes" && !requestedEnabled) {
        this.closeStandalonePlantImageViewer();
      }

      panelKeys.forEach((key) => {
        const shouldEnable = key === panelKey ? requestedEnabled : false;

        // The Layer Filters second checkbox is the master switch for the
        // corresponding type-label controls. Whenever that checkbox becomes
        // unchecked (including when another vegetation Type panel is opened),
        // clear every species checkbox from that panel and remove its map labels.
        if (!shouldEnable) {
          this.clearStandaloneVegetationTypeLabels(key);
        }

        this.$set(this.threeToolState, key, shouldEnable);
      });
    },

    isStandaloneVegetationTreeLabelAvailable() {
      if (!this.threeLayerAvailability.vegetation) return false;
      const children = this.getStandaloneThreeSubLayerOptions("vegetation");
      const trees = children.find((child) => child && child.key === "trees");
      return Boolean(trees && trees.available && trees.active);
    },

    async handleStandaloneVegetationLabelParentCheckboxChange(event) {
      const nextValue = Boolean(event && event.target && event.target.checked);

      // The Vegetation parent label control intentionally drives only the Trees
      // label/type control. Shrubs and GroundCover keep their own independent
      // label checkboxes, and unavailable vegetation datasets remain disabled.
      if (nextValue && !this.isStandaloneVegetationTreeLabelAvailable()) {
        if (event && event.target) event.target.checked = false;
        return;
      }

      this.setStandaloneVegetationTypePanel("treeTypes", nextValue);
      if (nextValue) await this.ensureStandaloneTreeTypeStats();
    },

    async handleStandaloneTreeTypeCheckboxChange(event) {
      const nextValue = Boolean(event && event.target && event.target.checked);
      this.setStandaloneVegetationTypePanel("treeTypes", nextValue);
      if (nextValue) await this.ensureStandaloneTreeTypeStats();
    },

    async handleStandaloneShrubTypeCheckboxChange(event) {
      const nextValue = Boolean(event && event.target && event.target.checked);
      this.setStandaloneVegetationTypePanel("shrubTypes", nextValue);
      if (nextValue) await this.ensureStandaloneVegetationTypeStats("shrubs");
    },

    async handleStandaloneGroundCoverTypeCheckboxChange(event) {
      const nextValue = Boolean(event && event.target && event.target.checked);
      this.setStandaloneVegetationTypePanel("groundCoverTypes", nextValue);
      if (nextValue)
        await this.ensureStandaloneVegetationTypeStats("groundcover");
    },

    async handleStandaloneThreeToolButtonClick(tool) {
      if (!tool || !tool.enabled) return;

      if (tool.key === "layers") {
        const nextValue = !this.threeToolState.treeTypes;
        this.setStandaloneVegetationTypePanel("treeTypes", nextValue);
        if (nextValue) {
          await this.ensureStandaloneTreeTypeStats();
        }
        return;
      }

      if (tool.key === "measure") {
        const nextValue = !this.threeToolState.conceptPaths;
        this.$set(this.threeToolState, "conceptPaths", nextValue);
        if (nextValue && !this.threeLayerVisibility.paths) {
          await this.setStandaloneThreeLayerVisibility("paths", true);
        }
        this.applyStandaloneConceptPathMode(nextValue);
        return;
      }

      if (tool.key !== "structureLabels") return;

      const nextValue = !this.threeToolState.structureLabels;

      if (nextValue && !this.threeLayerVisibility.structures) {
        await this.setStandaloneThreeLayerVisibility("structures", true);
      }

      // Keep the existing toolbar button as the master "all structure labels"
      // control. The new Layer Filters column can then refine labels by
      // individual Structures sub-category.
      this.setStandaloneAllStructureLabelVisibility(nextValue);
    },

    normalizeStandalonePlantCatalogName(value) {
      return String(value || "")
        .trim()
        .toLowerCase()
        .replace(/[_-]+/g, " ")
        .replace(/[^a-z0-9\s]/g, " ")
        .replace(/\s+/g, " ")
        .trim();
    },

    getStandalonePublicAssetUrl(pathValue) {
      const value = String(pathValue || "")
        .trim()
        .replace(/\\/g, "/");
      if (!value) return "";
      if (/^(?:https?:|data:|blob:)/i.test(value)) return value;

      const baseUrl =
        typeof process !== "undefined" && process.env && process.env.BASE_URL
          ? String(process.env.BASE_URL)
          : "/";
      return `${baseUrl.replace(/\/?$/, "/")}${value.replace(/^\/+/, "")}`;
    },

    async ensureStandalonePathCatalog() {
      // Paths metadata belongs exclusively to the standalone 3D renderer.
      // Never fetch it for a Street/Satellite-only Map.vue instance.
      if (!this.isStandaloneThreeMode || !THREE) return [];
      if (this.threePathCatalogLoaded) return this.threePathCatalogRows || [];
      if (this._threePathCatalogPromise) return this._threePathCatalogPromise;

      const cacheGeneration = Number(this._threeAssetCacheGeneration) || 0;
      const loadPromise = (async () => {
        const baseUrl =
          typeof process !== "undefined" && process.env && process.env.BASE_URL
            ? String(process.env.BASE_URL)
            : "/";
        const candidateUrls = Array.from(
          new Set([
            `${baseUrl.replace(/\/?$/, "/")}data/paths.json`,
            "/data/paths.json",
            "data/paths.json",
          ]),
        );
        let rows = [];
        for (const url of candidateUrls) {
          try {
            const response = await fetch(url, {
              cache: "default",
              signal: this.getStandaloneThreeLoadSignal(),
            });
            if (!response.ok) continue;
            const payload = await response.json();
            rows = Array.isArray(payload)
              ? payload
              : Array.isArray(payload && payload.materials)
                ? payload.materials
                : [];
            if (rows.length) break;
          } catch (error) {
            // Procedural CAD patterns remain the fallback when paths.json is absent.
          }
        }
        if (
          cacheGeneration !== (Number(this._threeAssetCacheGeneration) || 0) ||
          !this.isStandaloneThreeMode
        ) {
          return [];
        }
        // Do not probe every texture in the catalogue. Only textures referenced
        // by features in the currently enabled PATHS sub-layer are resolved.
        this.threePathCatalogRows = rows.filter(
          (row) => row && typeof row === "object",
        );
        this._threePathCatalogMatchCache = new Map();
        this.threePathCatalogLoaded = true;
        return this.threePathCatalogRows;
      })();
      this._threePathCatalogPromise = loadPromise;
      try {
        return await loadPromise;
      } finally {
        if (this._threePathCatalogPromise === loadPromise) {
          this._threePathCatalogPromise = null;
        }
      }
    },

    getStandalonePathCatalogTextureCandidates(row = {}) {
      if (!row || typeof row !== "object") return [];
      const values = [
        row.texture,
        row.image,
        ...(Array.isArray(row.texture_candidates)
          ? row.texture_candidates
          : []),
        ...(Array.isArray(row.textureCandidates) ? row.textureCandidates : []),
        ...(Array.isArray(row.alternate_textures)
          ? row.alternate_textures
          : []),
        ...(Array.isArray(row.alternateTextures) ? row.alternateTextures : []),
      ];
      const unique = [];
      const seen = new Set();
      values.forEach((value) => {
        const path = String(value || "")
          .trim()
          .replace(/\\/g, "/");
        if (!path) return;
        const key = path.toLowerCase();
        if (seen.has(key)) return;
        seen.add(key);
        unique.push(path);
      });
      return unique;
    },

    async resolveStandalonePathCatalogTexture(row = {}) {
      const candidates = this.getStandalonePathCatalogTextureCandidates(row);
      if (!candidates.length) return "";
      for (const candidate of candidates) {
        const url = this.getStandalonePublicAssetUrl(candidate);
        if (!url) continue;
        try {
          const response = await fetch(url, {
            method: "HEAD",
            cache: "default",
            signal: this.getStandaloneThreeLoadSignal(),
          });
          if (response && response.ok) return candidate;
        } catch (error) {
          // Keep trying the remaining local texture candidates.
        }
      }
      // If the server does not support HEAD requests, keep the configured primary
      // candidate so Three.js can still attempt to load it normally.
      return candidates[0];
    },

    async resolveStandalonePathCatalogTexturesForFeatures(features = []) {
      if (!this.isStandaloneThreeMode || !Array.isArray(features)) return;

      const matchedRows = new Set();
      features.forEach((feature) => {
        const row = this.getStandalonePathCatalogMatch(
          (feature && feature.properties) || {},
        );
        if (row && !row.__resolved_texture) matchedRows.add(row);
      });

      // Resolve only the small set of designs actually present in this PATHS
      // sub-layer. Sequential HEAD requests avoid the old all-catalogue burst.
      for (const row of matchedRows) {
        if (!this.isStandaloneThreeMode) return;
        const resolved = await this.resolveStandalonePathCatalogTexture(row);
        if (resolved) row.__resolved_texture = resolved;
      }
    },

    getStandalonePathCatalogMatch(properties = {}) {
      const rows = Array.isArray(this.threePathCatalogRows)
        ? this.threePathCatalogRows
        : [];
      if (!rows.length) return null;
      const normalize = (value) =>
        String(value || "")
          .trim()
          .toLowerCase()
          .replace(/[_-]+/g, " ")
          .replace(/\s+/g, " ");
      const materialName = normalize(
        properties.material_name ||
          properties.MATERIAL_NAME ||
          properties.APP_DISPLAY_LABEL ||
          "",
      );
      const cadColor = String(properties.CAD_PAVEMENT_COLOR_HEX || "")
        .trim()
        .toLowerCase();
      const cacheKey = `${materialName}|${cadColor}`;
      if (!this._threePathCatalogMatchCache) {
        this._threePathCatalogMatchCache = new Map();
      }
      if (this._threePathCatalogMatchCache.has(cacheKey)) {
        return this._threePathCatalogMatchCache.get(cacheKey);
      }
      const match =
        rows.find((row) => {
          if (!row) return false;
          const names = [
            row.material_name,
            row.name,
            ...(Array.isArray(row.aliases) ? row.aliases : []),
          ]
            .map(normalize)
            .filter(Boolean);
          if (!names.includes(materialName)) return false;
          const requiredColor = String(row.cad_color_hex || "")
            .trim()
            .toLowerCase();
          return !requiredColor || requiredColor === cadColor;
        }) || null;
      this._threePathCatalogMatchCache.set(cacheKey, match);
      return match;
    },

    getStandalonePathReferenceTexture(pathValue) {
      const path = String(pathValue || "").trim();
      if (!path) return null;
      if (!this._threePathReferenceTextureCache)
        this._threePathReferenceTextureCache = new Map();
      const url = this.getStandalonePublicAssetUrl(path);
      if (this._threePathReferenceTextureCache.has(url)) {
        return this._threePathReferenceTextureCache.get(url);
      }
      const texture = new THREE.TextureLoader().load(url);
      texture.wrapS = THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping;
      if ("colorSpace" in texture && THREE.SRGBColorSpace)
        texture.colorSpace = THREE.SRGBColorSpace;
      texture.needsUpdate = true;
      this._threePathReferenceTextureCache.set(url, texture);
      return texture;
    },

    async ensureStandalonePlantCatalog() {
      if (!this.isStandaloneThreeMode || !THREE) return [];
      if (this.threePlantCatalogLoaded) return this.threePlantCatalogRows;
      if (this._threePlantCatalogPromise) return this._threePlantCatalogPromise;

      this.threePlantCatalogLoading = true;
      const cacheGeneration = Number(this._threeAssetCacheGeneration) || 0;
      const loadPromise = (async () => {
        const baseUrl =
          typeof process !== "undefined" && process.env && process.env.BASE_URL
            ? String(process.env.BASE_URL)
            : "/";
        const candidateUrls = Array.from(
          new Set([
            `${baseUrl.replace(/\/?$/, "/")}data/plant.json`,
            "/data/plant.json",
            "data/plant.json",
            `${baseUrl.replace(/\/?$/, "/")}data/plants.json`,
            "/data/plants.json",
            "data/plants.json",
          ]),
        );

        // src/data/plants.json is the source of truth for plant names. Import it
        // with the Vue bundle so Arabic name_ar values are available even when
        // /data/plants.json is not exposed by the web server.
        let rows = Array.isArray(plantsCatalogRows) ? plantsCatalogRows : [];

        // Preserve the old public/data lookup only as a deployment fallback.
        if (!rows.length) {
          for (const url of candidateUrls) {
            try {
              const response = await fetch(url, {
                cache: "default",
                signal: this.getStandaloneThreeLoadSignal(),
              });
              if (!response.ok) continue;
              const payload = await response.json();
              if (Array.isArray(payload)) {
                rows = payload;
                break;
              }
            } catch (error) {
              // Try the next path. The app can still use Wikipedia/Commons if
              // plants.json is unavailable in a particular deployment.
            }
          }
        }

        // Keep every plant-catalog row with a usable English name. The same
        // catalogue supplies Arabic names for Trees, Shrubs and GroundCover.
        // Tree-only image enrichment still happens only for the Tree Type panel.
        const catalogRows = rows.filter(
          (row) => row && String(row.name_en || "").trim(),
        );
        if (
          cacheGeneration !== (Number(this._threeAssetCacheGeneration) || 0) ||
          !this.isStandaloneThreeMode
        ) {
          return [];
        }
        this.threePlantCatalogRows = catalogRows;
        this.threePlantCatalogLoaded = true;
        return this.threePlantCatalogRows;
      })();

      this._threePlantCatalogPromise = loadPromise;
      try {
        return await loadPromise;
      } finally {
        if (this._threePlantCatalogPromise === loadPromise) {
          this.threePlantCatalogLoading = false;
          this._threePlantCatalogPromise = null;
        }
      }
    },

    getStandalonePlantCatalogMatch(speciesValue) {
      const key = this.normalizeStandalonePlantCatalogName(speciesValue);
      if (!key) return null;
      const rows = Array.isArray(this.threePlantCatalogRows)
        ? this.threePlantCatalogRows
        : [];
      return (
        rows.find(
          (row) =>
            this.normalizeStandalonePlantCatalogName(row && row.name_en) ===
            key,
        ) || null
      );
    },

    getStandalonePlantPanelDisplayName(plant) {
      const row = plant && typeof plant === "object" ? plant : {};
      const englishName = String(row.name || row.name_en || "").trim();
      const arabicName = String(
        row.plantsJsonNameAr || row.name_ar || "",
      ).trim();
      return this.isArabicUI() && arabicName ? arabicName : englishName;
    },

    async applyStandalonePlantCatalogNames(stats = []) {
      const rows = Array.isArray(stats) ? stats : [];
      if (!rows.length) return;
      await this.ensureStandalonePlantCatalog();

      rows.forEach((plant) => {
        if (!plant || !plant.name) return;
        const catalogRow = this.getStandalonePlantCatalogMatch(plant.name);
        if (!catalogRow) return;
        this.$set(plant, "plantsJsonMatch", true);
        this.$set(
          plant,
          "plantsJsonNameAr",
          String(catalogRow.name_ar || "").trim(),
        );
      });
    },

    getStandalonePlantCatalogImageUrl(row) {
      if (!row || !Array.isArray(row.images) || !row.images.length) return "";
      const firstImage = row.images.find(
        (value) => value != null && String(value).trim(),
      );
      return this.getStandalonePublicAssetUrl(firstImage);
    },
    async ensureStandaloneBuildingCatalog() {
      if (!this.isStandaloneThreeMode || !THREE) return [];
      if (this.threeBuildingCatalogLoaded) return this.threeBuildingCatalogRows;
      if (this._threeBuildingCatalogPromise) {
        return this._threeBuildingCatalogPromise;
      }

      this.threeBuildingCatalogLoading = true;
      const cacheGeneration = Number(this._threeAssetCacheGeneration) || 0;
      const loadPromise = (async () => {
        const baseUrl =
          typeof process !== "undefined" && process.env && process.env.BASE_URL
            ? String(process.env.BASE_URL)
            : "/";
        const candidateUrls = Array.from(
          new Set([
            `${baseUrl.replace(/\/?$/, "/")}data/building.json`,
            "/data/building.json",
            "data/building.json",
          ]),
        );

        let rows = [];
        for (const url of candidateUrls) {
          try {
            const response = await fetch(url, {
              cache: "default",
              signal: this.getStandaloneThreeLoadSignal(),
            });
            if (!response.ok) continue;
            const payload = await response.json();
            if (Array.isArray(payload)) {
              rows = payload;
              break;
            }
          } catch (error) {
            // The structure renderer remains fully functional without
            // building.json; only source-specific design metadata/textures are
            // omitted in deployments that do not include the catalogue.
          }
        }

        const catalogRows = rows.filter(
          (row) => row && typeof row === "object",
        );
        if (
          cacheGeneration !== (Number(this._threeAssetCacheGeneration) || 0) ||
          !this.isStandaloneThreeMode
        ) {
          return [];
        }
        this.threeBuildingCatalogRows = catalogRows;
        this.threeBuildingCatalogLoaded = true;
        return this.threeBuildingCatalogRows;
      })();

      this._threeBuildingCatalogPromise = loadPromise;
      try {
        return await loadPromise;
      } finally {
        if (this._threeBuildingCatalogPromise === loadPromise) {
          this.threeBuildingCatalogLoading = false;
          this._threeBuildingCatalogPromise = null;
        }
      }
    },

    getStandaloneBuildingCatalogMatch(properties = {}) {
      const appModel = this.getStandaloneAppModel(properties);
      if (!appModel) return null;
      const rows = Array.isArray(this.threeBuildingCatalogRows)
        ? this.threeBuildingCatalogRows
        : [];
      return (
        rows.find((row) => {
          if (!row || !row.app_model) return false;
          const key = String(row.app_model)
            .trim()
            .toLowerCase()
            .replace(/[\s-]+/g, "_");
          return key === appModel;
        }) || null
      );
    },

    getStandaloneBuildingCatalogTexturePath(row, textureKey) {
      if (!row || !row.textures) return "";
      const value = row.textures[textureKey];
      if (Array.isArray(value)) {
        const first = value.find((item) => item != null && String(item).trim());
        return first ? String(first).trim() : "";
      }
      return value != null ? String(value).trim() : "";
    },

    getStandaloneBuildingCatalogTexture(row, textureKey) {
      const path = this.getStandaloneBuildingCatalogTexturePath(
        row,
        textureKey,
      );
      if (!path) return null;
      if (!this._threeBuildingTextureCache) {
        this._threeBuildingTextureCache = new Map();
      }
      const cacheKey = `${textureKey}|${path}`;
      if (this._threeBuildingTextureCache.has(cacheKey)) {
        return this._threeBuildingTextureCache.get(cacheKey);
      }
      try {
        const url = this.getStandalonePublicAssetUrl(path);
        const texture = new THREE.TextureLoader().load(url);
        texture.wrapS = THREE.RepeatWrapping;
        texture.wrapT = THREE.RepeatWrapping;
        const repeat = row && row.texture_repeat ? row.texture_repeat : {};
        const repeatValue = repeat[textureKey];
        if (Array.isArray(repeatValue) && repeatValue.length >= 2) {
          texture.repeat.set(
            Math.max(0.01, Number(repeatValue[0]) || 1),
            Math.max(0.01, Number(repeatValue[1]) || 1),
          );
        }
        if (THREE.SRGBColorSpace) texture.colorSpace = THREE.SRGBColorSpace;
        texture.needsUpdate = true;
        this._threeBuildingTextureCache.set(cacheKey, texture);
        return texture;
      } catch (error) {
        return null;
      }
    },
    getStandaloneMuanisiyahTreeReferenceCandidates(speciesValue) {
      const species = this.normalizeStandalonePlantCatalogName(speciesValue);
      // These candidate basenames mirror the Muanisiyah reference-image files, but
      // every path is resolved from the same projects_images/Trees folder used by
      // the existing dashboard tree assets. plants.json / GeoJSON explicit paths win.
      const names = {
        "acacia ehrenbergiana": [
          "Acacia_ehrenbergiana",
          "acacia ehrenbergiana",
        ],
        "acacia farnesiana": ["Acacia_farnesiana"],
        "azadirachta indica": ["Azadirachta_indica"],
        "delonix regia": ["Delonix_regia"],
        "ficus religiosa": ["Ficus_religiosa"],
        "ziziphus spina christi": [
          "Ziziphus_spina-christi",
          "Ziziphus_spina_christi",
        ],
        "acacia nilotica": ["ACACIA_NILOTICA", "Acacia_nilotica"],
        "acacia etbaica": ["ACACIA_ETBAICA", "Acacia_etbaica"],
        "acacia gerrardii": [
          "Acacia_gerrardii",
          "ACACIA_GERRADII",
          "ACACIA_GERRARDII",
        ],
        "acacia pycnantha": ["ACACIA_PYCNANTHA", "Acacia_pycnantha"],
        "albizia lebbeck": [
          "Albizia_lebbeck",
          "ALBIZIA_LEBBECK",
          "ALBIZIA_LEBBECK2",
        ],
        "bombax ceiba": ["BOMBAX_CEIBA", "Bombax_ceiba", "BOMBAX CEIBA"],
        "cercidium floridum": ["CERCIDIUM_FLORIDUM - Parkinsonia-florida_PRV1"],
        "melia azedarach": [
          "Melia_azedarach",
          "MELIA_AZEDARACH",
          "MELIA_AZEDARACH1",
        ],
        "parkinsonia aculeata": [
          "PARKINSONIA_ACUELATA",
          "PARKINSONIA_ACULEATA",
        ],
        "prosopis cineraria": [
          "prosopis cineraria",
          "Prosopis_cineraria",
          "PROSOPIS_CINERARIA",
        ],
      };
      const basenames = names[species] || [];
      const extensions = [".jpg", ".jpeg", ".png", ".JPG", ".PNG"];
      const paths = [];
      basenames.forEach((basename) => {
        extensions.forEach((extension) => {
          paths.push(`projects_images/Trees/${basename}${extension}`);
        });
      });
      return paths;
    },

    async loadStandaloneReferenceTexture(urlValue, options = {}) {
      const url = String(urlValue || "").trim();
      if (!url) return null;
      if (!this._threeReferenceTextureCache) {
        this._threeReferenceTextureCache = new Map();
      }
      const cutout = options.cutout === true;
      const cacheKey = `${cutout ? "cutout" : "plain"}:${url}`;
      if (this._threeReferenceTextureCache.has(cacheKey)) {
        return this._threeReferenceTextureCache.get(cacheKey);
      }

      const promise = new Promise((resolve) => {
        const loader = new THREE.TextureLoader();
        loader.load(
          url,
          (loadedTexture) => {
            let texture = loadedTexture;
            try {
              if (
                cutout &&
                loadedTexture &&
                loadedTexture.image &&
                typeof document !== "undefined"
              ) {
                const image = loadedTexture.image;
                const sourceWidth = Math.max(
                  1,
                  Number(image.naturalWidth || image.width) || 1,
                );
                const sourceHeight = Math.max(
                  1,
                  Number(image.naturalHeight || image.height) || 1,
                );
                const maxDimension = 768;
                const scale = Math.min(
                  1,
                  maxDimension / Math.max(sourceWidth, sourceHeight),
                );
                const width = Math.max(1, Math.round(sourceWidth * scale));
                const height = Math.max(1, Math.round(sourceHeight * scale));
                const canvas = document.createElement("canvas");
                canvas.width = width;
                canvas.height = height;
                const context = canvas.getContext("2d", {
                  willReadFrequently: true,
                });
                if (context) {
                  context.drawImage(image, 0, 0, width, height);
                  const imageData = context.getImageData(0, 0, width, height);
                  const data = imageData.data;
                  const cornerPoints = [
                    [1, 1],
                    [Math.max(0, width - 2), 1],
                    [1, Math.max(0, height - 2)],
                    [Math.max(0, width - 2), Math.max(0, height - 2)],
                  ];
                  let bgR = 0;
                  let bgG = 0;
                  let bgB = 0;
                  cornerPoints.forEach(([x, y]) => {
                    const offset = (y * width + x) * 4;
                    bgR += data[offset];
                    bgG += data[offset + 1];
                    bgB += data[offset + 2];
                  });
                  bgR /= cornerPoints.length;
                  bgG /= cornerPoints.length;
                  bgB /= cornerPoints.length;

                  for (let offset = 0; offset < data.length; offset += 4) {
                    const r = data[offset];
                    const g = data[offset + 1];
                    const b = data[offset + 2];
                    const dr = r - bgR;
                    const dg = g - bgG;
                    const db = b - bgB;
                    const distance = Math.sqrt(dr * dr + dg * dg + db * db);
                    const maxChannel = Math.max(r, g, b);
                    const minChannel = Math.min(r, g, b);
                    const lowSaturation = maxChannel - minChannel < 18;
                    const nearWhite = maxChannel > 238 && lowSaturation;
                    let alpha = data[offset + 3];
                    if (nearWhite || distance < 34) {
                      alpha = 0;
                    } else if (distance < 92) {
                      alpha = Math.min(
                        alpha,
                        Math.round(((distance - 34) / 58) * 255),
                      );
                    }
                    data[offset + 3] = alpha;
                  }
                  context.putImageData(imageData, 0, 0);
                  texture = new THREE.CanvasTexture(canvas);
                  if (loadedTexture.dispose) loadedTexture.dispose();
                }
              }

              texture.wrapS = THREE.ClampToEdgeWrapping;
              texture.wrapT = THREE.ClampToEdgeWrapping;
              texture.magFilter = THREE.LinearFilter;
              texture.minFilter = THREE.LinearMipmapLinearFilter;
              texture.generateMipmaps = true;
              if (THREE.SRGBColorSpace && "colorSpace" in texture) {
                texture.colorSpace = THREE.SRGBColorSpace;
              } else if (THREE.sRGBEncoding) {
                texture.encoding = THREE.sRGBEncoding;
              }
              texture.needsUpdate = true;
              resolve(texture);
            } catch (error) {
              if (loadedTexture && loadedTexture.dispose)
                loadedTexture.dispose();
              resolve(null);
            }
          },
          undefined,
          () => resolve(null),
        );
      });

      this._threeReferenceTextureCache.set(cacheKey, promise);
      return promise;
    },

    async resolveStandaloneTreeReferenceTexture(
      speciesValue,
      explicitPathValue = "",
    ) {
      await this.ensureStandalonePlantCatalog();
      const catalogRow = this.getStandalonePlantCatalogMatch(speciesValue);
      const catalogImages =
        catalogRow && Array.isArray(catalogRow.images) ? catalogRow.images : [];
      const preferredCatalogPaths = catalogImages.filter((value) =>
        /^(?:projects_images[\\/]Trees|Trees|Arboles)[\\/]/i.test(
          String(value || "").trim(),
        ),
      );
      const candidates = [
        String(explicitPathValue || "").trim(),
        ...preferredCatalogPaths,
        ...this.getStandaloneMuanisiyahTreeReferenceCandidates(speciesValue),
      ];
      const seen = new Set();
      for (const candidate of candidates) {
        const path = String(candidate || "")
          .trim()
          .replace(/\\/g, "/");
        if (!path || seen.has(path.toLowerCase())) continue;
        seen.add(path.toLowerCase());
        const url = this.getStandalonePublicAssetUrl(path);
        const texture = await this.loadStandaloneReferenceTexture(url, {
          cutout: true,
        });
        if (texture) return { texture, url, path };
      }
      return null;
    },

    async createStandaloneTreeReferenceImageGroup(treeRecords, loadToken) {
      const group = new THREE.Group();
      group.name = "vegetation-tree-reference-images";
      if (!Array.isArray(treeRecords) || !treeRecords.length) return group;

      const buckets = new Map();
      treeRecords.forEach((tree) => {
        const key = this.normalizeStandalonePlantCatalogName(tree.species);
        if (!key) return;
        if (!buckets.has(key)) {
          buckets.set(key, {
            species: tree.species,
            referenceImagePath: tree.referenceImagePath || "",
            trees: [],
          });
        }
        buckets.get(key).trees.push(tree);
      });

      const referenceProfileKeys = [];
      for (const bucket of buckets.values()) {
        if (loadToken !== this.threeVegetationLoadToken) break;
        const resolved = await this.resolveStandaloneTreeReferenceTexture(
          bucket.species,
          bucket.referenceImagePath,
        );
        if (!resolved || !resolved.texture) continue;
        const referenceProfileKey = this.getStandaloneTreeProfile(
          bucket.species,
        ).key;
        if (!referenceProfileKeys.includes(referenceProfileKey)) {
          referenceProfileKeys.push(referenceProfileKey);
        }

        const geometry = new THREE.PlaneGeometry(1, 1, 1, 1);
        const instanceOpacity = new THREE.InstancedBufferAttribute(
          new Float32Array(bucket.trees.length).fill(1),
          1,
        );
        instanceOpacity.setUsage(THREE.DynamicDrawUsage);
        geometry.setAttribute("instanceOpacity", instanceOpacity);
        const material = new THREE.MeshBasicMaterial({
          color: 0xffffff,
          map: resolved.texture,
          transparent: true,
          // The reference photo supplies species-specific leaf density, branching
          // and colour while the procedural canopy underneath preserves true 3D
          // volume from bird's-eye views.
          opacity: 0.78,
          alphaTest: 0.12,
          side: THREE.DoubleSide,
          depthTest: true,
          depthWrite: false,
          toneMapped: false,
        });
        this.enableStandaloneVegetationInstanceOpacity(material);

        // Two crossed photographic cutouts are the standard low-poly tree-card approach.
        // The existing procedural crown remains underneath so the tree still has a
        // believable top surface when the camera is high above the park.
        const angles = [0, Math.PI / 2];
        angles.forEach((angleOffset, planeIndex) => {
          const mesh = new THREE.InstancedMesh(
            geometry,
            material,
            bucket.trees.length,
          );
          mesh.name = `vegetation-reference-tree-${
            this.getStandaloneTreeProfile(bucket.species).key
          }-${planeIndex + 1}`;
          mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
          mesh.renderOrder = 13;
          mesh.userData.preserveReferenceTransparency = true;
          mesh.userData.referenceImageUrl = resolved.url;
          mesh.userData.instanceOpacityAttribute = instanceOpacity;
          mesh.userData.treeScreenRecords = bucket.trees.map((tree) => ({
            x: Number(tree.local.x),
            y: Number(tree.baseY) + Number(tree.height) * 0.52,
            z: Number(tree.local.z),
            radius: Math.max(Number(tree.crown || 0) / 2, 0.8),
          }));

          const dummy = new THREE.Object3D();
          bucket.trees.forEach((tree, index) => {
            // Match the CAD mature height/spread instead of the pixel dimensions
            // of the source photograph. This keeps scale exact while the photo
            // supplies species-specific silhouette, density, branching and colour.
            dummy.position.set(
              Number(tree.local.x),
              Number(tree.baseY) + Number(tree.height) * 0.5,
              Number(tree.local.z),
            );
            dummy.rotation.set(0, Number(tree.rotation || 0) + angleOffset, 0);
            dummy.scale.set(
              Math.max(1.2, Number(tree.crown || 0)),
              Math.max(2.5, Number(tree.height || 0)),
              1,
            );
            dummy.updateMatrix();
            mesh.setMatrixAt(index, dummy.matrix);
          });
          mesh.instanceMatrix.needsUpdate = true;
          group.add(mesh);
        });
      }

      group.userData.referenceProfileKeys = referenceProfileKeys;
      group.userData.referenceSpeciesCount = referenceProfileKeys.length;
      return group;
    },

    getStandalonePlantCatalogDescription(row, language = "en") {
      if (!row || typeof row !== "object") return "";
      const isArabic = String(language || "")
        .toLowerCase()
        .startsWith("ar");
      const preferredKeys = isArabic
        ? [
            "description_ar",
            "descriptionArabic",
            "description_arabic",
            "desc_ar",
            "remarks_ar",
            "notes_ar",
          ]
        : [
            "description_en",
            "descriptionEnglish",
            "description_english",
            "desc_en",
            "remarks_en",
            "notes_en",
          ];
      const fallbackKeys = [
        "description",
        "desc",
        "remarks",
        "notes",
        "summary",
      ];

      for (const key of [...preferredKeys, ...fallbackKeys]) {
        const value = row[key];
        if (value == null) continue;
        const description = String(value).trim();
        if (description) return description;
      }
      return "";
    },

    getStandaloneTreeViewerDescription(tree) {
      const row = tree && typeof tree === "object" ? tree : {};

      // plants.json currently supplies the plant names/images, while the visible
      // description is normally the Wikipedia intro. Keep the Wikipedia extracts
      // separate by language so switching the UI to Arabic never reuses the
      // English extract that may already have been loaded.
      if (this.isArabicUI()) {
        const localArabicDescription = String(
          row.plantsJsonDescriptionAr || "",
        ).trim();
        const arabicWikipediaDescription = String(
          row.wikipediaExtractAr || "",
        ).trim();

        if (localArabicDescription) return localArabicDescription;
        if (arabicWikipediaDescription) return arabicWikipediaDescription;
        return "لا يوجد وصف متاح لهذا النوع.";
      }

      const localEnglishDescription = String(
        row.plantsJsonDescriptionEn || "",
      ).trim();
      const englishWikipediaDescription = String(
        row.wikipediaExtractEn || row.wikipediaExtract || "",
      ).trim();

      if (localEnglishDescription) return localEnglishDescription;
      if (englishWikipediaDescription) return englishWikipediaDescription;
      return "No description is available for this species.";
    },

    async applyStandaloneTreeCatalogImages(stats = []) {
      const rows = Array.isArray(stats) ? stats : [];
      if (!rows.length) return;
      await this.ensureStandalonePlantCatalog();

      rows.forEach((tree) => {
        if (!tree || !tree.name) return;
        const speciesKey = this.normalizeStandalonePlantCatalogName(tree.name);
        const catalogRow = this.getStandalonePlantCatalogMatch(tree.name);

        let imageUrl = catalogRow
          ? this.getStandalonePlantCatalogImageUrl(catalogRow)
          : "";

        // Muanisiyah's Acacia etbaica reference image was renamed to this
        // clean filename. Prefer it directly so an older plants.json/browser
        // cache can never leave the Wikipedia/Commons placeholder in the panel.
        if (speciesKey === "acacia etbaica") {
          const localUrl = this.getStandalonePublicAssetUrl(
            "projects_images/Trees/ACACIA_ETBAICA.png",
          );
          const separator = localUrl.includes("?") ? "&" : "?";
          imageUrl = `${localUrl}${separator}v=20260906-acacia-etbaica`;
        }

        if (!catalogRow && !imageUrl) return;

        this.$set(tree, "plantsJsonMatch", Boolean(catalogRow));
        this.$set(
          tree,
          "plantsJsonId",
          catalogRow ? String(catalogRow.id || "") : "",
        );
        this.$set(
          tree,
          "plantsJsonNameAr",
          catalogRow ? String(catalogRow.name_ar || "") : "",
        );
        this.$set(
          tree,
          "plantsJsonDescriptionEn",
          this.getStandalonePlantCatalogDescription(catalogRow, "en"),
        );
        this.$set(
          tree,
          "plantsJsonDescriptionAr",
          this.getStandalonePlantCatalogDescription(catalogRow, "ar"),
        );

        if (imageUrl) {
          // Preserve any network image as a fallback in case the local public
          // asset is missing, but always prefer the explicit plants.json image.
          if (tree.imageUrl && tree.imageUrl !== imageUrl) {
            this.$set(tree, "fallbackImageUrl", String(tree.imageUrl));
          }
          this.$set(tree, "plantsJsonImage", true);
          this.$set(tree, "imageUrl", imageUrl);
        }
      });
    },

    updateStandalonePlantImageViewerBounds() {
      const host = this.$refs && this.$refs.threeParkHost;
      if (!host || typeof host.getBoundingClientRect !== "function") return;

      const rect = host.getBoundingClientRect();
      const viewportWidth =
        typeof window !== "undefined"
          ? Number(window.innerWidth) || rect.right
          : rect.right;
      const viewportHeight =
        typeof window !== "undefined"
          ? Number(window.innerHeight) || rect.bottom
          : rect.bottom;

      const left = Math.max(0, Math.min(viewportWidth, Number(rect.left) || 0));
      const top = Math.max(0, Math.min(viewportHeight, Number(rect.top) || 0));
      const right = Math.max(
        left,
        Math.min(viewportWidth, Number(rect.right) || left),
      );
      const bottom = Math.max(
        top,
        Math.min(viewportHeight, Number(rect.bottom) || top),
      );

      this.threePlantImageViewerStyle = {
        top: `${Math.round(top)}px`,
        left: `${Math.round(left)}px`,
        width: `${Math.max(0, Math.round(right - left))}px`,
        height: `${Math.max(0, Math.round(bottom - top))}px`,
        right: "auto",
        bottom: "auto",
      };
    },

    openStandalonePlantImageViewer(tree) {
      const src = tree && tree.imageUrl ? String(tree.imageUrl) : "";
      if (!src || !this.isStandaloneThreeMode) return;

      this.threePlantImageViewerSrc = src;
      // Use plants.json name_ar in Arabic mode instead of the CAD/GIS English
      // species name stored in tree.name.
      this.threePlantImageViewerName =
        this.getStandalonePlantPanelDisplayName(tree) ||
        this.mapUiText("Plant", "نبات", "Plant");
      this.threePlantImageViewerDescription =
        this.getStandaloneTreeViewerDescription(tree);
      this.updateStandalonePlantImageViewerBounds();
      this.threePlantImageViewerOpen = true;

      // Re-read the host rectangle after Vue has painted the overlay. This keeps
      // the viewer exactly inside the map even if the map was just expanded.
      this.$nextTick(() => {
        this.updateStandalonePlantImageViewerBounds();
      });

      if (typeof window !== "undefined") {
        window.removeEventListener(
          "resize",
          this.updateStandalonePlantImageViewerBounds,
        );
        window.addEventListener(
          "resize",
          this.updateStandalonePlantImageViewerBounds,
        );
      }
    },

    closeStandalonePlantImageViewer() {
      this.threePlantImageViewerOpen = false;
      this.threePlantImageViewerSrc = "";
      this.threePlantImageViewerName = "";
      this.threePlantImageViewerDescription = "";
      if (typeof window !== "undefined") {
        window.removeEventListener(
          "resize",
          this.updateStandalonePlantImageViewerBounds,
        );
      }
    },

    getStandaloneTreeWikipediaTitle(speciesValue) {
      // Keep the exact botanical name supplied by the CAD/GIS data as the primary
      // lookup term. Do not pre-emptively replace it with a modern synonym because
      // English Wikipedia does not necessarily have a standalone page under the
      // accepted name (Acacia etbaica / Vachellia etbaica is one such case).
      return String(speciesValue || "")
        .trim()
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ");
    },

    getStandaloneTreeAcceptedTaxonTitle(speciesValue) {
      const species = this.normalizeStandaloneTreeSpeciesKey(speciesValue);
      if (!species) return "";

      // Accepted botanical names are secondary lookup candidates only. Wikipedia's
      // own redirect/page resolution decides whether a real English article exists.
      const titles = {
        "acacia nilotica": "Vachellia nilotica",
        "vachellia nilotica": "Vachellia nilotica",
        "acacia etbaica": "Vachellia etbaica",
        "vachellia etbaica": "Vachellia etbaica",
        "acacia gerrardii": "Vachellia gerrardii",
        "vachellia gerrardii": "Vachellia gerrardii",
        "acacia farnesiana": "Vachellia farnesiana",
        "vachellia farnesiana": "Vachellia farnesiana",
        "cercidium floridum": "Parkinsonia florida",
        "parkinsonia florida": "Parkinsonia florida",
        "ziziphus spina christi": "Ziziphus spina-christi",
        "ziziphus spina-christi": "Ziziphus spina-christi",
      };
      return (
        titles[species] || this.getStandaloneTreeWikipediaTitle(speciesValue)
      );
    },

    getStandaloneTreeWikipediaCandidateTitles(speciesValue) {
      const originalTitle = this.getStandaloneTreeWikipediaTitle(speciesValue);
      const acceptedTitle =
        this.getStandaloneTreeAcceptedTaxonTitle(speciesValue);
      return Array.from(
        new Set(
          [originalTitle, acceptedTitle]
            .map((value) => String(value || "").trim())
            .filter(Boolean),
        ),
      );
    },

    getStandaloneTreeWikipediaArticleUrl(titleValue, language = "en") {
      const title = String(titleValue || "").trim();
      if (!title) return "";
      const languageCode = String(language || "en")
        .toLowerCase()
        .startsWith("ar")
        ? "ar"
        : "en";
      return `https://${languageCode}.wikipedia.org/wiki/${encodeURIComponent(
        title.replace(/\s+/g, "_"),
      ).replace(/%2F/gi, "/")}`;
    },

    getStandaloneTreeWikipediaSearchUrl(speciesValue, language = "en") {
      const title = String(speciesValue || "")
        .trim()
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ");
      if (!title) return "";

      const isArabic = String(language || "en")
        .toLowerCase()
        .startsWith("ar");
      // English botanical names benefit from the "tree" suffix. For Arabic,
      // search the plants.json name_ar directly so the result stays Arabic.
      const query = isArabic
        ? title
        : /\btree\b/i.test(title)
          ? title
          : `${title} tree`;
      const languageCode = isArabic ? "ar" : "en";
      return (
        `https://${languageCode}.wikipedia.org/w/index.php?` +
        `search=${encodeURIComponent(query)}` +
        "&title=Special%3ASearch&ns0=1"
      );
    },

    getStandaloneTreeWikipediaUrl(speciesValue) {
      // Until the Wikipedia API verifies that an exact page exists, use a safe
      // search URL. This prevents links to guessed/non-existent article titles.
      return this.getStandaloneTreeWikipediaSearchUrl(speciesValue, "en");
    },

    async getStandaloneCommonsTreeThumbnail(candidateTitles = []) {
      const candidates = Array.isArray(candidateTitles) ? candidateTitles : [];
      for (const candidateTitle of candidates) {
        const title = String(candidateTitle || "").trim();
        if (!title) continue;

        try {
          const endpoint =
            "https://commons.wikimedia.org/w/api.php" +
            "?origin=*" +
            "&action=query" +
            "&format=json" +
            "&generator=search" +
            "&gsrnamespace=6" +
            "&gsrlimit=8" +
            `&gsrsearch=${encodeURIComponent(`\"${title}\"`)}` +
            "&prop=imageinfo" +
            "&iiprop=url" +
            "&iiurlwidth=180";

          const response = await fetch(endpoint, {
            method: "GET",
            mode: "cors",
            credentials: "omit",
          });
          if (!response.ok) continue;

          const payload = await response.json();
          const pages =
            payload && payload.query && payload.query.pages
              ? Object.values(payload.query.pages)
              : [];
          const imagePage =
            pages.find((page) => {
              if (
                !page ||
                !Array.isArray(page.imageinfo) ||
                !page.imageinfo.length
              ) {
                return false;
              }
              const fileTitle = String(page.title || "").toLowerCase();
              return !/map|distribution|range|herbarium|specimen|drawing|illustration/.test(
                fileTitle,
              );
            }) ||
            pages.find(
              (page) =>
                page && Array.isArray(page.imageinfo) && page.imageinfo.length,
            );

          if (!imagePage) continue;
          const imageInfo = imagePage.imageinfo[0] || {};
          const url = String(imageInfo.thumburl || imageInfo.url || "").trim();
          if (url) return url;
        } catch (error) {
          // Commons imagery is optional. Continue with the next botanical synonym.
        }
      }
      return "";
    },

    async enrichStandaloneTreeTypeWikipedia(stats = []) {
      const rows = Array.isArray(stats) ? stats : [];
      if (!rows.length) return;

      const fetchWikipediaLanguage = async (tree, language = "en") => {
        const isArabic = String(language || "en")
          .toLowerCase()
          .startsWith("ar");
        const languageCode = isArabic ? "ar" : "en";
        const loadedKey = isArabic ? "wikipediaLoadedAr" : "wikipediaLoadedEn";
        if (tree[loadedKey]) return;

        const arabicName = String(tree.plantsJsonNameAr || "").trim();
        const candidateTitles = isArabic
          ? arabicName
            ? [arabicName]
            : []
          : this.getStandaloneTreeWikipediaCandidateTitles(tree.name);
        if (!candidateTitles.length) return;

        this.$set(tree, loadedKey, true);

        const searchName = isArabic ? arabicName : tree.name;
        const searchUrl = this.getStandaloneTreeWikipediaSearchUrl(
          searchName,
          languageCode,
        );
        this.$set(tree, isArabic ? "wikiUrlAr" : "wikiUrlEn", searchUrl);

        const applyPage = (page) => {
          if (
            !page ||
            page.missing != null ||
            !(Number(page.pageid) > 0) ||
            !page.title
          ) {
            return false;
          }

          const resolvedTitle = String(page.title);
          const articleUrl = this.getStandaloneTreeWikipediaArticleUrl(
            resolvedTitle,
            languageCode,
          );
          const extract = String(page.extract || "").trim();

          this.$set(
            tree,
            isArabic ? "wikiResolvedTitleAr" : "wikiResolvedTitleEn",
            resolvedTitle,
          );
          this.$set(tree, isArabic ? "wikiUrlAr" : "wikiUrlEn", articleUrl);
          if (extract) {
            this.$set(
              tree,
              isArabic ? "wikipediaExtractAr" : "wikipediaExtractEn",
              extract,
            );
            // Preserve the legacy English property for any older code paths.
            if (!isArabic) this.$set(tree, "wikipediaExtract", extract);
          }

          const thumbnail =
            page.thumbnail && page.thumbnail.source
              ? String(page.thumbnail.source)
              : "";
          if (thumbnail && !tree.plantsJsonImage && !tree.imageUrl) {
            this.$set(tree, "imageUrl", thumbnail);
          }
          return true;
        };

        try {
          // First try the exact title. English uses the botanical names; Arabic
          // uses name_ar from plants.json.
          const exactEndpoint =
            `https://${languageCode}.wikipedia.org/w/api.php` +
            "?origin=*" +
            "&action=query" +
            "&format=json" +
            "&redirects=1" +
            "&prop=pageimages%7Cextracts" +
            "&piprop=thumbnail" +
            "&pithumbsize=180" +
            "&exintro=1" +
            "&explaintext=1" +
            "&exsentences=3" +
            `&titles=${encodeURIComponent(candidateTitles.join("|"))}`;

          const exactResponse = await fetch(exactEndpoint, {
            method: "GET",
            mode: "cors",
            credentials: "omit",
          });

          let foundPage = false;
          if (exactResponse.ok) {
            const payload = await exactResponse.json();
            const pages =
              payload && payload.query && payload.query.pages
                ? Object.values(payload.query.pages)
                : [];
            const page = pages.find(
              (candidate) =>
                candidate &&
                candidate.missing == null &&
                Number(candidate.pageid) > 0,
            );
            foundPage = applyPage(page);
          }

          // name_ar will not always be the exact Arabic Wikipedia article title.
          // Search Arabic Wikipedia and use the best article result as a fallback.
          if (!foundPage && searchName) {
            const searchEndpoint =
              `https://${languageCode}.wikipedia.org/w/api.php` +
              "?origin=*" +
              "&action=query" +
              "&format=json" +
              "&generator=search" +
              "&gsrnamespace=0" +
              "&gsrlimit=5" +
              `&gsrsearch=${encodeURIComponent(searchName)}` +
              "&prop=pageimages%7Cextracts" +
              "&piprop=thumbnail" +
              "&pithumbsize=180" +
              "&exintro=1" +
              "&explaintext=1" +
              "&exsentences=3";

            const searchResponse = await fetch(searchEndpoint, {
              method: "GET",
              mode: "cors",
              credentials: "omit",
            });
            if (searchResponse.ok) {
              const payload = await searchResponse.json();
              const pages =
                payload && payload.query && payload.query.pages
                  ? Object.values(payload.query.pages)
                  : [];
              // MediaWiki search returns an index that represents result order.
              pages.sort(
                (a, b) =>
                  Number(a && a.index != null ? a.index : 9999) -
                  Number(b && b.index != null ? b.index : 9999),
              );
              applyPage(pages[0]);
            }
          }
        } catch (error) {
          // Keep the language-specific Wikipedia search URL when the API cannot
          // be reached. The popup will show the localized no-description message.
        }
      };

      await Promise.all(
        rows.map(async (tree) => {
          if (!tree || !tree.name) return;

          // Load both extracts once. This makes changing the app language instant
          // and prevents an English extract from remaining visible in Arabic mode.
          await Promise.all([
            fetchWikipediaLanguage(tree, "en"),
            fetchWikipediaLanguage(tree, "ar"),
          ]);

          const englishSearchUrl = this.getStandaloneTreeWikipediaSearchUrl(
            tree.name,
            "en",
          );
          if (!tree.wikiUrlEn) this.$set(tree, "wikiUrlEn", englishSearchUrl);

          // Keep legacy fields synchronized with English for existing code that
          // still expects wikiUrl/wikiResolvedTitle/wikiExactPage.
          this.$set(tree, "wikiUrl", tree.wikiUrlEn || englishSearchUrl);
          this.$set(
            tree,
            "wikiResolvedTitle",
            String(tree.wikiResolvedTitleEn || ""),
          );
          this.$set(tree, "wikiExactPage", Boolean(tree.wikiResolvedTitleEn));
          this.$set(tree, "wikipediaLoaded", true);

          // Commons remains an image-only fallback; the visible description comes
          // from the language-specific Wikipedia extract above.
          if (!tree.imageUrl) {
            const candidateTitles =
              this.getStandaloneTreeWikipediaCandidateTitles(tree.name);
            const commonsThumbnail =
              await this.getStandaloneCommonsTreeThumbnail([
                `${tree.name} tree`,
                ...candidateTitles,
              ]);
            if (commonsThumbnail) this.$set(tree, "imageUrl", commonsThumbnail);
          }
        }),
      );
    },

    openStandaloneTreeWikipedia(tree) {
      const row = tree && typeof tree === "object" ? tree : {};
      const url = this.isArabicUI()
        ? String(row.wikiUrlAr || "")
        : String(row.wikiUrlEn || row.wikiUrl || "");
      if (!url || typeof window === "undefined") return;
      const opened = window.open(url, "_blank", "noopener,noreferrer");
      if (opened) opened.opener = null;
    },

    handleStandaloneTreeNameWikipediaClick(tree, event) {
      // Names behave like links on a normal click, but a drag-selection must remain
      // copyable. If any text is selected, do not navigate/open a new tab.
      const selection =
        typeof window !== "undefined" &&
        typeof window.getSelection === "function"
          ? String(window.getSelection() || "").trim()
          : "";
      if (selection) {
        if (event && typeof event.preventDefault === "function")
          event.preventDefault();
        return;
      }
      this.openStandaloneTreeWikipedia(tree);
    },

    handleStandaloneTreeWikipediaImageError(event, tree) {
      if (tree) {
        const fallback = String(tree.fallbackImageUrl || "").trim();
        if (tree.plantsJsonImage && fallback && fallback !== tree.imageUrl) {
          this.$set(tree, "plantsJsonImage", false);
          this.$set(tree, "imageUrl", fallback);
          return;
        }
        this.$set(tree, "imageUrl", "");
      }
      const element = event && event.target;
      if (element && typeof element.removeAttribute === "function") {
        element.removeAttribute("src");
      }
    },

    getStandalonePlantSearchSuffix(kind = "groundcover") {
      if (kind === "trees" || kind === "tree") return "tree";
      if (kind === "shrubs" || kind === "shrub") return "shrub";
      return "plant";
    },

    getStandalonePlantSearchName(nameValue, kind = "groundcover") {
      const name = String(nameValue || "")
        .trim()
        .replace(/[_]+/g, " ")
        .replace(/\s+/g, " ");
      if (!name) return "";
      const suffix = this.getStandalonePlantSearchSuffix(kind);
      return new RegExp(`\\b${suffix}\\b`, "i").test(name)
        ? name
        : `${name} ${suffix}`;
    },

    getStandalonePlantWikipediaSearchUrl(nameValue, kind = "groundcover") {
      const query = this.getStandalonePlantSearchName(nameValue, kind);
      if (!query) return "";
      return (
        "https://en.wikipedia.org/w/index.php?" +
        `search=${encodeURIComponent(query)}` +
        "&title=Special%3ASearch&ns0=1"
      );
    },

    getStandalonePlantAcceptedLookupName(nameValue) {
      const raw = String(nameValue || "")
        .trim()
        .replace(/[_]+/g, " ")
        .replace(/\s+/g, " ");
      const key = raw.toLowerCase();
      // Keep the project's original spelling on-screen, but use corrected/common
      // botanical spellings as secondary search candidates when the CAD name has a typo.
      const aliases = {
        "atriplex semibacatta": "Atriplex semibaccata",
        "atriplex numularia": "Atriplex nummularia",
        "zygollium coccineum": "Zygophyllum coccineum",
        "dypterium glaucum": "Dipterygium glaucum",
        "caligonum comosum": "Calligonum comosum",
        "limonissatrum monopetalum": "Limoniastrum monopetalum",
        "lamprathus aureus": "Lampranthus aureus",
        "penisetum setaceum rubrum": "Pennisetum setaceum rubrum",
        "catasranthus roseus": "Catharanthus roseus",
        "asistasya gangetica": "Asystasia gangetica",
      };
      return aliases[key] || raw;
    },

    async enrichStandaloneVegetationTypeWikipedia(
      stats = [],
      kind = "groundcover",
    ) {
      const rows = Array.isArray(stats) ? stats : [];
      if (!rows.length) return;
      const suffix = this.getStandalonePlantSearchSuffix(kind);

      await Promise.all(
        rows.map(async (plant) => {
          if (!plant || !plant.name) return;
          const originalName = String(plant.name).trim();
          if (/^(flower bed|shrub planting bed)$/i.test(originalName)) {
            this.$set(plant, "wikiUrl", "");
            this.$set(plant, "wikiExactPage", false);
            this.$set(plant, "wikiResolvedTitle", "");
            if (plant.imageUrl == null) this.$set(plant, "imageUrl", "");
            return;
          }
          const acceptedName =
            this.getStandalonePlantAcceptedLookupName(originalName);
          const searchUrl = this.getStandalonePlantWikipediaSearchUrl(
            originalName,
            kind,
          );
          this.$set(plant, "wikiUrl", searchUrl);
          this.$set(plant, "wikiExactPage", false);
          this.$set(plant, "wikiResolvedTitle", "");
          if (plant.imageUrl == null) this.$set(plant, "imageUrl", "");
          if (plant.wikipediaLoaded) return;
          this.$set(plant, "wikipediaLoaded", true);

          const exactTitles = Array.from(
            new Set([originalName, acceptedName].filter(Boolean)),
          );
          try {
            // First try exact/redirected article titles.
            const exactEndpoint =
              "https://en.wikipedia.org/w/api.php" +
              "?origin=*" +
              "&action=query" +
              "&format=json" +
              "&redirects=1" +
              "&prop=pageimages" +
              "&piprop=thumbnail" +
              "&pithumbsize=180" +
              `&titles=${encodeURIComponent(exactTitles.join("|"))}`;
            const exactResponse = await fetch(exactEndpoint, {
              method: "GET",
              mode: "cors",
              credentials: "omit",
            });
            if (exactResponse.ok) {
              const payload = await exactResponse.json();
              const pages =
                payload && payload.query && payload.query.pages
                  ? Object.values(payload.query.pages)
                  : [];
              const page = pages.find(
                (candidate) =>
                  candidate &&
                  candidate.missing == null &&
                  Number(candidate.pageid) > 0,
              );
              if (page && page.title) {
                this.$set(plant, "wikiExactPage", true);
                this.$set(plant, "wikiResolvedTitle", String(page.title));
                this.$set(
                  plant,
                  "wikiUrl",
                  this.getStandaloneTreeWikipediaArticleUrl(page.title),
                );
                const thumbnail =
                  page.thumbnail && page.thumbnail.source
                    ? String(page.thumbnail.source)
                    : "";
                if (thumbnail) this.$set(plant, "imageUrl", thumbnail);
              }
            }

            // If no exact title exists, search with "shrub" / "plant" appended.
            // This is the same idea as adding "Tree" to Acacia etbaica in Google.
            if (!plant.wikiExactPage) {
              const query = `${acceptedName || originalName} ${suffix}`.trim();
              const searchEndpoint =
                "https://en.wikipedia.org/w/api.php" +
                "?origin=*" +
                "&action=query" +
                "&format=json" +
                "&generator=search" +
                "&gsrnamespace=0" +
                "&gsrlimit=5" +
                `&gsrsearch=${encodeURIComponent(query)}` +
                "&prop=pageimages" +
                "&piprop=thumbnail" +
                "&pithumbsize=180";
              const searchResponse = await fetch(searchEndpoint, {
                method: "GET",
                mode: "cors",
                credentials: "omit",
              });
              if (searchResponse.ok) {
                const payload = await searchResponse.json();
                const pages =
                  payload && payload.query && payload.query.pages
                    ? Object.values(payload.query.pages)
                    : [];
                const normalizedNeedle = acceptedName
                  .toLowerCase()
                  .replace(/[^a-z0-9]+/g, " ")
                  .trim();
                const page = pages
                  .filter(
                    (candidate) =>
                      candidate &&
                      candidate.title &&
                      Number(candidate.pageid) > 0,
                  )
                  .sort((a, b) => {
                    const aTitle = String(a.title)
                      .toLowerCase()
                      .replace(/[^a-z0-9]+/g, " ");
                    const bTitle = String(b.title)
                      .toLowerCase()
                      .replace(/[^a-z0-9]+/g, " ");
                    const aScore = aTitle.includes(normalizedNeedle)
                      ? 2
                      : normalizedNeedle
                          .split(" ")
                          .filter(Boolean)
                          .filter((w) => aTitle.includes(w)).length;
                    const bScore = bTitle.includes(normalizedNeedle)
                      ? 2
                      : normalizedNeedle
                          .split(" ")
                          .filter(Boolean)
                          .filter((w) => bTitle.includes(w)).length;
                    return bScore - aScore;
                  })[0];
                if (page && page.title) {
                  this.$set(plant, "wikiResolvedTitle", String(page.title));
                  this.$set(
                    plant,
                    "wikiUrl",
                    this.getStandaloneTreeWikipediaArticleUrl(page.title),
                  );
                  const thumbnail =
                    page.thumbnail && page.thumbnail.source
                      ? String(page.thumbnail.source)
                      : "";
                  if (thumbnail) this.$set(plant, "imageUrl", thumbnail);
                }
              }
            }
          } catch (error) {
            // Safe fallback stays as Wikipedia search with the plant-form suffix.
          }

          if (!plant.imageUrl) {
            const commonsThumbnail =
              await this.getStandaloneCommonsTreeThumbnail([
                `${acceptedName || originalName} ${suffix}`,
                acceptedName,
                originalName,
              ]);
            if (commonsThumbnail)
              this.$set(plant, "imageUrl", commonsThumbnail);
          }
        }),
      );
    },

    openStandalonePlantWikipedia(plant) {
      const url = plant && plant.wikiUrl ? String(plant.wikiUrl) : "";
      if (!url || typeof window === "undefined") return;
      const opened = window.open(url, "_blank", "noopener,noreferrer");
      if (opened) opened.opener = null;
    },

    handleStandalonePlantNameWikipediaClick(plant, event) {
      const selection =
        typeof window !== "undefined" &&
        typeof window.getSelection === "function"
          ? String(window.getSelection() || "").trim()
          : "";
      if (selection) {
        if (event && typeof event.preventDefault === "function")
          event.preventDefault();
        return;
      }
      this.openStandalonePlantWikipedia(plant);
    },

    getStandaloneTreeIconColor(speciesValue) {
      const palette = this.getStandaloneTreePalette(speciesValue);
      const value = Number(palette && palette.foliage);
      return `#${(Number.isFinite(value) ? value : 0x0f412c)
        .toString(16)
        .padStart(6, "0")}`;
    },

    isStandaloneActualTreePointFeature(feature) {
      const geometry = feature && feature.geometry;
      if (
        !geometry ||
        (geometry.type !== "Point" && geometry.type !== "MultiPoint")
      ) {
        return false;
      }

      const properties = (feature && feature.properties) || {};
      const normalize = (value) =>
        String(value || "")
          .trim()
          .toLowerCase()
          .replace(/[_-]+/g, " ")
          .replace(/\s+/g, " ");

      const sourceLayer = normalize(
        properties._source_layer ||
          properties.source_layer ||
          properties.sourceLayer,
      );
      const cadCategory = normalize(properties.cad_category);
      const appModel = normalize(properties.APP_MODEL);
      const featureType = normalize(this.getStandaloneFeatureType(feature));
      const descriptor = [
        sourceLayer,
        cadCategory,
        appModel,
        featureType,
        properties.APP_LABEL,
        properties.cad_object_type,
        properties.cad_layer,
      ]
        .filter((value) => value != null && String(value).trim())
        .map(normalize)
        .join(" ");

      // Tree pits, planting symbols/callouts and shrub/groundcover points used to
      // be counted as trees simply because their labels contained the word "tree".
      // Muanisiyah therefore showed 1,281 "Unknown tree type" records even though
      // the authoritative Trees Xref contains 889 actual tree inserts.
      if (
        /\b(tree pit|tree pits|pit|pits|shrub|shrubs|bush|bushes|ground cover|groundcover|planting|callout|symbol|marker|annotation|grid|label|leader|electrical pole|light pole)\b/.test(
          descriptor,
        )
      ) {
        return false;
      }

      // The normalized combined GeoJSON uses `_source_layer: "trees"` for the
      // authoritative GIS/CAD tree point set. This is the strongest signal.
      if (sourceLayer === "trees" || sourceLayer === "tree") return true;

      // Accept other projects that expose explicit tree-species columns even when
      // their source-layer naming differs.
      const hasExplicitTreeSpecies = [
        properties.TREE_SPECIES_RENDER,
        properties.CAD_TREE_SPECIES_RENDER,
        properties.CAD_TREE_SPECIES,
        properties.d_CL_TREE1,
        properties.CL_TREE_SPECIES_NAME,
        properties.tree_type,
        properties.TREE_TYPE,
      ].some((value) => value != null && String(value).trim());

      if (hasExplicitTreeSpecies) return true;

      // Legacy fallback: a point explicitly described as a tree/palm is valid only
      // when a species/name can actually be resolved.
      const resolvedSpecies = this.getStandaloneTreeSpecies(properties);
      return (
        /\b(tree|trees|palm|palms)\b/.test(descriptor) &&
        Boolean(String(resolvedSpecies || "").trim())
      );
    },

    buildStandaloneTreeAnnotations(geojson, modelData) {
      const features =
        geojson && Array.isArray(geojson.features) ? geojson.features : [];
      const origin = modelData && modelData.origin;
      if (!origin) return [];

      const annotations = [];
      features.forEach((feature, featureIndex) => {
        if (!this.isStandaloneActualTreePointFeature(feature)) return;
        const geometry = feature && feature.geometry;
        const properties = (feature && feature.properties) || {};
        const species = this.getStandaloneTreeSpecies(properties);
        if (!species) return;

        const coordinates =
          geometry.type === "Point"
            ? [geometry.coordinates]
            : geometry.coordinates;
        if (!Array.isArray(coordinates)) return;
        const dimensions = this.getStandaloneTreeDimensions(properties);
        const objectIds = Array.isArray(properties.OBJECTID_values)
          ? properties.OBJECTID_values
          : null;

        coordinates.forEach((coordinate, coordinateIndex) => {
          if (
            !Array.isArray(coordinate) ||
            coordinate.length < 2 ||
            !coordinate.slice(0, 2).map(Number).every(Number.isFinite)
          ) {
            return;
          }
          const local = this.lngLatToTerrainMeters(coordinate, origin);
          if (!local) return;
          const objectId =
            objectIds && objectIds.length > coordinateIndex
              ? objectIds[coordinateIndex]
              : properties.OBJECTID || properties.objectid || properties.ID_UID;
          const supportY = this.getStandaloneTerrainSupportHeightAtPoint(
            local,
            modelData,
            Math.max(0.25, Math.min(0.7, Number(dimensions.crown || 0) * 0.04)),
          );
          annotations.push({
            id: `tree-label-${objectId != null ? objectId : featureIndex}-${coordinateIndex}`,
            text: species,
            species,
            x: Number(local.x),
            z: Number(local.z),
            // Put the text just above the rendered crown. The procedural tree
            // renderer uses the same mature-height fields, so this tracks the
            // visible tree much more closely than a fixed-height label.
            absoluteY:
              Number(supportY || 0) +
              Math.max(2.5, Number(dimensions.height) || 8) +
              0.65,
          });
        });
      });

      return annotations;
    },

    handleStandaloneTreeTypeLabelCheckboxChange(tree, event) {
      if (!tree || !tree.name) return;
      const enabled = Boolean(event && event.target && event.target.checked);
      this.$set(this.threeTreeLabelVisibility, String(tree.name), enabled);
      this.updateStandaloneTreeLabelOverlay(true);
    },

    handleStandaloneAllTreeTypeLabelsCheckboxChange(event) {
      const enabled = Boolean(event && event.target && event.target.checked);
      const nextVisibility = { ...(this.threeTreeLabelVisibility || {}) };
      (Array.isArray(this.threeTreeTypeStats)
        ? this.threeTreeTypeStats
        : []
      ).forEach((tree) => {
        if (!tree || !tree.name) return;
        nextVisibility[String(tree.name)] = enabled;
      });
      this.$set(this, "threeTreeLabelVisibility", nextVisibility);
      this.updateStandaloneTreeLabelOverlay(true);
    },

    updateStandaloneTreeLabelOverlay(force = false) {
      if (
        !this.threeTreeLabelsAnyEnabled ||
        !this.threeCamera ||
        !this.$refs.threeParkHost
      ) {
        if (this.threeVisibleTreeLabels.length) {
          this.threeVisibleTreeLabels = [];
          this.threeTreeLabelOverlaySignature = "";
        }
        return;
      }

      const now = Date.now();
      if (!force && now - (this.threeTreeLabelOverlayUpdateAt || 0) < 140) {
        return;
      }
      this.threeTreeLabelOverlayUpdateAt = now;

      const annotations = Array.isArray(this.threeTreeAnnotations)
        ? this.threeTreeAnnotations
        : [];
      if (!annotations.length) {
        if (this.threeVisibleTreeLabels.length) {
          this.threeVisibleTreeLabels = [];
          this.threeTreeLabelOverlaySignature = "";
        }
        return;
      }

      const host = this.$refs.threeParkHost;
      const width = Math.max(1, host.clientWidth || 0);
      const height = Math.max(1, host.clientHeight || 0);
      const camera = this.threeCamera;
      const world = new THREE.Vector3();
      const selected = this.threeTreeLabelVisibility || {};
      const visible = [];

      // Intentionally keep every selected tree label anchored to its own tree.
      // The user can choose one species for a clean view or use Label All for
      // a complete inventory; we do not collapse duplicates into one label.
      annotations.forEach((annotation) => {
        if (!selected[annotation.species]) return;
        world.set(annotation.x, annotation.absoluteY, annotation.z);
        const point = world.clone().project(camera);
        if (point.z < -1 || point.z > 1) return;
        const screenX = (point.x * 0.5 + 0.5) * width;
        const screenY = (-point.y * 0.5 + 0.5) * height;
        if (
          screenX < -80 ||
          screenX > width + 80 ||
          screenY < -24 ||
          screenY > height + 24
        ) {
          return;
        }
        visible.push({
          id: annotation.id,
          text: annotation.text,
          x: Math.round(screenX),
          y: Math.round(screenY),
          depth: point.z,
        });
      });

      // Draw nearer labels after farther labels so the label on the foreground
      // tree remains readable when the user intentionally enables many species.
      visible.sort((a, b) => b.depth - a.depth);
      const signature = visible
        .map((item) => `${item.id}:${item.x}:${item.y}:${item.text}`)
        .join("|");
      if (!force && signature === this.threeTreeLabelOverlaySignature) return;
      this.threeTreeLabelOverlaySignature = signature;
      this.threeVisibleTreeLabels = visible;
    },

    buildStandaloneTreeTypeStats(geojson) {
      const features =
        geojson && Array.isArray(geojson.features) ? geojson.features : [];
      const counts = new Map();

      features.forEach((feature) => {
        if (!this.isStandaloneActualTreePointFeature(feature)) return;

        const geometry = feature && feature.geometry;
        const coordinateCount =
          geometry.type === "MultiPoint" && Array.isArray(geometry.coordinates)
            ? geometry.coordinates.length
            : 1;
        if (!coordinateCount) return;

        const properties = (feature && feature.properties) || {};
        const rawSpecies = this.getStandaloneTreeSpecies(properties);
        const name =
          rawSpecies ||
          this.mapUiText(
            "Unknown tree type",
            "نوع شجرة غير معروف",
            "Unknown tree type",
          );
        const existing = counts.get(name) || {
          name,
          count: 0,
          archetype: this.getStandaloneTreeArchetype(rawSpecies),
          color: this.getStandaloneTreeIconColor(rawSpecies),
        };
        existing.count += coordinateCount;
        counts.set(name, existing);
      });

      return Array.from(counts.values()).sort((a, b) => {
        if (b.count !== a.count) return b.count - a.count;
        return String(a.name).localeCompare(String(b.name));
      });
    },

    async ensureStandaloneTreeTypeStats() {
      if (this.threeTreeTypeStats.length || this.threeTreeTypeLoading) return;
      const urls = this.getStandaloneThreeLayerUrls();
      const url = urls.vegetation || urls.combined;
      if (!url) return;

      this.threeTreeTypeLoading = true;
      try {
        const sourceGeoJson = await this.getStandaloneCachedGeoJson(url);
        const vegetationGeoJson = this.filterStandaloneGeoJsonByLayer(
          sourceGeoJson,
          "vegetation",
        );
        this.threeTreeTypeStats =
          this.buildStandaloneTreeTypeStats(vegetationGeoJson);
        this.threeTreeAnnotations = this.buildStandaloneTreeAnnotations(
          vegetationGeoJson,
          this.threeParkModelData,
        );
        // Always attach plants.json name_ar before rendering the panel. Images
        // remain optional, but Arabic labels must not depend on image enrichment.
        await this.applyStandalonePlantCatalogNames(this.threeTreeTypeStats);
        await this.enrichStandaloneTreeTypeWikipedia(this.threeTreeTypeStats);
        await this.applyStandaloneTreeCatalogImages(this.threeTreeTypeStats);
        this.updateStandaloneTreeLabelOverlay(true);
      } catch (error) {
        console.error("Tree type data could not be loaded:", error);
        this.threeTreeTypeStats = [];
        this.threeTreeAnnotations = [];
        this.threeVisibleTreeLabels = [];
      } finally {
        this.threeTreeTypeLoading = false;
      }
    },

    getStandaloneVegetationTypeSpecies(properties = {}, kind = "shrubs") {
      const values =
        kind === "groundcover"
          ? [
              properties.groundcover_type,
              properties.GROUNDCOVER_TYPE,
              properties.species,
              properties.SPECIES,
              properties.DC_REMARK,
              properties.QC_REMARKS,
              properties.Remarks,
            ]
          : [
              properties.species,
              properties.SPECIES,
              properties.CL_SHRUB_SPECIES_NAME,
              properties.CL_SHRUB_GENUS,
              properties.DC_REMARK,
              properties.QC_REMARKS,
              properties.Remarks,
            ];
      const value = values.find(
        (item) =>
          item != null &&
          String(item).trim() &&
          !/^<?null>?$/i.test(String(item).trim()),
      );
      return value == null
        ? ""
        : String(value).trim().replace(/[_]+/g, " ").replace(/\s+/g, " ");
    },

    isStandaloneVegetationTypeFeature(feature, kind = "shrubs") {
      if (!feature || !feature.geometry) return false;
      const definition = this.getStandaloneSubLayerDefinition(
        "vegetation",
        feature,
      );
      return Boolean(definition && definition.key === kind);
    },

    getStandaloneVegetationTypeColour(kind, properties = {}) {
      let colour = 0x5f7850;
      if (kind === "shrubs") {
        colour =
          Number(this.getStandaloneShrubFoliageColour(properties)) || colour;
      } else {
        const style = this.getStandaloneGroundCoverSpeciesStyle(properties);
        colour = Number(style && style.foliage) || 0x6d8055;
      }
      return `#${colour.toString(16).padStart(6, "0")}`;
    },

    buildStandaloneVegetationTypeStats(geojson, kind = "shrubs") {
      const features =
        geojson && Array.isArray(geojson.features) ? geojson.features : [];
      const counts = new Map();
      features.forEach((feature) => {
        if (!this.isStandaloneVegetationTypeFeature(feature, kind)) return;
        const properties = (feature && feature.properties) || {};
        const name = this.getStandaloneVegetationTypeSpecies(properties, kind);
        if (!name) return;
        const geometry = feature && feature.geometry;
        const polygonParts = this.getStandalonePolygonParts(geometry);
        const areaCount = polygonParts.length || 1;
        const existing = counts.get(name) || {
          name,
          count: 0,
          color: this.getStandaloneVegetationTypeColour(kind, properties),
        };
        existing.count += areaCount;
        counts.set(name, existing);
      });
      return Array.from(counts.values()).sort((a, b) => {
        if (b.count !== a.count) return b.count - a.count;
        return String(a.name).localeCompare(String(b.name));
      });
    },

    buildStandaloneVegetationTypeAnnotations(
      geojson,
      modelData,
      kind = "shrubs",
    ) {
      const features =
        geojson && Array.isArray(geojson.features) ? geojson.features : [];
      const origin = modelData && modelData.origin;
      if (!origin) return [];
      const annotations = [];
      features.forEach((feature, featureIndex) => {
        if (!this.isStandaloneVegetationTypeFeature(feature, kind)) return;
        const properties = (feature && feature.properties) || {};
        const species = this.getStandaloneVegetationTypeSpecies(
          properties,
          kind,
        );
        if (!species) return;
        const geometry = feature && feature.geometry;
        const parts = this.getStandalonePolygonParts(geometry);
        parts.forEach((rings, partIndex) => {
          const localRings = this.getStandaloneLocalPolygonRings(rings, origin);
          if (!localRings.length || !localRings[0] || !localRings[0].length)
            return;
          const center = this.getStandalonePolygonCentroid(localRings[0]);
          if (!center) return;
          const x = Number(center.x);
          const z = Number(center.y);
          if (![x, z].every(Number.isFinite)) return;
          const supportY = this.getStandaloneTerrainHeightAtPoint(
            { x, z },
            modelData,
          );
          const lift =
            kind === "shrubs"
              ? Math.max(
                  0.65,
                  Number(
                    this.getStandaloneShrubSpeciesProfile(properties).height,
                  ) || 0.68,
                ) + 0.35
              : Math.max(
                  0.3,
                  Number(
                    this.getStandaloneGroundCoverSpeciesStyle(properties)
                      .height,
                  ) || 0.32,
                ) + 0.28;
          annotations.push({
            id: `${kind}-type-label-${featureIndex}-${partIndex}`,
            text: species,
            species,
            x,
            z,
            absoluteY: Number(supportY || 0) + lift,
          });
        });
      });
      return annotations;
    },

    handleStandaloneShrubTypeLabelCheckboxChange(plant, event) {
      if (!plant || !plant.name) return;
      const enabled = Boolean(event && event.target && event.target.checked);
      this.$set(this.threeShrubLabelVisibility, String(plant.name), enabled);
      this.updateStandaloneShrubLabelOverlay(true);
    },

    handleStandaloneAllShrubTypeLabelsCheckboxChange(event) {
      const enabled = Boolean(event && event.target && event.target.checked);
      const nextVisibility = { ...(this.threeShrubLabelVisibility || {}) };
      (Array.isArray(this.threeShrubTypeStats)
        ? this.threeShrubTypeStats
        : []
      ).forEach((plant) => {
        if (plant && plant.name) nextVisibility[String(plant.name)] = enabled;
      });
      this.$set(this, "threeShrubLabelVisibility", nextVisibility);
      this.updateStandaloneShrubLabelOverlay(true);
    },

    handleStandaloneGroundCoverTypeLabelCheckboxChange(plant, event) {
      if (!plant || !plant.name) return;
      const enabled = Boolean(event && event.target && event.target.checked);
      this.$set(
        this.threeGroundCoverLabelVisibility,
        String(plant.name),
        enabled,
      );
      this.updateStandaloneGroundCoverLabelOverlay(true);
    },

    handleStandaloneAllGroundCoverTypeLabelsCheckboxChange(event) {
      const enabled = Boolean(event && event.target && event.target.checked);
      const nextVisibility = {
        ...(this.threeGroundCoverLabelVisibility || {}),
      };
      (Array.isArray(this.threeGroundCoverTypeStats)
        ? this.threeGroundCoverTypeStats
        : []
      ).forEach((plant) => {
        if (plant && plant.name) nextVisibility[String(plant.name)] = enabled;
      });
      this.$set(this, "threeGroundCoverLabelVisibility", nextVisibility);
      this.updateStandaloneGroundCoverLabelOverlay(true);
    },

    updateStandaloneVegetationTypeLabelOverlay(kind = "shrubs", force = false) {
      const isShrub = kind === "shrubs";
      const visibility = isShrub
        ? this.threeShrubLabelVisibility || {}
        : this.threeGroundCoverLabelVisibility || {};
      const annotations = isShrub
        ? Array.isArray(this.threeShrubAnnotations)
          ? this.threeShrubAnnotations
          : []
        : Array.isArray(this.threeGroundCoverAnnotations)
          ? this.threeGroundCoverAnnotations
          : [];
      const anyEnabled = Object.values(visibility).some(Boolean);
      const visibleKey = isShrub
        ? "threeVisibleShrubLabels"
        : "threeVisibleGroundCoverLabels";
      const signatureKey = isShrub
        ? "threeShrubLabelOverlaySignature"
        : "threeGroundCoverLabelOverlaySignature";
      const updateAtKey = isShrub
        ? "threeShrubLabelOverlayUpdateAt"
        : "threeGroundCoverLabelOverlayUpdateAt";

      if (!anyEnabled || !this.threeCamera || !this.$refs.threeParkHost) {
        if ((this[visibleKey] || []).length) this[visibleKey] = [];
        this[signatureKey] = "";
        return;
      }
      const now = Date.now();
      if (!force && now - (this[updateAtKey] || 0) < 140) return;
      this[updateAtKey] = now;
      if (!annotations.length) {
        if ((this[visibleKey] || []).length) this[visibleKey] = [];
        this[signatureKey] = "";
        return;
      }

      const host = this.$refs.threeParkHost;
      const width = Math.max(1, host.clientWidth || 0);
      const height = Math.max(1, host.clientHeight || 0);
      const world = new THREE.Vector3();
      const visible = [];
      annotations.forEach((annotation) => {
        if (!visibility[annotation.species]) return;
        world.set(annotation.x, annotation.absoluteY, annotation.z);
        const point = world.clone().project(this.threeCamera);
        if (point.z < -1 || point.z > 1) return;
        const screenX = (point.x * 0.5 + 0.5) * width;
        const screenY = (-point.y * 0.5 + 0.5) * height;
        if (
          screenX < -100 ||
          screenX > width + 100 ||
          screenY < -30 ||
          screenY > height + 30
        )
          return;
        visible.push({
          id: annotation.id,
          text: annotation.text,
          x: Math.round(screenX),
          y: Math.round(screenY),
          depth: point.z,
        });
      });
      visible.sort((a, b) => b.depth - a.depth);
      const signature = visible
        .map((item) => `${item.id}:${item.x}:${item.y}:${item.text}`)
        .join("|");
      if (!force && signature === this[signatureKey]) return;
      this[signatureKey] = signature;
      this[visibleKey] = visible;
    },

    updateStandaloneShrubLabelOverlay(force = false) {
      this.updateStandaloneVegetationTypeLabelOverlay("shrubs", force);
    },

    updateStandaloneGroundCoverLabelOverlay(force = false) {
      this.updateStandaloneVegetationTypeLabelOverlay("groundcover", force);
    },

    async ensureStandaloneVegetationTypeStats(kind = "shrubs") {
      const isShrub = kind === "shrubs";
      const stats = isShrub
        ? this.threeShrubTypeStats
        : this.threeGroundCoverTypeStats;
      const loading = isShrub
        ? this.threeShrubTypeLoading
        : this.threeGroundCoverTypeLoading;
      if ((Array.isArray(stats) && stats.length) || loading) return;
      const urls = this.getStandaloneThreeLayerUrls();
      const url = urls.vegetation || urls.combined;
      if (!url) return;

      if (isShrub) this.threeShrubTypeLoading = true;
      else this.threeGroundCoverTypeLoading = true;
      try {
        const sourceGeoJson = await this.getStandaloneCachedGeoJson(url);
        const vegetationGeoJson = this.filterStandaloneGeoJsonByLayer(
          sourceGeoJson,
          "vegetation",
        );
        const nextStats = this.buildStandaloneVegetationTypeStats(
          vegetationGeoJson,
          kind,
        );
        const nextAnnotations = this.buildStandaloneVegetationTypeAnnotations(
          vegetationGeoJson,
          this.threeParkModelData,
          kind,
        );
        if (isShrub) {
          this.threeShrubTypeStats = nextStats;
          this.threeShrubAnnotations = nextAnnotations;
          await this.applyStandalonePlantCatalogNames(this.threeShrubTypeStats);
          this.enrichStandaloneVegetationTypeWikipedia(
            this.threeShrubTypeStats,
            "shrubs",
          );
          this.updateStandaloneShrubLabelOverlay(true);
        } else {
          this.threeGroundCoverTypeStats = nextStats;
          this.threeGroundCoverAnnotations = nextAnnotations;
          await this.applyStandalonePlantCatalogNames(
            this.threeGroundCoverTypeStats,
          );
          this.enrichStandaloneVegetationTypeWikipedia(
            this.threeGroundCoverTypeStats,
            "groundcover",
          );
          this.updateStandaloneGroundCoverLabelOverlay(true);
        }
      } catch (error) {
        console.error(`${kind} type data could not be loaded:`, error);
        if (isShrub) {
          this.threeShrubTypeStats = [];
          this.threeShrubAnnotations = [];
          this.threeVisibleShrubLabels = [];
        } else {
          this.threeGroundCoverTypeStats = [];
          this.threeGroundCoverAnnotations = [];
          this.threeVisibleGroundCoverLabels = [];
        }
      } finally {
        if (isShrub) this.threeShrubTypeLoading = false;
        else this.threeGroundCoverTypeLoading = false;
      }
    },

    getStandaloneStructureLabelText(featureType = "", properties = {}) {
      const propertyEntries = Object.entries(properties || {});
      const propertyLookup = new Map(
        propertyEntries.map(([key, value]) => [
          String(key).toLowerCase(),
          value,
        ]),
      );
      const getProperty = (...keys) => {
        for (const key of keys) {
          const value = propertyLookup.get(String(key).toLowerCase());
          if (value == null) continue;
          const text = String(value).trim();
          if (!text || /^<?null>?$/i.test(text)) continue;
          return text;
        }
        return "";
      };

      const appLabel = getProperty(
        "APP_DISPLAY_LABEL",
        "App Display Label",
        "app_display_label",
        "APP_LABEL",
        "app_label",
      );
      const appModel = getProperty(
        "APP_MODEL",
        "app_model",
        "APP_3D_MODEL",
        "app_3d_model",
        "App 3D Model",
      );
      const appHoopSide = getProperty("APP_HOOP_SIDE", "app_hoop_side");
      const detailedLandCover = getProperty(
        "CL_LAND_COVER_DETAILED",
        "CL_LANDUSE_DETAILED",
      );
      const qcRemarks = getProperty("QC_REMARKS");
      const departmentLabel = getProperty(
        "LABEL",
        "LABEL_EN",
        "DISPLAY_LABEL",
        "FACILITY_NAME",
        "FACILITY_TYPE",
        "ASSET_NAME",
        "ASSET_TYPE",
      );
      const typeValue = getProperty("Type", "featureType", "feature_type");
      const remarks = getProperty("Remarks", "DC_REMARK");
      const sourceLayer = getProperty("sourceLayer");
      const searchableText =
        `${featureType || ""} ${appModel} ${appLabel} ${appHoopSide} ${departmentLabel} ${detailedLandCover} ${qcRemarks} ${typeValue} ${remarks} ${sourceLayer}`.toLowerCase();

      // Do not label repetitive lighting fixtures or light posts.
      if (
        /lighting|light[_ -]?(?:post|pole|fixture)|luminaire|lamp/.test(
          searchableText,
        )
      ) {
        return null;
      }

      // Keep the label view focused on facilities/buildings. Repetitive
      // furniture and utility assets otherwise consume the overlap slots and
      // hide Restaurant, Bathrooms, Sports Courts, etc.
      if (
        /bench|recycling[_ -]?bin|waste[_ -]?bin|manhole|bollard|bike[_ -]?rack|spherical[_ -]?concrete|electrical[_ -]?pole|power[_ -]?line/.test(
          searchableText,
        )
      ) {
        return null;
      }

      // App Display Label is an app-specific display override. Preserve its exact
      // capitalization, punctuation and units instead of replacing it with a
      // generated/fallback structure label. APP_LABEL remains supported for
      // older GeoJSON exports.
      //
      // Covered Pergola is intentionally authored in ALL CAPS in the Qadisiyah
      // GIS data. Normalize this one legacy label defensively as well, because
      // older combined GeoJSON exports may still contain "Covered Pergola".
      if (appLabel) {
        if (/^covered\s+pergola$/i.test(appLabel)) return "COVERED PERGOLA";
        return appLabel;
      }

      // Use the actual ArcGIS properties shown in the project data.
      if (/sport[_ -]?(?:facilit|court)/.test(searchableText)) {
        return "Sports Courts";
      }
      if (/restaurant/.test(searchableText)) return "Restaurant";
      if (
        /double[_ -]?toilet|simple[_ -]?toilet|toilet|bathroom|washroom|restroom/.test(
          searchableText,
        )
      ) {
        return "Bathrooms";
      }
      if (/prayer[_ -]?room|mosque/.test(searchableText)) return "Prayer Room";
      if (
        /cycling[_ -]?(?:center|centre)|cycle[_ -]?(?:center|centre)/.test(
          searchableText,
        )
      ) {
        return "Cycling Center";
      }
      if (/visitor[_ -]?(?:center|centre)/.test(searchableText)) {
        return "Visitor Centre";
      }
      if (/administration[_ -]?(?:office|building)/.test(searchableText)) {
        return "Administration Office";
      }
      if (
        /maintenance[_ -]?(?:and[_ -]?water[_ -]?tanks|water[_ -]?tanks)/.test(
          searchableText,
        )
      ) {
        return "Maintenance and Water Tanks";
      }
      if (/maintenance[_ -]?building/.test(searchableText)) {
        return "Maintenance Building";
      }
      if (/electrical[_ -]?room/.test(searchableText)) {
        return "Electrical Room";
      }
      if (/electrical[_ -]?building/.test(searchableText)) {
        return "Electrical Building";
      }
      if (/technical[_ -]?building/.test(searchableText)) {
        return "Technical Building";
      }
      if (/large[_ -]?kiosk/.test(searchableText)) return "Large Kiosk";
      if (/small[_ -]?kiosk/.test(searchableText)) return "Small Kiosk";
      if (/kiosk/.test(searchableText)) return "Kiosk";

      const preferredKeys = [
        "APP_DISPLAY_LABEL",
        "App Display Label",
        "app_display_label",
        "APP_LABEL",
        "app_label",
        "LABEL",
        "LABEL_EN",
        "DISPLAY_LABEL",
        "FACILITY_NAME",
        "FACILITY_TYPE",
        "ASSET_NAME",
        "ASSET_TYPE",
        "CL_LAND_COVER_DETAILED",
        "CL_LANDUSE_DETAILED",
        "DisplayName",
        "display_name",
        "Name",
        "name",
        "FacilityName",
        "facility_name",
        "Title",
        "title",
        "QC_REMARKS",
        "Type",
        "type",
        "Remarks",
        "featureType",
        "feature_type",
        "sourceLayer",
      ];
      let label = "";
      preferredKeys.some((key) => {
        const value = getProperty(key);
        if (!value) return false;
        label = value;
        return true;
      });
      if (!label) {
        label = String(featureType || "Structure").replace(/[_-]+/g, " ");
      }

      label = label
        .replace(/[_-]+/g, " ")
        .replace(/\btable tenis\b/gi, "Table Tennis")
        .replace(/\bbbq\b/gi, "BBQ")
        .replace(/\bel\b/gi, "Electrical")
        .replace(/\bwc\b/gi, "Bathrooms")
        .replace(/\s+/g, " ")
        .trim();

      if (!label) {
        return this.mapUiText("Structure", "منشأ", "Structure");
      }

      return label
        .toLowerCase()
        .replace(/\b\w/g, (match) => match.toUpperCase());
    },

    getStandaloneStructureLabelPriority(featureType = "", properties = {}) {
      const searchableText = `${featureType || ""} ${
        properties.APP_MODEL ||
        properties.app_model ||
        properties.APP_3D_MODEL ||
        properties.app_3d_model ||
        properties["App 3D Model"] ||
        ""
      } ${
        properties.APP_DISPLAY_LABEL ||
        properties["App Display Label"] ||
        properties.app_display_label ||
        properties.APP_LABEL ||
        properties.app_label ||
        ""
      } ${
        properties.QC_REMARKS || ""
      } ${properties.CL_LAND_COVER_DETAILED || ""} ${
        properties.Type || ""
      } ${properties.Remarks || ""}`.toLowerCase();

      // App Display Label is an intentional ArcGIS -> app display override, so labels
      // such as Water Tanks Building, Electrical Building, Maintenance Building,
      // and Themed Gardens Classrooms should win overlap placement.
      if (
        String(
          properties.APP_DISPLAY_LABEL ||
            properties["App Display Label"] ||
            properties.app_display_label ||
            properties.APP_LABEL ||
            properties.app_label ||
            "",
        ).trim()
      ) {
        return 0;
      }

      if (
        /sport[_ -]?(?:facilit|court)|restaurant|toilet|bathroom|washroom|restroom|prayer|cycling[_ -]?(?:center|centre)|visitor[_ -]?(?:center|centre)|administration|maintenance[_ -]?building|electrical[_ -]?building|technical[_ -]?building|kiosk/.test(
          searchableText,
        )
      ) {
        return 0;
      }
      if (
        /pergola|playground|outdoor[_ -]?gym|petanque|running[_ -]?track/.test(
          searchableText,
        )
      ) {
        return 1;
      }
      if (
        /bench|bin|rack|manhole|pole|spherical|fixture/.test(searchableText)
      ) {
        return 3;
      }
      return 2;
    },

    getStandaloneStructureAnnotationPosition(feature, modelData) {
      if (!feature || !feature.geometry || !modelData) return null;
      const geometry = feature.geometry;
      const collect = [];
      const pushCoordinate = (coordinate) => {
        if (
          Array.isArray(coordinate) &&
          Number.isFinite(Number(coordinate[0])) &&
          Number.isFinite(Number(coordinate[1]))
        ) {
          collect.push([Number(coordinate[0]), Number(coordinate[1])]);
        }
      };

      // For polygons, use only the exterior ring. Including holes and every
      // nested ring can pull a label away from the actual facility building.
      if (geometry.type === "Polygon") {
        ((geometry.coordinates && geometry.coordinates[0]) || []).forEach(
          pushCoordinate,
        );
      } else if (geometry.type === "MultiPolygon") {
        const largestOuter =
          (geometry.coordinates || [])
            .map((polygon) => (polygon && polygon[0]) || [])
            .sort((a, b) => b.length - a.length)[0] || [];
        largestOuter.forEach(pushCoordinate);
      } else {
        const walk = (value) => {
          if (!Array.isArray(value) || !value.length) return;
          if (typeof value[0] === "number") {
            pushCoordinate(value);
            return;
          }
          value.forEach(walk);
        };
        walk(geometry.coordinates);
      }
      if (!collect.length) return null;

      const minLongitude = Math.min(
        ...collect.map((coordinate) => coordinate[0]),
      );
      const maxLongitude = Math.max(
        ...collect.map((coordinate) => coordinate[0]),
      );
      const minLatitude = Math.min(
        ...collect.map((coordinate) => coordinate[1]),
      );
      const maxLatitude = Math.max(
        ...collect.map((coordinate) => coordinate[1]),
      );
      const longitude = (minLongitude + maxLongitude) / 2;
      const latitude = (minLatitude + maxLatitude) / 2;

      const local = this.lngLatToTerrainMeters(
        [longitude, latitude],
        modelData.origin,
      );
      return {
        local,
        geometryType: geometry.type,
      };
    },

    buildStandaloneBuildingAnnotations(modelData) {
      const data =
        modelData && modelData.terrainAfterData
          ? modelData.terrainAfterData
          : modelData;
      const footprints =
        data && Array.isArray(data.buildingFootprints)
          ? data.buildingFootprints
          : [];

      return footprints
        .map((building, index) => {
          const outer = Array.isArray(building.outer) ? building.outer : [];
          if (!outer.length) return null;
          const center = outer.reduce(
            (accumulator, point) => {
              accumulator.x += Number(point.x) || 0;
              accumulator.z += Number(point.z) || 0;
              return accumulator;
            },
            { x: 0, z: 0 },
          );
          center.x /= outer.length;
          center.z /= outer.length;

          const properties = building.properties || {};
          const rawLabel =
            building.label ||
            properties.name_en ||
            properties.name ||
            properties.Name ||
            properties.type ||
            properties.class ||
            "Building";
          const text = String(rawLabel)
            .replace(/[_-]+/g, " ")
            .replace(/\s+/g, " ")
            .trim()
            .replace(/\b\w/g, (match) => match.toUpperCase());

          return {
            id: `mapbox-building-${index}`,
            text: text || "Building",
            x: center.x,
            z: center.z,
            absoluteY: Number(building.topY) + 0.9,
            yOffset: 0,
            source: "building",
            subLayerKey: "buildings-and-facilities",
          };
        })
        .filter(Boolean);
    },

    buildStandaloneStructureAnnotations(geojson, modelData) {
      const features =
        geojson && Array.isArray(geojson.features) ? geojson.features : [];
      const annotations = [];

      features.forEach((feature, index) => {
        const properties = (feature && feature.properties) || {};
        const featureType = this.getStandaloneFeatureType(feature);
        const anchor = this.getStandaloneStructureAnnotationPosition(
          feature,
          modelData,
        );
        if (!anchor) return;

        // APP_LABEL is authored display text from ArcGIS. Always render it
        // exactly as stored (including ALL CAPS, punctuation and units) and
        // only use the automatic label formatter when APP_LABEL is absent.
        let authoredAppLabel = String(
          this.getStandaloneCaseInsensitiveProperty(properties, [
            "APP_LABEL",
            "app_label",
          ]) || "",
        ).trim();

        // Guarantee the pergola label matches the authored all-caps GIS label
        // even if an older deployed/combined GeoJSON contains Title Case.
        if (/^covered\s+pergola$/i.test(authoredAppLabel)) {
          authoredAppLabel = "COVERED PERGOLA";
        }

        const label =
          authoredAppLabel ||
          this.getStandaloneStructureLabelText(featureType, properties);
        if (!label) return;

        let yOffset = 1.35;
        if (this.isStandaloneHalfBasketballCourtStructure(properties)) {
          // Keep the app label above the 3.05 m rim and backboard.
          yOffset = 4.75;
        } else if (/polygon/i.test(anchor.geometryType || "")) {
          yOffset = Math.max(
            1.3,
            this.getStandaloneStructureHeight(featureType, properties) + 0.8,
          );
        } else if (/line/i.test(anchor.geometryType || "")) {
          yOffset = 1.5;
        } else if (/pole|light/.test(featureType)) {
          yOffset = Math.max(
            2.5,
            Math.min(
              8,
              this.getStandaloneNumericProperty(
                properties,
                ["PoleHeight", "Height", "height_m"],
                5.6,
              ) + 0.8,
            ),
          );
        } else if (/manhole/.test(featureType)) {
          yOffset = 0.9;
        }

        annotations.push({
          id: `${properties.OBJECTID || properties.objectid || index}-${featureType || "structure"}`,
          text: label,
          x: anchor.local.x,
          z: anchor.local.z,
          yOffset,
          source: "arcgis-structure",
          subLayerKey: this.getStandaloneSubLayerDefinition(
            "structures",
            feature,
          ).key,
          priority: this.getStandaloneStructureLabelPriority(
            featureType,
            properties,
          ),
        });
      });

      return annotations;
    },

    updateStandaloneStructureLabelOverlay(force = false) {
      if (
        !this.threeToolState.structureLabels ||
        !this.threeCamera ||
        !this.$refs.threeParkHost ||
        !this.threeLayerVisibility.structures
      ) {
        if (this.threeVisibleStructureLabels.length) {
          this.threeVisibleStructureLabels = [];
          this.threeLabelOverlaySignature = "";
        }
        return;
      }

      const now = Date.now();
      if (!force && now - (this.threeLabelOverlayUpdateAt || 0) < 110) {
        return;
      }
      this.threeLabelOverlayUpdateAt = now;

      const annotations = Array.isArray(this.threeStructureAnnotations)
        ? this.threeStructureAnnotations
        : [];
      if (!annotations.length) {
        if (this.threeVisibleStructureLabels.length) {
          this.threeVisibleStructureLabels = [];
          this.threeLabelOverlaySignature = "";
        }
        return;
      }

      const host = this.$refs.threeParkHost;
      const width = Math.max(1, host.clientWidth || 0);
      const height = Math.max(1, host.clientHeight || 0);
      const camera = this.threeCamera;
      const world = new THREE.Vector3();
      const projected = [];

      const structureSubLayerVisibility =
        this.threeSubLayerVisibility.structures || {};
      const structureLabelVisibility = this.threeStructureLabelVisibility || {};
      annotations.forEach((annotation) => {
        if (
          annotation.subLayerKey &&
          structureSubLayerVisibility[annotation.subLayerKey] === false
        ) {
          return;
        }
        if (
          annotation.subLayerKey &&
          structureLabelVisibility[annotation.subLayerKey] !== true
        ) {
          return;
        }
        const terrainY = this.getStandaloneTerrainHeightAtPoint(
          { x: annotation.x, z: annotation.z },
          this.threeParkModelData,
        );
        const worldY = Number.isFinite(Number(annotation.absoluteY))
          ? Number(annotation.absoluteY)
          : terrainY + Number(annotation.yOffset || 0);
        world.set(annotation.x, worldY, annotation.z);
        const point = world.clone().project(camera);
        if (point.z < -1 || point.z > 1) return;
        const screenX = (point.x * 0.5 + 0.5) * width;
        const screenY = (-point.y * 0.5 + 0.5) * height;
        if (
          screenX < 16 ||
          screenX > width - 16 ||
          screenY < 12 ||
          screenY > height - 12
        ) {
          return;
        }
        const focusTarget =
          this.threeControls && this.threeControls.target
            ? this.threeControls.target
            : new THREE.Vector3();
        const focusDistance = Math.hypot(
          world.x - focusTarget.x,
          world.z - focusTarget.z,
        );

        projected.push({
          id: annotation.id,
          text: annotation.text,
          x: Math.round(screenX),
          y: Math.round(screenY),
          depth: point.z,
          distance: camera.position.distanceTo(world),
          focusDistance,
          priority: Number.isFinite(Number(annotation.priority))
            ? Number(annotation.priority)
            : String(annotation.id || "").startsWith("mapbox-building-")
              ? 1
              : 2,
        });
      });

      projected.sort((a, b) => {
        return a.priority - b.priority || a.distance - b.distance;
      });

      const target =
        this.threeControls && this.threeControls.target
          ? this.threeControls.target
          : new THREE.Vector3();
      const cameraDistance = camera.position.distanceTo(target);
      const maxDimension = Math.max(
        1,
        Number(
          this.threeParkModelData && this.threeParkModelData.maxDimension,
        ) || 500,
      );

      // Only the local cluster around the camera/orbit target uses collision
      // avoidance. Labels outside that focus area remain exactly over their
      // structures, even when they overlap one another.
      //
      // The focus radius shrinks naturally as the camera gets closer, so zooming
      // into one group of facilities gives readable labels for that group while
      // preserving precise anchors everywhere else in the park.
      const focusRadius = THREE.MathUtils.clamp(
        cameraDistance * 0.32,
        maxDimension * 0.055,
        maxDimension * 0.2,
      );
      const focusLabels = [];
      const distantLabels = [];

      projected.forEach((annotation) => {
        if (Number(annotation.focusDistance) <= focusRadius) {
          focusLabels.push(annotation);
        } else {
          distantLabels.push(annotation);
        }
      });

      const occupiedRectangles = [];
      const visible = [];
      const rectanglesOverlap = (first, second, padding = 6) =>
        !(
          first.right + padding <= second.left ||
          first.left >= second.right + padding ||
          first.bottom + padding <= second.top ||
          first.top >= second.bottom + padding
        );
      const estimateLabelSize = (text) => ({
        width: Math.min(
          220,
          Math.max(72, String(text || "").length * 6.25 + 22),
        ),
        height: 24,
      });

      // First keep every distant label at the exact projected structure
      // position. They intentionally do not participate in collision detection.
      distantLabels.forEach((annotation) => {
        if (visible.length >= 240) return;
        visible.push({
          ...annotation,
          x: Math.round(annotation.x),
          y: Math.round(annotation.y),
        });
      });

      // For the local cluster only, search nearby screen positions and prevent
      // those labels from overlapping each other. Distant labels are ignored by
      // this collision system so they never get pushed away from their structures.
      const baseOffsets = [[0, 0]];
      const xSteps = [0, 88, -88, 176, -176, 264, -264, 352, -352];
      const ySteps = [0, -32, 32, -64, 64, -96, 96, -128, 128];

      xSteps.forEach((offsetX) => {
        ySteps.forEach((offsetY) => {
          if (offsetX === 0 && offsetY === 0) return;
          baseOffsets.push([offsetX, offsetY]);
        });
      });
      baseOffsets.sort(
        (first, second) =>
          first[0] * first[0] +
          first[1] * first[1] -
          (second[0] * second[0] + second[1] * second[1]),
      );

      focusLabels
        .sort((a, b) => {
          return (
            a.priority - b.priority ||
            a.focusDistance - b.focusDistance ||
            a.distance - b.distance
          );
        })
        .forEach((annotation) => {
          if (visible.length >= 240) return;
          const size = estimateLabelSize(annotation.text);
          let placed = null;

          baseOffsets.some(([offsetX, offsetY]) => {
            const labelX = annotation.x + offsetX;
            const labelY = annotation.y + offsetY;
            const rectangle = {
              left: labelX - size.width / 2,
              right: labelX + size.width / 2,
              top: labelY - 10 - size.height,
              bottom: labelY - 10,
            };

            if (
              rectangle.left < 8 ||
              rectangle.right > width - 8 ||
              rectangle.top < 8 ||
              rectangle.bottom > height - 8
            ) {
              return false;
            }

            if (
              occupiedRectangles.some((existing) =>
                rectanglesOverlap(rectangle, existing, 8),
              )
            ) {
              return false;
            }

            placed = {
              ...annotation,
              x: Math.round(labelX),
              y: Math.round(labelY),
            };
            occupiedRectangles.push(rectangle);
            return true;
          });

          // If a very dense local cluster exhausts every candidate position,
          // keep the label anchored rather than hiding it entirely.
          if (!placed) {
            placed = {
              ...annotation,
              x: Math.round(annotation.x),
              y: Math.round(annotation.y),
            };
          }

          visible.push(placed);
        });

      // Include the rendered text in the overlay signature. Previously the
      // signature only tracked id/x/y, so a label whose APP_LABEL changed only
      // in capitalization (for example "Covered Pergola" -> "COVERED PERGOLA")
      // could be treated as unchanged and Vue would keep the stale title-cased
      // text until another camera/position change forced an overlay refresh.
      const signature = visible
        .map(
          (item) => `${item.id}:${item.x}:${item.y}:${String(item.text || "")}`,
        )
        .join("|");
      if (!force && signature === this.threeLabelOverlaySignature) {
        return;
      }
      this.threeLabelOverlaySignature = signature;
      this.threeVisibleStructureLabels = visible;
    },

    handleStandaloneThreeLayerCheckboxClick(layer) {
      // All available layers, including Terrain, now use the checkbox change
      // handler. Keep this method for the existing template event binding.
      if (!layer) return;
    },

    handleStandaloneThreeLayerCheckboxChange(layer, event) {
      if (!layer) return;

      this.setStandaloneThreeLayerVisibility(
        layer.key,
        Boolean(event && event.target && event.target.checked),
      );
    },

    async setStandaloneThreeLayerVisibility(layerKey, enabled, options = {}) {
      if (layerKey === "satelliteGround") {
        await this.setStandaloneSatelliteGroundVisibility(enabled);
        return;
      }

      if (layerKey === "compactedGround") {
        await this.setStandaloneCompactedGroundVisibility(enabled);
        return;
      }

      if (layerKey === "terrainBefore") {
        const visible = Boolean(enabled);
        this.threeTerrainMode = "before";
        this.$set(this.threeLayerVisibility, "terrain", visible);
        if (visible && !this.threeLayerGroups.terrainBefore) {
          this.threeLayerLoadingKey = "terrainBefore";
          await this.yieldStandaloneThreeBuildFrame();
          await this.ensureStandaloneTerrainDisplayGroup("before");
          this.threeLayerLoadingKey = "";
        }
        this.applyStandaloneTerrainDisplayMode("before", visible);
        this.threeLayerError = "";

        if (!visible && this.threeLayerVisibility.satelliteGround) {
          await this.setStandaloneSatelliteGroundVisibility(false);
        }
        if (!visible && this.threeLayerVisibility.compactedGround) {
          await this.setStandaloneCompactedGroundVisibility(false);
        }
        return;
      }

      if (layerKey === "terrainAfter") {
        const visible = Boolean(enabled);
        this.threeTerrainMode = "after";
        this.$set(this.threeLayerVisibility, "terrain", visible);
        if (visible && !this.threeLayerGroups.terrainAfter) {
          this.threeLayerLoadingKey = "terrainAfter";
          await this.yieldStandaloneThreeBuildFrame();
          await this.ensureStandaloneTerrainDisplayGroup("after");
          this.threeLayerLoadingKey = "";
        }
        this.applyStandaloneTerrainDisplayMode("after", visible);

        // Missing Landscape/LandXML is represented by the open perimeter shell:
        // keep the checkbox usable, but explain why the Terrain (after) top
        // surface is intentionally absent.
        this.threeLayerError =
          visible && !this.hasStandaloneProjectLandscapeData()
            ? this.getStandaloneMissingLandscapeMessage("terrainAfter")
            : "";

        if (!visible && this.threeLayerVisibility.satelliteGround) {
          await this.setStandaloneSatelliteGroundVisibility(false);
        }
        if (!visible && this.threeLayerVisibility.compactedGround) {
          await this.setStandaloneCompactedGroundVisibility(false);
        }
        return;
      }

      if (!this.threeLayerAvailability[layerKey]) return;

      // The GIS column controls whether these filters are available in the UI,
      // while Landscape/LandXML controls whether they can be placed on the
      // proposed Terrain (after) surface. With GIS but no landscape, allow the
      // checkbox interaction, then return a precise layer-level error instead
      // of failing the entire 3D terrain view.
      if (enabled && !this.hasStandaloneProjectLandscapeData()) {
        this.$set(this.threeLayerVisibility, layerKey, false);
        const existingGroup =
          this.threeLayerGroups && this.threeLayerGroups[layerKey];
        if (existingGroup) existingGroup.visible = false;
        this.threeLayerError =
          this.getStandaloneMissingLandscapeMessage(layerKey);
        return;
      }

      const preserveSubLayers = Boolean(options && options.preserveSubLayers);
      if (!preserveSubLayers) {
        this.setStandaloneAllSubLayerVisibility(layerKey, Boolean(enabled));
      }

      const urls = this.getStandaloneThreeLayerUrls();
      const url = urls[layerKey] || urls.combined;
      if (!url) return;

      this.threeLayerError = "";
      this.$set(this.threeLayerVisibility, layerKey, Boolean(enabled));

      const existingGroup =
        this.threeLayerGroups && this.threeLayerGroups[layerKey];

      if (existingGroup) {
        this.makeStandaloneLayerGroupOpaque(existingGroup);
        existingGroup.visible = Boolean(enabled);

        if (layerKey === "paths" && enabled) {
          const definitions = this.getStandaloneThreeSubLayerOptions("paths");
          const visibility = this.threeSubLayerVisibility.paths || {};
          for (const definition of definitions) {
            if (visibility[definition.key] !== true) continue;
            await this.ensureStandalonePathSubLayerLoaded(definition);
          }
        }

        if (layerKey === "tse" && enabled) {
          const definitions = this.getStandaloneThreeSubLayerOptions("tse");
          const visibility = this.threeSubLayerVisibility.tse || {};
          for (const definition of definitions) {
            if (visibility[definition.key] !== true) continue;
            await this.ensureStandaloneUtilitySubLayerLoaded(definition);
          }
        }

        this.applyStandaloneSubLayerVisibility(layerKey);
        if (layerKey === "paths") {
          this.applyStandaloneConceptPathMode(this.threeToolState.conceptPaths);
        }
        if (layerKey === "structures" && !enabled) {
          this.threeVisibleStructureLabels = [];
        }
        if (layerKey === "structures" && enabled) {
          this.updateStandaloneStructureLabelOverlay(true);
        }
        return;
      }

      if (!enabled) {
        if (layerKey === "structures") {
          this.threeVisibleStructureLabels = [];
        }
        return;
      }

      if (layerKey === "vegetation") {
        await this.ensureStandaloneVegetationLayer(url);
        return;
      }

      await this.ensureStandaloneGenericFeatureLayer(layerKey, url);
    },

    async loadStandaloneGeoJson(url) {
      const response = await fetch(String(url || ""), {
        // The initial alignment/stair pre-pass deliberately releases its parsed
        // FeatureCollection before LandXML is allocated. Let the browser reuse
        // the downloaded response when enabled GIS layers parse it again.
        cache: "default",
        credentials: "same-origin",
        signal: this.getStandaloneThreeLoadSignal(),
      });

      if (!response.ok) {
        throw new Error(
          `Unable to load GIS layer (${response.status} ${response.statusText}).`,
        );
      }

      const data = await response.json();
      if (
        !data ||
        data.type !== "FeatureCollection" ||
        !Array.isArray(data.features)
      ) {
        throw new Error(
          "The GIS file is not a valid GeoJSON FeatureCollection.",
        );
      }

      return data;
    },

    async getStandaloneCachedGeoJson(url) {
      const sourceUrl = String(url || "").trim();
      if (!sourceUrl) {
        throw new Error("The GIS layer URL is empty.");
      }

      if (this.threeProjectGisData && this.threeProjectGisUrl === sourceUrl) {
        return this.threeProjectGisData;
      }

      const cached =
        this.threeProjectGisCache && this.threeProjectGisCache.get(sourceUrl);
      if (cached) return cached;

      const geojson = await this.loadStandaloneGeoJson(sourceUrl);
      if (this.threeProjectGisCache) {
        this.threeProjectGisCache.set(sourceUrl, geojson);
      }
      return geojson;
    },

    async yieldStandaloneThreeBuildFrame(buildToken = null) {
      // setTimeout creates a true browser task boundary. Promise-only yielding
      // keeps a long geometry build in the same task and Chrome can still show
      // "This page isn't responding" even though the function is async.
      await new Promise((resolve) => setTimeout(resolve, 0));
      return (
        buildToken == null ||
        (buildToken === this.threeParkBuildToken &&
          this.shouldShowThreeParkLayer())
      );
    },

    getStandaloneTreeSpecies(properties = {}) {
      return String(
        properties.TREE_SPECIES_RENDER ||
          properties.CAD_TREE_SPECIES_RENDER ||
          properties.CAD_TREE_SPECIES ||
          properties.d_CL_TREE1 ||
          properties.CL_TREE_SPECIES_NAME ||
          properties.species ||
          properties.SPECIES ||
          properties.tree_type ||
          properties.TREE_TYPE ||
          properties.QC_REMARKS ||
          properties.CL_TREE_FAMILY ||
          "",
      ).trim();
    },

    normalizeStandaloneTreeSpeciesKey(speciesValue) {
      return String(speciesValue || "")
        .trim()
        .toLowerCase()
        .replace(/[_-]+/g, " ")
        .replace(/\s+/g, " ");
    },

    getStandaloneTreeCategory(properties = {}) {
      return String(
        properties.d_CL_TREE_ ||
          properties.CL_TREE_CATEGORY ||
          properties.category ||
          properties.CATEGORY ||
          "",
      )
        .trim()
        .toLowerCase();
    },

    getStandaloneTreeDimensions(properties = {}) {
      const category = this.getStandaloneTreeCategory(properties);
      const categoryDefaults = category.includes('"a"')
        ? { height: 12, crown: 9 }
        : category.includes('"b"')
          ? { height: 10, crown: 7 }
          : category.includes('"d"')
            ? { height: 5, crown: 3.5 }
            : { height: 8, crown: 6 };

      const heightCandidates = [
        properties.DC_MATURE_,
        properties.DC_MATURE_HEIGHT_M,
        properties.EC_TREE_HEIGHT_M,
        properties.mature_height,
        properties.height_m,
        properties.HEIGHT_M,
        properties.height,
      ];
      const crownCandidates = [
        properties.DC_MATURE1,
        properties.DC_MATURE_SPREAD_M,
        properties.EC_CANOPY_SQM
          ? Math.sqrt(Number(properties.EC_CANOPY_SQM) / Math.PI) * 2
          : null,
        properties.mature_crown,
        properties.crown_m,
        properties.CROWN_M,
        properties.canopy_m,
      ];

      const firstFinite = (values, fallback) => {
        const value = values
          .map((item) => Number(item))
          .find((item) => Number.isFinite(item) && item > 0);
        return Number.isFinite(value) ? value : fallback;
      };

      return {
        height: Math.max(
          2.5,
          Math.min(22, firstFinite(heightCandidates, categoryDefaults.height)),
        ),
        crown: Math.max(
          1.8,
          Math.min(16, firstFinite(crownCandidates, categoryDefaults.crown)),
        ),
      };
    },

