    },

    getDeterministicTreeRotation(properties = {}, index = 0) {
      const source = String(
        properties.ID_UID ||
          properties.id ||
          properties.OBJECTID ||
          properties.FID ||
          index,
      );
      let hash = 2166136261;

      for (let position = 0; position < source.length; position += 1) {
        hash ^= source.charCodeAt(position);
        hash = Math.imul(hash, 16777619);
      }

      return ((hash >>> 0) / 4294967295) * Math.PI * 2;
    },

    async prepareStandaloneTerrainHeightIndex(modelData, buildToken = null) {
      if (!modelData || modelData.terrainHeightIndex) {
        return modelData ? modelData.terrainHeightIndex || null : null;
      }

      const terrainVertexRecords = Array.isArray(modelData.terrainVertexRecords)
        ? modelData.terrainVertexRecords
        : [];
      const pointMap = modelData.pointMap;
      if (
        !terrainVertexRecords.length &&
        (!pointMap || typeof pointMap.values !== "function")
      ) {
        return null;
      }

      const cellSize = Math.max(
        5,
        Math.min(40, Number(modelData.gridSpacing) / 2 || 16),
      );
      const vertexCells = new Map();
      const triangleCells = new Map();
      const cellKey = (cellX, cellZ) => `${cellX}|${cellZ}`;
      const addVertexRecord = (record) => {
        const x = Number(record && record.x);
        const z = Number(record && record.z);
        const elevation = Number(record && record.elevation);
        if (![x, z, elevation].every(Number.isFinite)) return;
        const key = cellKey(Math.floor(x / cellSize), Math.floor(z / cellSize));
        if (!vertexCells.has(key)) vertexCells.set(key, []);
        vertexCells.get(key).push(record);
      };
      const assertBuildActive = async () => {
        if (!(await this.yieldStandaloneThreeBuildFrame(buildToken))) {
          throw new Error("The 3D terrain build was cancelled.");
        }
      };

      if (terrainVertexRecords.length) {
        for (
          let recordIndex = 0;
          recordIndex < terrainVertexRecords.length;
          recordIndex += 1
        ) {
          addVertexRecord(terrainVertexRecords[recordIndex]);
          if (recordIndex > 0 && recordIndex % 16000 === 0) {
            await assertBuildActive();
          }
        }
      } else {
        let recordIndex = 0;
        for (const record of pointMap.values()) {
          addVertexRecord(record);
          recordIndex += 1;
          if (recordIndex % 16000 === 0) await assertBuildActive();
        }
      }

      const indexedTriangles =
        modelData.triangleVertexIndices instanceof Uint32Array &&
        terrainVertexRecords.length
          ? modelData.triangleVertexIndices
          : null;
      const vertexKeys =
        !indexedTriangles && Array.isArray(modelData.triangleVertexKeys)
          ? modelData.triangleVertexKeys
          : [];
      const triangleReferenceCount = indexedTriangles
        ? indexedTriangles.length
        : vertexKeys.length;

      for (let index = 0; index + 2 < triangleReferenceCount; index += 3) {
        const recordA = indexedTriangles
          ? terrainVertexRecords[indexedTriangles[index]]
          : pointMap.get(vertexKeys[index]);
        const recordB = indexedTriangles
          ? terrainVertexRecords[indexedTriangles[index + 1]]
          : pointMap.get(vertexKeys[index + 1]);
        const recordC = indexedTriangles
          ? terrainVertexRecords[indexedTriangles[index + 2]]
          : pointMap.get(vertexKeys[index + 2]);
        if (!recordA || !recordB || !recordC) continue;

        const ax = Number(recordA.x);
        const az = Number(recordA.z);
        const bx = Number(recordB.x);
        const bz = Number(recordB.z);
        const cx = Number(recordC.x);
        const cz = Number(recordC.z);
        if (![ax, az, bx, bz, cx, cz].every(Number.isFinite)) continue;

        const minCellX = Math.floor(Math.min(ax, bx, cx) / cellSize);
        const maxCellX = Math.floor(Math.max(ax, bx, cx) / cellSize);
        const minCellZ = Math.floor(Math.min(az, bz, cz) / cellSize);
        const maxCellZ = Math.floor(Math.max(az, bz, cz) / cellSize);
        for (let cellX = minCellX; cellX <= maxCellX; cellX += 1) {
          for (let cellZ = minCellZ; cellZ <= maxCellZ; cellZ += 1) {
            const key = cellKey(cellX, cellZ);
            if (!triangleCells.has(key)) triangleCells.set(key, []);
            triangleCells.get(key).push(index);
          }
        }

        if (index > 0 && index % 48000 === 0) {
          await assertBuildActive();
        }
      }

      // These offsets remain for the lifetime of the 3D scene and are read as
      // numbers only. Packed Uint32 cells use four bytes per reference instead
      // of retaining large, over-allocated JavaScript number arrays.
      let compactedCellCount = 0;
      for (const [key, offsets] of triangleCells.entries()) {
        if (Array.isArray(offsets)) {
          triangleCells.set(key, Uint32Array.from(offsets));
        }
        compactedCellCount += 1;
        if (compactedCellCount % 256 === 0) {
          await assertBuildActive();
        }
      }

      modelData.terrainHeightIndex = {
        cellSize,
        vertexCells,
        triangleCells,
      };
      return modelData.terrainHeightIndex;
    },

    createStandaloneTerrainHeightIndex(modelData) {
      if (!modelData) return null;
      if (modelData.terrainHeightIndex) return modelData.terrainHeightIndex;

      const terrainVertexRecords = Array.isArray(modelData.terrainVertexRecords)
        ? modelData.terrainVertexRecords
        : [];
      const pointMap = modelData.pointMap;
      if (
        !terrainVertexRecords.length &&
        (!pointMap || typeof pointMap.forEach !== "function")
      ) {
        return null;
      }

      const cellSize = Math.max(
        5,
        Math.min(40, Number(modelData.gridSpacing) / 2 || 16),
      );
      const vertexCells = new Map();
      const triangleCells = new Map();
      const cellKey = (cellX, cellZ) => `${cellX}|${cellZ}`;

      const addVertexRecord = (record) => {
        const x = Number(record.x);
        const z = Number(record.z);
        const elevation = Number(record.elevation);
        if (![x, z, elevation].every(Number.isFinite)) return;

        const cellX = Math.floor(x / cellSize);
        const cellZ = Math.floor(z / cellSize);
        const key = cellKey(cellX, cellZ);

        if (!vertexCells.has(key)) vertexCells.set(key, []);
        // Reuse the canonical terrain record. The old index allocated a second
        // {x,z,y} object for every LandXML point (hundreds of thousands on KAP).
        vertexCells.get(key).push(record);
      };
      if (terrainVertexRecords.length) {
        terrainVertexRecords.forEach(addVertexRecord);
      } else {
        pointMap.forEach(addVertexRecord);
      }

      // Index the actual rendered TIN triangles. Layer objects must use the
      // same triangle plane as Terrain (after), not a nearest-vertex estimate.
      // Nearest-vertex interpolation can sit several metres below a steep or
      // flattened Civil 3D face and is what allowed objects to appear under it.
      const indexedTriangles =
        modelData.triangleVertexIndices instanceof Uint32Array &&
        terrainVertexRecords.length
          ? modelData.triangleVertexIndices
          : null;
      const vertexKeys =
        !indexedTriangles && Array.isArray(modelData.triangleVertexKeys)
          ? modelData.triangleVertexKeys
          : [];
      const triangleReferenceCount = indexedTriangles
        ? indexedTriangles.length
        : vertexKeys.length;

      for (let index = 0; index + 2 < triangleReferenceCount; index += 3) {
        const recordA = indexedTriangles
          ? terrainVertexRecords[indexedTriangles[index]]
          : pointMap.get(vertexKeys[index]);
        const recordB = indexedTriangles
          ? terrainVertexRecords[indexedTriangles[index + 1]]
          : pointMap.get(vertexKeys[index + 1]);
        const recordC = indexedTriangles
          ? terrainVertexRecords[indexedTriangles[index + 2]]
          : pointMap.get(vertexKeys[index + 2]);
        if (!recordA || !recordB || !recordC) continue;

        const ax = Number(recordA.x);
        const az = Number(recordA.z);
        const bx = Number(recordB.x);
        const bz = Number(recordB.z);
        const cx = Number(recordC.x);
        const cz = Number(recordC.z);
        if (![ax, az, bx, bz, cx, cz].every(Number.isFinite)) continue;

        const minX = Math.min(ax, bx, cx);
        const maxX = Math.max(ax, bx, cx);
        const minZ = Math.min(az, bz, cz);
        const maxZ = Math.max(az, bz, cz);
        const minCellX = Math.floor(minX / cellSize);
        const maxCellX = Math.floor(maxX / cellSize);
        const minCellZ = Math.floor(minZ / cellSize);
        const maxCellZ = Math.floor(maxZ / cellSize);

        for (let cellX = minCellX; cellX <= maxCellX; cellX += 1) {
          for (let cellZ = minCellZ; cellZ <= maxCellZ; cellZ += 1) {
            const key = cellKey(cellX, cellZ);
            if (!triangleCells.has(key)) triangleCells.set(key, []);
            // Store one integer offset into the existing topology buffer rather
            // than a new triangle plus three cloned point objects per face.
            triangleCells.get(key).push(index);
          }
        }
      }

      modelData.terrainHeightIndex = {
        cellSize,
        vertexCells,
        triangleCells,
      };
      return modelData.terrainHeightIndex;
    },

    getStandaloneExactTerrainHeightAtPoint(point, terrainData) {
      if (!point || !terrainData) return null;

      const pointX = Number(point.x);
      const pointZ = Number(point.z);
      if (![pointX, pointZ].every(Number.isFinite)) return null;

      const index = this.createStandaloneTerrainHeightIndex(terrainData);
      if (!index) return null;

      const cellX = Math.floor(pointX / index.cellSize);
      const cellZ = Math.floor(pointZ / index.cellSize);
      const localTriangles = index.triangleCells.get(`${cellX}|${cellZ}`) || [];
      const indexedTriangles =
        terrainData.triangleVertexIndices instanceof Uint32Array &&
        Array.isArray(terrainData.terrainVertexRecords)
          ? terrainData.triangleVertexIndices
          : null;
      const vertexKeys = Array.isArray(terrainData.triangleVertexKeys)
        ? terrainData.triangleVertexKeys
        : [];
      const minimumElevation = Number(terrainData.minimumElevation) || 0;
      const verticalExaggeration = Math.max(
        1,
        Number(terrainData.verticalExaggeration) || 1,
      );
      const toHeight = (record) =>
        (Number(record.elevation) - minimumElevation) * verticalExaggeration;
      const epsilon = 1e-7;

      for (
        let triangleIndex = 0;
        triangleIndex < localTriangles.length;
        triangleIndex += 1
      ) {
        const triangleOffset = localTriangles[triangleIndex];
        const a = indexedTriangles
          ? terrainData.terrainVertexRecords[indexedTriangles[triangleOffset]]
          : terrainData.pointMap.get(vertexKeys[triangleOffset]);
        const b = indexedTriangles
          ? terrainData.terrainVertexRecords[
              indexedTriangles[triangleOffset + 1]
            ]
          : terrainData.pointMap.get(vertexKeys[triangleOffset + 1]);
        const c = indexedTriangles
          ? terrainData.terrainVertexRecords[
              indexedTriangles[triangleOffset + 2]
            ]
          : terrainData.pointMap.get(vertexKeys[triangleOffset + 2]);
        if (!a || !b || !c) continue;
        const ax = Number(a.x);
        const az = Number(a.z);
        const bx = Number(b.x);
        const bz = Number(b.z);
        const cx = Number(c.x);
        const cz = Number(c.z);
        if (![ax, az, bx, bz, cx, cz].every(Number.isFinite)) continue;
        const denominator = (bz - cz) * (ax - cx) + (cx - bx) * (az - cz);
        if (Math.abs(denominator) < epsilon) continue;

        const weightA =
          ((bz - cz) * (pointX - cx) + (cx - bx) * (pointZ - cz)) / denominator;
        const weightB =
          ((cz - az) * (pointX - cx) + (ax - cx) * (pointZ - cz)) / denominator;
        const weightC = 1 - weightA - weightB;

        if (weightA >= -epsilon && weightB >= -epsilon && weightC >= -epsilon) {
          return (
            weightA * toHeight(a) +
            weightB * toHeight(b) +
            weightC * toHeight(c)
          );
        }
      }

      return null;
    },

    getStandaloneNearestTerrainHeightAtPoint(point, terrainData) {
      if (!point || !terrainData) return null;
      const pointX = Number(point.x);
      const pointZ = Number(point.z);
      if (![pointX, pointZ].every(Number.isFinite)) return null;

      const index = this.createStandaloneTerrainHeightIndex(terrainData);
      if (!index) return null;

      const cellX = Math.floor(pointX / index.cellSize);
      const cellZ = Math.floor(pointZ / index.cellSize);
      const nearest = [];
      let candidateCount = 0;
      const considerCandidate = (sample) => {
        const sampleX = Number(sample && sample.x);
        const sampleZ = Number(sample && sample.z);
        const elevation = Number(sample && sample.elevation);
        if (![sampleX, sampleZ, elevation].every(Number.isFinite)) return;
        const dx = sampleX - pointX;
        const dz = sampleZ - pointZ;
        const item = { sample, distanceSquared: dx * dx + dz * dz };
        candidateCount += 1;
        const insertAt = nearest.findIndex(
          (existing) => item.distanceSquared < existing.distanceSquared,
        );
        if (insertAt < 0) nearest.push(item);
        else nearest.splice(insertAt, 0, item);
        if (nearest.length > 6) nearest.pop();
      };

      for (let radius = 0; radius <= 12 && candidateCount < 18; radius += 1) {
        for (let xOffset = -radius; xOffset <= radius; xOffset += 1) {
          for (let zOffset = -radius; zOffset <= radius; zOffset += 1) {
            if (
              radius > 0 &&
              Math.abs(xOffset) !== radius &&
              Math.abs(zOffset) !== radius
            ) {
              continue;
            }
            const cell = index.vertexCells.get(
              `${cellX + xOffset}|${cellZ + zOffset}`,
            );
            if (cell) cell.forEach(considerCandidate);
          }
        }
      }

      if (!nearest.length) return null;
      const minimumElevation = Number(terrainData.minimumElevation) || 0;
      const verticalExaggeration = Math.max(
        1,
        Number(terrainData.verticalExaggeration) || 1,
      );
      const sampleHeight = (sample) =>
        (Number(sample.elevation) - minimumElevation) * verticalExaggeration;
      if (nearest[0].distanceSquared < 0.0001) {
        return sampleHeight(nearest[0].sample);
      }

      let weightedHeight = 0;
      let totalWeight = 0;
      nearest.forEach((item) => {
        const weight = 1 / Math.max(0.25, item.distanceSquared);
        weightedHeight += sampleHeight(item.sample) * weight;
        totalWeight += weight;
      });
      return totalWeight > 0 ? weightedHeight / totalWeight : null;
    },

    getStandaloneRawTerrainHeightForStairAdjustment(point, terrainData) {
      if (!point || !terrainData) return null;

      const exact = this.getStandaloneExactTerrainHeightAtPoint(
        point,
        terrainData,
      );
      if (Number.isFinite(Number(exact))) return Number(exact);

      const nearest = this.getStandaloneNearestTerrainHeightAtPoint(
        point,
        terrainData,
      );
      return Number.isFinite(Number(nearest)) ? Number(nearest) : null;
    },

    isStandaloneActualPathStairFeature(feature) {
      if (!feature || !feature.geometry) return false;
      const geometryType = String(feature.geometry.type || "");
      if (geometryType !== "LineString" && geometryType !== "MultiLineString") {
        return false;
      }

      const properties = feature.properties || {};
      // Terrain-embedded Muanisiyah stair/bleacher edge lines are still REAL
      // visible stair geometry. Keep them eligible for the PATHS > Stairs
      // renderer. Their Terrain/Pedestrian cutout is controlled separately in
      // buildStandaloneStairTerrainAdjustmentProfiles(), so restoring the visible
      // stair mesh does not require corrupting or reshaping the LandXML terrain.
      const effectiveLayer = this.getStandaloneFeatureLayer(feature);
      const pathDefinition = this.getStandaloneSubLayerDefinition(
        "paths",
        feature,
      );
      const pathLabel = String((pathDefinition && pathDefinition.label) || "")
        .trim()
        .toLowerCase();
      const explicitPathFlag = String(
        properties.layerFilter || properties.layer_filter || "",
      )
        .trim()
        .toLowerCase();
      const explicitModel = String(properties.APP_MODEL || "")
        .trim()
        .toLowerCase();
      const explicitType = String(properties.Type || properties.type || "")
        .trim()
        .toLowerCase();
      const cadLayer = String(
        properties.cad_layer ||
          properties.CAD_LAYER ||
          properties.layer ||
          properties.Layer ||
          "",
      )
        .trim()
        .toLowerCase()
        .replace(/[_-]+/g, " ");

      // Never let WATER reference/detail linework become PATHS/Stairs merely
      // because a label contains words such as "stair cascade" or "steps".
      // A visible staircase must be explicitly classified as PATHS + STAIRS in
      // the exported GeoJSON, or be on the verified stair/step edge-line layer.
      const explicitPathStair =
        explicitPathFlag === "paths" &&
        (explicitModel === "stairs" || explicitType === "stairs");
      const semanticPathStair =
        effectiveLayer === "paths" && pathLabel === "stairs";
      const verifiedCadStair =
        effectiveLayer === "paths" &&
        /\bedge\s*line\s*(?:stair|step)\b/.test(cadLayer);

      return explicitPathStair || semanticPathStair || verifiedCadStair;
    },

    buildStandaloneStairTerrainAdjustmentProfiles(
      geojson,
      terrainData,
      terrainBeforeData = null,
    ) {
      if (
        !geojson ||
        !Array.isArray(geojson.features) ||
        !terrainData ||
        !terrainData.origin
      ) {
        return [];
      }

      // Build the cutout from the EXACT SAME renderer that creates the visible
      // 3D staircase. The previous Map.vue implementation independently grouped
      // CAD lines a second time; those two algorithms could disagree, which is
      // why Terrain (After) / Pedestrian Space sometimes covered real stairs and
      // sometimes created holes where no rendered stair existed.
      //
      // maskOnly=true performs a geometry pre-pass with no visible meshes. The
      // returned userData profiles contain ONLY tread pairs that the renderer
      // actually emitted. Therefore:
      //   Photo 2 (Stairs + Terrain After)
      //   Photo 3 (Stairs + Terrain After + Pedestrian Space)
      // keep the same staircase silhouette as Photo 1.
      const stairRecords = geojson.features
        .filter((feature) => {
          const properties = (feature && feature.properties) || {};
          // The east-side Muanisiyah bleacher/stair bands are already encoded in
          // the Terrain (After) LandXML. Keep them out of the shader cutout mask,
          // but DO NOT hide them from the visible stair renderer. This avoids the
          // old zebra-shaped terrain holes while preserving the actual stairs.
          const hasAuthoritativeCadRailing =
            properties.APP_HAS_CAD_RAILING_NEARBY === true;
          if (
            (properties.APP_TERRAIN_EMBEDDED_BLEACHER === true ||
              properties.APP_SKIP_SEPARATE_STAIR_RENDER === true) &&
            !hasAuthoritativeCadRailing
          ) {
            return false;
          }
          return this.isStandaloneActualPathStairFeature(feature);
        })
        .map((feature) => ({
          feature,
          featureType: this.getStandaloneFeatureType(feature),
        }));

      if (!stairRecords.length) return [];

      const maskTerrainModel = {
        ...terrainData,
        origin: terrainData.origin,
        terrainAfterData: terrainData,
        terrainBeforeData: terrainBeforeData || null,
      };

      const maskProbe = createStairTreadGroup({
        records: stairRecords,
        THREE,
        toLocal: (coordinate) =>
          this.lngLatToTerrainMeters(coordinate, terrainData.origin),
        // Use the same ground query as the visible staircase renderer. This keeps
        // uphill/downhill orientation AND the extrapolated final tread identical
        // between the mask pre-pass and the real stair mesh. Terrain elevations
        // are only sampled; they are never modified.
        getTerrainHeight: (point) =>
          this.getStandaloneTerrainHeightAtPoint(point, maskTerrainModel),
        clearance: 0.015,
        surfaceClearance: THREE_PATH_PEDESTRIAN_CLEARANCE_METERS,
        defaultStepHeight: 0.1,
        resolveStepHeight: (context) =>
          this.isStandaloneMuanisiyahProjectActive() &&
          context &&
          context.splitWideStaircase === true
            ? NaN
            : this.getStandaloneMuanisiyahCadStairRiserMeters(context),
        // Each lateral DXF stair section samples its own real endpoint terrain.
        // Do not search farther uphill for the highest shared landing; that is
        // what pulled short sections away from the Pedestrian Space they end at.
        preferHighestTopLanding: false,
        suppressSplitSectionTopExtensions:
          this.isStandaloneMuanisiyahProjectActive(),
        // IMPORTANT: do not force all variable-length DXF stair sections onto
        // one shared elevation ladder. Their source nosing lines already tell us
        // where each section starts/stops; solve each section against Terrain
        // (After)/Pedestrian Space at its own two endpoints instead.
        synchronizeSplitSectionElevations: false,
        suppressSyntheticTopTreads: this.isStandaloneMuanisiyahProjectActive(),
        // Keep the three-step connector flights at the tall stair landing's
        // corrected Pedestrian elevation instead of letting their old TIN
        // endpoints pull the shared landing into a ramp.
        reconcileShortConnectorStairs:
          this.isStandaloneMuanisiyahProjectActive(),
        maskOnly: true,
        // Do not reconstruct the compact stair-edge groups that cross through
        // the middle of authoritative Muanisiyah Water polygons. Those are
        // water/cascade detail linework, not pedestrian staircases. Genuine
        // short stairs elsewhere are left untouched.
        stairExclusionFeatures:
          this.isStandaloneMuanisiyahProjectActive() &&
          Array.isArray(geojson.features)
            ? geojson.features.filter((feature) =>
                this.isStandaloneAuthoritativeMuanisiyahWaterFeature(feature),
              )
            : [],
        clipTreadsAgainstExclusion: this.isStandaloneMuanisiyahProjectActive(),
      });

      const profiles =
        maskProbe &&
        maskProbe.userData &&
        Array.isArray(maskProbe.userData.stairSurfaceCutoutProfiles)
          ? maskProbe.userData.stairSurfaceCutoutProfiles
          : [];

      // Exact renderer-derived profiles remain the primary mask source.
      const exactProfiles = profiles.filter((profile) => {
        if (!profile) return false;

        const hasFiniteBounds = [
          profile.ux,
          profile.uz,
          profile.nx,
          profile.nz,
          profile.cutoutAlongMin,
          profile.cutoutAlongMax,
          profile.cutoutNormalMin,
          profile.cutoutNormalMax,
        ].every((value) => Number.isFinite(Number(value)));
        if (!hasFiniteBounds) return false;

        const treadCells = Array.isArray(profile.treadCells)
          ? profile.treadCells.filter(
              (cell) =>
                cell &&
                Number.isFinite(Number(cell.treadY)) &&
                Number.isFinite(Number(cell.alongMin)) &&
                Number.isFinite(Number(cell.alongMax)) &&
                Number.isFinite(Number(cell.normalMin)) &&
                Number.isFinite(Number(cell.normalMax)),
            )
          : [];
        return treadCells.length >= 1;
      });

      // HARD FALLBACK FOR SHORT CAD STAIRS.
      // Some 5-6 step Muanisiyah stair runs are visible because the stair renderer
      // can reconstruct them from the source nosing lines, but their small/partial
      // CAD groups can fail to merge into one renderer cutout profile during the
      // earlier mask-only pass. Terrain (After) and Pedestrian Space must still be
      // punched out there. Add a tiny oriented mask rectangle around ONLY source
      // lines explicitly named as the real stair/step edge layers, and only when
      // that source line is not already covered by an exact renderer profile.
      // This is a mask fallback only: it does not create any visible staircase.
      const pointCoveredByExactProfile = (point) => {
        if (!point || !exactProfiles.length) return false;
        return exactProfiles.some((profile) => {
          const along =
            Number(point.x) * Number(profile.ux) +
            Number(point.z) * Number(profile.uz);
          const normal =
            Number(point.x) * Number(profile.nx) +
            Number(point.z) * Number(profile.nz);
          return (
            along >= Number(profile.cutoutAlongMin) - 0.08 &&
            along <= Number(profile.cutoutAlongMax) + 0.08 &&
            normal >= Number(profile.cutoutNormalMin) - 0.08 &&
            normal <= Number(profile.cutoutNormalMax) + 0.08
          );
        });
      };

      const fallbackProfiles = [];
      stairRecords.forEach(({ feature }) => {
        const geometry = feature && feature.geometry;
        const properties = (feature && feature.properties) || {};
        const cadLayer = String(
          properties.cad_layer ||
            properties.CAD_LAYER ||
            properties.layer ||
            properties.Layer ||
            "",
        );
        // Deliberately narrow whitelist: these are the actual Muanisiyah stair
        // nosing/step layers. Do not turn generic STEPS/DAM/WEIR linework into a
        // terrain hole.
        if (
          !/edge\s*line\s*(stair|step)/i.test(cadLayer.replace(/[_-]+/g, " "))
        ) {
          return;
        }

        const lineSets =
          geometry && geometry.type === "LineString"
            ? [geometry.coordinates]
            : geometry && geometry.type === "MultiLineString"
              ? geometry.coordinates
              : [];

        lineSets.forEach((line) => {
          if (!Array.isArray(line) || line.length < 2) return;
          for (let index = 0; index < line.length - 1; index += 1) {
            const a = this.lngLatToTerrainMeters(
              line[index],
              terrainData.origin,
            );
            const b = this.lngLatToTerrainMeters(
              line[index + 1],
              terrainData.origin,
            );
            if (!a || !b) continue;
            const dx = Number(b.x) - Number(a.x);
            const dz = Number(b.z) - Number(a.z);
            const length = Math.hypot(dx, dz);
            if (!Number.isFinite(length) || length < 0.12) continue;

            const midpoint = {
              x: (Number(a.x) + Number(b.x)) * 0.5,
              z: (Number(a.z) + Number(b.z)) * 0.5,
            };
            // The renderer-derived tread cells are authoritative. Check across
            // the whole source segment (not only its midpoint): a wide nosing can
            // be split into left/right rendered cells by a Water channel, leaving
            // its midpoint intentionally empty. Re-adding the full source line in
            // that case recreated the broad black/cyan gap across both flights.
            const touchesExactProfile = [0.1, 0.3, 0.5, 0.7, 0.9].some(
              (ratio) =>
                pointCoveredByExactProfile({
                  x: THREE.MathUtils.lerp(Number(a.x), Number(b.x), ratio),
                  z: THREE.MathUtils.lerp(Number(a.z), Number(b.z), ratio),
                }),
            );
            if (touchesExactProfile) continue;

            let ux = dx / length;
            let uz = dz / length;
            if (ux < -1e-6 || (Math.abs(ux) <= 1e-6 && uz < 0)) {
              ux *= -1;
              uz *= -1;
            }
            const nx = -uz;
            const nz = ux;
            const alongA = Number(a.x) * ux + Number(a.z) * uz;
            const alongB = Number(b.x) * ux + Number(b.z) * uz;
            const normalCenter = midpoint.x * nx + midpoint.z * nz;
            // Keep the emergency mask close to the source nosing. Neighbouring
            // 25-40 cm tread lines still overlap, but the mask no longer extends
            // a third of a metre into either landing.
            const halfDepth = 0.22;
            const treadYRaw = this.getStandaloneTerrainHeightAtPoint(
              midpoint,
              maskTerrainModel,
            );
            const treadY = Number.isFinite(Number(treadYRaw))
              ? Number(treadYRaw)
              : 0;
            const alongMin = Math.min(alongA, alongB) - 0.04;
            const alongMax = Math.max(alongA, alongB) + 0.04;
            const normalMin = normalCenter - halfDepth;
            const normalMax = normalCenter + halfDepth;

            fallbackProfiles.push({
              sourceFallback: true,
              sectionId: -1,
              splitWideStaircase: false,
              ux,
              uz,
              nx,
              nz,
              alongMin,
              alongMax,
              normalMin,
              normalMax,
              cutoutAlongMin: alongMin,
              cutoutAlongMax: alongMax,
              cutoutNormalMin: normalMin,
              cutoutNormalMax: normalMax,
              cutoutOnly: true,
              Steps: 1,
              stepCount: 1,
              handrailEligible: false,
              treadCells: [
                {
                  treadIndex: 0,
                  treadY,
                  alongMin,
                  alongMax,
                  normalMin,
                  normalMax,
                  normalStart: normalMin,
                  normalEnd: normalMax,
                },
              ],
            });
          }
        });
      });

      if (fallbackProfiles.length) {
        console.info(
          "Short-stair source mask fallbacks:",
          fallbackProfiles.length,
        );
      }
      return exactProfiles.concat(fallbackProfiles);
    },

    getStandaloneStairTerrainProfileHeight(point, modelData = null) {
      const rootData = modelData || this.threeParkModelData;
      const afterData = rootData && (rootData.terrainAfterData || rootData);
      const profiles =
        afterData && Array.isArray(afterData.stairTerrainAdjustmentProfiles)
          ? afterData.stairTerrainAdjustmentProfiles
          : [];
      if (!point || !profiles.length) return null;

      const pointX = Number(point.x);
      const pointZ = Number(point.z);
      if (![pointX, pointZ].every(Number.isFinite)) return null;

      let best = null;
      profiles.forEach((profile) => {
        const along = pointX * profile.ux + pointZ * profile.uz;
        const normal = pointX * profile.nx + pointZ * profile.nz;
        const alongMin = profile.alongMin - profile.sideMargin;
        const alongMax = profile.alongMax + profile.sideMargin;
        const normalMin = profile.normalMin - profile.endMargin;
        const normalMax = profile.normalMax + profile.endMargin;
        if (
          along < alongMin ||
          along > alongMax ||
          normal < normalMin ||
          normal > normalMax
        ) {
          return;
        }

        const denominator = profile.endNormal - profile.startNormal;
        const t =
          Math.abs(denominator) > 1e-6
            ? THREE.MathUtils.clamp(
                (normal - profile.startNormal) / denominator,
                0,
                1,
              )
            : 0;
        const height = THREE.MathUtils.lerp(
          profile.startHeight,
          profile.endHeight,
          t,
        );
        const centerAlong = (profile.alongMin + profile.alongMax) / 2;
        const centerDistance = Math.abs(along - centerAlong);
        if (!best || centerDistance < best.distance) {
          best = { height, distance: centerDistance };
        }
      });

      return best ? best.height : null;
    },

    applyStandaloneStairTerrainAdjustments(terrainData, geojson) {
      if (!terrainData || !terrainData.pointMap || !geojson) return 0;

      const profiles = this.buildStandaloneStairTerrainAdjustmentProfiles(
        geojson,
        terrainData,
      );
      terrainData.stairTerrainAdjustmentProfiles = profiles;
      if (!profiles.length) return 0;

      const minimumElevation = Number(terrainData.minimumElevation) || 0;
      const verticalExaggeration = Math.max(
        0.0001,
        Number(terrainData.verticalExaggeration) || 1,
      );
      let adjustedVertexCount = 0;

      terrainData.pointMap.forEach((record) => {
        if (!record) return;
        const x = Number(record.x);
        const z = Number(record.z);
        if (![x, z].every(Number.isFinite)) return;

        const profileHeight = this.getStandaloneStairTerrainProfileHeight(
          { x, z },
          terrainData,
        );
        if (!Number.isFinite(Number(profileHeight))) return;

        record.elevation =
          minimumElevation + Number(profileHeight) / verticalExaggeration;
        adjustedVertexCount += 1;
      });

      // The height index stores the previous TIN vertex elevations. Throw it
      // away so Terrain (After), Pedestrian Space and every later ground query
      // all use the locally corrected staircase support surface.
      terrainData.terrainHeightIndex = null;
      return adjustedVertexCount;
    },

    getStandaloneStairSurfaceCutoutUniformData(
      modelData = null,
      maximumMasks = 64,
    ) {
      const rootData = modelData || this.threeParkModelData;
      const afterData = rootData && (rootData.terrainAfterData || rootData);
      const profiles =
        afterData && Array.isArray(afterData.stairSurfaceCutoutProfiles)
          ? afterData.stairSurfaceCutoutProfiles.filter((profile) => {
              if (!profile) return false;
              const treadCells = Array.isArray(profile.treadCells)
                ? profile.treadCells.filter(
                    (cell) => cell && Number.isFinite(Number(cell.treadY)),
                  )
                : [];
              // Keep the uniform fallback consistent with the texture mask:
              // every actual rendered tread is a cutout, including short stairs.
              return treadCells.length >= 1;
            })
          : [];
      const safeMaximum = Math.max(1, Math.min(64, Number(maximumMasks) || 64));
      const activeProfiles = profiles.slice(0, safeMaximum);
      const projections = [];
      const bounds = [];

      for (let index = 0; index < safeMaximum; index += 1) {
        const profile = activeProfiles[index];
        if (!profile) {
          projections.push(new THREE.Vector4(1, 0, 0, 1));
          bounds.push(new THREE.Vector4(0, -1, 0, -1));
          continue;
        }

        // This profile has already passed the exact same elevation test used
        // for handrails, so it is a confirmed real staircase. Expand the cutout
        // by only 2 cm around the rendered stair body. That tiny margin removes
        // Terrain (After) that can otherwise poke through the lower treads and
        // make them look like sloped/angled ramps.
        const cutoutExpansion = 0.02;
        projections.push(
          new THREE.Vector4(
            Number(profile.ux) || 1,
            Number(profile.uz) || 0,
            Number(profile.nx) || 0,
            Number(profile.nz) || 1,
          ),
        );
        const cutoutAlongMin = Number.isFinite(Number(profile.cutoutAlongMin))
          ? Number(profile.cutoutAlongMin)
          : Number(profile.alongMin);
        const cutoutAlongMax = Number.isFinite(Number(profile.cutoutAlongMax))
          ? Number(profile.cutoutAlongMax)
          : Number(profile.alongMax);
        const cutoutNormalMin = Number.isFinite(Number(profile.cutoutNormalMin))
          ? Number(profile.cutoutNormalMin)
          : Number(profile.normalMin);
        const cutoutNormalMax = Number.isFinite(Number(profile.cutoutNormalMax))
          ? Number(profile.cutoutNormalMax)
          : Number(profile.normalMax);

        bounds.push(
          new THREE.Vector4(
            cutoutAlongMin - cutoutExpansion,
            cutoutAlongMax + cutoutExpansion,
            cutoutNormalMin - cutoutExpansion,
            cutoutNormalMax + cutoutExpansion,
          ),
        );
      }

      return {
        count: activeProfiles.length,
        projections,
        bounds,
      };
    },

    convertStandaloneTerrainHeightBetweenModels(
      localHeight,
      sourceData,
      targetData,
    ) {
      if (!Number.isFinite(Number(localHeight)) || !sourceData || !targetData) {
        return null;
      }
      const sourceExaggeration = Math.max(
        0.0001,
        Number(sourceData.verticalExaggeration) || 1,
      );
      const targetExaggeration = Math.max(
        0.0001,
        Number(targetData.verticalExaggeration) || 1,
      );
      const absoluteElevation =
        Number(localHeight) / sourceExaggeration +
        (Number(sourceData.minimumElevation) || 0);
      return (
        (absoluteElevation - (Number(targetData.minimumElevation) || 0)) *
        targetExaggeration
      );
    },

    getStandaloneTerrainHeightAtPoint(point, modelData = null) {
      const rootData = modelData || this.threeParkModelData;
      if (!point || !rootData) return 0;

      const afterData = rootData.terrainAfterData || rootData;
      const beforeData =
        rootData.terrainBeforeData ||
        (this.threeParkModelData &&
          this.threeParkModelData.terrainBeforeData) ||
        null;

      // IMPORTANT: combined/multi-surface Civil 3D LandXML projects such as KAP
      // must place EVERY rendered park object on the finished Terrain (After).
      // Never let Terrain (Before) determine an object's elevation just because
      // the exact XY falls on a tiny TIN seam/gap. Use the nearest valid AFTER
      // sample instead. This policy is intentionally limited to multi-surface
      // LandXML projects so existing single-surface parks keep their proven
      // legacy behavior unchanged.
      const hasUsableTerrainAfter = Boolean(
        afterData &&
        afterData.hasLandscapeData &&
        afterData.showTopSurface !== false &&
        String(afterData.terrainSource || "").toLowerCase() === "landxml",
      );
      const useAuthoritativeTerrainAfter = Boolean(
        hasUsableTerrainAfter &&
        (this.isStandaloneMuanisiyahProjectActive() ||
          Number(afterData.landXmlSurfaceCount || 0) > 1),
      );

      // Ground-height queries always start with the untouched Terrain (After).
      // Stair visibility is solved with shader cutouts; the TIN itself stays exact.
      const exactAfter = this.getStandaloneExactTerrainHeightAtPoint(
        point,
        afterData,
      );
      if (Number.isFinite(exactAfter)) return exactAfter;

      if (useAuthoritativeTerrainAfter) {
        // KAP/multi-surface rule: remain on the finished-design TIN even when the
        // XY lands directly on a zone seam or in a very small triangulation gap.
        const nearestAfter = this.getStandaloneNearestTerrainHeightAtPoint(
          point,
          afterData,
        );
        if (Number.isFinite(nearestAfter)) return nearestAfter;

        // Only if the Civil 3D Terrain (After) truly has no nearby support point
        // do we use Mapbox as a last geographic fallback. Terrain (Before) is
        // deliberately NOT consulted for these projects.
        const strictOrigin = rootData.origin || afterData.origin;
        if (strictOrigin) {
          const lngLat = this.terrainMetersToLngLat(point, strictOrigin);
          const mapboxElevation = this.queryStandaloneTerrainElevation(lngLat);
          if (Number.isFinite(Number(mapboxElevation))) {
            return (
              (Number(mapboxElevation) -
                (Number(afterData.minimumElevation) || 0)) *
              Math.max(0.0001, Number(afterData.verticalExaggeration) || 1)
            );
          }
        }

        return 0;
      }

      // Legacy path for existing single-surface/no-LandXML parks. Keep the old
      // order exactly so this KAP fix cannot unexpectedly change their object
      // placement.
      if (beforeData && beforeData !== afterData) {
        const exactBefore = this.getStandaloneExactTerrainHeightAtPoint(
          point,
          beforeData,
        );
        if (Number.isFinite(exactBefore)) {
          const converted = this.convertStandaloneTerrainHeightBetweenModels(
            exactBefore,
            beforeData,
            afterData,
          );
          if (Number.isFinite(converted)) return converted;
        }
      }

      const origin = rootData.origin || afterData.origin;
      if (origin) {
        const lngLat = this.terrainMetersToLngLat(point, origin);
        const mapboxElevation = this.queryStandaloneTerrainElevation(lngLat);
        if (Number.isFinite(Number(mapboxElevation))) {
          return (
            (Number(mapboxElevation) -
              (Number(afterData.minimumElevation) || 0)) *
            Math.max(0.0001, Number(afterData.verticalExaggeration) || 1)
          );
        }
      }

      const nearestAfter = this.getStandaloneNearestTerrainHeightAtPoint(
        point,
        afterData,
      );
      if (Number.isFinite(nearestAfter)) return nearestAfter;

      if (beforeData && beforeData !== afterData) {
        const nearestBefore = this.getStandaloneNearestTerrainHeightAtPoint(
          point,
          beforeData,
        );
        if (Number.isFinite(nearestBefore)) {
          const converted = this.convertStandaloneTerrainHeightBetweenModels(
            nearestBefore,
            beforeData,
            afterData,
          );
          if (Number.isFinite(converted)) return converted;
        }
      }

      return 0;
    },

    getStandaloneTerrainSupportHeightAtPoint(
      point,
      modelData = null,
      footprintRadius = 0,
    ) {
      const centerHeight = this.getStandaloneTerrainHeightAtPoint(
        point,
        modelData,
      );
      const radius = Math.max(0, Number(footprintRadius) || 0);
      if (!radius) return centerHeight;

      // Point assets can straddle a steep Terrain (after) TIN face or sit
      // directly on the clipped park boundary. Use the highest terrain sample
      // beneath the small model footprint so the visible trunk/pole base is
      // never swallowed by an adjacent triangle.
      //
      // Multi-surface Terrain (After) parks such as KAP get a denser two-ring
      // footprint probe. Existing single-surface parks keep the exact legacy
      // eight-sample pattern so their already-good placement is not disturbed.
      const rootData = modelData || this.threeParkModelData;
      const afterData = rootData && (rootData.terrainAfterData || rootData);
      const useDenseFinishedTerrainSupport = Boolean(
        afterData &&
        afterData.hasLandscapeData &&
        String(afterData.terrainSource || "").toLowerCase() === "landxml" &&
        Number(afterData.landXmlSurfaceCount || 0) > 1,
      );
      const offsets = [];
      if (useDenseFinishedTerrainSupport) {
        [0.5, 1].forEach((ringScale) => {
          const ringRadius = radius * ringScale;
          for (let step = 0; step < 16; step += 1) {
            const angle = (step / 16) * Math.PI * 2;
            offsets.push([
              Math.cos(angle) * ringRadius,
              Math.sin(angle) * ringRadius,
            ]);
          }
        });
      } else {
        offsets.push(
          [radius, 0],
          [-radius, 0],
          [0, radius],
          [0, -radius],
          [radius * 0.7071, radius * 0.7071],
          [-radius * 0.7071, radius * 0.7071],
          [radius * 0.7071, -radius * 0.7071],
          [-radius * 0.7071, -radius * 0.7071],
        );
      }
      let supportHeight = centerHeight;
      offsets.forEach(([offsetX, offsetZ]) => {
        const sampledHeight = this.getStandaloneTerrainHeightAtPoint(
          {
            x: Number(point.x) + offsetX,
            z: Number(point.z) + offsetZ,
          },
          modelData,
        );
        if (Number.isFinite(sampledHeight)) {
          supportHeight = Math.max(supportHeight, sampledHeight);
        }
      });
      return supportHeight;
    },

    getStandaloneFinishedTerrainObjectSupportHeight(
      point,
      modelData = null,
      footprintRadius = 0,
    ) {
      const muanisiyahApronSupportHeight =
        this.getStandaloneMuanisiyahPedestrianApronSupportHeight(
          point,
          modelData,
          footprintRadius,
        );
      if (Number.isFinite(Number(muanisiyahApronSupportHeight))) {
        return Number(muanisiyahApronSupportHeight);
      }

      const rootData = modelData || this.threeParkModelData;
      const afterData = rootData && (rootData.terrainAfterData || rootData);
      const useFinishedFootprintSupport = Boolean(
        afterData &&
        afterData.hasLandscapeData &&
        String(afterData.terrainSource || "").toLowerCase() === "landxml" &&
        Number(afterData.landXmlSurfaceCount || 0) > 1,
      );

      return useFinishedFootprintSupport
        ? this.getStandaloneTerrainSupportHeightAtPoint(
            point,
            modelData,
            footprintRadius,
          )
        : this.getStandaloneTerrainHeightAtPoint(point, modelData);
    },

    getStandaloneNearestStairTreadHeight(
      point,
      modelData = null,
      maximumDistance = 1.45,
    ) {
      if (!point) return null;
      const rootData = modelData || this.threeParkModelData;
      const afterData = rootData && (rootData.terrainAfterData || rootData);
      const profiles =
        afterData && Array.isArray(afterData.stairSurfaceCutoutProfiles)
          ? afterData.stairSurfaceCutoutProfiles
          : [];
      if (!profiles.length) return null;

      const pointX = Number(point.x);
      const pointZ = Number(point.z);
      if (![pointX, pointZ].every(Number.isFinite)) return null;

      let bestDistance = Infinity;
      let bestY = null;
      profiles.forEach((profile) => {
        if (!profile) return;
        const ux = Number(profile.ux);
        const uz = Number(profile.uz);
        const nx = Number(profile.nx);
        const nz = Number(profile.nz);
        if (![ux, uz, nx, nz].every(Number.isFinite)) return;
        const along = pointX * ux + pointZ * uz;
        const normal = pointX * nx + pointZ * nz;
        const cells = Array.isArray(profile.treadCells)
          ? profile.treadCells
          : [];
        cells.forEach((cell) => {
          if (!cell) return;
          const alongMin = Number(cell.alongMin);
          const alongMax = Number(cell.alongMax);
          const normalMin = Number(cell.normalMin);
          const normalMax = Number(cell.normalMax);
          const treadY = Number(cell.treadY);
          if (
            ![alongMin, alongMax, normalMin, normalMax, treadY].every(
              Number.isFinite,
            )
          ) {
            return;
          }
          const da =
            along < alongMin
              ? alongMin - along
              : along > alongMax
                ? along - alongMax
                : 0;
          const dn =
            normal < normalMin
              ? normalMin - normal
              : normal > normalMax
                ? normal - normalMax
                : 0;
          const distance = Math.hypot(da, dn);
          if (distance < bestDistance) {
            bestDistance = distance;
            bestY = treadY;
          }
        });
      });

      return Number.isFinite(Number(bestY)) &&
        bestDistance <= Math.max(0.2, Number(maximumDistance) || 1.45)
        ? Number(bestY)
        : null;
    },

    getStandaloneMuanisiyahWaterCascadeProfiles(modelData = null) {
      const rootData = modelData || this.threeParkModelData;
      const afterData = rootData && (rootData.terrainAfterData || rootData);
      if (!afterData || !afterData.origin) return [];

      const validProfiles = (profiles) =>
        (Array.isArray(profiles) ? profiles : []).filter((profile) => {
          if (!profile) return false;
          const cells = Array.isArray(profile.treadCells)
            ? profile.treadCells.filter((cell) =>
                [
                  cell && cell.treadY,
                  cell && cell.alongMin,
                  cell && cell.alongMax,
                  cell && cell.normalMin,
                  cell && cell.normalMax,
                ].every((value) => Number.isFinite(Number(value))),
              )
            : [];
          return cells.length >= 2;
        });

      // 1) Best source: the profiles from the ACTUAL visible white staircase.
      //    These are guaranteed to have exactly the same treadY values that the
      //    user sees on screen.
      const visibleProfiles = validProfiles(
        (rootData && rootData.muanisiyahRenderedStairSurfaceProfiles) ||
          afterData.muanisiyahRenderedStairSurfaceProfiles,
      );
      if (visibleProfiles.length) {
        afterData.muanisiyahWaterCascadeProfiles = visibleProfiles;
        return visibleProfiles;
      }

      // 2) Next best: the already-qualified Terrain/Pedestrian stair profiles.
      //    They were built with the SAME water-overlap exclusion as the visible
      //    staircase, so pseudo "stair" linework belonging to the water feature
      //    cannot steal the water-height match.
      const authoritativeProfiles = validProfiles(
        afterData.stairSurfaceCutoutProfiles,
      );
      if (authoritativeProfiles.length) {
        afterData.muanisiyahWaterCascadeProfiles = authoritativeProfiles;
        return authoritativeProfiles;
      }

      if (Array.isArray(afterData.muanisiyahWaterCascadeProfiles)) {
        return validProfiles(afterData.muanisiyahWaterCascadeProfiles);
      }

      // 3) Last-resort fallback: reconstruct the profiles, but use EXACTLY the
      //    same exclusions as the visible stair renderer. v2-v4 deliberately
      //    omitted this exclusion; that allowed compact water-detail linework to
      //    become false stair profiles and could place Water below the real stair.
      const geojson = this.threeProjectGisData;
      const features =
        geojson && Array.isArray(geojson.features) ? geojson.features : [];
      if (!features.length) {
        afterData.muanisiyahWaterCascadeProfiles = [];
        return [];
      }

      const stairRecords = features
        .filter((feature) => {
          if (!this.isStandaloneActualPathStairFeature(feature)) return false;
          const properties = (feature && feature.properties) || {};
          const hasAuthoritativeCadRailing =
            properties.APP_HAS_CAD_RAILING_NEARBY === true;
          if (
            (properties.APP_TERRAIN_EMBEDDED_BLEACHER === true ||
              properties.APP_SKIP_SEPARATE_STAIR_RENDER === true) &&
            !hasAuthoritativeCadRailing
          ) {
            return false;
          }
          return true;
        })
        .map((feature) => ({
          feature,
          featureType: this.getStandaloneFeatureType(feature),
        }));

      if (!stairRecords.length) {
        afterData.muanisiyahWaterCascadeProfiles = [];
        return [];
      }

      const waterProbeModel = {
        ...afterData,
        origin: afterData.origin,
        terrainAfterData: afterData,
        terrainBeforeData:
          (rootData && rootData.terrainBeforeData) ||
          (this.threeParkModelData &&
            this.threeParkModelData.terrainBeforeData) ||
          null,
      };

      const stairExclusionFeatures = features.filter((feature) =>
        this.isStandaloneAuthoritativeMuanisiyahWaterFeature(feature),
      );

      const probe = createStairTreadGroup({
        records: stairRecords,
        THREE,
        toLocal: (coordinate) =>
          this.lngLatToTerrainMeters(coordinate, afterData.origin),
        getTerrainHeight: (point) =>
          this.getStandaloneTerrainHeightAtPoint(point, waterProbeModel),
        clearance: 0.015,
        surfaceClearance: THREE_PATH_PEDESTRIAN_CLEARANCE_METERS,
        defaultStepHeight: 0.1,
        resolveStepHeight: (context) =>
          this.isStandaloneMuanisiyahProjectActive() &&
          context &&
          context.splitWideStaircase === true
            ? NaN
            : this.getStandaloneMuanisiyahCadStairRiserMeters(context),
        // Each lateral DXF stair section samples its own real endpoint terrain.
        // Do not search farther uphill for the highest shared landing; that is
        // what pulled short sections away from the Pedestrian Space they end at.
        preferHighestTopLanding: false,
        suppressSplitSectionTopExtensions:
          this.isStandaloneMuanisiyahProjectActive(),
        // IMPORTANT: do not force all variable-length DXF stair sections onto
        // one shared elevation ladder. Their source nosing lines already tell us
        // where each section starts/stops; solve each section against Terrain
        // (After)/Pedestrian Space at its own two endpoints instead.
        synchronizeSplitSectionElevations: false,
        suppressSyntheticTopTreads: this.isStandaloneMuanisiyahProjectActive(),
        // Keep the three-step connector flights at the tall stair landing's
        // corrected Pedestrian elevation instead of letting their old TIN
        // endpoints pull the shared landing into a ramp.
        reconcileShortConnectorStairs:
          this.isStandaloneMuanisiyahProjectActive(),
        maskOnly: true,
        stairExclusionFeatures,
        clipTreadsAgainstExclusion: this.isStandaloneMuanisiyahProjectActive(),
      });

      const profiles = validProfiles(
        probe && probe.userData && probe.userData.stairSurfaceCutoutProfiles,
      );

      afterData.muanisiyahWaterCascadeProfiles = profiles;
      console.info("Muanisiyah Water cascade stair profiles v5:", {
        source: "same-exclusion-stair-probe",
        sourceStairRecordCount: stairRecords.length,
        cascadeProfileCount: profiles.length,
        treadCellCount: profiles.reduce(
          (sum, profile) =>
            sum +
            (Array.isArray(profile && profile.treadCells)
              ? profile.treadCells.length
              : 0),
          0,
        ),
      });
      return profiles;
    },

    getStandaloneMuanisiyahWaterStairTreadMatch(
      point,
      modelData = null,
      maximumEdgeSnap = THREE_MUANISIYAH_WATER_STAIR_EDGE_SNAP_METERS,
    ) {
      if (!point) return null;
      const rootData = modelData || this.threeParkModelData;
      const profiles =
        this.getStandaloneMuanisiyahWaterCascadeProfiles(rootData);
      if (!profiles.length) return null;

      const pointX = Number(point.x);
      const pointZ = Number(point.z !== undefined ? point.z : point.y);
      if (![pointX, pointZ].every(Number.isFinite)) return null;

      const normalSnap = Math.max(
        0,
        Number(maximumEdgeSnap) ||
          THREE_MUANISIYAH_WATER_STAIR_EDGE_SNAP_METERS,
      );
      const lateralReach = THREE_MUANISIYAH_WATER_STAIR_LATERAL_REACH_METERS;
      let bestMatch = null;

      profiles.forEach((profile, profileIndex) => {
        if (!profile) return;
        const ux = Number(profile.ux);
        const uz = Number(profile.uz);
        const nx = Number(profile.nx);
        const nz = Number(profile.nz);
        if (![ux, uz, nx, nz].every(Number.isFinite)) return;

        const along = pointX * ux + pointZ * uz;
        const normal = pointX * nx + pointZ * nz;
        const cells = Array.isArray(profile.treadCells)
          ? profile.treadCells
          : [];

        cells.forEach((cell, cellIndex) => {
          if (!cell) return;
          const alongMin = Number(cell.alongMin);
          const alongMax = Number(cell.alongMax);
          const rawNormalStart = Number(cell.normalStart);
          const rawNormalEnd = Number(cell.normalEnd);
          const rawNormalMin = Number(cell.normalMin);
          const rawNormalMax = Number(cell.normalMax);
          const treadY = Number(cell.treadY);

          const normalMin =
            Number.isFinite(rawNormalStart) && Number.isFinite(rawNormalEnd)
              ? Math.min(rawNormalStart, rawNormalEnd)
              : Math.min(rawNormalMin, rawNormalMax);
          const normalMax =
            Number.isFinite(rawNormalStart) && Number.isFinite(rawNormalEnd)
              ? Math.max(rawNormalStart, rawNormalEnd)
              : Math.max(rawNormalMin, rawNormalMax);

          if (
            ![alongMin, alongMax, normalMin, normalMax, treadY].every(
              Number.isFinite,
            )
          ) {
            return;
          }

          // CRITICAL: the stair progresses along the profile NORMAL axis.
          // The cascade channel can sit laterally beside/between the tread mesh,
          // so do not use one radial distance for both axes.
          const normalGap =
            normal < normalMin
              ? normalMin - normal
              : normal > normalMax
                ? normal - normalMax
                : 0;
          if (normalGap > normalSnap) return;

          const alongGap =
            along < alongMin
              ? alongMin - along
              : along > alongMax
                ? along - alongMax
                : 0;
          if (alongGap > lateralReach) return;

          const insideNormal = normalGap <= 1e-7;
          const insideAlong = alongGap <= 1e-7;
          const normalCenter = (normalMin + normalMax) * 0.5;

          // First lock to the correct STEP BAND. Only after that choose the
          // nearest stair flight laterally. This stops the water from jumping
          // forward/backward to the wrong tread while letting a center channel
          // borrow the elevation of the adjacent stair.
          const score =
            (insideNormal ? 0 : 100000) +
            normalGap * 10000 +
            (insideAlong ? 0 : 1000) +
            alongGap * 100 +
            Math.abs(normal - normalCenter);

          const isMeaningfullyBetter =
            !bestMatch || score < bestMatch.score - 0.25;
          const isSameStepBandButHigher =
            bestMatch &&
            Math.abs(score - bestMatch.score) <= 0.25 &&
            Number(treadY) > Number(bestMatch.treadY) + 0.002;

          if (isMeaningfullyBetter || isSameStepBandButHigher) {
            bestMatch = {
              score,
              inside: insideNormal && insideAlong,
              distance: Math.hypot(alongGap, normalGap),
              alongGap,
              normalGap,
              treadY,
              profile,
              cell,
              profileIndex,
              cellIndex,
            };
          }
        });
      });

      return bestMatch;
    },

    getStandaloneCadHandrailSupportHeight(point, modelData = null) {
      const rootData = modelData || this.threeParkModelData;
      const afterData = rootData && (rootData.terrainAfterData || rootData);
      const profiles =
        afterData && Array.isArray(afterData.stairSurfaceCutoutProfiles)
          ? afterData.stairSurfaceCutoutProfiles
          : [];
      let bestScore = Infinity;
      let bestY = NaN;

      profiles.forEach((profile) => {
        if (!profile) return;
        const ux = Number(profile.ux);
        const uz = Number(profile.uz);
        const nx = Number(profile.nx);
        const nz = Number(profile.nz);
        if (![ux, uz, nx, nz].every(Number.isFinite)) return;
        const along = Number(point.x) * ux + Number(point.z) * uz;
        const normal = Number(point.x) * nx + Number(point.z) * nz;
        const cells = Array.isArray(profile.treadCells)
          ? profile.treadCells.filter(
              (cell) =>
                cell &&
                [
                  cell.alongMin,
                  cell.alongMax,
                  cell.normalMin,
                  cell.normalMax,
                  cell.treadY,
                ].every((value) => Number.isFinite(Number(value))),
            )
          : [];
        cells.forEach((cell) => {
          const alongPad = 0.35;
          const normalPad = 0.55;
          const alongMin = Number(cell.alongMin) - alongPad;
          const alongMax = Number(cell.alongMax) + alongPad;
          const normalMin = Number(cell.normalMin) - normalPad;
          const normalMax = Number(cell.normalMax) + normalPad;
          const da =
            along < alongMin
              ? alongMin - along
              : along > alongMax
                ? along - alongMax
                : 0;
          const dn =
            normal < normalMin
              ? normalMin - normal
              : normal > normalMax
                ? normal - normalMax
                : 0;
          const score =
            Math.hypot(da, dn) + (profile.handrailEligible ? 0 : 0.12);
          if (score < bestScore) {
            bestScore = score;
            bestY = Number(cell.treadY);
          }
        });
      });

      if (Number.isFinite(bestY) && bestScore <= 1.35) {
        return bestY + 0.02;
      }
      return this.getStandaloneFinishedTerrainObjectSupportHeight(
        point,
        modelData,
        0.12,
      );
    },

    enableStandaloneVegetationInstanceOpacity(material) {
      if (!material || material.userData.__vegetationInstanceOpacity) return;
      material.userData.__vegetationInstanceOpacity = true;
      material.transparent = true;

      const previousOnBeforeCompile = material.onBeforeCompile;
      material.onBeforeCompile = (shader, renderer) => {
        if (typeof previousOnBeforeCompile === "function") {
          previousOnBeforeCompile(shader, renderer);
        }
        shader.vertexShader = shader.vertexShader
          .replace(
            "#include <common>",
            `#include <common>
attribute float instanceOpacity;
varying float vVegetationInstanceOpacity;`,
          )
          .replace(
            "#include <begin_vertex>",
            `#include <begin_vertex>
vVegetationInstanceOpacity = instanceOpacity;`,
          );
        shader.fragmentShader = shader.fragmentShader
          .replace(
            "#include <common>",
            `#include <common>
varying float vVegetationInstanceOpacity;`,
          )
          .replace(
            "#include <opaque_fragment>",
            `diffuseColor.a *= clamp(vVegetationInstanceOpacity, 0.0, 1.0);
#include <opaque_fragment>`,
          );
      };

      const oldCacheKey = material.customProgramCacheKey;
      material.customProgramCacheKey = () =>
        `${typeof oldCacheKey === "function" ? oldCacheKey.call(material) : ""}-vegetation-instance-opacity-v1`;
      material.needsUpdate = true;
    },

    updateStandaloneVegetationLineLod() {
      if (!this.threeCamera || !this.threeControls || !this.threeLayerGroups) {
        return;
      }
      const vegetation = this.threeLayerGroups.vegetation;
      if (!vegetation || !vegetation.visible) return;

      const target = this.threeControls.target || new THREE.Vector3();
      const distance = this.threeCamera.position.distanceTo(target);
      const maxDimension = Math.max(
        1,
        Number(
          this.threeParkModelData && this.threeParkModelData.maxDimension,
        ) || 500,
      );
      const farRatio = THREE.MathUtils.clamp(
        (distance - maxDimension * 0.55) / (maxDimension * 1.9),
        0,
        1,
      );

      // If an individual tree crown becomes a foreground obstruction and fills
      // roughly 75% of the viewport height, fade that tree to ~25% opacity.
      // The fade starts earlier so it is smooth instead of suddenly popping.
      const verticalFov = THREE.MathUtils.degToRad(
        Number(this.threeCamera.fov) || 45,
      );
      const cameraPosition = this.threeCamera.position;
      const cameraForward = new THREE.Vector3();
      this.threeCamera.getWorldDirection(cameraForward);
      const tempPosition = new THREE.Vector3();
      const toTree = new THREE.Vector3();

      vegetation.traverse((object) => {
        if (!object || !object.material) return;
        const name = String(object.name || "");
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];

        // Per-instance foreground transparency is attached only to the canopy
        // owner. Its geometry/instanceOpacity attribute is shared by the matching
        // outline and glow InstancedMeshes.
        if (
          object.isInstancedMesh &&
          Array.isArray(object.userData.treeScreenRecords) &&
          object.userData.instanceOpacityAttribute
        ) {
          const attribute = object.userData.instanceOpacityAttribute;
          const records = object.userData.treeScreenRecords;
          let changed = false;

          records.forEach((record, index) => {
            tempPosition.set(record.x, record.y, record.z);
            toTree.copy(tempPosition).sub(cameraPosition);
            const treeDistance = Math.max(0.02, toTree.length());
            const radius = Math.max(0.25, Number(record.radius) || 1);
            const forwardDistance = toTree.dot(cameraForward);

            // The previous test accidentally excluded the most important case:
            // when the camera was inside / almost inside a large canopy.
            const cameraInsideOrNear = treeDistance <= radius * 1.35;
            const inFront =
              forwardDistance > -radius * 0.2 || cameraInsideOrNear;

            const effectiveDistance = Math.max(
              0.05,
              treeDistance - radius * 0.62,
            );
            const angularDiameter = inFront
              ? 2 * Math.atan2(radius, effectiveDistance)
              : 0;
            const screenHeightFraction =
              verticalFov > 0 ? angularDiameter / verticalFov : 0;

            const fade = cameraInsideOrNear
              ? 1
              : THREE.MathUtils.smoothstep(screenHeightFraction, 0.42, 0.72);
            // A fully obstructing foreground tree becomes 82% transparent.
            const nextOpacity = THREE.MathUtils.lerp(1, 0.18, fade);
            if (Math.abs(attribute.getX(index) - nextOpacity) > 0.015) {
              attribute.setX(index, nextOpacity);
              changed = true;
            }
          });

          if (changed) attribute.needsUpdate = true;
        }

        materials.forEach((material) => {
          if (!material || !material.transparent) return;
          if (
            name.includes("-outline") ||
            name === "vegetation-trunk-outlines"
          ) {
            material.opacity = THREE.MathUtils.lerp(0.38, 0.045, farRatio);
            material.needsUpdate = true;
          } else if (name.includes("-glow")) {
            material.opacity = THREE.MathUtils.lerp(0.065, 0.008, farRatio);
            material.needsUpdate = true;
          }
        });
      });
    },

    getStandaloneTreeCanopyClusterLayout(profile = {}) {
