      const cluster = (x, y, z, sx, sy, sz) => ({
        x,
        y,
        z,
        sx,
        sy,
        sz,
      });

      // Each layout is normalized to roughly a unit crown. The whole disconnected
      // cluster geometry is still rendered with ONE InstancedMesh per species, so
      // 889 Munisiyah trees can look biologically different without creating one
      // Mesh object per foliage lobe.
      const layouts = {
        // Vachellia/Acacia nilotica: broad, flat-topped umbrella with several
        // overlapping foliage pads and visible gaps between the major limbs.
        "acacia-nilotica": [
          cluster(0.0, 0.16, 0.0, 0.58, 0.38, 0.56),
          cluster(-0.38, 0.04, 0.05, 0.48, 0.3, 0.4),
